(window.GAMES = window.GAMES || {})[2000] = [{"t":"007 Racing","p":["PlayStation"],"r":"November 20","l":"https://en.wikipedia.org/wiki/007_Racing"},{"t":"10Six","p":["Windows"],"d":"SegaSoft","u":"SegaSoft","g":"MMORTS","r":"February 28, 2000","l":"https://en.wikipedia.org/wiki/10Six","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xag.jpg","s":"10Six is a massively multiplayer online strategy game developed by Segasoft and published by Sega for Windows PCs.\n\n10Six was Sega's first foray into MMO's, a persistent online RTS where players signed up for one of four mega-corporations aiming to conquer the rogue planet Visitor, which has entered the solar system and contains a treasure of valuable resources.\n\nPlayers construct and capture mining sites, construct defenses and NPC units to help defend and attack in a fairly traditional RTS mode, but much of the game also consists of player on player combat in first or third person modes, similar to Battlezone or Planetside.\n\nThe server infrastructure was designed to be able to handle a million simultaneous players and was hosted through SegaSoft's Heat.net (and later 10SIX.com), but never saw player counts that high. After failing to attract a sufficiently large audience Sega shut down the game in June 2002, offering refunds to anybody with subscription time left.\n\nIt was set to be ported to the Sega Dreamcast, originally for Autumn 2000 but was delayed and then cancelled in March 2001.\n\nA community effort to relaunch the game was started soon after the servers were taken down. Conundrum Studios was formed in late 2002, and the game was relaunched under the name Project Visitor in 2003."},{"t":"1944: The Loop Master","p":["Arcade"],"d":"Raizing","u":"Capcom","g":"Scrolling shooter","r":"September 2000","l":"https://en.wikipedia.org/wiki/1944:_The_Loop_Master","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kqq.jpg","s":"The game takes place in the heated battles of 1944 during the Second World War as a super ace pilot attempts to defeat an entire army. The game operates and plays like most standard shooters. The objective of every level is to shoot enemy planes, tanks, trains, turrets, battleships, and defeat the boss after each level. Unlike its predecessor, 19XX: The War Against Destiny, the game plays more like the early games in the series."},{"t":"3-D Ultra Pinball: Thrillride","p":["Windows","macOS","Game Boy Color"],"d":"Dynamix, Left Field Productions","u":"Sierra On-Line","g":"Pinball","r":"December 29, 2000","l":"https://en.wikipedia.org/wiki/3-D_Ultra_Pinball:_Thrillride","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6w3e.jpg","s":"Imagine a pinball machine emulating a full amusement park, and not just any park, but Hersheypark in Hershey, Pennsylvania, \"The sweetest place on Earth!\"!\nOver 15 action-packed \"rides\", plenty of special events include \"lights out\" fireworks show, double multi-ball event, side tables, multiple flipper sets, and more!"},{"t":"4 Wheel Thunder","p":["Dreamcast"],"r":"May 4","l":"https://en.wikipedia.org/wiki/4_Wheel_Thunder"},{"t":"4x4 Evo","p":["Dreamcast","macOS","Windows"],"d":"Terminal Reality","u":"Gathering of Developers","g":"Racing","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/4x4_Evo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co292q.jpg","s":"4x4 EVO is a racing game featuring real-life pickup trucks and SUV's. Actual trucks from manufacturers such as Chevrolet, Ford, Dodge, Nissan, Toyota and more are included.\n\nThe actual racing game is based very heavily on Terminal Reality's Monster Truck Madness series of games, except with SUV's instead of monster trucks.\n\nOne significant feature of 4x4 Evo is the online multi-player option. The Dreamcast, PC, and Macintosh versions can compete against each other in 4 player online races."},{"t":"7 Blades","p":["PlayStation 2"],"d":"Konami Computer Entertainment Japan East, Paradise Pictures","u":"Konami","g":"Action-adventure","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/7_Blades","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co80rm.jpg","s":"7 Blades is an action-adventure video game developed by Konami for the PlayStation 2."},{"t":"9:05","p":["Windows","macOS","Browser","Linux","MS-DOS"],"d":"Adam Cadre","g":"Interactive fiction","l":"https://en.wikipedia.org/wiki/9:05","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xri.jpg","s":"The phone rings.\n\nOh, no — how long have you been asleep? Sure, it was a tough night, but... This is bad. This is very bad."},{"t":"A-Train 6","p":["PlayStation 2"],"g":"Simulator, Strategy","l":"https://en.wikipedia.org/wiki/A-Train_6","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaapx.jpg","s":"In A Train 6 your goal as a the head of a major transport company is to build up an effective railway network.\n\nYou will gain the main amount of your income by transporting passengers and cargo. It is also possible to earn money by buying and selling land, housing planning and developing the local industry. It is crucial to keep optimizing the schedules, in order to improve the cost-effectiveness of your transport network.\n\nThe game is completely in 3D and offers 40 trains, each with its individual advantages and disadvantages, such as speed, capacity and costs per mile. The game features a total amount of 80 buildings and allows you to play in 6 different scenarios, all of which include unique tasks and possibilities."},{"t":"Aces High","p":["Windows"],"d":"HiTech Creations","g":"Air combat simulation","r":"May 8, 2000","l":"https://en.wikipedia.org/wiki/Aces_High_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3uf6.jpg","s":"Aces High is a multiplayer game in which three teams fight over domination of the map. The success is measured in ground targets: a team loses when they only have their headquarters left. To capture a target (some have to be simply destroyed), the team has to bring its defenses down and then bring in troops (for example with a C-47). However, this is not enough because - depending on the damage taken - it first has to be built up again. The time this takes depend on various factors, e.g. what other near targets are available, and can be sped up with supply drops by transport aircraft. Available ground installments also have other effects, e.g. the availability of ammo or troops.\n\nThe majority of of the action is fought in the air with World War II aircraft, but there are also ground (e.g. tanks) and naval vehicles available. The matches itself are of a grand scale and can take multiple hours; afterwards the map is reset. Overall the controls are somewhere between simulation and action. Depending on the arena, which can also be crafted with the editor, the exact winning conditions can be slightly different. While the multiplayer matches are subscription-based, there is also a free offline mode for training included.\n\nIn the years after release, the game was under continuous development and saw many minor and major changes. This includes World War I vehicles, a tool to record/replay gameplay footage and changes to the technical framework resulting in updated system requirements."},{"t":"Aconcagua","p":["PlayStation"],"d":"WACWAC!","u":"Sony Computer Entertainment","g":"Point-and-click adventure","r":"June 1, 2000","l":"https://en.wikipedia.org/wiki/Aconcagua_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oj0.jpg","s":"Aconcagua is a 2000 PlayStation adventure video game developed by Sony Computer Entertainment. It was released only in Japan.\n\nThe game is set on a mountain after a plane crash, and allows for the switching between characters."},{"t":"AeroWings 2: Airstrike","p":["Dreamcast","Windows"],"d":"CRI","u":"CRI Middleware, Crave Entertainment","g":"Air combat simulation","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/AeroWings_2:_Airstrike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40dv.jpg","s":"Whereas the first AeroWings game was all about flight acrobatics, AeroWings 2: Air Strike is a fighter jet game. The most important modes selectable are free flight, which as the name implies gives you freedom to fly what you want (land it in the middle of a freeway if you'd like or next to skyscrapers) and over what type of weather and the split-screen versus mode (2 player). In addition to those modes, the game features training in over 30 fighter training missions and 15 tactical challenges. Successful completion of these challenges will unlock additional fighters (including the XF-3 Super Recipro, F-2B Support Fighter or F-15DJ Aggressor 2 to name a few) and decals/paint for the plane models.\n\nAs far as the realism goes, the game is customizable with options for either Standard or Professional Flight controls. The main difference between the two being the inclusion of more realistic G-Forces on your plane. It's also important to note that the controls are nearly identical to the first game with one or two buttons difference."},{"t":"Age of Empires II: The Conquerors","p":["Windows"],"u":"Microsoft","r":"August 24, 2000"},{"t":"Agharta: The Hollow Earth","p":["Windows"],"d":"Aniware AB","u":"Egmont Interactive","g":"Action, adventure","l":"https://en.wikipedia.org/wiki/Agharta:_The_Hollow_Earth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8y06.jpg","s":"Agharta: The Hollow Earth is an point and click adventure game set in 1926, where you play as a pilot who is asked to fly to the North Pole and find a scientist who was lost with his expedition to find the entrance to the Hollow Earth."},{"t":"Air","p":["Windows"],"d":"Key","u":"Visual Arts, NEC Interchannel, Prototype","g":"Eroge, visual novel","r":"September 8, 2000","l":"https://en.wikipedia.org/wiki/Air_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co76v4.jpg","s":"Air is a Japanese visual novel developed by Key that follows the story of the life of Yukito Kunisaki, a traveling showman searching for the \"girl in the sky\". He arrives in a quiet, seaside town where he meets three girls, one of whom is the key to the end of his journey. The gameplay in Air follows a branching plot line that offers pre-determined scenarios with courses of interaction and focuses on the appeal of the three female main characters by the player character."},{"t":"Airfix Dogfighter","p":["Windows"],"d":"Unique Development Studios, Paradox Entertainment","u":"Vision Park, EON Digital Entertainment","g":"Action, vehicular combat","r":"November 3, 2000","l":"https://en.wikipedia.org/wiki/Airfix_Dogfighter"},{"t":"Airport Tycoon","p":["Windows"],"d":"Krisalis Software","u":"TalonSoft, Global Star Software","g":"Business simulation game","r":"April 25, 2000","l":"https://en.wikipedia.org/wiki/Airport_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/u0d6tsgormzttf8dskyd.jpg","s":"An airport-business simulation developed by Krisalis."},{"t":"Alice in Wonderland","p":["Game Boy Color"],"d":"Digital Eclipse","u":"Nintendo","g":"Platformer","r":"October 4, 2000","l":"https://en.wikipedia.org/wiki/Alice_in_Wonderland_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ph9.jpg","s":"A true translation right from the Disney movie, Alice finds herself in the wonderland that she's expected to.\n\nOver the course of the game Alice meets major characters from the story, who will have either lost an item or need some help in some sort, for which Alice will volunteer to help."},{"t":"Alien Resurrection","p":["PlayStation"],"d":"Argonaut Games","u":"Fox Interactive","g":"First-person shooter, survival horror","r":"October 20, 2000","l":"https://en.wikipedia.org/wiki/Alien_Resurrection_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaszn.jpg","s":"Gameplay is standard FPS action, with limited ammo and plenty of hazards to detour around or find the switch to deactivate. The player switches between the four main characters at each level change, each with a slightly different set of abilities (Call has a motion tracker, Christie has his twin pistols from the film). Levels are based around keeping the Auriga running, and making their way through the ship to escape.\n\nThis was to be Fox Interactive's last Sega Saturn game, but development was pulled on the Saturn version before it was completed. PC and Dreamcast ports of the game were also planned but were never developed due to the original title's poor sales."},{"t":"All Star Pro-Wrestling","p":["PlayStation 2"],"d":"Square","u":"Square","g":"Professional wrestling","r":"June 8, 2000","l":"https://en.wikipedia.org/wiki/All_Star_Pro-Wrestling","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co80kz.jpg","s":"The breathtaking realism is the ultimate goal! The warriors of the ring will capture your imagination and come to life. Square has entered the arena of professional wrestling, and it will shock you and bring you into the action!"},{"t":"All-Star Baseball 2001","p":["Nintendo 64","Game Boy Color"],"d":"High Voltage Software, KnowWonder","u":"Acclaim Entertainment","g":"Sports game","r":"March 30, 2000","l":"https://en.wikipedia.org/wiki/All-Star_Baseball_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co47fd.jpg","s":"The last All-Star Baseball release on the N64 once again includes some new features as well as improvements in relation to previous play modes & options. For 2001, a new team is included, The Coopertown Legends, featuring a selection of some of the finest players to ever grace the MLB, including Yogi Berra, Willie Stargell and Reggie Jackson.\nAlong with the legends team, you can choose from every player, team and stadium from the real 2000 MLB season. Each player includes facial expressions and looks inspired to realism, plus motion-captured player movements, batting stances and reactions to key events during play."},{"t":"Allegiance","p":["Windows"],"d":"Microsoft Research","u":"Microsoft","g":"Space simulation, real-time strategy, action","r":"March 31, 2000","l":"https://en.wikipedia.org/wiki/Allegiance_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qo7.jpg","s":"Allegiance is a multiplayer space combat sim originally developed by Microsoft that offers the action of ship-to-ship combat. From small, agile scouts to massive destroyers, you not only fly but also man the turrets. With real-time strategy components such as fully upgradeable tech and massive multiplayer capability, Allegiance stands at the forefront of online interstellar combat."},{"t":"America","p":["Windows"],"d":"Related Designs","u":"Data Becker","g":"Real-time strategy","r":"December 2000","l":"https://en.wikipedia.org/wiki/America_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3s5x.jpg","s":"A*M*E*R*I*C*A is a Wild West-themed real-time strategy game set over 90 years in post civil war America. The events portrayed in America are taken straight from the annals of American history. Players choose between Native Americans (specifically the Sioux tribe), Mexicans, Outlaws, or the Settlers in an attempt to settle the wild western frontier. Each side has certain advantages abilities and limitations to help balance out the sides. As in a typical real-time strategy game, workers gather resources to pay for units and buildings. There are various scenarios to play. Multiplayer with up to 8 players is also supported."},{"t":"American McGee's Alice","p":["Windows"],"r":"December 6","l":"https://en.wikipedia.org/wiki/American_McGee%27s_Alice"},{"t":"Animastar","p":["Dreamcast"],"g":"Simulator","l":"https://en.wikipedia.org/wiki/Animastar","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4tqj.jpg","s":"Animastar is a Japanese-only monster raising and racing sim for the Sega Dreamcast. Players raise and evolve creatures to compete with others from around the world on the racetrack."},{"t":"Animorphs","p":["Game Boy Color"],"d":"Runny-Fun","u":"Ubi Soft","g":"Adventure, role-playing","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/Animorphs_(GBC_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4wny.jpg","s":"The best-received of the three Animorphs games, this RPG made much better use of the series' extended cast and universe. Battles play out similar to the Pokémon series, with turn-based battles and \"capturing\" morphs."},{"t":"Animorphs: Shattered Reality","p":["PlayStation"],"d":"SingleTrac","u":"Infogrames","g":"Action, platform","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/Animorphs:_Shattered_Reality","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4wo0.jpg","s":"The Animorphs are Jake, Rachel, Marco and Cassie, a group of children with the power to morph into animals as they battle the evil Yeerks and keep the world safe, while also dealing with the trials and tribulations involved with school, friends and parents. The book series by author K.A. Applegate has more than 32 million copies in print and there is a popular TV show airing on Nickelodeon.\n\nIn the PlayStation game Animorphs - Shattered Reality, the characters find themselves in a time warp. You must help them gather the shards of the Time Matrix Crystal and restore the timeline back to normal. You can play as any of the Animorphs as you battle The Yeerks and Visser 3."},{"t":"Aqua Aqua","p":["PlayStation 2"],"d":"Zed Two","u":"Imagineer, SCi Games, The 3DO Company","g":"Puzzle","r":"November 2, 2000","l":"https://en.wikipedia.org/wiki/Aqua_Aqua","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/d3wfysu7dyowz5djfrma.jpg","s":"Aqua Aqua (アクアアクア?), known in Europe as Aqua Aqua: Wetrix 2, is a puzzle video game for the PlayStation 2 and is the sequel to game Wetrix. It offers fewer features than Wetrix, but it features improved graphics and a new story mode. The aim of the story mode is to travel through four eras and survive attacks from monsters from each one. To survive the attacks simply get enough points to power up the shield. There is also an unlockable world if the player gets enough points. The game also offers a two player vs mode and a single player puzzle mode.\n\nThe title was a launch game for the PlayStation 2 release in Europe."},{"t":"Aqua GT","p":["Dreamcast"],"d":"East Point Software","u":"Take-Two Interactive","g":"Racing","r":"December 22, 2000","l":"https://en.wikipedia.org/wiki/Aqua_GT","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yes.jpg","s":"Aqua GT is powerboat racing game. It features three modes: Championship, Arcade and Two-player.\n\nChampionship mode is the main single player game, where you advance through the Bronze, Silver and Gold Championships. In the Arcade gameplay mode you have to beat the clock. In two-player split screen mode you go head to head against another player.\n\nThere are 5 boats to choose from, and you can unlock another 15 while progressing through the game. All boat vary in speed, acceleration and handling.\n\nThe tracks are set in canals of major cities, like London, Amsterdam and New York. Each track has a high or low tide, and you can race at day time or during the night time."},{"t":"Arcatera: The Dark Brotherhood","p":["Windows"],"r":"August 1","l":"https://en.wikipedia.org/wiki/Arcatera"},{"t":"Armada F/X Racers","p":["Game Boy Color"],"d":"Metropolis Digital","u":"Metro3D","g":"Racing","r":"August 25, 2000","l":"https://en.wikipedia.org/wiki/Armada_F/X_Racers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/krwhbrr9tskg4wydmghj.jpg","s":"Put adventure into overdrive, as you captain a futuristic vehicle, and race through six alien worlds to face off in a battle of wills, thrills, chills and spills. Take on opposing high-tech vehicles, obstacles and obstructions - all as you approach a final showdown against multiple-bosses in a good 'ol game of bumper cars, minus the bumpers."},{"t":"Armored Core 2","p":["PlayStation 2"],"d":"FromSoftware","u":"FromSoftware, Agetec, Ubi Soft, Crave Entertainment","g":"Third-person shooter","r":"August 3, 2000","l":"https://en.wikipedia.org/wiki/Armored_Core_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4dtx.jpg","s":"The genuine sequel to the original Armored Core. Thrown into the world of AC mechs, you must complete the objectives set for you by a range of different companies, each with a hefty pay packet attached. If the mission is completed, the money goes towards upgrades and repairs to your mech.\n\nThe collection of items to upgrade your mech is fully stocked with weapons, defense systems, rocket packs and guidance systems to increase accuracy and speed. Certain missions require a particular upgrade for the mission to be completed correctly, so spending the cash wisely is important to your career.\n\nOnce your mech is ready for battle, you can also take on a friend in arena mode, where one-on-one battles rage on for as long as you wish in huge outdoor areas."},{"t":"Army Men: Air Attack 2","p":["PlayStation"],"d":"The 3DO Company, Wide Games","u":"The 3DO Company","g":"Third-person shooter","r":"November 6, 2000","l":"https://en.wikipedia.org/wiki/Army_Men:_Air_Attack_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4epg.jpg","s":"Army Men: Air Attack 2, the sequel to the PlayStation's Army Men: Air Attack, has Captain Blade and his Alpha Wolf Squadron returning to action to continue the now infamous battles between the Green and Tan armies. The sequel features over twenty-five new missions with highly improved graphics, fully interactive environments, and gameplay reminiscent of Electronic Arts' Strike series.\n\nAir Attack 2 has the same gameplay found in the first Air Attack game. You can move in all directions in this plastic 3D world using the left analog stick, strafe using the L1 and R1 buttons, and deploy various artillery, as well as use your chopper's winch, using the controller's face buttons. The different military hardware at your disposal depends on the helicopter and copilot you select between missions. These choices also have an impact on other aspects of the gameplay, such as weapons accuracy, winch speed, chopper speed, and the amount of abuse your craft can handle. These features offer nothing new in the way of gameplay, but their tight and responsive control more than make up for that."},{"t":"Army Men: Air Tactics","p":["Windows"],"d":"The 3DO Company","u":"The 3DO Company","g":"Real-time tactics","r":"March 8, 2000","l":"https://en.wikipedia.org/wiki/Army_Men:_Air_Tactics","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1yy7.jpg","s":"Take to the skies with this new addition to the Army Men series. This time you must take control of the latest air attack machines in the world of war, and bash the plastic out of the Tan forces before they do it to you!! Fly through the bathroom, clash in the sandbox or destroy the flower garden, the choice is yours. Plus four new ways to clash with your pals."},{"t":"Army Men: Sarge's Heroes 2","p":["Nintendo 64","PlayStation","Game Boy Color"],"d":"The 3DO Company","u":"The 3DO Company","g":"Third-person shooter","r":"September 27, 2000","l":"https://en.wikipedia.org/wiki/Army_Men:_Sarge's_Heroes_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tak.jpg","s":"Sarge's Heroes 2 starts where Sarge's Heroes left off. It is announced that the capture of Field Marshal Tannenberg will end the war. Since General Plastro has disappeared, it is suggested that he has become a victim of plastrification and been trapped in the real world. The game introduces Bridgette Bleu, a spy for the Blue Nation. She has developed a serum that reverses plastrification. Your job as Sarge and sometimes Vikki is to destroy the serum, eliminate Tan soldiers, and capture Plastro and Tannenburg."},{"t":"Army Men: World War","p":["PlayStation","Windows"],"d":"The 3DO Company","u":"The 3DO Company","g":"Third-person shooter, real-time tactics","r":"April 3, 2000","l":"https://en.wikipedia.org/wiki/Army_Men:_World_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6svt.jpg","s":"Your mission is to lead the Green Army in a vicious battle against the Tan nemesis. Carefully guide your troops through a deadly barrage of enemy fire in over 15 World War II themed missions. Only the best military minds will prevail in this blazing battle of ground-based infantry. Many weapons from the era are at your disposal; call in strategic air strikes, a swarm of paratroopers, or quietly shoot the enemy from a distance with your sniper rifle. Never before has a plastic war reached this size and scale. Dive into the trenches!"},{"t":"Army Men: World War - Land, Sea, Air","p":["PlayStation"],"d":"The 3DO Company","u":"The 3DO Company","g":"Third-person shooter","r":"September 20, 2000","l":"https://en.wikipedia.org/wiki/Army_Men:_World_War_-_Land,_Sea,_Air"},{"t":"Arthur's Knights","p":["Windows"],"d":"Cryo Interactive","u":"Cryo Interactive, Wanadoo Edition, DreamCatcher Interactive","g":"Role-playing, adventure","r":"November 28, 2000","l":"https://en.wikipedia.org/wiki/Arthur's_Knights"},{"t":"Arthur's Preschool","p":["Windows"],"d":"Human Code","u":"Mattel Interactive","g":"Educational","l":"https://en.wikipedia.org/wiki/Arthur's_Preschool"},{"t":"ATV: Quad Power Racing","p":["PlayStation"],"d":"Climax Development, Tantalus Interactive","u":"Acclaim Entertainment","g":"Racing","r":"August 29, 2000","l":"https://en.wikipedia.org/wiki/ATV:_Quad_Power_Racing"},{"t":"Austin Powers: Oh, Behave! and Welcome to My Underground Lair!","p":["Game Boy Color"],"d":"Tarantula Studios","u":"Rockstar Games","g":"Action","r":"September 18, 2000","l":"https://en.wikipedia.org/wiki/Austin_Powers:_Oh,_Behave!_and_Welcome_to_My_Underground_Lair!"},{"t":"Avalon Hill's Squad Leader","p":["Windows"],"d":"Random Games","u":"Hasbro Interactive","g":"Strategy","r":"October 24, 2000","l":"https://en.wikipedia.org/wiki/Avalon_Hill's_Squad_Leader","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tdu.jpg","s":"Squad based WW2 combat adapted from the Avalon Hill board game."},{"t":"B-17 Flying Fortress: The Mighty 8th","p":["Windows"],"d":"Wayward Design","u":"Hasbro Interactive","g":"Combat flight simulator","r":"December 15, 2000","l":"https://en.wikipedia.org/wiki/B-17_Flying_Fortress:_The_Mighty_8th","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1yq6.jpg","s":"With Twenty five scenarios in which you must manage your crew’s strengths and weaknesses, test your pilot and leadership skills. This is your team, they are under your command, and it is your job as a cap-tain to complete the mission and take them home in one piece.\n\nSee what it was like to be part of a 10-man crew on dangerous bombing missions over occupied Europe. In addition, you are able to switch sides and fight against “The Mighty Eighth” taking the role of a German Luftwaffe pilot and find out first hand why the B-17 bomber codename was the “Flying Fortress”."},{"t":"Backyard Baseball 2001","p":["Windows","macOS"],"d":"Humongous Entertainment","u":"Humongous Entertainment","g":"Sports video game","r":"June 6, 2000","l":"https://en.wikipedia.org/wiki/Backyard_Baseball_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8az1.jpg","s":"Backyard Baseball 2001 is a Baseball Sim game, developed and published by Humongous Entertainment, which was released in 2000. This version of Backyard Baseball is notable because it is the first Backyard Baseball to incorporate Major League baseball players."},{"t":"Backyard Soccer MLS Edition","p":["macOS","Windows"],"d":"Humongous Entertainment","u":"Infogrames","g":"Sports","r":"October 3, 2000","l":"https://en.wikipedia.org/wiki/Backyard_Soccer_MLS_Edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/wnvmy10rnrmpa7nzpiok.jpg","s":"Backyard Soccer MLS Edition gives you the chance to kick the ball around with America's professional soccer stars from the MLS and star women players from the US Olympic team.\n\nPlayer's create a junior avatar of themselves and draft a team from other backyard kids and kid versions of 15 famous American soccer players then deck themselves out in their favorite uniforms and hit the field. Standard sports simulation game types are available including exhibition games and season play but the emphasis is on fun and accessibility for all ages."},{"t":"Bad Milk","p":["Windows","macOS"],"d":"Dreaming Media","g":"Puzzle","r":"October 12, 2000","l":"https://en.wikipedia.org/wiki/Bad_Milk","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5y79.jpg","s":"Bad Milk is a puzzle video game developed by New York developers Dreaming Media. The game begins with a first person full motion video, in which the player drinks spoiled milk and collapses onto the table. This launches a puzzle game in which the player must complete a series of minigames to obtain clues to \"escape\" their situation. The player is spoken to in various phone calls by an unseen third party and given hints to complete the puzzles. Clues are hidden in FMV clips including a \"dismembered bald head, a disembodied voice, a drowning man, and chronic smokers\", and often use reversed audio."},{"t":"Baldur's Gate II: Shadows of Amn","p":["Windows"],"u":"Interplay Entertainment","r":"September 21, 2000"},{"t":"Bang! Gunship Elite","p":["Windows","Dreamcast"],"d":"RayLand","u":"Red Storm Entertainment","g":"Space combat simulator","r":"July 19, 2000","l":"https://en.wikipedia.org/wiki/Bang!_Gunship_Elite","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ei6.jpg","s":"A local multiplayer game for 2-4 players.\nOnly the fastest guns and the fastest on their feet can win!"},{"t":"Banjo-Tooie","p":["Nintendo 64"],"u":"Nintendo","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/Banjo-Tooie"},{"t":"Barbie Fashion Pack Games","p":["Game Boy Color"],"d":"Pulsar Interactive","g":"Puzzle","r":"September 2000","l":"https://en.wikipedia.org/wiki/Barbie_Fashion_Pack_Games"},{"t":"Barbie: Magic Genie Adventure","p":["Game Boy Color"],"d":"Vicarious Visions","u":"Mattel Interactive","g":"Action-adventure","r":"November 11, 2000","l":"https://en.wikipedia.org/wiki/Barbie:_Magic_Genie_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6t6u.jpg","s":"Barbie: Magic Genie Adventure is an Action game, developed by Vicarious Visions and published by Mattel, which was released in 2000."},{"t":"Bass Rush: ECOGEAR PowerWorm Championship","p":["Dreamcast","Nintendo 64"],"d":"Visco Corporation","u":"Visco Corporation","g":"Fishing","r":"April 28, 2000","l":"https://en.wikipedia.org/wiki/Bass_Rush:_ECOGEAR_PowerWorm_Championship","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6w26.jpg","s":"Bass Rush: Ecogear PowerWorm Championship is a fishing simulation game for the Nintendo 64. It was released only in Japan in 2000."},{"t":"Batman Beyond: Return of the Joker","p":["PlayStation","Game Boy Color","Nintendo 64"],"r":"November 20"},{"t":"Battle Isle: The Andosia War","p":["Windows"],"d":"Cauldron","u":"Blue Byte","g":"Turn-based strategy","r":"November 24, 2000","l":"https://en.wikipedia.org/wiki/Battle_Isle:_The_Andosia_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x91.jpg","s":"“Our troops were swept away, General, and then the sect stopped its advance right before the gates to Hallwa. We have an ultimatum from the leader of the sect. She is demanding a kind of duel, sir, and will accept only you as her opponent.”\n\nThe year is 345 N.A. on the planet Chromos, a civilization that once boasted a flourishing society ruled by the Council of the Wise. Power struggles, corruption, war – that is the reality on Chromos now and, with the Andosia War, the Battle Isle saga continues with new features to the series by bridging the gap between turn based and real time combat."},{"t":"Battleship: Surface Thunder","p":["Windows"],"d":"Meyer/Glass Interactive","u":"Hasbro Interactive","g":"Action game","r":"September 12, 2000","l":"https://en.wikipedia.org/wiki/Battleship:_Surface_Thunder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pj2.jpg","s":"Battleship: Surface Thunder is an updated representation of the classic board game."},{"t":"BattleSphere","p":["Atari Jaguar"],"r":"February 29","l":"https://en.wikipedia.org/wiki/BattleSphere"},{"t":"BCV: Battle Construction Vehicles","p":["PlayStation 2"],"d":"Artdink","u":"Artdink, Midas Interactive Entertainment","g":"Fighting","r":"June 1, 2000","l":"https://en.wikipedia.org/wiki/BCV:_Battle_Construction_Vehicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co53mi.jpg","s":"BCV: Battle Construction Vehicles is a fighting game between present-day mechs: construction vehicles.\n\nPlayers choose between 15 drivers and 14 bulldozers, steamrollers, cranes and forklifts, to name a few, and the goal is to defend your father's construction business. The player can fully customize the vehicles parts, attack moves and appearance, which adds to the replay value of the story mode, consisting of 16 interactive stages, aside from the 2-player mode. Most of the attacks consist or ramming other vehicles or utilizing the mechanical parts that do damage upon impact. The story is furthered through anime-like cut-scenes."},{"t":"Beach Head 2000","p":["Windows","macOS"],"d":"Digital Fusion, Inc.","u":"WizardWorks","g":"First-person shooter, shooting gallery","r":"June 13, 2000","l":"https://en.wikipedia.org/wiki/Beach_Head_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobe73.jpg","s":"A first person shooter where you defend a beach from an oncoming invasion with one gun emplacement."},{"t":"Beach Volleyball","p":["Game Boy Color","PlayStation"],"d":"Carapace Game Development, Spark Creative","u":"Infogrames/Canal+ Multimedia, Infogrames, Mindscape","g":"Sports","r":"October 27, 2000","l":"https://en.wikipedia.org/wiki/Beach_Volleyball_(video_game)"},{"t":"Beatmania","p":["PlayStation"],"d":"Konami","u":"Konami","g":"Music game","r":"June 2000","l":"https://en.wikipedia.org/wiki/Beatmania_(European_video_game)"},{"t":"Beatmania IIDX 3rd Style","p":["Arcade","PlayStation 2"],"d":"Bemani","u":"Konami","g":"Music","r":"February 25, 2000","l":"https://en.wikipedia.org/wiki/Beatmania_IIDX_3rd_Style","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co964h.jpg","s":"The 3rd title in the beatmania IIDX series. Features the first of several Dance Express High Speed licenses."},{"t":"Beatmania III","p":["Arcade"],"d":"Konami","u":"Konami","g":"D.J.","r":"March 8, 2000","l":"https://en.wikipedia.org/wiki/Beatmania_III"},{"t":"Beetle Crazy Cup","p":["Windows"],"d":"Xpiral","u":"Infogrames","g":"Racing","r":"February 11, 2000","l":"https://en.wikipedia.org/wiki/Beetle_Crazy_Cup","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ivjwud4phapt6reagqez.jpg","s":"Choose your favorite from more than 50 incredibly detailed vehicles and race to become champion in each of 5 maddening events. Experience the thrill of breakneck SPEED as you race against the competition in your powerful, souped-up VW. Defy the laws of gravity by activating your nitro-boosters for a spectacular, high-flying JUMP. Drive enormous wheels and massive engines on a course littered with cars for your MONSTER vehicle to smash, bash and crash. You can almost taste the dirt in your mouth as you skid around the stock car CROSS challenge. Enjoy the sun and sand while racing your BUGGY on the beach, but watch out for that surf and don't get burned!"},{"t":"Bible Black","p":[],"l":"https://en.wikipedia.org/wiki/Bible_Black"},{"t":"Big Buck Hunter","p":["Arcade","Windows"],"d":"Play Mechanix","u":"Incredible Technologies, Raw Thrills, Crave Entertainment, GameMill Entertainment","g":"Shooter, Arcade","r":"December 2000","l":"https://en.wikipedia.org/wiki/Big_Buck_Hunter","s":"Released in December 2000."},{"t":"Bionic Commando: Elite Forces","p":["Game Boy Color"],"d":"Nintendo Software Technology","u":"Nintendo","g":"Platform game, Metroidvania","r":"January 24, 2000","l":"https://en.wikipedia.org/wiki/Bionic_Commando:_Elite_Forces","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2na3.jpg","s":"You are the ultimate weapon. You are the perfect synthesis of human and machine - a Bionic Commando.Your latest mission - to rescue a fellow commando, Commando Joe - will take you deep into the heart of enemy territory. Use your Bionic Claw to grapple and swing through more than 20 levels of forest, deserts, mountains and futuristic cities Blast through dozens of unique with your Assault Rifle, Rocket Launcher and Flame Thrower as you seek to destroy the overlord Arturus, and save your homeland of Karinia from utter destruction."},{"t":"Blade","p":["Game Boy Color","PlayStation"],"d":"HammerHead, HAL Corporation, Avit Inc.","u":"Activision","g":"Action","r":"November 21, 2000","l":"https://en.wikipedia.org/wiki/Blade_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9iqv.jpg","s":"Blade is an action game based on the 1998 film Blade. It was developed by HammerHead for the PlayStation in 2000, and by HAL Laboratory and Avit Inc. for the Game Boy Color. The game was published by Activision and serves as a prequel to the movie, following the adventure of Blade with help of his mentor and friend Abraham Whistler. Reviews were mixed, with criticism of the graphics, camera, controls, and voice acting."},{"t":"Blair Witch Volume I: Rustin Parr","p":["Windows"],"r":"October 4"},{"t":"Blair Witch Volume II: The Legend of Coffin Rock","p":["Windows"],"d":"Human Head Studios","u":"Gathering of Developers, Take-Two Interactive","g":"Survival horror","r":"October 25, 2000","l":"https://en.wikipedia.org/wiki/Blair_Witch_Volume_II:_The_Legend_of_Coffin_Rock"},{"t":"Blair Witch Volume III: The Elly Kedward Tale","p":["Windows"],"d":"Ritual Entertainment","u":"Gathering of Developers, Take-Two Interactive","g":"Survival horror","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/Blair_Witch_Volume_III:_The_Elly_Kedward_Tale"},{"t":"Blaster Master: Blasting Again","p":["PlayStation"],"d":"Art System","u":"Sunsoft, Crave Entertainment","g":"Action-adventure","r":"July 13, 2000","l":"https://en.wikipedia.org/wiki/Blaster_Master:_Blasting_Again","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9b58.jpg","s":"Blaster Master: Blasting Again (known as Blaster Master in Japan) is a 2000 action-adventure video game developed by Art System and published by Sunsoft in Japan and Europe and Crave Entertainment in North America for the PlayStation. The fifth title in the Blaster Master series, it was released in Japan in July 2000, Europe in September 2000, and North America in November 2001.\n\nBlaster Master: Blasting Again is a third-person 3D platformer in which the player takes control of the high-tech, all-terrain combat vehicle SOPHIA J-7. The player navigates through several areas of caverns to uncover and ultimately stop the treacherous plans of a mysterious alien race of Lightning Beings. On some occasions the player's character must exit SOPHIA and go solo through alien complexes. As the game progresses, the player will earn upgrades for SOPHIA, and be able to salvage weapon upgrades for the pilot. The player views cut-scenes that convey the key elements in the story. The character will fight a boss at the end of each stage."},{"t":"Blaster Master: Enemy Below","p":["Game Boy Color"],"d":"Outback Pty. Co., Sunsoft Games","u":"Sunsoft","g":"Run and gun, Metroidvania","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/Blaster_Master:_Enemy_Below","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ndw.jpg","s":"Jason, brave hero of yesteryear, is roused from retirement by the news that mutant lifeeorms, thought to have been long since destroyed, are once again on the move, hollowing out subterranean niches in the image of their old haunts. The decision to reactivate Sophia seems to Jason nothing more than an inevitability. Back into the cold once more...\n\n- Eight areas to explore, to find the keys and kill the sub human bosses\n- Use the tank’s suction system to drive up walls and along ceilings\n- Drive Sophia or go it alone with Jason."},{"t":"Blobby Volley","p":["Windows"],"g":"Sport","l":"https://en.wikipedia.org/wiki/Blobby_Volley","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u2y.jpg","s":"A volleyball mini-game where 2 blobs have to win by having the ball touch the ground on opponent's side."},{"t":"Blood: The Last Vampire","p":[],"l":"https://en.wikipedia.org/wiki/Blood:_The_Last_Vampire"},{"t":"Bloody Roar 3","p":["Arcade"],"d":"Eighting","u":"Hudson Soft, Namco, Activision, Virgin Interactive","g":"Fighting","r":"December 2000","l":"https://en.wikipedia.org/wiki/Bloody_Roar_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7z9w.jpg","s":"Bloody Roar 3 pits 12 outlandish combatants against each other in one of the most ambitious 3D fighting games to grace the PlayStation 2. Returning from Hudson's widely acclaimed PS1 titles are Stun, Long and Jenny, each of who brings a unique fighting skill to the arena. During each bout, players build an energy bar based on the number of successful kicks and punches they land on their opponent. As the bar fills, players can then morph their combatant into terrifying manimals from beasts such as lions and tigers to moles. The morph, in turn, unlocks a secondary control system specifically designed with each creature's combat moves and appearance in mind. In effect, this offers players two distinct combat types within one game."},{"t":"Blue Submarine No. 6","p":[],"l":"https://en.wikipedia.org/wiki/Blue_Submarine_No._6"},{"t":"Blues Brothers 2000","p":["Nintendo 64"],"r":"November 16","l":"https://en.wikipedia.org/wiki/Blues_Brothers_2000_(video_game)"},{"t":"Boku no Natsuyasumi","p":["PlayStation"],"d":"Millennium Kitchen","u":"Sony Computer Entertainment","g":"Adventure, simulation","r":"June 22, 2000","l":"https://en.wikipedia.org/wiki/Boku_no_Natsuyasumi","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8igb.jpg","s":"The game revolves around Boku, a 9 year old boy sent to his aunt and uncle in Japan's wooded countryside and the daily adventures he encounters there. Boku is there because his Mother is in her final month of pregnancy. The player controls him for the 31 days of August 1975 (In Japan, a Summer Vacation, called natsuyasumi last for one month). You explore the game's area and can catch bugs and pit them against each other, collect bottle caps, fly a kite, or just relax."},{"t":"Bomberman 64: The Second Attack","p":["Nintendo 64"],"r":"May 28"},{"t":"Bomberman Land","p":["PlayStation"],"d":"Hudson Soft","u":"Hudson Soft","g":"Minigames","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Bomberman_Land","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9d7d.jpg","s":"A spin-off of the Bomberman series, allowing players to navigate an amusement park and play numerous mini-games."},{"t":"Bomberman Max","p":["Game Boy Color"],"r":"May 14","l":"https://en.wikipedia.org/wiki/Bomberman_Max"},{"t":"Breath of Fire IV","p":["PlayStation"],"d":"Capcom Development Studio 3","u":"Capcom, SourceNext","g":"Role-playing","r":"April 27, 2000","l":"https://en.wikipedia.org/wiki/Breath_of_Fire_IV","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6opw.jpg","s":"Breath of Fire IV is a single-player game that continues the story with these \"dragon people,\" who gave their lives to eradicate the evil goddess and restore peace in their world. This time around, battle has broken out between two powerful continents, and the fair Princess Elena has disappeared during a tour of the war-torn region. The princess's sister, Nina, who reigns o'er the Windia Kingdom, vows to retrieve her missing sibling. She meets Ryu along the way, who joins the epic quest"},{"t":"Brunswick Circuit Pro Bowling 2","p":["PlayStation"],"d":"Adrenalin Entertainment","u":"THQ","g":"Ten pin bowling","r":"February 10, 2000","l":"https://en.wikipedia.org/wiki/Brunswick_Circuit_Pro_Bowling_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nshexgdzyxz5d4xyvc36.jpg","s":"The sequel to Brunswick Circuit Pro Bowling, released exclusively for the Playstation."},{"t":"Buffy the Vampire Slayer","p":["Game Boy Color"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Buffy_the_Vampire_Slayer_(2000_video_game)"},{"t":"Bugs Bunny & Taz: Time Busters","p":["Windows","PlayStation"],"d":"Artificial Mind and Movement","u":"Infogrames","g":"Platform","r":"September 2000","l":"https://en.wikipedia.org/wiki/Bugs_Bunny_&_Taz:_Time_Busters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7k5e.jpg","s":"Daffy Duck has somehow managing to break Granny's time regulator, causing himself and the Time Gem that acts as the heart of the regulator to be pitched back into the shrouded annals of history. Well, if there are two people you know to call when it comes to times of crisis they would be Bugs Bunny and ... Taz? Well, regardless of the intelligence of the decision, Bugs and Taz will have to work together on this mission, traveling through four different eras in a quest to find Daffy, recover the Time Gem and set things back to the way they ought to be.\n\nTake control of the two famous Warner Bros. characters in Bugs Bunny & Taz: Time Busters for the PlayStation. You will alternate between the wise-cracking rabbit and the Tasmanian eating machine in an attempt to rescue the Time Crystal and Daffy. To do so, they'll have to use the Time Regulator themselves, blasting back through four different eras to complete their quest. These time periods are The Aztec Era, The Viking Era, The Arabian Era and Transylvanian Era.\n\nEach character has his own set of moves, from Bugs' quickness to Taz's spinning fury. You can play each of the characters at any point, calling your friend to your location and switching between them, occasionally using them at nearly the same time to get past a given obstacle. If you don't want to play the game alone, you can even bring in a second friend to play the other character."},{"t":"Bugs Bunny in Crazy Castle 4","p":["Game Boy Color"],"d":"Kemco","u":"Kemco","g":"Platform","r":"April 21, 2000","l":"https://en.wikipedia.org/wiki/Bugs_Bunny_in_Crazy_Castle_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3b6n.jpg","s":"Bugs Bunny returns in BUGS BUNNYS CRAZY CASTLE 4 for Game Boy Color! Thinking he has found the Carrot Castle, Bugs has once again entered the Crazy Castle. You must help him escape in this single-player action or puzzle game. This time, more than 60 rooms await Bugs, and he'll have to use all of his wits and skills to escape with his \"hare\" intact. Once again, the Crazy Castle is loaded with traps and hazards that will cut your carrot-collecting career short so make sure you don't get reacquainted with them the hard way. As CRAZY CASTLE fans are probably used to, several Warner Bros. cartoon characters are here to keep Bugs on his toes. You'll have to fight off Daffy Duck, Yosemite Sam, Foghorn Leghorn, Pepe Le Pew, Tweety, and the Tazmanian Devil with one of a variety of weapons, or make tracks to the nearest safe spot. A password save will chart your progress so that you don't have to start from scratch each time you play."},{"t":"Bust-a-Move Millennium","p":["Game Boy Color"],"r":"October 27","l":"https://en.wikipedia.org/wiki/Bust-a-Move_Millennium"},{"t":"Buzz Lightyear of Star Command","p":["PlayStation","Dreamcast","Game Boy Color","Windows"],"d":"Traveller's Tales","u":"Activision","g":"Platform, shooter","r":"October 4, 2000","l":"https://en.wikipedia.org/wiki/Buzz_Lightyear_of_Star_Command_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3zbj.jpg","s":"Buzz Lightyear of Star Command is a Windows PC game created by Traveller's Tales with Disney Interactive and PIXAR in 2000. The game consists of multiple planets, each with a villain on it. In each level, the players race the villain to their getaway destination. Then, they engage in a one-on-one battle with the villain, which usually requires destroying an energy shield surrounding the villain."},{"t":"Bōken Jidai Katsugeki Goemon","p":["PlayStation 2"],"d":"Konami Computer Entertainment Kobe","u":"Konami","g":"Action, role-playing","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/B%C5%8Dken_Jidai_Katsugeki_Goemon"},{"t":"Cabela's GrandSlam Hunting: North American 29","p":[],"l":"https://en.wikipedia.org/wiki/Cabela's_GrandSlam_Hunting:_North_American_29"},{"t":"Caesars Palace 2000","p":["PlayStation","Dreamcast","Windows"],"d":"Runecraft","u":"Interplay Entertainment","g":"Gambling simulation","r":"June 16, 2000","l":"https://en.wikipedia.org/wiki/Caesars_Palace_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uqy.jpg","s":"Now you can get all the action of Las Vegas without the smoky casinos in CAESARS PALACE 2000: Millennium Gold Edition. There are a variety of games to play including Blackjack, Mini-Baccarat, Paigow Poker, Spanish 21, Red Dog, Casino War, Roulette, Craps, Video Poker, Video Keno, Poker Challenge, and five different slot machines. All games are played according to the Vegas rules, giving you the most realistic experience you can get this side of Nevada. Things are so authentic in this virtual casino that the slot machines even have the faces of their real-world counterparts. There is also an intuitive interface that allows you to utilize even the most complex betting strategies with ease. So get the Vegas experience without draining your savings account with CAESARS PALACE 2000: Millennium Gold Edition."},{"t":"Call to Power II","p":["Windows"],"d":"Activision","u":"Activision","g":"Turn-based strategy","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/Call_to_Power_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zos.jpg","s":"Prepare to accept history's greatest challenge - build the world's most powerful empire over a span of 6,300 years, reaching from primitive history to the future realms of science-fiction. Take your place beside history's greatest leaders as you master the intricate strategies of governing, warfare, diplomacy, trade and science. Sow the seeds of an empire as you cultivate a tribe of settlers in 4,000 BC. Hear the cheers of approval as you lead your flourishing society into the future of 2,300 AD."},{"t":"Canary","p":[],"l":"https://en.wikipedia.org/wiki/Canary_(video_game)"},{"t":"Cannon Spike","p":["Arcade","Dreamcast"],"d":"Psikyo","u":"Capcom","g":"Multi-directional shooter","r":"November 15, 2000","l":"https://en.wikipedia.org/wiki/Cannon_Spike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ix8.jpg","s":"Cannon Spike (released in Japan as Gunspike) is a top-down run-and-gun shooting game developed by Psikyo & published by Capcom in the year 2000. Players select from a roster of classic Capcom characters, then play through a series of short stages & boss battles in a randomly selected order."},{"t":"Canvas: Sepia-iro no Motif","p":[],"l":"https://en.wikipedia.org/wiki/Canvas:_Sepia-iro_no_Motif"},{"t":"Capcom vs. SNK: Millennium Fight 2000","p":["Dreamcast"],"r":"November 6"},{"t":"Cardcaptor Sakura: Tomoyo no Video Daisakusen","p":["Dreamcast"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Cardcaptor_Sakura:_Tomoyo_no_Video_Daisakusen","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tmz.jpg","s":"Step into Tomoyo's shoes and film Sakura in this anime adaption for Dreamcast."},{"t":"Carl Lewis Athletics 2000","p":["Game Boy Color"],"d":"Planet Interactive Development","u":"Ubi Soft","g":"Sports","r":"September 2000","l":"https://en.wikipedia.org/wiki/Carl_Lewis_Athletics_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9azo.jpg","s":"A track and field game for the Game Boy Color based around the Decathlon. It was only released in Europe."},{"t":"Carmageddon TDR 2000","p":["Windows"],"d":"Torus Games","u":"Sales Curve Interactive, Xicat Interactive","g":"Vehicular combat, racing","r":"September 8, 2000","l":"https://en.wikipedia.org/wiki/Carmageddon_TDR_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zoo.jpg","s":"Carmageddon TDR 2000 has been designed from the ground up for Internet playing. Unique arenas and play modes, packed full of highly charged AI computer players, will add a whole new dimension for serious gamers.\n\nThe focus of the game is centred around fast action gameplay in a completely new 'immersive' environment- far more advanced than in any previous driving game on the PC.\n\nWith loads of new features such as aggressive characters, real-time reflections and incredible graphics, Carmageddon TDR 2000 will kick you harder than ever before giving you the option to do well whatever you want."},{"t":"Carrier","p":["Dreamcast"],"d":"Jaleco","u":"Jaleco, Xicat Interactive","g":"Survival horror","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/Carrier_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40ek.jpg","s":"In the 21st Century terrorism reigns supreme. You are part of an elite unit chosen to isolate and destroy ARK before it reaches land. You never know what's lurking in the murky water or around the next corner. Meanwhile, ARK is gaining power after attacking itself to the nuclear core of the Heimdal. Sheer wit and brute force are all that can save you.\n\nTo control Earth, the Southern Cross bombs the Heimdal, setting free ARK -- a prehistoric organism. ARK implants itself in humans making them hideous, monstrous drones that carry ARK seeds and infect others determined to eliminate ALL of humanity. ARK breeds, mutates, and insanely lusts for the end of human life. Even if it looks human it may be an ARK drone."},{"t":"CART Fury Championship Racing","p":["Arcade"],"d":"Midway","u":"Midway","g":"Racing","l":"https://en.wikipedia.org/wiki/CART_Fury_Championship_Racing"},{"t":"Catechumen","p":["Windows"],"d":"N'Lightning Software Development","u":"N'Lightning Software Development","g":"First-person shooter","r":"October 1, 2000","l":"https://en.wikipedia.org/wiki/Catechumen_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2po4.jpg","s":"A Christian-themed first-person-shooter, you are a Christian-in-training in the Ancient Roman times. You are battling the hordes of demons sent by the devil to corrupt Roman souls. Most of your comrades have been locked away by the possessed Romans. Only you, armed with a holy sword that shoots word of God, can enlighten the possessed Centurions, banish the demons, save your fellow Christians, and defeat Satan himself..."},{"t":"Challenge ProMode Arena","p":["macOS","MS-DOS","Linux","Windows"],"d":"CPMA team, The Promode Team","g":"First-person shooter","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/Challenge_ProMode_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coabnt.jpg","s":"Challenge ProMode Arena is a competition-oriented gameplay overhaul mod for Quake III Arena."},{"t":"Championship Bass","p":["PlayStation","Windows"],"d":"EA Seattle, Engineering Animation","u":"EA Sports","g":"Fishing","r":"March 7, 2000","l":"https://en.wikipedia.org/wiki/Championship_Bass","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7qij.jpg","s":"Bass fishing reaches new level with Championship Bass! Artificial Intelligence creates the most realistic behavior in simulated bass ever. False strikes, swerves, return attacks, and short-strike lunges will keep you on the edge. Even if you do land a strike, watch these fish go for obstacles in order ot break your line! Multiple difficulty levels, plenty of tricks in your lure box, multiple game modes, multiple lakes, and more. Sit in a boat and go for the fish, or simulate a whole fishing trip. The choice is yours!"},{"t":"Championship Manager: Season 00/01","p":["Windows"],"d":"Sports Interactive","u":"Eidos Interactive","g":"Sports","r":"November 10, 2000","l":"https://en.wikipedia.org/wiki/Championship_Manager:_Season_00/01"},{"t":"Championship Motocross 2001 Featuring Ricky Carmichael","p":["Game Boy Color"],"d":"Tiertex Design Studios, Funcom Dublin","u":"THQ","g":"Sports, racing","r":"October 2000","l":"https://en.wikipedia.org/wiki/Championship_Motocross_2001_Featuring_Ricky_Carmichael","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaar6.jpg","s":"THQ's second installment in their motocross franchise."},{"t":"Championship Rally","p":["Atari Lynx"],"d":"Songbird Productions","u":"Songbird Productions","g":"Racing","r":"December 15, 2000","l":"https://en.wikipedia.org/wiki/Championship_Rally_(2000_video_game)"},{"t":"Championship Surfer","p":["Windows","Dreamcast","PlayStation"],"d":"Krome Studios","u":"Mattel Interactive, GAME Studios","g":"Sports","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/Championship_Surfer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40f5.jpg","s":"10 outrageous beaches, 5-to-30-foot breakers, and 8 world class surfers including Cory Lopex, Shane Beschen, and Rochelle Ballard."},{"t":"Chaos Break","p":["PlayStation"],"d":"Taito","u":"Taito, EON Digital Entertainment","g":"Survival horror, third-person shooter","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Chaos_Break","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coacqw.jpg","s":"Chaos Break is a third-person shooting game, with echoes of survival horror such as Resident Evil. Set in an abandoned biochemical laboratory on an isolated island, the two player characters, Mitsuki and Rick, are part of an investigatory and cleansing force sent to find out the cause of an 'anomalous thermal reaction'. This game is a spin-off, set in the same universe as the arcade game Chaos Heat."},{"t":"Charge 'n Blast","p":["Dreamcast"],"d":"CSK Research Institute, SIMS Co., Ltd.","u":"SIMS Co., Ltd., Xicat Interactive","g":"Shooter","r":"December 7, 2000","l":"https://en.wikipedia.org/wiki/Charge_'n_Blast","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40ev.jpg","s":"Charge 'N Blast is a shooting game where you play as one of three marines who have to rid the earth of alien scum. The gameplay is similar to Cabal, you move left and right dodging enemies while charging up you weapons to blast them away.\n\nThere are three different marines you can choose from, each with their own set of weapons. As usual there is the balanced character (Johnny Rock), a weaker but faster one (Pamela Hewitt) and a slower but stronger one (Nicholas Woods).\n\nYou can choose to play in one player mode, time attack or two player mode. The missions are broken up into small areas where you have to kill all enemies before moving on to the next area. Each mission ends with a boss character such as a giant insect or a Godzilla-like monster.\n\nUse the X, Y or B buttons to choose a weapon, press A to charge and shoot and aim with analog stick. There are different types of weapons that can be used on the different types of enemies. For example the single missiles for far away targets and torpedoes for underwater enemies.\n\nYou can fire your weapon continuously, but this doesn't do as much damage compared to a fully charged shot. Charging each shot means you have to aim a little more carefully, but you'll especially need this in the later levels. You can dodge enemies with the L and R buttons."},{"t":"Chase the Express","p":["PlayStation"],"d":"TYO Entertainment","u":"Sony Computer Entertainment, Activision","g":"Third-person shooter","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Chase_the_Express","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4o8y.jpg","s":"Covert Ops: Nuclear Dawn, otherwise known as Chase the Express, is a video game created by Sugar and Rockets for the PlayStation, and released in 2000. On March 16, 2000 Activision announced that they had acquired the North American publishing rights to Sony Computer Entertainment's Japanese action-adventure game, Chase The Express. The game was then renamed Covert Ops: Nuclear Dawn for the North American market."},{"t":"Chemical Existence","p":["Windows"],"d":"Red Genesis","g":"First-person shooter","r":"October 14, 2000","l":"https://en.wikipedia.org/wiki/Chemical_Existence","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9fml.jpg","s":"Chemical Existence puts you in the role of Reece Max whom simply is in the wrong place at the wrong time. He gets mixed up with fighting gangs, evil corporations and mutated creatures…"},{"t":"Chessmaster 8000","p":["Windows"],"d":"Mattel Interactive","u":"Mattel Interactive","g":"Computer chess","r":"November 14, 2000","l":"https://en.wikipedia.org/wiki/Chessmaster_8000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9rr6.jpg","s":"The grandmaster of PC chess is back and better than ever! The revamped chess AI plays at grandmaster level, even stronger than before. New chess sets with 16-bit art looks better than ever. Improved \"Natural Language Advice\" help you get into the game and gets kids interested in chess. Special chess lessons by Josh Waitzkin (chess grandmaster) and Bruce Pandolfini (chess author and teacher) are also included."},{"t":"Chicken Run","p":["Game Boy Color","Dreamcast","PlayStation","Windows"],"d":"Blitz Games","u":"Eidos Interactive, THQ","g":"Platform, stealth","r":"November 2, 2000","l":"https://en.wikipedia.org/wiki/Chicken_Run_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co99k9.jpg","s":"Re-live the hilarious action from the blockbuster film. Ginger is a chicken on a mission. She bravely leads the flock in a number of wild and wacky escape attempts from the barbed wire confines of Tweedy's farm. To do this, she enlists the help of Rocky, a smooth-talking American rooster and the cheeky, cockney rodents Nick and Fetcher. Will they make it to freedom before they end up as pies? Their fate is in your hands!\n\nHuge, detailed 3D immersive environments!\nCharacters, voices, and locations based on the film\nFluid gameplay featuring stealth, puzzle solving, and arcade elements\n4 playable characters including Ginger, Rocky, and their rodent accomplices Nick and Fetcher"},{"t":"Chicken Shoot","p":["Windows","macOS"],"d":"Toontraxx, Frontline Studios","u":"Zuxxez/TopWare Interactive, DSI Games, Zoo Digital Publishing","g":"Shooter","l":"https://en.wikipedia.org/wiki/Chicken_Shoot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9pwc.jpg","s":"Chicken Shoot is a shooting gallery game with adventure elements where you blow the chickens away. In each mission the player can collect a number of things and can receive many extra points for different actions. Climb behind the trigger and help our distressed farmer friend obliterate hordes of no good cluckers. This classic shooter uses a cartoonish feel, some great comic sound effects, and catchy original songs to fashion a world where hunting fowl is a blast. Great animation takes you through forests and villages, through deserts and mountains, winging winged adversaries and piling up points. As the missions progress in difficulty, you'll soon find yourself challenged to the limit of your Kentucky Fried skills! Colorful, fun, enticing, and addictive, this is one game that is sure to leave your sunny side up."},{"t":"Chris Kamara's Street Soccer","p":["PlayStation"],"d":"Pixel Storm","u":"Midas Interactive Entertainment","g":"Sports","r":"August 25, 2000","l":"https://en.wikipedia.org/wiki/Chris_Kamara's_Street_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/rajuymslmqpwwyivp2zb.jpg","s":"Chris Kamara's Street Soccer is a video game released for the PlayStation in 2000. It was developed by Italian company Pixel Storm and published by Midas Interactive Entertainment. The game is named after former footballer, manager and current pundit Chris Kamara, who appears on the game's cover. \n \nPlayers choose from 25 teams to compete in five-a-side street soccer. 20 are available from the start and 5 can be unlocked. The teams are cities from different countries, such as London, England and Paris, France. The game incorrectly lists Prague as from Norway rather than Czech Republic. Some of the teams consist of female players. \n \nThe game can be played in either Exhibition, Arcade, Time Attack, League, Cup and Penalty Shootout mode. The game allows up to 8 players to play via multi-tap."},{"t":"Chrono Cross","p":["PlayStation"],"r":"August 15","l":"https://en.wikipedia.org/wiki/Chrono_Cross"},{"t":"Close Combat: Invasion: Normandy","p":["Windows"],"d":"Atomic Games","u":"Mattel Interactive","g":"Computer wargame","r":"October 2000","l":"https://en.wikipedia.org/wiki/Close_Combat:_Invasion:_Normandy"},{"t":"Clue Chronicles: Fatal Illusion","p":["Windows"],"d":"EAI Interactive","u":"Hasbro Interactive","g":"Adventure","r":"January 31, 2000","l":"https://en.wikipedia.org/wiki/Clue_Chronicles:_Fatal_Illusion"},{"t":"Clusterball","p":["macOS","Windows"],"d":"Daydream Software","u":"Daydream Software, Strategy First","g":"Racing","r":"July 17, 2000","l":"https://en.wikipedia.org/wiki/Clusterball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/sawradqbgd7wcdkr8ovz.jpg","s":"What is Clusterball? It's a sport. Clusterball is an online sport, designed to invoke the same adrenaline rush as Quake and Unreal, but replacing the spatter and gore with pure gameplay. By combining the feel and gaming experience from ball, flight and racing games, Clusterball is totally unlike anything you?ve ever seen before."},{"t":"Coji-Coji","p":[],"l":"https://en.wikipedia.org/wiki/Coji-Coji"},{"t":"Colin McRae Rally 2.0","p":["PlayStation"],"u":"Codemasters","r":"July 7, 2000","l":"https://en.wikipedia.org/wiki/Colin_McRae_Rally_2.0"},{"t":"Colony Wars: Red Sun","p":["PlayStation"],"d":"Psygnosis","u":"Sony Computer Entertainment, Midway","g":"Space combat simulator","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/Colony_Wars:_Red_Sun","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23s6.jpg","s":"Red Sun is the third in Psygnosis' Star Wars inspired \"Colony Wars\" saga. This time around you follow the personal quest of Valdmar a miner who gets caught up in the wars between the League and the Navy after meeting the enigmatic \"General\" in a series of mysterious dreams."},{"t":"Combat Flight Simulator 2","p":["Windows"],"d":"Microsoft","u":"Microsoft","g":"Combat flight simulator","r":"October 10, 2000","l":"https://en.wikipedia.org/wiki/Combat_Flight_Simulator_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9mqy.jpg","s":"The sequel to Microsoft's first Combat Flight Simulator, the focus shifts to the Pacific theater, where carrier battles and island hopping dominate the strategy.\n\nFly for the Japanese Navy or the American Navy/Airforce in either single battles or branching campaigns. Controllable aircraft include the standard Zero, the P-38, Wildcat, Hellcat, Corsair, and George, each fighter representing different design philosophies from the most nimble Japanese planes to the powerhouse American designs. Escort bombers, strafe transports, and provide CAP for your carrier group. Learn how to successfully land on a carrier in strong winds."},{"t":"Combat Mission: Beyond Overlord","p":["Windows"],"u":"Battlefront.com","g":"Simulation, Strategy","r":"May 31, 2000","l":"https://store.steampowered.com/app/3843550","i":"images/steam-3843550.jpg","s":"The first in the award-winning series, Combat Mission: Beyond Overlord lets you command German or Allied forces from Normandy to Germany in WWII. Battle through towns, woods, and fields in deep, immersive, turn-based and real-time tactical combat."},{"t":"Command & Conquer: Red Alert 2","p":["Windows"],"r":"October 25"},{"t":"Confidential Mission","p":["Arcade"],"d":"Hitmaker","u":"Sega","g":"Shooter","l":"https://en.wikipedia.org/wiki/Confidential_Mission","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40f6.jpg","s":"Confidential Mission is a light-gun compatible shooting game most easily likened to Sega's Virtua Cop series. You play as either Howard Gibson or Jean Clifford, both super-agents a la James Bond, and you are taken through scenarios shooting enemies and attempting to avoid civilian casualties."},{"t":"Cool Boarders 2001","p":["PlayStation"],"d":"Idol Minds","u":"Sony Computer Entertainment","g":"Snowboarding","r":"October 24, 2000","l":"https://en.wikipedia.org/wiki/Cool_Boarders_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6q5z.jpg","s":"Cool Boarders 2001 features new board parks, champion snowboarders, and 20 diverse courses with various events like downhill and trick completion. Compete in the Vans Triple Crown of Snowboarding to unlock tracks and boards.\n\nCool Boarders 2001 is the only Cool Boarders title to be released exclusively in North America."},{"t":"Cool Boarders Pocket","p":["Neo Geo Pocket Color"],"d":"UEP Systems","u":"SNK","g":"Snowboarding","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/Cool_Boarders_Pocket","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xlr.jpg","s":"Cool Boarders Pocket, is a Snowboarding video game developed by UEP Systems and published by SNK Playmore for the Neo Geo Pocket Color.\n\nCool Boarders Pocket differs to other games in the Cool Boarders series. It features an isometric (overhead) view instead of a third-person perspective. The game features two play modes a free-ride mode where the player navigates an obstacle course with no restrictions until he/she reaches the goal, and a survival mode where the player snowboards through the obstacle course until they run out of health. The game allows the player to choose one of two characters; a female or male snowboarder."},{"t":"Cool Boarders: Code Alien","p":["PlayStation 2"],"d":"UEP Systems","u":"UEP Systems","g":"Snowboarding","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Cool_Boarders:_Code_Alien","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/txpoxyawugy24hg7xsj9.jpg","s":"Cool Boarders: Code Alien is the only Cool Boarders title to be released exclusively in Japan."},{"t":"Cool Cool Toon","p":["Dreamcast"],"d":"SNK","u":"SNK","g":"Rhythm","r":"August 10, 2000","l":"https://en.wikipedia.org/wiki/Cool_Cool_Toon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6aw9.jpg","s":"Cool Cool Toon (クルクルトゥーン?) is a rhythm-based music video game exclusive to the Dreamcast. It was developed and published by SNK and released in Japan only on August 10, 2000.The letters A, B, X and Y appear at the edge or in the middle of a large circle on screen. The player must use the analogue stick to move a marker to the letter and press the corresponding button on the controller at the right time. If the player misses too many letters, they will fail."},{"t":"Cossacks: European Wars","p":["Windows"],"d":"GSC Game World","u":"CDV Software Entertainment","g":"Real-time strategy","r":"November 28, 2000","l":"https://en.wikipedia.org/wiki/Cossacks:_European_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nll.jpg","s":"Cossacks: European Wars is a real-time strategy computer game for Windows made by the Ukrainian developer GSC Game World. It was released on April 24, 2001. The game has an isometric view and is set in the 17th and 18th centuries of Europe. It features sixteen playable nations each with its own architectural styles, technologies and units.\nPlayers must avoid famine and engage in army expansion, building construction and simple resource gathering. Mission scenarios range from conflicts such as Thirty Years' War to the War of the Austrian Succession, and the game is renowned for the seemingly unlimited number of units players may control. This ability set it apart from other games of the time such as Age of Empires and Empire Earth.\nCossacks is a game which allows the user to gain strategy skills and even pick up some relative history of that period by the inclusion of a comprehensive encyclopedia. This top selling title has won two awards and was positively favoured by a majority of reviewers."},{"t":"Counter-Strike","p":["Windows"],"u":"Sierra Entertainment","g":"Action","r":"November 9, 2000","l":"https://en.wikipedia.org/wiki/Counter-Strike_(video_game)","i":"images/steam-10.jpg","s":"Play the world's number 1 online action game. Engage in an incredibly realistic brand of terrorist warfare in this wildly popular team-based game. Ally with teammates to complete strategic missions. Take out enemy sites. Rescue hostages. Your role affects your team's success. Your team's success affects your role."},{"t":"Crash Bash","p":["PlayStation"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Crash_Bash"},{"t":"Crazy Taxi","p":["Dreamcast"],"u":"Sega","r":"January 24, 2000","l":"https://en.wikipedia.org/wiki/Crazy_Taxi_(video_game)"},{"t":"Cricket 2000","p":["PlayStation","Windows"],"d":"Krisalis Software","u":"EA Sports","g":"Sports","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/Cricket_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/uqpdcepvibwqegxfkspk.jpg"},{"t":"Crime Cities","p":["Windows"],"g":"Action, Simulation","r":"December 1","l":"https://en.wikipedia.org/wiki/Crime_Cities","i":"images/steam-1112570.jpg","s":"Revisit Crime Cities, a revolutionary cross between a shooter and a futuristic vehicle simulator, originally published in 2000. Immerse yourself in the dense atmosphere of a grim future, as you follow a complex plot and complete a variety of deadly, unpredictable missions."},{"t":"Crimson Skies","p":["Windows"],"d":"Zipper Interactive","u":"Microsoft Games, Tsunami Visual Technologies","g":"Action, arcade flight","r":"September 18, 2000","l":"https://en.wikipedia.org/wiki/Crimson_Skies_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22i8.jpg","s":"The series is set within an alternate history of the 1930s invented by Weisman and McCoy. Within this divergent timeline, the United States has collapsed, and air travel has become the most popular mode of transportation in North America; as a result, air pirates thrive in the world of Crimson Skies. In describing the concept of Crimson Skies, Jordan Weisman stated he wanted to \"take the idea of 16th century Caribbean piracy and translate into a 1930s American setting.\""},{"t":"Cro-Mag Rally","p":["macOS"],"d":"Pangea Software","u":"Aspyr","g":"Kart racing game","r":"October 2000","l":"https://en.wikipedia.org/wiki/Cro-Mag_Rally"},{"t":"Croc","p":["Game Boy Color"],"d":"Virtucraft, Argonaut Games","u":"THQ","g":"Platform","r":"June 6, 2000","l":"https://en.wikipedia.org/wiki/Croc_(2000_video_game)"},{"t":"Cue Club","p":["Windows"],"d":"Bulldog Interactive","u":"Bulldog Interactive","g":"Sports simulation","l":"https://en.wikipedia.org/wiki/Cue_Club","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ugd.jpg","s":"Cue Club is a sports simulation video game developed by British Games developer Bulldog Interactive and released for Microsoft Windows on 10 November 2000. It is a realistic interpretation of pool and snooker. The game was initially published by Midas Interactive and later by GSP (now known as Avanquest), but since 2012 it has been distributed exclusively by Bulldog through the official Cue Club website."},{"t":"Cultures","p":["Windows"],"d":"Funatics Software, Headup Games","u":"Phenomedia, Headup Games","g":"City-building game","r":"September 1, 2000","l":"https://en.wikipedia.org/wiki/Cultures_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23hl.jpg","s":"Before Christopher Columbus sailed the ocean blue in 1492, the Vikings set out on their own journey of discovery and possible looting and pillaging. Having accidentally stumbled upon the Americas, they began their remarkable adventure in a new and unfamiliar land. Welcome to Cultures, where you can actively shape the destiny of your people as they struggle to gain a foothold on unfamiliar shores. Success hinges on your ability to balance achieving your goals with the needs and desires of your clan. It is up to you to nurture and guide your people: determine their names, occupations, marital partners, and, eventually, the gender of their children. The happiness of your settlers is paramount to achieving your goals in this exploration and construction-focused RTS."},{"t":"Custom Robo V2","p":["Nintendo 64"],"d":"Noise","u":"Nintendo","g":"Action role-playing","r":"November 10, 2000","l":"https://en.wikipedia.org/wiki/Custom_Robo_V2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co509x.jpg","s":"Custom Robo V2 is the second game in the Custom Robo series. It is similar to the first, but it features tag teaming. The player travels an overworld, and participates in Custom Robo battles. The goal of the game is to win every battle of the storyline while collecting every Robo, battle part, and item."},{"t":"Cyber Groove","p":["Windows"],"d":"Front Fareast Industrial Corporation","g":"Dance","r":"January 2000","l":"https://en.wikipedia.org/wiki/Cyber_Groove"},{"t":"Daikatana","p":["Windows"],"g":"Action","r":"May 24","l":"https://en.wikipedia.org/wiki/Daikatana","i":"images/steam-242980.jpg","s":"In 2455 AD, Kage Mishima used the magical powers of Daikatana, the most powerful sword ever forged, to alter time and establish himself as supreme dictator. You are Hiro Miyamoto, one of the few people on earth who knows what happened."},{"t":"Dance Dance Revolution 4thMix","p":["Arcade"],"d":"Konami","u":"Konami","g":"Music, exercise","r":"August 24, 2000","l":"https://en.wikipedia.org/wiki/Dance_Dance_Revolution_4thMix","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u80.jpg","s":"Dance Dance Revolution 4thMix, or 4thMix, is the 4th game in the main Dance Dance Revolution series of music video games. It was released as an arcade game by Konami on August 24, 2000. Although only officially released in Japan, units exist worldwide. 4thMix features 136 songs, 49 of which are new to this mix. Twelve of the songs are initially hidden and must be unlocked by the arcade operator. 12 songs are unlockable in 4th Mix Plus, giving them 150 songs in total. In DDR 4th Mix, new songs that first appears in DDR 3rd Mix Plus, DDR 3rd Mix Korea and DDR Solo appears in this mix.\n\nThe home version of 4thMix was released in Japan on March 15, 2001, for the Sony PlayStation console. It contains 55 songs, including 3 from Dance Dance Revolution 3rdMix (which were not present in the home version of that version) and six hidden songs: one from 4thMix Plus and one as preview songs for the next arcade version, Dance Dance Revolution 5thMix. The game also features the 6-panel mode, branded as Solo Mode."},{"t":"Dance Dance Revolution Disney Mix","p":["Arcade","Game Boy Color","PlayStation"],"d":"Konami Computer Entertainment Tokyo","u":"Konami","g":"Music, exercise","r":"November 30, 2000","l":"https://en.wikipedia.org/wiki/Dance_Dance_Revolution_Disney_Mix","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49gg.jpg","s":"The revolution continues with Dance Dance Revolution Disney Mix. Featuring your favorite Disney characters and dance mixes of popular Disney tunes, this is the hottest dancing game this side of Magic Kingdom. Get ready to heat up the dance floor and put your skills to the test as you move to the groove. Let Mickey and his friends make your dreams come true as you become a star.\n\n- Dance to high-energy remixes of popular Disney tunes, including It's A Small World, Zip-A-Dee-Doo-Dah, and Mickey Mouse March.\n- Select from your favorite Disney characters, including Mickey Mouse, Donald Duck, Goofy and more!\n- Re-create the DDR experience with Konami's Dance Dance Revolution controller (sold seperately).\n- Special Work Out features let you have fun getting in shape - while tracking the calories you burn.\n- Multiple difficulty settings makes DDR Disney Mix easy to learn for all ages."},{"t":"Dancing Stage EuroMix","p":["Arcade"],"d":"Konami","u":"Konami","g":"Music, Exercise","r":"August 2000","l":"https://en.wikipedia.org/wiki/Dancing_Stage_EuroMix"},{"t":"Danger Girl","p":["PlayStation"],"d":"n-Space","u":"THQ","g":"Third-person shooter","r":"September 11, 2000","l":"https://en.wikipedia.org/wiki/Danger_Girl_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc3oo.jpg","s":"Danger Never Looked So Good!\n\n3rd person action-adventure has never been sexier with DANGER GIRL, the only videogame based on on the best-selling comic book series by J. Scott Campbell and Andy Hartnell.\n\nDare to take control of 3 beautiful yet leathal Danger Girls in an espionage-themed thrill-ride deemed to dangerous for any man to handle!\n\n* \"I love to unleash my bullwhip, sniper rifle, and grenades on hammer goons!\"\n* \"Check out our loading screens, featuring original artwork by our creators!\"\n* \"Help me use my high-tech spy gadgets including infra-red goggles, bomb decoders and more...\"\n\nCOLLECTORS ITEM!\nManual features exclusive character sketches, bios and artwork from the creators!"},{"t":"Daria's Inferno","p":["Windows","macOS"],"d":"Hypnotix","u":"Simon & Schuster Interactive","g":"Adventure, puzzle","l":"https://en.wikipedia.org/wiki/Daria's_Inferno","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5vg5.jpg","s":"Daria's Inferno is based on MTV's hit television series, Daria and the classic poem Dante's Inferno. Daria's Inferno is a 2d adventure game with simple point and click interface."},{"t":"Dark Cloud","p":["PlayStation 2"],"r":"December 14","l":"https://en.wikipedia.org/wiki/Dark_Cloud"},{"t":"Dark Reign 2","p":["Windows"],"r":"July 3","l":"https://en.wikipedia.org/wiki/Dark_Reign_2"},{"t":"Darkstalkers Chronicle: The Chaos Tower","p":["Dreamcast"],"d":"Capcom Production Studio 5","u":"Capcom","g":"Fighting","r":"August 10, 2000","l":"https://en.wikipedia.org/wiki/Darkstalkers_Chronicle:_The_Chaos_Tower"},{"t":"Dave Mirra Freestyle BMX","p":["Dreamcast"],"r":"November 20","l":"https://en.wikipedia.org/wiki/Dave_Mirra_Freestyle_BMX"},{"t":"Daytona USA 2001","p":["Dreamcast"],"d":"Amusement Vision, Genki","u":"Sega, Hasbro Interactive, Infogrames","g":"Racing","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Daytona_USA_2001"},{"t":"Dead or Alive 2","p":["Dreamcast","PlayStation 2"],"u":"Tecmo","r":"February 29, 2000","l":"https://en.wikipedia.org/wiki/Dead_or_Alive_2"},{"t":"Death Crimson OX","p":["Arcade"],"d":"Ecole Software","u":"Sega, Ecole Software, Sammy Entertainment, Play It","g":"Light gun shooter","r":"October 2000","l":"https://en.wikipedia.org/wiki/Death_Crimson_OX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40f0.jpg","s":"Death Crimson OX is a light gun shooting game developed by Ecole. It was released in arcades in 2000 then ported to the Dreamcast console in 2001 (published by Sammy Entertainment), several months after Sega had dropped support for the console. It is the third game in the Death Crimson series, and the only one to be released outside Japan. The game can be played with either a standard controller or a light gun."},{"t":"Deep Fighter","p":["Dreamcast","Windows"],"d":"Criterion Games","u":"Ubi Soft","g":"Submarine simulator","r":"August 23, 2000","l":"https://en.wikipedia.org/wiki/Deep_Fighter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22ld.jpg","s":"As a private in the defense force by The General, players take on deadly missions to seek out and destroy enemies, perform reconnaissance into uncharted waters and rescue damaged craft and installations. Meanwhile, droids and drones scuttle around busily, maintaining and repairing the slowly crumbling city.\n\nWith the ultimate objective of the construction of a giant mothership, the Leviathan, that will transport the entire civilization away from hostile waters.\n\nThis games combines elements of furious 3-D dogfighting and challenging exploration in true 3-D environments. 3-D worlds actually react and evolve around you as the game's level of difficulty adapts to your skill level.\n\nFive life-like and realistic environments, including the Abyss, Atlantis, and Jungle. Dynamic modes of battle include 3-D combat, unique weapons, special attack moves and upgradable fighter submarines."},{"t":"DeFRaG","p":["macOS","Linux","Windows"],"d":"DeFRaG team","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/DeFRaG"},{"t":"Delta Force: Land Warrior","p":["Windows"],"d":"NovaLogic","u":"NovaLogic","g":"Tactical first-person shooter","r":"November 8, 2000","l":"https://en.wikipedia.org/wiki/Delta_Force:_Land_Warrior","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co905c.jpg","s":"Engage the enemy across vast outdoor environments and expansive indoor environments as you take control of the US Army's elite anti-terrorist unit. Delta Force Land Warrior introduces new weapons and characters for both single player and intense online multiplayer via NovaWorld.\nSelect from a team of diverse characters, each with their own special abilities. (Sniper, Demolitions, Close Quarters Battle, Aquatics and Heavey Gunner)\nAdvanced new rifles, systems, machine guns and grenade launcher\nDeveloped from the same engine used to train the US ARMY elite Land Warrior Soldiers\nWage war on the massive battlefields of NovaWorld with up to 50 players simultaneously\nRank Yourself against your enemies and allies on NovaWorld"},{"t":"Demise: Rise of the Ku'tan","p":["Windows"],"d":"Artifact Entertainment","u":"IPC Software","g":"Role-playing video game","r":"January 15, 2000","l":"https://en.wikipedia.org/wiki/Demise:_Rise_of_the_Ku'tan","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6s8x.jpg","s":"Demise: Rise of the Ku'tan is a first-person RPG that has you slowly crawling your way through its dungeon."},{"t":"Derby Owners Club","p":["Arcade","Windows"],"d":"Sega-AM3","u":"Sega","g":"Horse racing","l":"https://en.wikipedia.org/wiki/Derby_Owners_Club","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobn6q.jpg"},{"t":"DeSpiria","p":["Dreamcast"],"g":"Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/DeSpiria","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co97je.jpg","s":"deSpiria is an RPG adventure that takes place in the futuristic Japan of 2070. Twenty-two years after the World War III, an organization known as Church has taken power. You play as Allure Valentine, a girl who was recruited by the Church as an undercover agent. On one of her missions, Allure boards a train that crashes shortly thereafter. Her first task will be to find a way out of the underground tunnel and to discover who or what was behind that crash.\n\nThe game is a RPG with elements of pure adventure. The entire game is viewed from first-person perspective. You fight enemies in turn-based battles, but instead of usual party you have several \"minds\", a kind of summoned monsters who will fight together with Allure. They will heal or attack the enemy using special \"mind attacks\" of various elements - love, curse, etc. In adventure mode, you explore the environments by pressing the A button, which will highlight objects you can interact with. The movements are shown as short CG sequences, similar to many Western-style adventures."},{"t":"Destruction Derby Raw","p":["PlayStation"],"r":"September 26","l":"https://en.wikipedia.org/wiki/Destruction_Derby_Raw"},{"t":"Deus Ex","p":["Windows","macOS"],"u":"Eidos Interactive","g":"Action, Adventure, RPG","r":"June 23, 2000","l":"https://en.wikipedia.org/wiki/Deus_Ex_(video_game)","s":"This is Deus Ex Remastered – the definitive version of Ion Storm’s legendary cyberpunk immersive sim, modernized with visual upgrades, modern enhancements, and quality-of-life improvements for a new generation of operatives."},{"t":"Devilman","p":["PlayStation"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Devilman_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v2g.jpg","s":"Survival horror game based on Go Nagai's influential 1972 horror manga."},{"t":"Dexter's Laboratory: Robot Rampage","p":["Game Boy Color"],"r":"November 14"},{"t":"Diablo II","p":["Windows","macOS"],"u":"Blizzard Entertainment","r":"June 28, 2000","l":"https://en.wikipedia.org/wiki/Diablo_II"},{"t":"Die Hard Trilogy 2: Viva Las Vegas","p":["PlayStation","Windows"],"d":"n-Space","u":"Fox Interactive","g":"Third-person shooter, light gun shooter, racing","r":"February 29, 2000","l":"https://en.wikipedia.org/wiki/Die_Hard_Trilogy_2:_Viva_Las_Vegas","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22lu.jpg","s":"Ready to kick some more terrorist butt? In Die Hard Trilogy 2: Viva Las Vegas for the PlayStation, you'll reprise the role of John McClane as you lay waste to the threats and save innocent people along the way -- this time in the Sin City capital of the world: Las Vegas, Nevada. The game comes packaged as a three-in-one deal, just like the original Die Hard Trilogy, for a total of 25 non-stop action-packed levels."},{"t":"Digimon Adventure 02: D1 Tamers","p":[],"l":"https://en.wikipedia.org/wiki/Digimon_Adventure_02:_D1_Tamers"},{"t":"Digimon Adventure 02: Tag Tamers","p":["WonderSwan"],"g":"Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/Digimon_Adventure_02:_Tag_Tamers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7znh.jpg","s":"Digimon Adventure 02: Tag Tamers is a role-playing video game by Bandai, for the WonderSwan. It was released in Japan on 3 August 2000. The game is based on the manga series Digimon, in which children can travel to a digital world and help good digital monsters to defeat evil ones."},{"t":"Digimon Digital Card Battle","p":["PlayStation"],"d":"BEC","u":"Bandai","g":"Digital collectible card game, Strategy","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Digimon_Digital_Card_Battle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49fg.jpg","s":"Can you imagine Digimon and humans living together and participating in Digital Card Battles? It sounds impossible, but you'd better believe it! Full of intense strategy and hardcore tactical maneuvering, DIGIMON DIGITAL CARD BATTLE is a genuine test of your skills and smarts. Each victory will increase your strength level, allowing you to move on to the next stage of play. Three Partner Decks will be at your disposal throughout play: Veemon will help you with offense; Armodillomon will provide surprise attacks; and Hawkmon will lend itself to quick digi-volving. The 40 new characters will provide plenty for series addicts to sink their teeth into, while 30 varieties of power-up cards will help gamers take down their competition. If all of this sounds like a foreign language to you, you're due to dive into the magical world of trainers and their monsters, known as DIGIMON. Play alone or challenge a friend!"},{"t":"Digimon World 2","p":["PlayStation"],"d":"BEC","u":"Bandai","g":"Role-playing","r":"July 27, 2000","l":"https://en.wikipedia.org/wiki/Digimon_World_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u4v.jpg","s":"Digimon World 2 is a dungeon crawler video game developed by BEC and published by Bandai for the PlayStation as part of their Digimon series. It is the sequel to the original Digimon World, and was released in Japan in July 2000 and North America the following year in May 2001. The player controls Akira, a Digimon Tamer whose goal is to climb to the top of the Digimon World."},{"t":"Dimahoo","p":["Arcade"],"d":"8ing/Raizing","u":"Capcom","g":"Bullet hell","r":"January 21, 2000","l":"https://en.wikipedia.org/wiki/Dimahoo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2s5n.jpg","s":"In this impressive blend of an overhead shoot'em up with RPG characteristics, you must help a group of mystic bounty hunters save the earth against the evil Gobligan Underground Empire. Features excellent 2-D graphics and sound, awesome character & enemy artwork designs, a level-up and elemental-based weapon system and LOTS of hidden items!"},{"t":"Dino Crisis 2","p":["PlayStation"],"d":"Capcom Production Studio 4","u":"Capcom, Virgin Interactive","g":"Action-adventure","r":"September 13, 2000","l":"https://en.wikipedia.org/wiki/Dino_Crisis_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8qbu.jpg","s":"Dino Crisis 2 is a third-person action-adventure game and sequel to Dino Crisis. In a change from the survival horror theme of the first game, Dino Crisis 2 is more shoot 'em up oriented. The character always runs, removing the need for the run button from the first game; players can carry a second gun, and more weapons were added. Besides gameplay changes, the game also introduces new species of dinosaurs and lizards."},{"t":"Dirt Track Racing: Sprint Cars","p":["Windows"],"d":"Ratbag Games","u":"WizardWorks","g":"Racing","r":"October 19, 2000","l":"https://en.wikipedia.org/wiki/Dirt_Track_Racing:_Sprint_Cars"},{"t":"Disney Learning: Mickey Mouse","p":[],"d":"Disney Interactive","u":"Disney Interactive","g":"Educational video game","l":"https://en.wikipedia.org/wiki/Disney_Learning:_Mickey_Mouse"},{"t":"Disney's 102 Dalmatians: Puppies to the Rescue","p":["Windows","PlayStation","Dreamcast","Game Boy Color"],"d":"Toys for Bob","u":"Eidos Interactive","g":"Platform, action-adventure","r":"November 13, 2000","l":"https://en.wikipedia.org/wiki/Disney's_102_Dalmatians:_Puppies_to_the_Rescue","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86yp.jpg","s":"Disney's 102 Dalmatians: Puppies to the Rescue is a platform game loosely based on the live-action Disney movie 102 Dalmatians. In Puppies to the Rescue you work your way through obstacles and mini games to save your siblings and parents from Cruella."},{"t":"Disney's Aladdin in Nasira's Revenge","p":["Windows","PlayStation"],"r":"December 1","l":"https://en.wikipedia.org/wiki/Disney%27s_Aladdin_in_Nasira%27s_Revenge"},{"t":"Disney's Beauty and the Beast Magical Ballroom","p":["Windows"],"d":"Creative Capers Entertainment","u":"Disney Interactive","g":"Action, strategy","l":"https://en.wikipedia.org/wiki/Disney's_Beauty_and_the_Beast_Magical_Ballroom"},{"t":"Disney's Dinosaur","p":["Game Boy Color","PlayStation","Dreamcast","PlayStation 2","Windows"],"d":"Ubi Soft Paris, Sandbox Studios, Digital Eclipse","u":"Ubi Soft","g":"Action-adventure, platformer, puzzle","r":"May 19, 2000","l":"https://en.wikipedia.org/wiki/Disney's_Dinosaur_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vtf.jpg","s":"The soaring Disney epic about the dinosaurs now has its very own game for the PC. Your species faces the grim possibility of extinction, and you're just the prehistoric monster to stop things before they get out of hand. Control Aladar, Flia, and Zini in this detailed, 3D game based on the film. You'll have to find and save eggs, battle deadly Raptors, and escape meteor showers throughout the 11 stages of this incredible tale. Each character has unique abilities, and the only way to solve the puzzles and make it to the game's end is by employing good, old-fashioned teamwork."},{"t":"Disney's Mickey Saves The Day 3D Adventure","p":["Windows"],"d":"Human Code","u":"Disney Interactive","g":"Adventure","r":"October 3, 2000","l":"https://en.wikipedia.org/wiki/Disney's_Mickey_Saves_The_Day_3D_Adventure"},{"t":"DOA2: Hardcore","p":["PlayStation 2"],"u":"Tecmo","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/Dead_or_Alive_2"},{"t":"Dogs of War","p":["Windows"],"d":"Silicon Dreams Studio","u":"TalonSoft, Take-Two Interactive","g":"Sci-fi Real-time strategy","r":"April 14, 2000","l":"https://en.wikipedia.org/wiki/Dogs_of_War_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/g8gyv9qjcwptfa0ot4eh.jpg"},{"t":"Doguu Senki: Haou","p":["Dreamcast"],"g":"Simulator, Strategy","l":"https://en.wikipedia.org/wiki/Doguu_Senki:_Haou","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/oooecycb9kj54gad3i55.jpg","s":"Turn-based strategy game for the Sega Dreamcast."},{"t":"Dokapon MillenniumQuest","p":["Game Boy Color"],"d":"Asmik Ace Entertainment","u":"Asmik Ace Entertainment","g":"Role-playing","r":"July 14, 2000","l":"https://en.wikipedia.org/wiki/Dokapon_MillenniumQuest"},{"t":"Donald Duck: Goin' Quackers","p":["Windows","PlayStation","Nintendo 64","PlayStation 2","Dreamcast","Game Boy Color"],"r":"October 19"},{"t":"Donkey Kong Country","p":["Game Boy Color"],"u":"Nintendo","r":"November 4, 2000","l":"https://en.wikipedia.org/wiki/Donkey_Kong_Country"},{"t":"Draconus: Cult of the Wyrm","p":["Dreamcast"],"r":"June 22"},{"t":"Dracula 2: The Last Sanctuary","p":["Windows","PlayStation"],"d":"Wanadoo Edition","u":"Index+, France Telecom Multimedia, Canal+ Multimedia, Cryo Interactive","g":"Graphic adventure","r":"September 25, 2000","l":"https://en.wikipedia.org/wiki/Dracula_2:_The_Last_Sanctuary","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3j0g.jpg","s":"The blood-curdling sequel to Dracula: Resurrection brings an even scarier adventure to life.\n\nAfter saving Mina, Jonathan Harker and his beloved return to London carrying a mysterious Dragon Ring."},{"t":"Dracula: Resurrection","p":["Windows"],"r":"June 7"},{"t":"Dragon Blaze","p":["Arcade"],"d":"Psikyo","u":"Psikyo","g":"Scrolling shooter","l":"https://en.wikipedia.org/wiki/Dragon_Blaze","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2nx1.jpg","s":"Dragon Blaze is a vertical scrolling shoot 'em up arcade game released in 2000 by Psikyo. It was ported in 2004 to the PlayStation 2 as part of the Psikyo Shooting Collection Vol. 3:Sol Divide & Dragon Blaze compilation. The game was later also released on its own for the PS2 in Europe by 505 Games."},{"t":"Dragon Dance","p":["Game Boy Color"],"d":"Natsume Co., Ltd.","u":"Crave Entertainment","g":"Action","r":"September 30, 2000","l":"https://en.wikipedia.org/wiki/Dragon_Dance_(video_game)"},{"t":"Dragon Quest VII","p":["PlayStation"],"r":"August 26","l":"https://en.wikipedia.org/wiki/Dragon_Quest_VII"},{"t":"Dragon Warrior I & II","p":["Game Boy Color"],"r":"September 27","l":"https://en.wikipedia.org/wiki/Dragon_Quest"},{"t":"Dragon Warrior Monsters","p":["Game Boy Color"],"r":"January 27","l":"https://en.wikipedia.org/wiki/Dragon_Warrior_Monsters"},{"t":"Driver 2","p":["PlayStation"],"d":"Reflections Interactive","u":"Infogrames","g":"Driving, action","r":"November 14, 2000","l":"https://en.wikipedia.org/wiki/Driver_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7t4j.jpg","s":"Driver 2: Back on the Streets is an open-world driving and action game developed by Reflections Interactive and published by Infogrames in 2000 for the PlayStation. It is the sequel to Driver and follows undercover cop Tanner and his partner Jones as they investigate a crime syndicate. The game introduces the ability for players to exit vehicles and explore environments on foot. Missions take place across four cities: Chicago, Havana, Las Vegas, and Rio de Janeiro. Gameplay combines story-driven objectives with free-roaming exploration."},{"t":"Driving Emotion Type-S","p":["PlayStation 2"],"d":"Escape","u":"Square, Square Electronic Arts, Electronic Arts","g":"Racing","r":"March 30, 2000","l":"https://en.wikipedia.org/wiki/Driving_Emotion_Type-S","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kbr.jpg","s":"Driving Emotion Type-S takes advantage of the power of the PlayStation2 computer entertainment system to bring you real-world physics, and realistically rendered cars and tracks."},{"t":"Duck Dodgers Starring Daffy Duck","p":["Nintendo 64"],"d":"Paradigm Entertainment","u":"Infogrames","g":"Platform","r":"August 15, 2000","l":"https://en.wikipedia.org/wiki/Duck_Dodgers_Starring_Daffy_Duck","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6woy.jpg","s":"Marvin The Martian has developed an ultimate weapon that will allow him to finally destroy Earth, which will ultimately allow him to take control of the universe. Upon the demonstration of the weapon, a slight snag hinders Marvin from completing his devious deed. The Weapon is out of Atoms, which it runs on, so he sends his minions (All of which are characters from the Looney Tune universe) to gather Atoms to fuel his weapon.\n\nDuck Dodgers is informed by his academy of Marvin's deeds and sets out to find the one-hundred Atoms before Marvin can. This ultimately has Dodgers and his sidekick, Cadet, trekking to four different planets, including a large pirate ship, to obtain the upper-hand over Marvin."},{"t":"Duke Nukem: Land of the Babes","p":["PlayStation"],"d":"n-Space","u":"Infogrames, Take-Two Interactive","g":"Third-person shooter","r":"October 16, 2000","l":"https://en.wikipedia.org/wiki/Duke_Nukem:_Land_of_the_Babes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9gcw.jpg","s":"In the distant future, vicious aliens rule the Earth. Only bodacious babes survive, enslaved by the hostile alien overlords. The women and the world need a hero. And there's only one man big enough for the job! Duke Nukem is back, and he's ready to settle the score!\n\n-21 action filled mission to hunt and destroy alien life\n-New weapons arsenal including: sniper riffle, flame thrower, grenade launcher and many more.\n-High tech gadgets including jetpack and infrared goggles\n-Numerous 3D cut-scenes to die for\n-In Your Face music by Static-Xtches."},{"t":"Dynasty Warriors 2","p":["PlayStation 2"],"r":"August 3","l":"https://en.wikipedia.org/wiki/Dynasty_Warriors_2"},{"t":"Eagle One: Harrier Attack","p":["PlayStation"],"d":"Glass Ghost","u":"Infogrames","g":"Flight simulator","r":"January 28, 2000","l":"https://en.wikipedia.org/wiki/Eagle_One:_Harrier_Attack","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2n9k.jpg","s":"Aloha... Hawaii is under siege from terrorist fanatics. As Eagle One, command the searing action and fly 5 different attack aircraft, including the versatile Harrier Jumpjet, in 25 adrenaline-pumping missions. Turn'n burn, baby... it doesn't get much Harrier than this."},{"t":"Earth 2150","p":["Windows"],"r":"May 22","l":"https://en.wikipedia.org/wiki/Earth_2150"},{"t":"Earth 2150: The Moon Project","p":["Windows"],"d":"TopWare Interactive","u":"1C Company, Game Studios","g":"Strategy","l":"https://en.wikipedia.org/wiki/Earth_2150:_The_Moon_Project","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fl1.jpg","s":"Take the completely 3-dimensional landscape into account while planning your troop movements: you'll need to scale towering mountains, dig out protective bulwarks and create entire tunnel systems. Explosions and detonations can change entire regions in an instant.\n\n“The Moon Project” is one of the blackest chapters in the history of mankind. While the Lunar Corporation, the Eurasian Dynasty and the United Civilized States are preparing themselves for the last all-encompassing battle, work is being feverishly carried out on a secret project on the Moon."},{"t":"Ecco the Dolphin: Defender of the Future","p":["Dreamcast"],"d":"Appaloosa Interactive","u":"Sega, Acclaim Entertainment, Sony Computer Entertainment","g":"Action-adventure","r":"June 16, 2000","l":"https://en.wikipedia.org/wiki/Ecco_the_Dolphin:_Defender_of_the_Future","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co53la.jpg","s":"At the dawn of the 30th Century, dolphins and humans had been together in a cross-species society for 500 years. Together, they had set out to explore space, offering peace and friendship to all who would welcome it. But space had its dangers; a violent species known as the Foe decided to conquer Earth. However, the dolphins and humans drove them to the brink of defeat, and so the Foe sought vengeance on Earth. The few caretaker dolphins who had been left behind on Earth were not entirely defenseless; they were protected by their creation called the Guardian—a gigantic, sentient being made of a crystalline substance which projected a forcefield over the entire planet. Undeterred, the Foe made suicide attacks on the field, searching for a weak point."},{"t":"ECW Anarchy Rulz","p":["Dreamcast"],"r":"December 30","l":"https://en.wikipedia.org/wiki/ECW_Anarchy_Rulz_(video_game)"},{"t":"ECW Hardcore Revolution","p":["Game Boy Color","Nintendo 64","PlayStation","Dreamcast"],"d":"Acclaim Studios Salt Lake City, Crawfish Interactive","u":"Acclaim Entertainment","g":"Sports","r":"February 17, 2000","l":"https://en.wikipedia.org/wiki/ECW_Hardcore_Revolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40g0.jpg","s":"Often imitated, never duplicated, ECW Hardcore Revolution takes you to Hell and back with the most intense hardcore wrestling action the human body can endure. Remember, scars never heal. Debut of over 40 hardcore ECW stars including Rob Van Dam, Sabu, Tommy Dreamer, Raven, Mike Awesome, Francine and New Jack! Real gutter-mouth crowd chants and commentary from ECW's Joey Styles. Brutal finishers and chair shots. \"3-Way Dance\" plus over 20 game modes!"},{"t":"Egypt II: The Heliopolis Prophecy","p":["Windows","PlayStation","macOS"],"d":"Cryo Interactive","u":"Cryo Interactive, DreamCatcher Interactive","g":"Adventure","r":"September 27, 2000","l":"https://en.wikipedia.org/wiki/Egypt_II:_The_Heliopolis_Prophecy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7lho.jpg","s":"The game is set in 1360 BC and Heliopolis, the City of the Sun, has been struck by a plague. The player's father has also been infected. In a first person perspective, the player must find a cure and save your father and the rest of Heliopolis."},{"t":"El Dorado Gate","p":["Dreamcast"],"d":"Capcom","u":"Capcom","g":"Role-playing","r":"October 10, 2000","l":"https://en.wikipedia.org/wiki/El_Dorado_Gate"},{"t":"El Tesoro de Isla Alcachofa","p":["Windows"],"d":"Alcachofa Soft","u":"Alcachofa Soft","g":"Graphic adventure","r":"August 8, 2000","l":"https://en.wikipedia.org/wiki/El_Tesoro_de_Isla_Alcachofa","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t1b.jpg","s":"Our name is Jim, a young man who wants to open a future in the world of pirates and has done many different jobs and of all kinds. This time we are going to look for Captain Flint's treasure and start the game remembering how everything happened and how we arrived at Alcachofa Island where he was buried."},{"t":"Elasto Mania","p":["Windows","Xbox"],"d":"Balázs Rózsa","g":"Platform","r":"January 2000","l":"https://en.wikipedia.org/wiki/Elasto_Mania","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27s6.jpg","s":"Elasto Mania (also known as Elma) is a physics-simulation game released in 2000. It claims to be \"based on a real physical model.\" It explores the notion of elastic motorcycles. The goal of each level is to collect every apple (disappearing by contact) spread throughout it, and then to touch the flower (the exit object). Some people, especially the ones part of online groups such as Mopolauta, play the game trying to finish levels as fast as possible, while others, mostly quite-new-to-the-game players, simply concern themselves with the accomplishment of levels, often first requiring figuring out a way for them to be solved. Ultimately, though, experienced players are motivated by the objective of finishing levels in the least amount of time possible, trying either to settle down personal, or world, records. That contributes to setting the stage for serious competition, especially in the official game levels."},{"t":"Elevator Action EX","p":["Game Boy Color"],"d":"Altron, Taito","u":"Altron, TDK Mediactive Europe","g":"Platform, shooter","r":"September 29, 2000","l":"https://en.wikipedia.org/wiki/Elevator_Action_EX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4m7f.jpg","s":"Elevator Action EX is an update to the Game Boy version of Elevator Action published by Taito in 1991. In addition to colour, players can choose between three characters: Mike, Guy and Sarah."},{"t":"Empire of the Ants","p":["Windows"],"d":"Microïds","u":"Microïds, Strategy First","g":"Strategy","r":"April 20, 2000","l":"https://en.wikipedia.org/wiki/Empire_of_the_Ants_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22up.jpg","s":"Empire of the Ants takes you into the undergrowth of the frantic world of colonization and dominance within the insect kingdom. Build up huge colonies, lead your armies into battle for supremacy, hunt down food, and breed to improve your numbers. Featuring 11 missions, 13 different breeds of ant to control, and numerous units such as exploding soldier ants, queen's gunners, and doorkeepers. Real-time effects include winter and summer seasons, rain, wind, and night/day. Beautifully rendered 3-D graphics depict a lavish insect kingdom. Play alone or in multiplayer mode over a network. Innovative AI reproduces the instinctual behaviors of every insect."},{"t":"Enemy Engaged: RAH-66 Comanche vs. KA-52 Hokum","p":["Windows"],"u":"Empire Interactive","r":"July 31, 2000"},{"t":"Ephemeral Fantasia","p":["PlayStation 2"],"d":"KCEJ East","u":"Konami","g":"Role-playing","r":"August 10, 2000","l":"https://en.wikipedia.org/wiki/Ephemeral_Fantasia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xkc.jpg","s":"In this game, the player controls Mouse, a silent musician who travels with his talking guitar Pattimo. One day Mouse is invited to play at a royal wedding on an island called Pandule. But soon he discovers that the groom Xelpherpolis has put an awful time-looping spell on the island, and intends to destroy this way the entire population. Mouse has to stop the villain and, most importantly, recruit other people to help him break the spell.\n\nEphemeral Fantasia is a Japanese-style role-playing game with turn-based combat. Several characters can be recruited to the party. The game's stand-out feature is the time-looping system, which is somewhat similar to the one implemented in The Legend of Zelda: Majora's Mask. The game has an internal clock, and the first five days repeat themselves until Mouse finds a way to stop it. Certain events occur only if Mouse travels to a specific location at a specific time."},{"t":"Escape from Monkey Island","p":["Windows"],"g":"Adventure","r":"November 8","l":"https://en.wikipedia.org/wiki/Escape_from_Monkey_Island","i":"images/steam-730830.jpg","s":"Fourth in the legendary Monkey Island series of graphic adventures!"},{"t":"ESPN MLS GameNight","p":["PlayStation"],"d":"Saffire, Konami Computer Entertainment Tokyo","u":"Konami","g":"Sports","r":"September 20, 2000","l":"https://en.wikipedia.org/wiki/ESPN_MLS_GameNight"},{"t":"ESPN NBA 2Night","p":["Dreamcast","PlayStation 2"],"d":"Sunset Entertainment, Konami Computer Entertainment Osaka","u":"Konami","g":"Sports","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/ESPN_NBA_2Night","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/jsvqlvfgjn5gj7xltsyt.jpg","s":"Play NBA with the stars on the Sega Dreamcast."},{"t":"ESPN Winter X-Games Snowboarding","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Snowboarding","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/ESPN_Winter_X-Games_Snowboarding"},{"t":"Eternal Ring","p":["PlayStation 2"],"d":"FromSoftware","u":"FromSoftware, Agetec, Ubi Soft / Crave","g":"Action role-playing","r":"March 4, 2000","l":"https://en.wikipedia.org/wiki/Eternal_Ring","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3tov.jpg","s":"A young magician is sent by his king to investigate the strange happenings on the Island of No Return. Armed with his sword and his natural talent as a sorcerer, Cain attempts to be the first person to return from the island alive. Legend has it that the island is inhabited by numerous beasts, enormous dragons, and magical items that were supposed to be buried long ago. As Cain, you must solve several baffling scenarios and defend yourself while you search for the magic ring."},{"t":"Europa Universalis","p":["Windows"],"d":"Paradox Development Studio","u":"Blackstar Interactive, Vision Park, Strategy First, Koch Media","g":"Grand strategy","r":"October 20, 2000","l":"https://en.wikipedia.org/wiki/Europa_Universalis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sm8.jpg","s":"Based on a French board game of the same name, Europa Universalis allows players to take control of a civilization between 1492 and 1792"},{"t":"Europa Universalis: Crown of the North","p":["Windows"],"d":"Paradox Interactive","u":"Levande Böcker, PAN Vision, Koch Media, Strategy First","g":"Real-time strategy, Grand strategy","l":"https://en.wikipedia.org/wiki/Europa_Universalis:_Crown_of_the_North","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q3s.jpg","s":"Based on the Europa Universalis engine, Crown of the North takes place in the years between 1275 and 1340 in a time where Sweden is about to launch into its only civil war. Play as Norway, Sweden, or Denmark and plot to change the historical legacy of a region seldom explored by games."},{"t":"EverGrace","p":["PlayStation 2"],"d":"FromSoftware","u":"FromSoftware, Agetec, Ubi Soft, Crave Entertainment","g":"Action role-playing","r":"April 27, 2000","l":"https://en.wikipedia.org/wiki/EverGrace","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3tgq.jpg","s":"Two complete adventures await Darius and Sharline - heroes who must face an evil reborn. Begin your journey as either hero and discover unique characters and monsters for each adventurer. Master the art of arming yourself with items of incredible might and untold magical abilities to thwart the powers of darkness that have swept into your once peaceful land."},{"t":"EverQuest: The Ruins of Kunark","p":["Windows"],"u":"Sony Online Entertainment","r":"April 24, 2000","l":"https://en.wikipedia.org/wiki/EverQuest_expansions"},{"t":"Evil Dead: Hail to the King","p":["PlayStation"],"r":"December 4"},{"t":"Evil Islands: Curse of the Lost Soul","p":["Windows"],"d":"Nival Interactive","u":"1C Entertainment, Fishtank Interactive","g":"Role playing game, real-time strategy","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/Evil_Islands:_Curse_of_the_Lost_Soul","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2152.jpg","s":"Evil Islands is a PC game by Nival Interactive that combines role-playing, stealth, and real-time strategy. It is the third game of the Allods franchise, after Rage of Mages and Rage of Mages 2: Necromancer. Evil Islands introduces a new interface and full 3D graphics."},{"t":"Evolva","p":["Windows"],"g":"Action, Adventure, Strategy","r":"June 1","l":"https://en.wikipedia.org/wiki/Evolva","i":"images/steam-771430.jpg","s":"Evolva combines the excitement of a fast paced shoot-em-up with the tactical challenge of commanding a squad. Fight against the alien parasites and save the planet. This is survival of the fittest!"},{"t":"Excitebike 64","p":["Nintendo 64"],"u":"Nintendo","r":"April 30, 2000","l":"https://en.wikipedia.org/wiki/Excitebike_64"},{"t":"F-18 Thunder Strike","p":["Game Boy Color"],"d":"Morning Star Multimedia","u":"Majesco","g":"Combat flight simulator","r":"July 30, 2000","l":"https://en.wikipedia.org/wiki/F-18_Thunder_Strike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fpjqxykvdzzr5b3frcdr.jpg","s":"Supersonic jet dogfighting comes to the small screen in F-18 THUNDERSTRIKE for the Game Boy Color. In this one-player flight sim, you take the role of a daring pilot who's flying an elite fighter jet. Slide into an inside-the-cockpit view, battle against multiple enemies, and practice your aerial combat and evasion maneuvers to prove your air superiority. You can play in either Arcade or Simulation mode, each affording you a unique experience. Arcade mode offers looser controls that make things easier for rookie pilots, while experts will want to jump right into Simulation mode, which will challenge the ability of even the most experienced flyboy. Head into multiple missions of dogfighting action and perform aerial tricks that will break the sound barrier, but don't think that it's all fun and games. When the mission's complete, you'll have to carefully land your jet on an aircraft carrier."},{"t":"F1 2000","p":["PlayStation","Windows"],"d":"Visual Science, Image Space Incorporated","u":"EA Sports","g":"Racing","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/F1_2000_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q49.jpg","s":"F1 2000 allows you to take on the role of any of the 2000 FIA Formula One Championship drivers. All of the tracks used during the 2000 season are also included, even the US Grand Prix at Indianapolis.\n\nChampionship, quick race, weekend and time trial are just some of the modes included in the game. The championship mode allows you to go through a full season of FIA action, from start to finish. Time trial mode lets you challenge the computer's (or your own) best times on a track of your choice. The weekend mode allows you to take part in a full weekend of events, from the practice sessions to the actual race itself."},{"t":"F1 Championship Season 2000","p":["Windows","PlayStation","PlayStation 2","Game Boy Color"],"r":"September 28","l":"https://en.wikipedia.org/wiki/F1_Championship_Season_2000"},{"t":"F1 Manager","p":["Windows"],"d":"Intelligent Games","u":"EA Sports","g":"Sports","r":"October 6, 2000","l":"https://en.wikipedia.org/wiki/F1_Manager_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coascd.jpg","s":"F1 Manager is a sports video game developed by Intelligent Games and published by EA Sports exclusively for Microsoft Windows. It was the last officially licensed F1 Management game until F1 Manager 2022 by Frontier Developments.\n\nThe game takes place from the 1999 Formula One World Championship onwards. The player assumes the role of the team principal of a Formula One constructor, managing and negotiating various aspects of the team."},{"t":"F1 Racing Championship","p":["Game Boy Color","Nintendo 64","PlayStation"],"d":"Ubi Soft Shanghai, Ubi Soft Milan","u":"Video System","g":"Sim racing","r":"September 15, 2000","l":"https://en.wikipedia.org/wiki/F1_Racing_Championship","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xxz.jpg","s":"You'll line up against the fiercest opponents of all time in this ultimate F-1 simulation. Featuring real circuits from the 1999 Formula One season, F-1 RACING CHAMPIONSHIP boasts the inclusion of the brand new Sepang track in Malaysia. All of the drivers from the ’99 season are included, and each uses the strategies and techniques that he’d use in a real race.\n\nTwo different modes allow you to try your hand at both ultra-realistic driving simulation, and arcade-style racing with brutal crashes and fast-paced, forgiving action. Each car has eight technical settings that can be tweaked to your taste, or you can just trust the judgment of the mechanic. Try out Solo mode; Time Attack (a race against your own best time); World Championship; Split-Screen Duel; and the helpful Driving School mode. Awesome graphics and true-to-life F-1 physics make this the most harrowing racing game to date, and impressive computer AI will have you working at this beast for quite awhile."},{"t":"Fairy Tale About Father Frost, Ivan and Nastya","p":["Windows"],"d":"Centauri Production, Bohemia Interactive","u":"Bohemia Interactive","g":"Adventure","r":"December 20, 2000","l":"https://en.wikipedia.org/wiki/Fairy_Tale_About_Father_Frost,_Ivan_and_Nastya"},{"t":"FantaVision","p":["PlayStation 2"],"r":"October 26","l":"https://en.wikipedia.org/wiki/Fantavision_(video_game)"},{"t":"Far Gate","p":["Windows"],"d":"Super X Studios / Thrushwave Technology","u":"Microïds","g":"Real-time strategy","r":"December 2000","l":"https://en.wikipedia.org/wiki/Far_Gate"},{"t":"Fear Effect","p":["PlayStation","Windows"],"d":"Kronos Digital Entertainment, Implicit Conversions","u":"Eidos Interactive","g":"Action-adventure","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/Fear_Effect","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8j85.jpg","s":"Fear Effect is an action adventure waiting to unfold! Wee Ming Lam disappears a few days before her 18th birthday under mysterious circumstances. Three ruthless mercenaries conspire to track her down and ransom her off to her father, Mr. Lam, a powerful Triad leader in Hong Kong. An extortion mission to retrieve Wee Ming Lam becomes a lesson in survival against the most unimaginable of enemies."},{"t":"Ferazel's Wand","p":["macOS"],"d":"Ambrosia Software","u":"Ambrosia Software","g":"Platform","r":"March 2000","l":"https://en.wikipedia.org/wiki/Ferazel's_Wand","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocz4e.jpg","s":"Ferazel's Wand is a platform game by Ambrosia Software for Mac OS released in 2000."},{"t":"Ferret Monogatari: Watashi no Okini Iri","p":["Game Boy Color"],"d":"Culture Brain","g":"Simulation, digital pet","l":"https://en.wikipedia.org/wiki/Ferret_Monogatari:_Watashi_no_Okini_Iri","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ifioqwj26zcqjkhnbnbv.jpg","s":"A Japanese Game Boy Color game about raising ferrets."},{"t":"Field & Stream: Trophy Bass 4","p":["Windows"],"d":"Dynamix","u":"Sierra Sports","g":"Sports","r":"May 25, 2000","l":"https://en.wikipedia.org/wiki/Field_&_Stream:_Trophy_Bass_4"},{"t":"FIFA 2001","p":["Windows","PlayStation","PlayStation 2"],"d":"EA Canada","u":"EA Sports","g":"Sports","r":"October 31, 2000","l":"https://en.wikipedia.org/wiki/FIFA_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tan.jpg","s":"FIFA 2001 aims to immerse its fans with the most realistic football experience possible. Over 50 international teams, including England, France, Germany, Holland, Spain, and the United States have made the cut, while 17 of the planet's top leagues have been incorporated as well. New motion captured moves from Matthaus, Mendieta, Scholes, and other soccer legends support the game's realism, with animated linesman and authentic light sourcing add that much more to the presentation. Perhaps the most important features, though, are the advanced sets of artificial intelligence, in-game cinematic cutscenes, and a ton of game modes that have been specially built for tournaments from around the world."},{"t":"Fighting Mania","p":[],"d":"Konami","u":"Konami","r":"March 2000","l":"https://en.wikipedia.org/wiki/Fighting_Mania"},{"t":"Final Fantasy IX","p":["PlayStation"],"u":"Square","r":"July 7, 2000","l":"https://en.wikipedia.org/wiki/Final_Fantasy_IX"},{"t":"Final Fight Revenge","p":["Sega Saturn"],"r":"March 30","l":"https://en.wikipedia.org/wiki/Final_Fight_Revenge"},{"t":"Firearms","p":["Windows","Linux"],"d":"FireArms Development Team","g":"First-person shooter","r":"April 30, 2000","l":"https://en.wikipedia.org/wiki/Firearms_(video_game)"},{"t":"Flirtboat","p":[],"l":"https://en.wikipedia.org/wiki/Flirtboat"},{"t":"Flying Heroes","p":["Windows"],"d":"Pterodon, Illusion Softworks","u":"Take 2 Interactive","g":"Shooter","r":"April 28, 2000","l":"https://en.wikipedia.org/wiki/Flying_Heroes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vr1p30wun8wypwyzfowg.jpg","s":"Flying Heroes is an arena based shooter game that takes place on various flying creatures. There are four clans to choose from, with varying creatures or machines for players. The four clans are: Sky Knights, Lizard Riders, Hammercraft, and Magion. Each clan offers different options, such as different amounts of health, different weapons and different flying crafts. There is also a multiplayer mode. In the beginning, or in the demo, only Lizard Riders and Magion are available choices; Sky Knights and Hammercraft become available when the career mode is beaten."},{"t":"Ford Racing","p":["Windows"],"d":"Elite Systems, Toolbox Design","u":"Empire Interactive","g":"Racing","r":"November 2, 2000","l":"https://en.wikipedia.org/wiki/Ford_Racing_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9c2t.jpg","s":"The Ford cars that you know and love have come to the PC in FORD RACING. You can drive the entire line of Ford vehicles including the Ka, Escort, Fiesta, Taurus, F-150, Explorer, Mustang, and GT90. Thanks to a realistic physics model the vehicles handle like their real-world counterparts, so you'll get an accurate feel of what it's like to drive them. So get ready to race all your favorite Fords in FORD RACING."},{"t":"Formula One 2000","p":["PlayStation","Game Boy Color"],"d":"Studio 33, Tarantula Studios","u":"Midway Games, Sony Computer Entertainment, Take-Two Interactive","g":"Racing","r":"October 4, 2000","l":"https://en.wikipedia.org/wiki/Formula_One_2000_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8532.jpg","s":"Formula One 2000 is an officially licensed Formula One racing game. The game is the 5th in Psygnosis/Sony series of Formula One racing games. All tracks, teams, cars and drivers from the 2000 season are in the game and can be selected. The game features a realistic damage model and various racing modes, including championship, single race-weekend, free practice and splitscreen mode for two players. Before each race, many aspects of the car can be customised. This is the first in the series to feature a safety car."},{"t":"Freedom: First Resistance","p":["Windows"],"d":"Red Storm Entertainment","u":"Red Storm Entertainment","g":"Action-adventure","r":"December 12, 2000","l":"https://en.wikipedia.org/wiki/Freedom:_First_Resistance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x5i.jpg","s":"Freedom: First Resistance is a third-person action-adventure game set in a future where Earth has been invaded by the alien Catteni race.\nPlayers take on the role of Angel Sanchez, a human resistance leader, and lead a team of rebels against the oppressive alien regime. The game features stealth-based gameplay, puzzle-solving, and strategic use of different team members to overcome challenges and liberate humanity"},{"t":"Freefall 3050 A.D.","p":["Nuon"],"d":"Total ArKade Software","u":"VM Labs, TAKS","g":"Action","r":"December 12, 2000","l":"https://en.wikipedia.org/wiki/Freefall_3050_A.D.","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xqw.jpg","s":"Falling at 150 mph without a parachute has never been so much fun!\n\nThe year is 3050 and you are a cop out on the beat. The hot pursuit is in full force, so grab your vest, your gun and leap head first out the window! Freefall 3050 A.D. is a fast paced action game featuring the unique combination of freefalling through space while blasting bad guys into oblivion! Rotate in 360 spins while you plummet at neck-breaking speeds. This is not your typical shoot'em up game - so don't miss out because this one is sure to make an impact."},{"t":"Freestyle Motocross: McGrath vs Pastrana","p":["PlayStation"],"d":"Z-Axis, Ltd.","u":"Acclaim Entertainment","g":"Racing","r":"November 2, 2000","l":"https://en.wikipedia.org/wiki/Freestyle_Motocross:_McGrath_vs_Pastrana"},{"t":"Frogger 2: Swampy's Revenge","p":["Game Boy Color","PlayStation","Windows","Dreamcast"],"d":"Blitz Games, Game Titan","u":"Hasbro Interactive","g":"Action","r":"September 21, 2000","l":"https://en.wikipedia.org/wiki/Frogger_2:_Swampy's_Revenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q73.jpg","s":"Because of his envy of Frogger's achievements and the attention he receives, Swampy the Crocodile hatches a devious scheme to invade his pond and kidnap Lillie Frog's brothers and sisters. What a vile crocodile! Assuming the role of the vengeful frog, you must thwart the evil crocodile and save the innocent tadpoles from harm.\n\nDivided into various interactive 3D worlds, Frogger's mission spans over 30 levels crammed with life threatening obstacles and monstrous cronies blocking the path to victory. Fortunately, the frog has been endowed with supreme powers including regular hops and super-hops, the ability to float over water and land, a Power Croak for calling missing tadpoles and a bug-seeking tongue."},{"t":"Front Line Force","p":["Windows"],"g":"First-person shooter","r":"November 17, 2000","l":"https://en.wikipedia.org/wiki/Front_Line_Force"},{"t":"Fur Fighters","p":["Dreamcast","Windows"],"d":"Bizarre Creations","u":"Acclaim Entertainment","g":"Third-person shooter, platformer","r":"June 23, 2000","l":"https://en.wikipedia.org/wiki/Fur_Fighters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9nzg.jpg","s":"A group of baby stuffed animals are kidnapped from their families by the Stupid Bears (an evil gang of stuffed teddy bears, of all things!), and it is up to the Fur Fighters to save the young ones.\n\nThe group that you control ranges from Kangaroos and Penguins to Cats and Dogs, all with their unique abilities and styles of fighting, which you must use to not only defeat the Stupid Bears, but complete puzzles and specific objectives along the way. You can control only one character at a time, but there are teleport areas so that you can change your character to one that can complete the tasks at hand."},{"t":"Galaga: Destination Earth","p":["Game Boy Color","PlayStation","Windows"],"d":"King of the Jungle, Pipe Dream Interactive","u":"Hasbro Interactive, Majesco","g":"Shoot 'em up","r":"September 20, 2000","l":"https://en.wikipedia.org/wiki/Galaga:_Destination_Earth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ye3.jpg","s":"Galaga, the \"slide-and-shoot\" arcade classic from 1981, has been updated with nine new worlds, 3D graphics, futuristic backgrounds and more in GALAGA -- Destination: Earth.\n\nLike in the original game, you begin this enhanced version of Galaga controlling a ship that moves horizontally along the bottom of the playfield and fires upward at wave after wave of diving, swirling aliens that eventually fly into formation. However, unlike the original, this game, depending on what mission you are playing, features a number of other viewpoints, including over the shoulder, top down and side on. You can fire just two shots at a time, but you can gain the ability to have three shots onscreen at once.\n\nAlso like the original game, GALAGA -- Destination: Earth features challenge waves in which you blast streams of enemies for points while not having to worry about your own safety. And, of course, you can let a Galaga capture your ship, then shoot your ship's captor, letting the captured ship fall to you, enabling you to double your firepower. Similar to Gaplus, the sequel to classic Galaga, this game also lets you collect beam power-ups that enable you to capture enemies, place them by your side and use their weapons."},{"t":"Galatea","p":["Windows","macOS","Linux"],"d":"Emily Short","u":"Self published","g":"Interactive fiction","l":"https://en.wikipedia.org/wiki/Galatea_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fla.jpg","s":"A conversation with a work of art. \"47. Galatea. White Thasos marble. Non-commissioned work by the late Pygmalion of Cyprus. (The artist has since committed suicide.) Originally not an animate. The waking of this piece from its natural state remains unexplained.\""},{"t":"Ganbare Goemon: Seikūshi Dynamites Arawaru!!","p":["Game Boy Color"],"d":"Konami Computer Entertainment Kobe","u":"Konami","g":"Action-adventure","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Ganbare_Goemon:_Seik%C5%ABshi_Dynamites_Arawaru!!"},{"t":"Gauntlet Dark Legacy","p":["Arcade"],"d":"Midway Games West","u":"Midway","g":"Hack and slash, dungeon crawl","r":"June 2000","l":"https://en.wikipedia.org/wiki/Gauntlet_Dark_Legacy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3kry.jpg","s":"Gauntlet Dark Legacy is the follow-up to Gauntlet Legends and another installment in the long-running Gauntlet series of hack-and-slash action games. As with all the Gauntlet games, you play a medieval fantasy character who, along with allies if you have them, fights his or her way through hordes of evil creatures on the never ending quest for more gold and perhaps even an eventual goal.\n\nThis version contains the characters and levels from Gauntlet Legends, plus the new characters and levels from the Dark Legacy arcade game, with a few extra levels thrown in.\n\nThere are eight characters to initially choose from: the mighty Warrior, the deadly Valkyrie, the quick-footed Archer, the powerful Wizard, the spellcasting Sorceress, the stalwart Knight, the valiant Dwarf, and the chaotic Jester. Although there are similarities between characters from the two games, each character looks and plays differently. In addition, there are eight alternative-modes for these characters to unlock, plus dozens of secret characters to obtain. With a multi-tap, up to four players can play, with rules governing how much they can hurt each other. Unlike the original Gauntlets, the levels you'll face take place in various terrain from forests to mountains to volcanic plains. Many of the monsters are familiar to old fans of the series, but there are some new blood among the ranks of evil, including some rather large foes."},{"t":"Gekido","p":["PlayStation"],"d":"NAPS team","u":"Infogrames, Interplay Entertainment","g":"Beat 'em up, fighting","r":"May 15, 2000","l":"https://en.wikipedia.org/wiki/Gekido","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40w5.jpg","s":"Gekido (known as Gekido: Urban Fighters in Europe) is a beat 'em up for the PlayStation game console. The game uses a fast paced beat 'em up system, with many bosses and a colorful design in terms of graphics. The game features the music of Fatboy Slim and Apartment 26. Marvel comic book artist Joe Madureira also contributed. A version of Gekido was also released on the Game Boy Color in Europe. It was later followed by a GBA spin-off called Gekido Advance: Kintaro's Revenge. A second sequel has been announced, Gekido: The Dark Angel."},{"t":"Gekitotsu Toma L'Arc: TomaRunner vs L'Arc-en-Ciel","p":["PlayStation"],"d":"Desert Productions","u":"Sony Computer Entertainment","g":"Racing","r":"July 19, 2000","l":"https://en.wikipedia.org/wiki/Gekitotsu_Toma_L'Arc:_TomaRunner_vs_L'Arc-en-Ciel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co706r.jpg","s":"Gekitotsu Toma L'Arc: TomaRunner vs L'Arc-en-Ciel is a Japan-exclusive racing game for the PlayStation. It is the sequel to TomaRunner and includes members of the Japanese band L'Arc-en-Ciel as playable characters.\n\nEach member of the band voices the in-game characters themselves. The L'Arc-en-Ciel songs that play within the game are \"Driver's High\", \"Stay Away\", \"Route 666\", \"Trick\", and \"Niji\".\n\nThe game was popular enough to receive a PS one Books re-release on December 21, 2001.\n\nThe dream has finally become reality with the help of L'Arc en Ciel! Every fan must have this! And of course, there is fun to be had with this game. This summer, why don't you try the Tomarunner experience for yourself?"},{"t":"Genesys","p":["Windows","macOS"],"d":"Cybele Productions, Wanadoo Edition","g":"Education, Adventure","l":"https://en.wikipedia.org/wiki/Genesys_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/kvkfnkp0ehc1captlut0.jpg","s":"Educational historical FMV puzzle game. Follow the evolution of human civilization and technology from prehistory to modern times and solve puzzles tied to what you've learned to progress.\n\nEducational video game, The player is guided by Jeanne Moreau through Claude Richardet's game. The game allows the player to discover the key stages of the evolution of various human societies around the world."},{"t":"Gensō Suikogaiden","p":["PlayStation"],"d":"Konami Computer Entertainment Tokyo","u":"Konami","g":"Visual novel","r":"September 21, 2000","l":"https://en.wikipedia.org/wiki/Gens%C5%8D_Suikogaiden"},{"t":"Get!! Colonies","p":["Dreamcast"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Get!!_Colonies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8iu8.jpg","s":"Puzzle game on the Sega Dreamcast. Object of the game is to fill the playfield with more of your colored spheres than your opponent.\n\nGet!! Colonies was originally released as \"Hello Kitty: Lovely Fruit Park\"... no... seriously, it was. The game was then re-skinned for a wider audience."},{"t":"Giant Gram 2000: All-Japan Pro Wrestling 3","p":[],"l":"https://en.wikipedia.org/wiki/Giant_Gram_2000:_All-Japan_Pro_Wrestling_3"},{"t":"Giant Killers","p":["Windows"],"d":"IO Productions, Smoking Gun Productions","u":"AAA Game Ltd","g":"Soccer Management Simulation","l":"https://en.wikipedia.org/wiki/Giant_Killers_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/sj8ggdtxv6tno618l4sz.jpg","s":"Giant Killers is a text-based European football management game, and as such the focus of the game is on the statistics and not on the action. \n \nBased on the 1999 UK season, the game allows the player to take control of any team in the UK's Premier league, Divisions One, Two or Three, or the Conference league. The game has three levels of difficulty. In the easy level the player's club has a wealthy benefactor who makes £25m available, in the medium setting £25m is still available, but two other clubs in the league also receive the same cash injection. In the hard mode there is no extra cash available."},{"t":"Giants: Citizen Kabuto","p":["Windows"],"g":"Violent, Action, Adventure, RPG","r":"December 7","l":"https://store.steampowered.com/app/557750","i":"images/steam-557750.jpg","s":"Before man climbed down from the trees to shop in megastores and drink cappuccino, before the Earth wadded itself into a ball, there was the Island. A fragment from a long-lost planet. Upon the surface of this paradise wandered Kabuto the giant. Little does he know, it was home to others before him."},{"t":"Gift","p":["Windows"],"d":"Eko Software","u":"Cryo Interactive, Wanadoo Edition","g":"Platform, action-adventure","r":"November 10, 2000","l":"https://en.wikipedia.org/wiki/Gift_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g40.jpg","s":"Gift is a strange anti-hero who must bring seven little garden gnomes to a self-proclaimed Snow White: in order to accomplish its mission, Gift will have to visit seven crazy and parodistic worlds (like Tipanic and Star Stress!).\nTwo of the authors are the comics artist Régis Loisel and Philippe Ulrich.\n\nThis 3D puzzle-platformer was developed by Eko Software and published in 2001 by Cryo Interactive, the team behind the Game Boy Color edition of the game.\n\nAlso, Loisel created an animated series of 8 episodes in 2005 (VHS/DVD) based on this title."},{"t":"Globetrotter","p":["Windows"],"d":"Deadline Games","u":"Vision Park","g":"Educational, quiz","l":"https://en.wikipedia.org/wiki/Globetrotter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4o4z.jpg","s":"Globetrotter plays similar to the Backpacker series. You start the game as a new member in the Globetrotter Club. Your objective is now to become the president. To do so you will have to complete various tasks that you are assigned by the club. Your job is to take pictures of famous sights all over the world. For these you will get money and experience which is used to reach more far away locations."},{"t":"Go Go Golf","p":["PlayStation 2"],"d":"Mahou","u":"Mahou, Midas Interactive Entertainment","g":"Sports game","r":"September 21, 2000","l":"https://en.wikipedia.org/wiki/Go_Go_Golf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5431.jpg","s":"A golf simulation game released in Japan and Europe."},{"t":"Gobs of Games","p":["Game Boy Color"],"d":"2N Productions","u":"The 3DO Company","g":"Puzzle","r":"September 2000","l":"https://en.wikipedia.org/wiki/Gobs_of_Games","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/aupvdvao3yy4a8cgdvgx.jpg","s":"GOBS OF GAMES brings many childhood games to the Game Boy Color. The 16 different games are broken into four categories: Paper games, Peg games, Puzzle games, and Board games. The Paper games include Hangman, Dot Boxes, Triangle Boxes, Share, Color Snakes, and Tic-Tac-Toe. Peg Game is a series of boards in which the goal is to remove all of the pegs by jumping over them. Scramble and Move It are Puzzle games, and the only Board game is Checkers. All of the games can be played solo, but some can also played against another person via a link cable. Try to relive your younger days with GOBS OF GAMES."},{"t":"Godzilla: The Series: Monster Wars","p":["Game Boy Color"],"r":"November 30"},{"t":"Gold and Glory: The Road to El Dorado","p":["Game Boy Color","Windows","PlayStation"],"d":"Planet Interactive, Revolution Software","u":"Ubi Soft, Light & Shadow Production","g":"Adventure","r":"April 30, 2000","l":"https://en.wikipedia.org/wiki/Gold_and_Glory:_The_Road_to_El_Dorado","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25i5.jpg","s":"After stowing away on Cortes's ship bound for the New World, Miguel and Tulio find themselves in a strange land with no food. However, they do find part of a map that might lead them to El Dorado, the lost city of gold. You take the role of either Miguel or Tulio as they search 20 levels of action that span swamps, rainforests, Spanish galleons, and even El Dorado for treasure and the other pieces of the map. Along the way, the heroes will have to fight bulls, native warriors, Spanish soldiers, wild boars, and rhinos, and they'll also have to brave the Circle of Fire. Luckily, the heroes are equipped with swords to dispatch any problems they might run into. If you play the game well, you just might get to ride Altivo, the horse. Help Miguel and Tulio find GOLD AND GLORY: The Road to El Dorado."},{"t":"GoVenture Educational Games and Simulations","p":[],"l":"https://en.wikipedia.org/wiki/GoVenture_Educational_Games_and_Simulations"},{"t":"Gradius III and IV","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Shoot 'em up","r":"April 13, 2000","l":"https://en.wikipedia.org/wiki/Gradius_III_and_IV"},{"t":"Grand Prix 3","p":["Windows"],"d":"MicroProse Chipping Sodbury Studio","u":"Hasbro Interactive","g":"Racing simulation","r":"July 28, 2000","l":"https://en.wikipedia.org/wiki/Grand_Prix_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q9n.jpg","s":"Grand Prix 3 (GP3) is a computer racing simulator by MicroProse. Released in 2000 by Hasbro Interactive featuring the 1998 Formula One season (with all drivers except Jacques Villeneuve, who is instead replaced by a fictional character, John Newhouse). The game wasn't quite as well received as its predecessors, but at the time was widely considered to be the best racing simulation available.\n\nAn add-on to the game, called GP3-2000 or GP32k, was released by Hasbro which updated the game to the 2000 Formula One season. A few other changes were made as well including: updated damage physics including damage from on-circuit debris, improved AI, a new replay system, and EAX 3D-sound.\n\nSince the release of Grand Prix 4, the GP3 modding scene has slowly declined, and with the cracking of track editing for GP4 many track modders left GP3 for the newer title."},{"t":"Grandia II","p":["Dreamcast"],"u":"Game Arts","r":"August 3, 2000","l":"https://en.wikipedia.org/wiki/Grandia_II"},{"t":"Grandia: Parallel Trippers","p":["Game Boy Color"],"d":"Game Arts","u":"Hudson Soft","g":"Role-playing","r":"December 22, 2000","l":"https://en.wikipedia.org/wiki/Grandia:_Parallel_Trippers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6irv.jpg","s":"This is the story of Yuuhi's journey to return home. To do this he must obtain three keys from different areas of the world so that he can unlock a seal in the Tower of White. The evil Gurgan, who is responsible for Yuuhi's appearance in this new world, must be defeated!"},{"t":"Grind Session","p":["PlayStation"],"d":"Shaba Games","u":"Sony Computer Entertainment","g":"Sports","r":"May 23, 2000","l":"https://en.wikipedia.org/wiki/Grind_Session","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/yeslbtp1rv2dxk4qguw0.jpg","s":"Grind Session translates the spirit and thrill of hard-core boarding into arcade-style action. Gamers compete in street and tournament competitions, flow on the halfpipe, and freestyle it for the covers of the big skating magazines. The game features eight unique 3-D arenas, such as Van's Triple Crown skate park, and includes hundreds of tricks, customizable gear, and instant replay modes with different camera angles. \n \nPlay your friends in such multiplayer modes as versus, team play, competition, tech challenge, S-K-A-T-E, and endurance. Grind Session also boasts 10 different skaters with the moves of board stars Daewon Song, Willie Santos, Pigpen, John Cardiel, and Cara Beth Burside, among others. If you want to go your own way, create a skater from scratch. The game's soundtrack is blessed by such hard-core artists as Man or Astroman, Sonic Youth, Suicidal Tendencies, GZA, and DJ Shadow."},{"t":"Gromada","p":["Windows"],"d":"Buka Entertainment","u":"Buka Entertainment, Bethesda Softworks","g":"Arcade","r":"April 24, 2000","l":"https://en.wikipedia.org/wiki/Gromada_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ku6.jpg","s":"Aliens have taken over the planet Gromada - a former testing site for new military units. - and now control a high-tech arsenal. Armed only with a tank called Kassandra, you must defeat the alien-controlled forces amassed against you and rid the planet of the aliens once and for all."},{"t":"Grouch","p":["Windows"],"d":"Revistronic Games","u":"Big City Games","g":"Action","r":"October 2000","l":"https://en.wikipedia.org/wiki/Grouch_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/eszsn0xxejdbqtdhetyc.jpg","s":"Rocko's Quest is an action game on the PC."},{"t":"Ground Control","p":["Windows"],"r":"June 1","l":"https://en.wikipedia.org/wiki/Ground_Control_(video_game)"},{"t":"Ground Control: Dark Conspiracy","p":["Windows"],"d":"Massive Entertainment, High Voltage Software","u":"Sierra On-Line","g":"Real-time tactics","r":"December 1, 2000","l":"https://en.wikipedia.org/wiki/Ground_Control:_Dark_Conspiracy"},{"t":"Grudge Warriors","p":["PlayStation"],"d":"Tempest Software","u":"Take-Two Interactive","g":"Action, car combat","r":"April 27, 2000","l":"https://en.wikipedia.org/wiki/Grudge_Warriors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qqzq4i7youcfxcxoo5pq.jpg","s":"Grudge Warriors is a tank combat game released by Take-two Interactive in April 2000 solely for playstation 1. The aim of the game is to destroy and conquer the map which is controlled by hostile enemy tanks, turrets and equipment with also objectives including solving puzzles. With also the option for two players. similar to the earlier game of twisted metal released on playstation 1, there is a choice of eleven special armoured vehicles. Each one is equipped with five types of weaponry. Four of the weapons are similar on each vehicle but the fifth weapon is unique. It is set in the not too distant future where enemy gangs and crews control the areas needing to be seized."},{"t":"Guilty Gear X","p":["Windows","Arcade"],"r":"July 13","l":"https://en.wikipedia.org/wiki/Guilty_Gear_X"},{"t":"Gundam Side Story 0079: Rise from the Ashes","p":["Dreamcast"],"r":"April 28"},{"t":"Gungriffon Blaze","p":["PlayStation 2"],"d":"Game Arts","u":"Capcom, Working Designs, Swing! Entertainment","g":"Vehicle simulation","r":"August 10, 2000","l":"https://en.wikipedia.org/wiki/Gungriffon_Blaze","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w85.jpg","s":"Gungriffon Blaze was a Playstation 2 launch title. Set in a devastated post World War III world, the player plays as a mech equipped UN soldier who must maintain peace."},{"t":"Gunlok","p":["Windows"],"d":"Rebellion Developments","u":"Virgin Interactive","g":"Action-adventure","r":"December 8, 2000","l":"https://en.wikipedia.org/wiki/Gunlok","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28ow.jpg","s":"At the end of the 21st Century, robots finally enslaved mankind. Desperately, a few pockets of the human resistance fight on. You are Gunlok, a member of Earth’s Special Forces. Isolated during the robots’ uprising, you’ve now mastered your experimental battle armour and decided to return from the wilderness."},{"t":"Gunman Chronicles","p":["Windows"],"d":"Rewolf Software","u":"Sierra Studios","g":"First-person shooter","r":"November 21, 2000","l":"https://en.wikipedia.org/wiki/Gunman_Chronicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc2nq.jpg","s":"Originally, Gunman Chronicles was developed by Rewolf Software as a mod for the first person shooter Half Life; after negotiations Sierra released it as a retail version in 2000.\n\nIn Gunman Chronicles, the general of the Gunmen fell in battle with the Xenomes, a strange alien species which suddenly appeared on the planet Banzure Prime. Now, a mysterious presence has tinkered with the DNA of these Xenomes, making them bigger and stronger than ever before, and the scourge is spreading once again. As Major Archer, leader of the Gunmen, the only law in this area of the galaxy, you must set things right - find the source of this hostile invasion, and clear these alien scum from the rim of the galaxy!"},{"t":"Gunship!","p":["Windows"],"d":"MicroProse Hunt Valley Studio","u":"Hasbro Interactive","g":"Combat flight simulation","r":"April 4, 2000","l":"https://en.wikipedia.org/wiki/Gunship!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j7u.jpg","s":"Fly low and strike deep in the re-invention of the Gunship flight combat franchise. In Gunship!, you're the point man for WWIII -- Russian forces have amassed on one side, NATO on the other in a flashpoint conflict in Eastern Europe. You are about to deploy the most devastating weapon in the inventory of war: the helicopter Gunship! Finesse, raw power, stealth and speed blend in a high-wire balancing act of exacting proportions. In the 21st century, the fate of war can turn on one micro-engagement in the epicenter of action."},{"t":"Habbo","p":["Browser"],"d":"Sampo Karjalainen, Aapo Kyrölä, Sulake","g":"Point-and-click, Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/Habbo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co87n7.jpg","s":"Habbo (formerly known as Habbo Hotel) is an online vintage pixel-art style virtual community where you can create your own avatar, make friends, chat, build rooms, design + play games and so much more! Almost anything is possible in this strange place full of awesome people."},{"t":"Hanagumi Taisen Columns 2","p":["Dreamcast"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Hanagumi_Taisen_Columns_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5bxd.jpg","s":"The members of the Sakura Wars Hanagumi meet together and confront again with the falling object puzzle. Compete with Sakura fans all over the country while staying at home for online matches! Using the communication function of Dreamcast, you can play online. You can test your skills with \"Hana Kora\" fans nationwide at home. Of course, you can also enjoy Sakura-related information on the Internet. A variety of game modes with a story and a single play! A variety of game modes are available, including the Red Boy vs Red Lizard Mode, where members of the Hanagumi clash over the protagonist, the 2P battle mode in which players compete with each other, and the 1P mode in which columns are played intently. Of course, there is also a story mode where you can get a glimpse of the daily lives of the Hanagumi members."},{"t":"Handkerchief","p":["Windows"],"d":"Opus Corp.","u":"Xsiv Games","g":"Adventure, Strategy","l":"https://en.wikipedia.org/wiki/Handkerchief_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4hrq.jpg","s":"Handkerchief, developed Opus Corp. / Ask, Co., Ltd., published by XSIV Games (Stealth Media Group).\nSide-scrolling run'n'gun similar to Metal Slug or Jazz Jackrabbit. Shoot, jump, use weapons and vehicles to combat the enemy army. Single or multiplayer."},{"t":"Happy Lesson: First Lesson","p":["Dreamcast"],"l":"https://en.wikipedia.org/wiki/Happy_Lesson:_First_Lesson","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nw8.jpg","s":"Fan disc released with \"Happy Slot\" (slot machine), \"Happy Gallery\" (art gallery) and \"Happy Net\""},{"t":"Harley-Davidson: Wheels of Freedom","p":["Windows"],"d":"Canopy Games, G2M Games","u":"Infogrames, Inc.","g":"Racing","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/Harley-Davidson:_Wheels_of_Freedom"},{"t":"Haruka: Beyond the Stream of Time","p":["PlayStation"],"g":"Role-playing (RPG), Simulator, Adventure","l":"https://en.wikipedia.org/wiki/Haruka:_Beyond_the_Stream_of_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fa7.jpg","s":"Harukanaru Toki no Naka de is the first installment in the Haruka series, the starting title for the second and longest Neoromance IP. It is the game which receives the most outside coverage and spin-offs within the series. Yasuhiro Misawa is the main composer for the game."},{"t":"Harvest Moon: Back to Nature","p":["PlayStation"],"r":"November 22"},{"t":"Hataraku Chocobo","p":["WonderSwan Color"],"g":"Point-and-click, Simulator","l":"https://en.wikipedia.org/wiki/Hataraku_Chocobo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5qko.jpg","s":"A sim featuring Square's mascot released on the WonderSwan Color in Japan only.\nThe player must raise a Chocobo while completing various tasks to earn items."},{"t":"HBO Boxing","p":["PlayStation"],"d":"Osiris Studios","u":"Acclaim Entertainment","g":"Sports, fighting","r":"November 21, 2000","l":"https://en.wikipedia.org/wiki/HBO_Boxing_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/g1idbhilhj1yegaiofo6.jpg","s":"Time to step into the ring and slug it out with more than 35 real life boxers. Some of the fighters featured in the game are George Foreman, Roy Jones Jr., Rocky Marciano, Hector Camacho, and Jack Dempsey. Modes of play include Career, Exhibition, Tournament, and Quickbout. Players can create their own boxer and tweak his abilities in style, power, stamina, foot speed, and invincibility. Providing the commentary for the matches are Jim Lampley, Larry Merchant, and Harold Lederman.\n\nAcclaim Sports' HBO Boxing is \"The Heart & Soul of Boxing\" video games! This debut release is the most complete boxing video game franchise ever developed. Featuring past and present champions in the most accurate and exciting boxing experience ever!"},{"t":"Heavy Metal: F.A.K.K. 2","p":["Windows","macOS"],"r":"August 1"},{"t":"Heisei Mahjong Shou","p":[],"l":"https://en.wikipedia.org/wiki/Heisei_Mahjong_Shou"},{"t":"Hellboy: Dogs of the Night","p":["Windows"],"d":"Cryo Studios North America, Hoplite Research, LLC","u":"Cryo Interactive, Dreamcatcher Interactive","g":"Action","r":"December 2000","l":"https://en.wikipedia.org/wiki/Hellboy:_Dogs_of_the_Night","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co29gh.jpg","s":"The first game starring the gruff half-demon Hellboy. Later ported to PlayStation under Hellboy: Asylum Seeker."},{"t":"Hello Kitty no Magical Block","p":["Dreamcast"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Hello_Kitty_no_Magical_Block","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co73uk.jpg","s":"Hello Kitty Magical Block is a Japanese exclusive puzzle game based on the Hello Kitty series."},{"t":"Hello Kitty no Waku Waku Cookies","p":[],"l":"https://en.wikipedia.org/wiki/Hello_Kitty_no_Waku_Waku_Cookies"},{"t":"Hercules: The Legendary Journeys","p":["Nintendo 64"],"d":"Player 1","u":"Titus Interactive","g":"Action-adventure","r":"August 18, 2000","l":"https://en.wikipedia.org/wiki/Hercules:_The_Legendary_Journeys_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3dke.jpg","s":"Take control of the legendary hero Hercules and his friends Iolaus and Serena as they attempt to stop Ares from completing his diabolical plans. Use each character's unique attributes: Hercules' legendary strength, Iolaus' nimble nature and Serena's accuracy to complete your quest. Travel through 12 unique fully 3D worlds, from the sunny seaside town of Porticus to the snowy mountains of Alpsius. Explore the bandit-overrun forrests of Traycus or heavenly Mount Olympus. Fight mythical terrifying monsters such as the Minotaur, Cyclops, and more!"},{"t":"Heroes Chronicles","p":["Windows"],"d":"New World Computing","u":"The 3DO Company","g":"Turn-based strategy","r":"September 27, 2000","l":"https://en.wikipedia.org/wiki/Heroes_Chronicles"},{"t":"Heroes of Might and Magic","p":[],"d":"KnowWonder","u":"The 3DO Company","g":"Turn-based strategy","r":"June 20, 2000","l":"https://en.wikipedia.org/wiki/Heroes_of_Might_and_Magic_(GBC_video_game)"},{"t":"Heroes of Might and Magic III: The Shadow of Death","p":["Windows","macOS"],"d":"New World Computing","u":"The 3DO Company, Ubisoft","g":"Turn-based strategy","r":"March 21, 2000","l":"https://en.wikipedia.org/wiki/Heroes_of_Might_and_Magic_III:_The_Shadow_of_Death"},{"t":"Hitman: Codename 47","p":["Windows"],"g":"Action","r":"November 19","l":"https://store.steampowered.com/app/6900","i":"images/steam-6900.jpg","s":"As the enigmatic Hitman, you must use stealth and tactical problem solving to enter, execute and exit your assignment with minimum attention and maximum effectiveness. For a price, you have access to the most devious devices, but how you use them will determine if you retire as a millionaire or get permanently retired."},{"t":"Hogs of War","p":["PlayStation","Windows"],"d":"Infogrames Sheffield House","u":"Infogrames","g":"Turn-based tactics, artillery game","r":"June 16, 2000","l":"https://en.wikipedia.org/wiki/Hogs_of_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5hul.jpg","s":"Hogs of War is a turn-based tactics game where players take turns controlling individual members of their squad of hogs to engage in combat with the opposition, similar to Worms. Each turn, a player takes control of a single squad member in a third-person perspective to move around the map, including jumping over terrain and swimming over bodies of water, yet can only engage in combat when stationary. Each turn has a set time limit and ends if the timer counts down to zero, the player skips their turn, a weapon or ability is used or if they have accidentally injured themselves such as walking into a mine field or falling from a high surface. Other hazards include bodies of water that, while they can be swam in, is damaging to nearly all types of soldiers and drains health as they swim. If a teammate is knocked into water by an opponent, they will automatically swim to the nearby shore line. While difficult, it is also possible to knock hogs off the map resulting in instant death. If all health is gone and the player is on land, they will fall over with a last comical remark before exploding."},{"t":"Homeworld: Cataclysm","p":["Windows"],"u":"Sierra Entertainment","r":"June 30, 2000"},{"t":"Hot Wheels Micro Racers","p":["Windows"],"d":"Unique Development Studios","u":"Mattel Interactive, THQ","g":"Racing","r":"April 28, 2000","l":"https://en.wikipedia.org/wiki/Hot_Wheels_Micro_Racers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6is0.jpg","s":"Hot Wheels Micro Racers features mini Hot Wheels vehicles as the game's playable and computer-controlled racers, with gameplay consisting of arcade-style racing."},{"t":"Hoyle Card Games","p":["Game Boy Color"],"d":"Sandbox Studios","u":"Sierra Attractions","g":"Strategy, Card & Board Game","l":"https://en.wikipedia.org/wiki/Hoyle_Card_Games","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wmm.jpg","s":"Hoyle Card Games is a Game Boy Color-only video game that was developed by Sandbox Studios and published by Sierra On-Line under their Sierra Attractions label."},{"t":"Hugo: Quest for the Sunstones","p":["PlayStation","Windows"],"d":"ITE Media","u":"ITE Media","g":"Platform game","r":"March 11, 2000","l":"https://en.wikipedia.org/wiki/Hugo:_Quest_for_the_Sunstones"},{"t":"Hyper Force","p":["Atari Jaguar"],"d":"Visual Impact","u":"Songbird Productions","g":"Action, platform","r":"April 10, 2000","l":"https://en.wikipedia.org/wiki/Hyper_Force","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/pywrmoylmwteaynumdvb.jpg","s":"It's Just You, Your Gun, and a Corporate Army Bent On Your Destruction.\n\nTrans Con is decimating world after world in search of enough resources and wealth to launch an attack against the Terran High Command. The politicians don't want a direct confrontation that might hurt their corporate sponsors. So, Interstellar Special Forces has been called in to send a lone warrior to eliminate the Trans Con threat. Wanna guess who that warrior is?"},{"t":"Icewind Dale","p":["Windows"],"r":"June 29","l":"https://en.wikipedia.org/wiki/Icewind_Dale"},{"t":"ID4 Online","p":["Windows"],"d":"Mythic Entertainment","u":"Centropolis Interactive","l":"https://en.wikipedia.org/wiki/ID4_Online"},{"t":"IHRA Drag Racing","p":["Windows","PlayStation","PlayStation 2","Xbox"],"d":"Digital Dialect, Bethesda Softworks, Super Happy Fun Fun, Vir2L Studios","u":"Bethesda Softworks","g":"Racing","l":"https://en.wikipedia.org/wiki/IHRA_Drag_Racing"},{"t":"IHRA Drag Racing","p":["Windows"],"d":"Digital Dialect","u":"Bethesda Softworks, Vir2L Studios","g":"Racing","r":"November 29, 2000","l":"https://en.wikipedia.org/wiki/IHRA_Drag_Racing_(video_game)"},{"t":"In Cold Blood","p":["PlayStation","Windows"],"d":"Revolution Software","u":"Sony Computer Entertainment, Ubi Soft, DreamCatcher Interactive","g":"Action-adventure","r":"July 14, 2000","l":"https://en.wikipedia.org/wiki/In_Cold_Blood_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xc5.jpg","s":"In Cold Blood requires players to use more brains than brawn in solving a case of international intrigue, puzzle-solving, clue gathering, and the unwinding of a tangled web of espionage, double-crosses and a sinister plot that might threaten the free world. The story unwinds in an unusual manner: At the start of the game, your character, Agent John Cord, has been captured by the enemy and is in the midst of a grueling interrogation. The scenes from the game come from his memories as he is undergoing this ordeal, with players taking on his previous adventures that lead him up to this point. It is a spy-thriller in the vein of James Bond, and as Cord remembers more, the overall story begins to make more sense.\n\nThroughout In Cold Blood, players will have to search for hidden objects and talk to a whole host of characters, attempting at every turn to solve the puzzles that pop up in their way. But tricky conundrums aren't the only thing blocking their paths -- they'll also have to take control of Agent Cord in high-octane gun battles against enemy agents. Occasionally, the player can outwit the enemies, but they'll often they'll have to fight it out in a duel to the death."},{"t":"Incredible Crisis","p":["PlayStation"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Incredible_Crisis"},{"t":"Indy Racing 2000","p":["Nintendo 64"],"d":"Paradigm Entertainment","u":"Infogrames","g":"Racing","r":"June 7, 2000","l":"https://en.wikipedia.org/wiki/Indy_Racing_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6q83.jpg","s":"INDY RACING 2000 for the Nintendo 64 combines realistic racing simulations and far-out arcade racers to make a game that closely follows the rules, but is still a lot of fun to play. There are many modes such as Practice, Race, Competition, and Championship. Before each race, the player can choose one of 20 real-life drivers and their actual vehicle. Players also have the ability to customize the car as desired, by adjusting everything from the tire pressure to the transmission. In addition to the official Indy Racing League tracks, there are road courses to race on as well. Players will have to race their hardest, as the cartridge will save all of their racing data so that they can compare their stats to a friend, or even race one in the Multiplayer mode. INDY RACING 2000 manages to keep the franchise fresh by offering plenty of tracks and options, with great racing fun in the lead."},{"t":"Innova Disc Golf","p":["Windows"],"d":"Sundial Interactive","u":"WizardWorks","g":"Sports","r":"April 12, 2000","l":"https://en.wikipedia.org/wiki/Innova_Disc_Golf_(video_game)"},{"t":"Insane","p":["Windows"],"d":"Invictus Games, Ltd.","u":"Codemasters","g":"Racing","r":"November 24, 2000","l":"https://en.wikipedia.org/wiki/Insane_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wop.jpg","s":"Levels are set in real world locations, scattered throughout North America, Europe, Africa, Asia and Australia. The actual design, however, is fictitious.\n\nThe single player campaign comprises a series of championships in different vehicle classes, where the player unlocks new vehicles and locations, based on their score.\n\nVehicles range from utility vehicles to light buggies and are either fictional or inspired by actual production vehicles. Though the names do not correspond with any actual vehicle, the fact is evident both visually in-game and in the names of the game's files."},{"t":"Inspector Gadget: Operation Madkactus","p":["Game Boy Color"],"d":"RFX Interactive","u":"Ubi Soft, Light & Shadow Production","g":"Action","r":"December 1, 2000","l":"https://en.wikipedia.org/wiki/Inspector_Gadget:_Operation_Madkactus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ai2dzz281rywcg8nojo5.jpg","s":"The evil Dr. Claw is about to unleash the deadly MadKactus virus on the world, and it's up to Inspector Gadget to stop him. Since Gadget always needs a little help, his niece Penny and their dog Brain are at the ready to make their contribution. You, as the enigmatic Inspector, will have to work your way through 20 levels that span five different worlds. Luckily, many of your famous devices are available to help out including the helicopter, spring arms, rocket-powered roller skates, and hammer hat. If there is something that you can't do as Gadget, you can switch characters and use Penny or Brain to get past an obstacle or solve a puzzle. Gather up your go-go gadgets and get ready to save the world from Dr. Claw in INSPECTOR GADGET."},{"t":"International Karate 2000","p":["Game Boy Color"],"d":"Studio 3 Interactive Entertainment","g":"Fighting","r":"November 17, 2000","l":"https://en.wikipedia.org/wiki/International_Karate_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ax0.jpg","s":"The classic karate fighter is back on the Game Boy Color, remade with the nostalgic gameplay that fans around the world will adore, and new play modes to keep the action fresh and exciting. Hiyah!"},{"t":"Invictus","p":["Windows"],"d":"Quicksilver Software","u":"Interplay Entertainment","g":"Real-time strategy, Role-playing video game","r":"March 2, 2000","l":"https://en.wikipedia.org/wiki/Invictus_(video_game)"},{"t":"Iron Aces","p":["Dreamcast"],"d":"Marionette","u":"Global A Entertainment, Xicat Interactive","g":"Combat flight simulator","r":"June 29, 2000","l":"https://en.wikipedia.org/wiki/Iron_Aces","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40o5.jpg","s":"Iron Aces is fictional World War 2 flight simulator. What that \"fictional\" means is that great liberties have been taken with the historical accuracy of the world and events. The most obvious point is that although most planes come from real World War 2 aircraft, the theatre of operations is a bit unique; The four major sides to the conflict (American, British, German, Japanese) are all fighting one another over a group of islands somewhere in the Pacific. Thus each of these nations is represented in close proximity and in direct conflict to one another.\n\nThe gameplay takes place over a series of single-player flight missions in which your American pilot will fight against the Axis forces and ally with the British. The majority of the missions take place in the air against other aerial targets."},{"t":"Iron Soldier 3","p":["PlayStation"],"d":"Eclipse Software Design","u":"Vatical Entertainment, Telegames, VM Labs","g":"Mech simulation","r":"June 14, 2000","l":"https://en.wikipedia.org/wiki/Iron_Soldier_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4s03.jpg","s":"Iron Soldier 3 is a combat game/mech sim where players have an arsenal of weapons at their disposal."},{"t":"ISS","p":["PlayStation","PlayStation 2"],"d":"Major A","u":"Konami","g":"Sports","r":"August 3, 2000","l":"https://en.wikipedia.org/wiki/ISS_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u7x.jpg","s":"International Superstar Soccer (abbreviated as ISS) is a football video game in the International Superstar Soccer series by Konami.\n\nPlayers can train and edit their teams, and they can change the formations and tactics before the match. During the match, they can adjust camera angles, make substitutions and tactical changes, adjust the game speed, and so on. The main game element is controlling the players, making searching passes, and scoring goals."},{"t":"ISS Pro Evolution 2","p":["PlayStation"],"d":"Konami Computer Entertainment Tokyo","u":"Konami","g":"Sports","r":"August 24, 2000","l":"https://en.wikipedia.org/wiki/ISS_Pro_Evolution_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u87.jpg","s":"ISS Pro Evolution 2 (known as World Soccer Jikkyou Winning Eleven 2000: U-23 Medal he no Chousen in Japan) is the fourth video game in the ISS Pro series and the second instalment of the ISS Pro Evolution series. It was developed exclusively for the PlayStation by Konami Computer Entertainment Tokyo. It was available in Europe and Japan but not North America, as ESPN MLS GameNight was released in that territory instead.\n\nIt is the first ISS Pro game with proper licenses, although partial, with some players having real names. The game has an extended Master League, with two divisions and eight more clubs, resulting in twenty-four club teams, such as Leeds United and Boca Juniors. More international teams were added as well. The gameplay also changed, becoming smoother and more realistic. The Japanese version of the game also contains Under-23 National Teams, which are not present in the European versions of the game."},{"t":"Jackie Chan Stuntmaster","p":["PlayStation"],"d":"Radical Entertainment","u":"Midway Games, Sony Computer Entertainment","g":"Beat 'em up, platform","r":"March 28, 2000","l":"https://en.wikipedia.org/wiki/Jackie_Chan_Stuntmaster"},{"t":"Jahmong","p":["Dreamcast"],"g":"Card & Board Game","l":"https://en.wikipedia.org/wiki/Jahmong","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co98rt.jpg","s":"Jahmong is a Sega Dreamcast online mahjong game developed and published by Visit. Released exclusively in Japan in August 2000,\n\nVoice recognition mahjong game. It's a hot game with a voice recognition system like never before, with increased luck depending on the size of your voice.\n\nPlay against strong enemies all over the country at Gourmet Mode. From Hokkaido in the north to Kyushu in the south, around the country, get all the local specialties!!"},{"t":"Jane's F/A-18","p":["Windows"],"u":"Electronic Arts","r":"January 11, 2000","l":"https://en.wikipedia.org/wiki/Jane%27s_F/A-18"},{"t":"Japan Pro Golf Tour 64","p":["Nintendo 64DD"],"d":"Media Factory","u":"Media Factory","g":"Sports","r":"May 2, 2000","l":"https://en.wikipedia.org/wiki/Japan_Pro_Golf_Tour_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2exx.jpg","s":"Japan Pro Golf Tour 64 is a golf simulation game, developed for the short-lived Nintendo 64 Disk Drive add-on. It is best-known for being the only title for the system to offer a form of online play. The game features six gameplay modes, polygonal graphics, and a player editor. One or two players can compete in Match Play mode while up to four can compete for the best score in the 18-hole Stroke Player mode. The game also sports a Grand Opening Mode (compete with the world's best Japan Pro-Golfers,), a Career Mode, Qualifying Tournament (you create your own player and start with a handicap of 0) and Network Opening. The latter lets you connect to Randnet and compete in an All-Japan tournament."},{"t":"Jeremy McGrath Supercross 2000","p":["Nintendo 64","Game Boy Color","PlayStation","Dreamcast"],"d":"Acclaim Studios Salt Lake City","u":"Acclaim Entertainment","g":"Racing","r":"February 28, 2000","l":"https://en.wikipedia.org/wiki/Jeremy_McGrath_Supercross_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40o7.jpg","s":"Jeremy McGrath Supercross 2000 is a title based on the sport of motocross racing, where players can compete indoors, outdoors, in tournaments or in a series of freestyle challenges. The game is played from a perspective behind the bike as you strive to place first while negotiating the various hills and turns that characterize the dirt-filled tracks.\n\nA total of four game modes are available to aspiring riders: Race, Series Mode, Time Trial and Freestyle. Race is a contest to see who is the fastest driver on your choice of tracks; after the race is over, you can choose another track and rider or move on to another mode. Series Mode is the heart of the game, where you'll be able to embark on an Indoor SuperCross, Outdoor Nationals, Combined event or your own Custom series."},{"t":"Jet Set Radio","p":["Dreamcast"],"u":"Sega","r":"June 29, 2000","l":"https://en.wikipedia.org/wiki/Jet_Set_Radio"},{"t":"Jim Henson's Muppets","p":["Game Boy Color"],"d":"Tarantula Studios","g":"Platformer","r":"March 31, 2000","l":"https://en.wikipedia.org/wiki/Jim_Henson's_Muppets_(video_game)"},{"t":"Jinsei Game for Dreamcast","p":["Dreamcast"],"g":"Card & Board Game","l":"https://en.wikipedia.org/wiki/Jinsei_Game_for_Dreamcast","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48lx.jpg"},{"t":"Jissen Pachi-Slot Hisshouhou! @VPACHI: Kongdom","p":[],"l":"https://en.wikipedia.org/wiki/Jissen_Pachi-Slot_Hisshouhou!_@VPACHI:_Kongdom"},{"t":"JumpStart Kindergarten","p":["MS-DOS","Windows","macOS"],"d":"Fanfare Software","u":"Knowledge Adventure","g":"Educational","l":"https://en.wikipedia.org/wiki/JumpStart_Kindergarten"},{"t":"Kaged","p":["Windows"],"g":"Simulator, Adventure","l":"https://en.wikipedia.org/wiki/Kaged","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/wqh3esam9tg8zmpqga13.jpg","s":"A piece of Interactive Fiction written by Ian Finley. Winner of the 6th Annual Interactive Fiction Competition (2000)."},{"t":"Kao the Kangaroo","p":["Windows","Dreamcast"],"d":"X-Ray Interactive, Titus Interactive Studio","u":"Licomp Empik Multimedia, Titus Interactive","g":"Platform","r":"November 23, 2000","l":"https://en.wikipedia.org/wiki/Kao_the_Kangaroo_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co292m.jpg","s":"Action-adventure game released in 2000 by Tate Interactive. During development it was known as Denis the Kangaroo."},{"t":"Keep the Balance","p":["Windows","Game Boy Color"],"d":"Item Multimedia, Karma Studios","u":"JoWooD Productions","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Keep_the_Balance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/uch2gvkhzehwjcoehfbr.jpg","s":"Keep the balance! is a puzzle game, where you have to balance a big weighing scale. The longer it stays in balance the more point you gain. To do this, you have a catapult at your disposal, the objects you need to use to balance the scale are given to you by conveyor belt. One on the left and one on the right. But these objects differ in weight, so you must carefully choose the scales bucket you're going to put the objects in. To make things worse, all kinds of trouble appear on screen to make it just a little bit more challenging. Like crocodiles that eat object or jokers that throw around playing cards offsetting your carefully balance scale. The game stages 5 different game worlds each divided into 16 levels."},{"t":"Keitai Denjū Telefang","p":["Game Boy Color","Game Boy Advance"],"d":"Natsume Co., Ltd.","u":"Smilesoft","g":"Role-playing","r":"November 3, 2000","l":"https://en.wikipedia.org/wiki/Keitai_Denj%C5%AB_Telefang"},{"t":"Kengo: Master of Bushido","p":["PlayStation 2"],"d":"Lightweight","u":"Genki, Crave Entertainment, Crave/Ubi Soft","g":"Fighting","r":"December 14, 2000","l":"https://en.wikipedia.org/wiki/Kengo:_Master_of_Bushido","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2k2g.jpg","s":"The mind is a powerful weapon. So is the sword. When combined, they create the ultimate force. To be a Samurai master, you must silence one and make fierce the other. The rhythm of battle awaits you. Now, go young apprentice, and earn your glory."},{"t":"Kessen","p":["PlayStation 2"],"r":"March 4","l":"https://en.wikipedia.org/wiki/Kessen"},{"t":"Keyboardmania","p":["Arcade"],"d":"Konami","u":"Konami","g":"Music","l":"https://en.wikipedia.org/wiki/Keyboardmania","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u7z.jpg","s":"Keyboardmania (alternately KEYBOARD MANIA, and abbreviated KBM) is a rhythm video game created by the Bemani division of Konami. In this game up to two players use 24-key keyboards to play the piano or keyboard part of a selected song. Notes are represented on-screen by small bars that scroll downward above an image of the keyboard itself. The goal is to play the matching key when a note bar descends to the red play point line. The arcade cabinet has two screens - one for each player."},{"t":"Kikou Seiki Unitron","p":["Neo Geo Pocket Color"],"d":"Yumekobo","u":"SNK","g":"Role-playing game","r":"January 20, 2000","l":"https://en.wikipedia.org/wiki/Kikou_Seiki_Unitron","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xlp.jpg","s":"The game takes place 400 years after Biomotor Unitron. Kikou Seiki Unitron plays similar to Biomotor Unitron with top down dungeons and menu-based combat. The game requires the player to upgrade their unitron robot with various weapons and accessories to compete against various enemies within the dungeon areas. Using a link cable two players can pit their unitrons against each other in a head-to-head battle."},{"t":"Kirby 64: The Crystal Shards","p":["Nintendo 64"],"r":"March 24"},{"t":"Kiss Pinball","p":["Windows"],"d":"Wildfire Studios, Tarantula Studios","u":"On Deck Interactive, Take-Two Interactive","g":"Pinball","r":"November 3, 2000","l":"https://en.wikipedia.org/wiki/Kiss_Pinball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6smt.jpg","s":"The storyline for KISS Pinball revolves around the band battling the Dark Lord and claiming the \"Kissneth\" as their own. Your objectives include getting past security to snag an autograph, lighting \"PASS\" to access backstage, collecting weapons, shooting a spinner to upgrade record sales, hitting the Statue of Liberty repeatedly to reveal the Destroyer Skull to start 3-ball, spelling \"MAYHEM\" to light video mode, collecting lost souls, discovering hidden power-ups, locking balls with Gene's tongue and much more.\n\nYour perspective is directly above each table. You can see approximately one-third of the playfield at a time with the screen scrolling to follow the course of the ball. Each table has the standard two-flipper layout, with the ability to nudge the table up, left, and right to influence ball movement. But be careful not to \"tilt\" the machine!"},{"t":"Kiss: Psycho Circus - The Nightmare Child","p":["Windows","Dreamcast"],"d":"Third Law Interactive, Tremor Entertainment","u":"Gathering of Developers, Take-Two Interactive","g":"First-person shooter","r":"July 20, 2000","l":"https://en.wikipedia.org/wiki/Kiss:_Psycho_Circus_-_The_Nightmare_Child","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40po.jpg","s":"Wicked Jester, a band of four, are headed for a Friday night gig at The Coventry, a rundown dive outside of town. They arrive only to find the parking lot deserted, the club seemingly dead. The band's members: Pablo Ramirez, Andy Chang, Gabriel Gordo and Patrick Scott, stepping from their van, are startled by a voice from the shadows. She offers them four tickets to a circus -- tonight's the grand finale! Having nothing better to do, the four accept and the nightmare begins.\n\nBased on characters from comic book author Todd McFarlane, KISS Psycho Circus: The Nightmare Child brings the horror and carnage of the Psycho Circus to the PC in a shooter format. There are two-dozen creatures to battle with and three classes of weapons to use, each with four specific types: melee (beast claws, thornblade, twister and punisher), common (zero cannon, magma cannon, windblade and scourge) and ultimate (stargaze, galaxion, spirit lance and draco). In addition to the weaponry, temporary power-ups and instant items such as health, attack and defense powers are available."},{"t":"Kiteretsu Shounen's Gangagan","p":[],"l":"https://en.wikipedia.org/wiki/Kiteretsu_Shounen's_Gangagan"},{"t":"Knockout Kings 2001","p":["PlayStation"],"d":"Black Ops Entertainment","u":"EA Sports","g":"Boxing","r":"October 31, 2000","l":"https://en.wikipedia.org/wiki/Knockout_Kings_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1owi.jpg","s":"All the egomaniacal, violent splendor of heavyweight boxing comes to the PlayStation 2 in Knockout Kings 2001 by EA Sports. This title employs EA's new CyberScan technology, which allows the boxers faces to be accurately reproduced in full polygonal glory. In addition to the graphical overhaul, the game features new modes of play and simplified control. Choose your champion from a stable of boxing's greatest, including Muhammad Ali, Joe Louis, Rocky Marciano, and Lennox Lewis. A new career mode allows you to play through several weight classes and to box at famous arenas all around the world."},{"t":"Kurt Warner's Arena Football Unleashed","p":["PlayStation"],"d":"Midway Games","u":"Midway Home Entertainment","g":"Sports","r":"May 18, 2000","l":"https://en.wikipedia.org/wiki/Kurt_Warner's_Arena_Football_Unleashed"},{"t":"L.O.L.: Lack of Love","p":["Dreamcast"],"d":"Love-de-Lic","u":"ASCII Corporation","g":"Life simulation","r":"November 2, 2000","l":"https://en.wikipedia.org/wiki/L.O.L.:_Lack_of_Love","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tqs.jpg","s":"L.O.L: Lack Of Love, is an evolutionary adventure game developed by Love-de-Lic and published by ASCII Entertainment for the Sega Dreamcast. The game was released exclusively in Japan on November 2, 2000."},{"t":"Lake Masters Pro Dreamcast Plus!","p":[],"l":"https://en.wikipedia.org/wiki/Lake_Masters_Pro_Dreamcast_Plus!"},{"t":"Laser Arena","p":["Windows"],"d":"Trainwreck Studios","u":"ValuSoft","g":"First-person shooter","r":"September 2000","l":"https://en.wikipedia.org/wiki/Laser_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ut8.jpg"},{"t":"Last Call","p":["Windows","macOS"],"d":"Cutler Creative","u":"Simon & Schuster Interactive","r":"March 27, 2000","l":"https://en.wikipedia.org/wiki/Last_Call_(video_game)"},{"t":"Le Mans 24 Hours","p":["Dreamcast"],"u":"Sega","r":"November 13, 2000","l":"https://en.wikipedia.org/wiki/Le_Mans_24_Hours_(video_game)"},{"t":"Legacy of Kain: Soul Reaver","p":["Dreamcast"],"u":"Eidos Interactive","r":"January 27, 2000"},{"t":"Lego Alpha Team","p":["Windows","Game Boy Color"],"d":"Digital Domain, Climax Studios","u":"Lego Media","g":"Puzzle","r":"September 22, 2000","l":"https://en.wikipedia.org/wiki/Lego_Alpha_Team_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8jg.jpg","s":"Based on the LEGO toy line of the same name. Solve puzzles and lead the Alpha Team to thwart the evil Ogel's plans for world domination."},{"t":"Lego Creator: Knights' Kingdom","p":["Windows"],"d":"Superscape","u":"Lego Software","g":"Construction and management simulation","r":"October 2, 2000","l":"https://en.wikipedia.org/wiki/Lego_Creator:_Knights'_Kingdom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4fgg.jpg","s":"LEGO Creator: Knights' Kingdom is a construction simulation video game for Microsoft Windows; it uses virtual Lego pieces to build a medieval kingdom and then use the kingdom in a battle against the character Cedric the Bull."},{"t":"Lego Stunt Rally","p":["Windows"],"r":"September 13","l":"https://en.wikipedia.org/wiki/Lego_Stunt_Rally"},{"t":"Legoland","p":["Windows"],"d":"Krisalis Software","u":"Lego Media","g":"Construction and management simulation","r":"May 1, 2000","l":"https://en.wikipedia.org/wiki/Legoland_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co61mq.jpg","s":"Legoland is an educational game that shows how to build a good park. You get the job as a park manager at a LEGOLAND Park. Professor Voltage creates a time machine, and when showing it to all the other park employees, the time machine breaks and the park blows up. As park manager you, the loudspeaker man Johnathon Ablebody, and Professor Voltage have to rebuild the park and make it better than before."},{"t":"Lemmings Revolution","p":["Windows"],"d":"Psygnosis Leeds","u":"Take-Two Interactive","g":"Puzzle","r":"May 1, 2000","l":"https://en.wikipedia.org/wiki/Lemmings_Revolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44e4.jpg","s":"An installation in the Lemmings franchise where players control lemmings within cylindrical environments."},{"t":"Links 2001","p":["Windows","macOS"],"d":"Access Software, Microsoft Games Group","u":"Microsoft","g":"Sports","r":"October 2000","l":"https://en.wikipedia.org/wiki/Links_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8hzk.jpg","s":"The venerable golf simulation from Access (nee Microsoft) returns.\n\nNew features in this updated version include new graphics and ball physics, new courses and tour players, centimeter accurate greens, custom club distances; faster, easier online play and golfers that each have their own personalities.\n\nIncluded in the game are some of your favourite golfing heros, Arnold Palmer, Sergio Garcia and Annika Sörenstam to mention a few. Play as them or against them.\n\nThere are six world-class courses featured in the game, San Diego's Aviara, Canada's Chateau Whistler, The Prince Course on Kauai, Hawaii; Westfields Golf Club, St Andrews Old Course and Mesa Roja fantasy course. More courses can be downloaded for free from the Web.\n\nAlso included in the game is the Arnold Palmer Course Designer. Build your dream course, from the tee to the fairway to the hole."},{"t":"Little Fighter 2","p":["Windows"],"d":"Marti Wong, Starsky Wong","g":"Beat 'em up","l":"https://en.wikipedia.org/wiki/Little_Fighter_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ern.jpg","s":"Little Fighter 2 is a popular Hong Kong freeware PC fighting game for Windows and is the sequel to the game Little Fighter (LF1). Little Fighter 2 was created by Marti Wong and Starsky Wong in 1999, and released in a long series of updates.\nThe game supports up to 4 human players on one computer and a total of 8 characters using online play or computer-controlled opponents. Characters are controlled using the keyboard or a gamepad. All keys can be set via a configuration menu.\nThe game has a commercially released sequel, Little Fighter Online. In 2009, in celebration of Little Fighter 2's tenth anniversary, version 2.0 was released. The update fixed minor bugs and added a gameplay recording feature, a new stage called 'Survival', a browser toolbar that is not mentioned in the installation process and obstructive ads being displayed while the game is being loaded. Version 2.0a was released in late 2009, with only a bug fix."},{"t":"Little Nicky","p":["Game Boy Color"],"d":"Digital Eclipse","u":"Ubisoft","g":"Platform","r":"December 23, 2000","l":"https://en.wikipedia.org/wiki/Little_Nicky_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7x6x.jpg","s":"Satan wants to appoint a new ruler in Hell. However, nobody meets his high standards, so the dark prince must remain atop Hell's throne. Displeased by their father's lack of confidence in them, Adrian and Cassius leave Hell and go to Earth to create a new Hell. Since Satan has no time to deal with Adrian and Cassius, he sends his other son Nicky to stop them. You take the role of Nicky as he travels through 24 levels, where he must collect a certain number of items or destroy demons. However, the key to making it through all of the levels is Nicky's power. When Nicky gets close to fire, his powers increase. He will run faster, jump higher, and spit fireballs. Should he get too hot, Nicky will be unable to control his powers until he cools down. Help Nicky capture Adrian and Cassius in LITTLE NICKY."},{"t":"Looney Tunes Collector: Martian Alert!","p":["Game Boy Color"],"d":"Infogrames Lyon House","u":"Infogrames","g":"Action","r":"June 26, 2000","l":"https://en.wikipedia.org/wiki/Looney_Tunes_Collector:_Martian_Alert!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7xtn.jpg","s":"Marvin the Martian's faithful companion K-9 cleaned out the flying saucer. In doing so, K-9 accidentally threw out 10 pieces of the teleporter that are required to execute Marvin's plan to destroy the Earth. Bugs Bunny happens to overhear the Martian's plan, and now he must travel throughout the world and collect the other Looney Tunes characters 47 in all. While Bugs can perform basic tasks, solving all of the game's puzzles and collecting all 10 teleporter pieces requires the special skills and talents of each character. For example, Elmer Fudd can blast obstacles with his gun, while Daffy Duck can swim and dive into deep water. Learning how and when to use each character is the key to success in LOONEY TUNES COLLECTOR: Alert!"},{"t":"Looney Tunes Collector: Martian Revenge!","p":["Game Boy Color"],"d":"Infogrames Lyon House","u":"Infogrames","g":"Action","r":"November 23, 2000","l":"https://en.wikipedia.org/wiki/Looney_Tunes_Collector:_Martian_Revenge!"},{"t":"Looney Tunes Racing","p":["PlayStation","Game Boy Color"],"d":"Circus Freak Studios, Xantera","u":"Infogrames","g":"Racing","r":"November 28, 2000","l":"https://en.wikipedia.org/wiki/Looney_Tunes_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3df7.jpg","s":"Rev your engines - It's time to burn some Looney Tunes rubber! ACME Corporation, the corporate juggernaut behind such successful products as the Acme Disintegrator Gun and the Acme Portable Hole, is sponsoring a number of racing contests all over the universe for the Looney Tunes characters to compete for the looniest racing champion title."},{"t":"Looney Tunes: Space Race","p":["Dreamcast"],"d":"Infogrames Melbourne House","u":"Infogrames","g":"Kart racing","r":"November 3, 2000","l":"https://en.wikipedia.org/wiki/Looney_Tunes:_Space_Race","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7xg0.jpg","s":"Looney Tunes: Space Race features eight all-time favorite characters, including Bugs Bunny, Daffy Duck, Taz, Sylvester, Yosemite Sam, and Wile E. Coyote. The 12 tracks include shortcuts, jumps, and traps, and there are over 40 competitive events. Players can pummel opponents with gags like the portable hole, falling elephants, retractable boxing glove, and instant storm. Up to four players can race at a time."},{"t":"Love Hina: Totsuzen no Engeji Happening","p":["Dreamcast"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Love_Hina:_Totsuzen_no_Engeji_Happening","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5vrv.jpg","s":"There is a new girl in the Hinata Sou. Her name is Fujisawa Mizuho and she is a Tokyo University Student. She is asked by Keitarou-kun's grandmother to become a tutor for Keitarou-kun. If Keitarou-kun fail to pass the coming Entrance Exam for Tokyo University, Mizuho-chan says that she will take the responsibility for it and marry Keitarou-kun."},{"t":"Love Story","p":["PlayStation 2"],"d":"General Entertainment","u":"Enix","g":"Adventure, interactive movie, visual novel","r":"April 27, 2000","l":"https://en.wikipedia.org/wiki/Love_Story_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5rlw.jpg","s":"ØSTORY (Love Story) is a full-motion video adventure about a dead man after a motorcycle accident. Then appears the Japanese Angel of Love, who gives them a second chance, so long as Rina falls in love with them in 6 days. Developed by General Entertainment and published by Enix in 2000."},{"t":"Madden NFL 2001","p":["PlayStation 2","PlayStation","Nintendo 64","Game Boy Color"],"u":"EA Sports","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/Madden_NFL_2001"},{"t":"Majesty: The Fantasy Kingdom Sim","p":["Windows","macOS","Mobile phone"],"d":"Cyberlore Studios, HeroCraft","u":"Hasbro Interactive, MacPlay","g":"Real-time strategy","r":"March 21, 2000","l":"https://en.wikipedia.org/wiki/Majesty:_The_Fantasy_Kingdom_Sim","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qmt.jpg","s":"Majesty is a fantasy kingdom simulation game where players build, tax, and manage their kingdom, but the units control themselves."},{"t":"Mario Party 2","p":["Nintendo 64"],"r":"January 24","l":"https://en.wikipedia.org/wiki/Mario_Party_2"},{"t":"Mario Party 3","p":["Nintendo 64"],"r":"December 7","l":"https://en.wikipedia.org/wiki/Mario_Party_3"},{"t":"Mario Tennis","p":["Nintendo 64","Game Boy Color"],"u":"Nintendo","r":"July 21, 2000","l":"https://en.wikipedia.org/wiki/Mario_Tennis"},{"t":"Marionette Handler 2","p":["Dreamcast"],"g":"Strategy","l":"https://en.wikipedia.org/wiki/Marionette_Handler_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nw0.jpg","s":"Sequel to Marionette Handler a turn-based strategy game on Dreamcast."},{"t":"Mars Matrix","p":["Arcade","Dreamcast"],"d":"Takumi Corporation","u":"Capcom","g":"Scrolling shooter","r":"April 2000","l":"https://en.wikipedia.org/wiki/Mars_Matrix","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25gc.jpg","s":"A prediction is that before human civilization, there was once an advanced civilization on Mars. A sorceress destroyed the civilization and everything that was remembered of it, except a chip called \"INFINITY\". In 2100, millions of people were starving due to massive food shortages and has caused civil wars around the world. Centuries later, however, the world government had sent colonists to Mars which began to solve these problems. At a nearby farm, the Infinity chip was discovered and it revealed all the technology of the advanced civilization. In 2309, a Declaration of Independence has been sent to Earth. Large armies have been amassed on Mars, and a gigantic armada was waiting for any attack from Earth. The Earth government sends out a fleet of battleships followed by a special air raid unit called ACID; ACID is equipped with a new fighter ship known as the Mosquito. Their mission is to enter Mars, stop the rebel violence, locate and destroy the rebel leader, whoever... or whatever it may be..."},{"t":"Martian Gothic: Unification","p":["Windows"],"d":"Creative Reality, Coyote Developments","u":"TalonSoft, Take-Two Interactive","g":"Survival horror","r":"April 28, 2000","l":"https://en.wikipedia.org/wiki/Martian_Gothic:_Unification","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4puk.jpg","s":"Martian Gothic : Unification is one of the numerous titles which came out at the end of the PlayStation lifespan. At first glance, it looks like a typical Resident Evil rip-off with a futuristic paint, a disturbing cover and bad voice-acting. Of course, the game ended up selling very poorly. But it's so much more than that.\n\nIncidentally, it is also Creative Reality's last game. Sharing the same team and the same writer than Dreamweb, it comes as no surprise that the game heavily relies on writing and puzzles. This reliance (and a few more things) makes Martian Gothic: Unification a title to look back at."},{"t":"Marvel vs Capcom 2","p":["Dreamcast"],"r":"June 29","l":"https://en.wikipedia.org/wiki/Marvel_vs_Capcom_2"},{"t":"Marvel vs. Capcom 2: New Age of Heroes","p":["Dreamcast"],"u":"Capcom","r":"March 30, 2000"},{"t":"Mary-Kate and Ashley: Get A Clue","p":["Game Boy Color"],"d":"Crawfish Interactive","u":"Acclaim Entertainment","r":"May 31, 2000","l":"https://en.wikipedia.org/wiki/Mary-Kate_and_Ashley:_Get_A_Clue"},{"t":"Mary-Kate and Ashley: Pocket Planner","p":["Game Boy Color"],"d":"Powerhead Games","u":"Acclaim Entertainment","g":"Digital planner, Minigames","r":"November 21, 2000","l":"https://en.wikipedia.org/wiki/Mary-Kate_and_Ashley:_Pocket_Planner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co83uy.jpg","s":"Is your life totally disorganized? Do you lose track of what you need to do? Have you lost the phone number of the cutest guy in school? Get organized with MARY-KATE & ASHLEY: Pocket Planner for the Game Boy Color. Use the calendar to keep track of all those really important messages and never forget a phone number with the phone book. You can also write super-secret messages to your friends and beam them to another Game Boy Color. In addition to these features, several games have been included. You can help raise Mary-Kate and Ashley's dog, Clue. If you have a question, go to Ask Ashley, and she will check her crystal ball for an answer. If you are completely unorganized and need some help, run out and get MARY-KATE & ASHLEY: Pocket Planner."},{"t":"Master of the Skies: The Red Ace","p":["Windows"],"d":"Fiendish Games","u":"Small Rockets","g":"Vehicle simulation game, action","r":"April 30, 2000","l":"https://en.wikipedia.org/wiki/Master_of_the_Skies:_The_Red_Ace","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lfi3ltpyst2985fsqmdh.jpg","s":"WWI dogfighting game."},{"t":"Maximum Pool","p":["Windows","macOS","Dreamcast"],"d":"Dynamix","u":"Sierra Sports","g":"Sports","r":"September 8, 2000","l":"https://en.wikipedia.org/wiki/Maximum_Pool","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40p7.jpg","s":"Rack 'em up with seven classic pool games featuring super-accurate physics, video-captured opponents, and online play. Earn access to five crazy bonus games by beating a tough opponent or joining an online game!"},{"t":"MDK2","p":["Dreamcast","Windows"],"u":"Interplay Entertainment","g":"Action","r":"March 31, 2000","l":"https://en.wikipedia.org/wiki/MDK2","i":"images/steam-38460.jpg","s":"3 Unlikely Heroes, 1 Ultimate Goal Kurt Hectic is back to save the universe. This time he is teamed with the genius Dr. Hawkins and the 6-legged gun-toting robotic dog, Max. Together they must out-sneak, out-blast and out-think their enemies as they attempt to reclaim earth from a vile alien menace."},{"t":"MechWarrior 4: Vengeance","p":["Windows","Arcade"],"r":"November 23"},{"t":"Medal of Honor: Underground","p":["PlayStation"],"d":"DreamWorks Interactive, Rebellion Developments","u":"Electronic Arts, Destination Software, Zoo Digital Publishing","g":"First-person shooter","r":"October 25, 2000","l":"https://en.wikipedia.org/wiki/Medal_of_Honor:_Underground","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8yzk.jpg","s":"The game is a prequel to Medal of Honor and it is set in the early stages of WWII. You play as Manon Batiste, who briefed the missions for you in the original Medal of Honor. She is a new member of a small band of French rebels who fight against the tyranny of the Germans.\n\nThere are 7 missions in total, featuring 12 different historical weapons. There are NPCs helping you out by cracking safes and driving. Not all enemies are on foot; expect to face tanks and bikes amongst other things."},{"t":"MediEvil 2","p":["PlayStation"],"d":"Sony Computer Entertainment Europe","u":"Sony Computer Entertainment","g":"Action-adventure, hack and slash","r":"April 21, 2000","l":"https://en.wikipedia.org/wiki/MediEvil_2"},{"t":"Mega Man Legends 2","p":["Windows","PlayStation"],"r":"October 24","l":"https://en.wikipedia.org/wiki/Mega_Man_Legends_2"},{"t":"Mega Man Xtreme","p":["Game Boy Color"],"d":"Capcom","u":"Capcom","g":"Platform","r":"October 20, 2000","l":"https://en.wikipedia.org/wiki/Mega_Man_Xtreme","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co202i.jpg","s":"The future world is in turmoil. The peace keeping mother computer has been hacked and a virus runs rampant throughout the world. Only Mega Man X has the ability to traverse eight dangerous levels in cyberspace, battle huge bosses along the way and restore the mother computer to its normal state. When the going gets too intence, Mega Man X's pal, Zero can be summoned to help him out of the most dangerous situations. It's an X-treme situation that only Mega Man X can resolve!"},{"t":"Men in Black 2: The Series","p":["Game Boy Color"],"d":"David A. Palmer Productions","u":"Crave Entertainment","g":"Action, platform","r":"June 2000","l":"https://en.wikipedia.org/wiki/Men_in_Black_2:_The_Series","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d0z.jpg","s":"Based on the cartoon series of the same name, MEN IN BLACK: The Series 2 starts with aliens invading the Earth. It is up to a covert organization, known only as Men In Black, to stop the invasion. You take the role of Agent J as he hunts down 12 different alien races, including the Skraaldians and the Fmeck. Luckily, J has a wide range of weapons to help him put an end to the alien menace; most notable is the Noisy Cricket. While most aliens are relatively easy to spot, some can change shape and will not reveal themselves until J gets close to them...so keep your eyes peeled. When a stage is cleared, you are treated to an animated sequence that advances the plot. Will the Agent J be able to save the world? Play MEN IN BLACK: The Series 2 and find out."},{"t":"Mercedes-Benz Truck Racing","p":["Windows"],"d":"Synetic","u":"THQ","g":"Racing","l":"https://en.wikipedia.org/wiki/Mercedes-Benz_Truck_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yd5.jpg","s":"Mercedes-Benz Truck Racing is a truck racing game based on the BreakNeck engine, with the Mercedes license behind it. Test your skills in racing a million-dollar souped-up Freightliner in a 1st or 3rd person view. The game supports a variety of steering devices, though a simple keyboard will do. It features real truck racing teams and drivers, realistic damage, a replay editor, and an optional unlimited speed mode (trucks are normally limited to 160 km/h to minimize the damage these 5 tonners do when they spin out of control). Compete in a single race or full season mode on a number of licensed race tracks from around Europe, or practice all tracks with or without a Ghost truck."},{"t":"Mercurius Pretty: End of the Century","p":["Dreamcast"],"g":"Simulator, Adventure","l":"https://en.wikipedia.org/wiki/Mercurius_Pretty:_End_of_the_Century","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobnqz.jpg","s":"A remake of the PC-98 life simulation \"Mercurius Pretty\" for the Sega Dreamcast. The main subject is to raise a fairy!"},{"t":"Merlin","p":["Game Boy Color"],"d":"RFX Interactive","u":"Light & Shadow Production, Electronic Arts","g":"Action","r":"December 2000","l":"https://en.wikipedia.org/wiki/Merlin_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1hkm.jpg","s":"Join Merlin, the greatest magician of all time, in his quest to save the five mystical worlds from the evil Dragon. Legend's told of the Dragon who would emerge from his sleep every thousand years to reign over the Earth, peace and harmony would give way to war and disaster. Already kindly magical creatures of the worlds have been enslaved by the dragon to carry out his evil designs. \nCan Merlin restore peace and harmony to the mystical realms?"},{"t":"Messiah","p":["Windows"],"d":"Shiny Entertainment","u":"Interplay Entertainment","g":"Action-adventure","r":"March 29, 2000","l":"https://en.wikipedia.org/wiki/Messiah_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa3t3.jpg","s":"Bob is an angel ordered by God himself to go and clean up the putrid world of the future. He has been given the power of possession so that he can sneak up on any person, animal or genetically engineered being and leap right into their souls!\nThe rules are up to you - enjoy the freedom."},{"t":"Metal Fatigue","p":["Windows"],"d":"Zono","u":"Psygnosis, TalonSoft","g":"Real-time strategy","r":"May 18, 2000","l":"https://en.wikipedia.org/wiki/Metal_Fatigue_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3nuk.jpg","s":"Lead one of the three warring factions to victory as one of three brothers; Jonus, Stefan or Diego. Only one faction will stand above the rest in the end; Mil-Agro, Rimtech or Neuropa. The Hedoth technology will decide the course of the war, in particular the end."},{"t":"Metal Gear Solid ( Metal Gear: Ghost Babel )","p":["Game Boy Color"],"u":"Konami","r":"April 24, 2000"},{"t":"Metal Gear: Ghost Babel","p":["Game Boy Color"],"r":"May 5"},{"t":"Metal Slader Glory","p":["Nintendo Entertainment System","Super Nintendo Entertainment System"],"d":"HAL Laboratory","u":"HAL Laboratory","g":"Adventure","r":"November 29, 2000","l":"https://en.wikipedia.org/wiki/Metal_Slader_Glory"},{"t":"Metal Slug 2nd Mission","p":["Neo Geo Pocket Color"],"r":"May 22","l":"https://en.wikipedia.org/wiki/Metal_Slug_2nd_Mission"},{"t":"Metal Slug 3","p":["Arcade","Neo Geo AES"],"d":"SNK, Noise Factory, DotEmu, Code Mystics","u":"SNK, Playmore, MEGA, Ignition Entertainment","g":"Run and gun","r":"March 23, 2000","l":"https://en.wikipedia.org/wiki/Metal_Slug_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobu6p.jpg","s":"“METAL SLUG 3”, the masterpiece in SNK’s emblematic 2D run & gun action shooting game series, still continues to fascinate millions of fans worldwide to this day for its intricate dot-pixel graphics, and simple and intuitive game controls!"},{"t":"Metropolis Street Racer","p":["Dreamcast"],"u":"Sega","r":"November 3, 2000","l":"https://en.wikipedia.org/wiki/Metropolis_Street_Racer"},{"t":"Mia's Science Adventure: Romaine's New Hat","p":["Windows","macOS"],"d":"Kutoka Interactive","u":"Kutoka Interactive","g":"Educational","l":"https://en.wikipedia.org/wiki/Mia's_Science_Adventure:_Romaine's_New_Hat"},{"t":"Michelin Rally Masters: Race of Champions","p":["Windows","PlayStation"],"d":"Digital Illusions CE","u":"Infogrames","g":"Racing","r":"April 12, 2000","l":"https://en.wikipedia.org/wiki/Michelin_Rally_Masters:_Race_of_Champions","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa3st.jpg","s":"This is the OFFICIAL game of the real Race of Champions! Take the various authentic ROC cars (22 in all) through different tracks on head-to-head SuperSpecial challenge modes or traditional rally stages as you speed and slide through mud, gravel, snow, and more. Five levels of difficulty will let you learn at your own pace. Multiple game modes (RoC, Challenge Cup, Challenge Trophy, time attack, single race, single stage) keep you challenged. Run races online with other players through dedicated servers or setup your own."},{"t":"Mickey's Speedway USA","p":["Nintendo 64"],"d":"Rare","u":"Nintendo","g":"Kart racing","r":"November 13, 2000","l":"https://en.wikipedia.org/wiki/Mickey's_Speedway_USA","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tem.jpg","s":"Buckle up and get ready to race! Rally across America with Mickey and friends! Race around 20 All-American courses - from Alaska to the Everglades - as you try to track down the Weasels and rescue poor dognapped Pluto. Use Ludwig Von Drake's wacky weapons - such as the \"Antigrav-o-Kit Magno Flyer\" or the \"Stormy Weather Whenever Engager\" - to give you the edge. Then blast past your friends and listen as the drivers taunt each other using Disney's original character voices!"},{"t":"Micro Maniacs","p":["PlayStation"],"d":"Codemasters","u":"Codemasters, THQ","g":"Racing","r":"April 7, 2000","l":"https://en.wikipedia.org/wiki/Micro_Maniacs"},{"t":"Microsoft Baseball 2001","p":["Windows"],"d":"Microsoft","u":"Microsoft","g":"Sports","r":"March 2000","l":"https://en.wikipedia.org/wiki/Microsoft_Baseball_2001"},{"t":"Microsoft Golf 2001 Edition","p":["Windows"],"d":"Microsoft","u":"Microsoft","g":"Sports","r":"August 24, 2000","l":"https://en.wikipedia.org/wiki/Microsoft_Golf_2001_Edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8qbo.jpg","s":"Take your golfing game to seven different authentically recreated courses. With over a dozen different scoring modes, Zone and LAN multiplayer support, this game has plenty of options for you to play even if you've never laid hands on a golf club before. Full tutorial and quickstart options ease you into the game. Multiple swing methods and customizations keep the game catering to you, not the other way around."},{"t":"Midnight Club: Street Racing","p":["PlayStation 2"],"r":"October 26"},{"t":"Midtown Madness 2","p":["Windows"],"d":"Angel Studios","u":"Microsoft","g":"Racing","r":"September 21, 2000","l":"https://en.wikipedia.org/wiki/Midtown_Madness_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6t3f.jpg","s":"Midtown Madness 2 is a free roam racing/arcade sequel to Midtown Madness, part of the Midtown Madness series, developed by Angel Studios (now Rockstar San Diego) and published by Microsoft, which features a range of vehicles that can be driven around London and San Francisco."},{"t":"Midway's Greatest Arcade Hits","p":["Dreamcast","Nintendo 64"],"d":"Digital Eclipse","u":"Midway","g":"Various","r":"June 27, 2000","l":"https://en.wikipedia.org/wiki/Midway's_Greatest_Arcade_Hits"},{"t":"Might and Magic VIII: Day of the Destroyer","p":["Windows"],"d":"New World Computing","u":"The 3DO Company, Imagineer","g":"Role-playing","r":"March 2, 2000","l":"https://en.wikipedia.org/wiki/Might_and_Magic_VIII:_Day_of_the_Destroyer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3jhz.jpg","s":"The Destroyer again walks the land. In the four corners of the world gates to the planes of Fire, Air, Earth, and Water have opened and denizens of those realms are sweeping across the lands. Lead a band of rugged adventures on a most perilous mission to save the world. This is not necessarily an adventure just for Knights, and Clerics, you may need to enlist the aid of the darker races such as, Trolls, Dark Elves, and Minotaurs. Save the kingdoms from ruin or watch as the lands are decimated forever in Might and Magic VIII."},{"t":"Mighty! Pang","p":["Arcade"],"g":"Shooter, Arcade","l":"https://en.wikipedia.org/wiki/Mighty!_Pang","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3mar.jpg","s":"Mighty! Pang is an arcade-style action game where players shoot wires to pop balloons that bounce around the screen. Balloons split into smaller ones when hit, and disappear when reduced to their smallest size. Touching a balloon results in losing a life. The game features three modes:\n\nTour Mode: Clear each stage by eliminating all balloons while traveling through different locations.\n\nPanic Mode: Survive as long as possible against an endless wave of balloons.\n\nExpert Mode: Tackle challenging stages designed for experienced players."},{"t":"Mike Tyson Boxing","p":["PlayStation"],"d":"Codemasters, Virtucraft","u":"Codemasters, Ubi Soft","g":"Sports, fighting","r":"October 31, 2000","l":"https://en.wikipedia.org/wiki/Mike_Tyson_Boxing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4o41.jpg","s":"Mike Tyson Boxing is a 3D simulation based on one of the best-known fighters of the '80s and '90s. The game offers three main modes of play: \"Vs.\" mode offers fast, arcade-style matches in which the loser walks and the winner stays on to meet the next challenger. \"Showcase\" mode allows up to eight players and eight CPU boxers to meet for rotating tournament action. In \"World\" mode, the player starts with a rookie fighter and guides his career fight after fight through the ranks of contenders until he finally faces the champ for the belt. Mike Tyson Boxing features over 90 different boxers and 16 world-class venues.\n\nFighters can interact with the ring environment and blood, sweat, and bruises are graphically depicted on the characters. Scoring is based on the point system used in real boxing and a special score bar helps players keep track of how they are doing in the heat of battle."},{"t":"Millennium Winter Sports","p":["Game Boy Color"],"d":"Konami","u":"Konami","g":"Snowboarding","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Millennium_Winter_Sports","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/krduzdl8bnvdzj8zfloh.jpg","s":"MILLENNIUM WINTER SPORTS allows you to experience the thrill of victory and the agony of defeat in eight winter sports. Try to get through the course as fast a possible in the bobsled; out-skate your opponent to the finish line in speed skating; see who can jump the farthest in two separate ski-jumping events; see if you can pull off twists and flips while flying through the air in the aerials competition; strap on the skis and navigate the downhill course; or strap on a snowboard to navigate the giant slalom course. For the ultimate in snowboarding action, try to impress the judges with your performance on the halfpipe. Practice any of the events in the Challenge mode or try to become the best winter athlete in the world with the Championship mode. All of the action of winter sports can be yours with MILLENNIUM WINTER SPORTS."},{"t":"Missing on Lost Island","p":["Windows"],"d":"Mayhem Studios","u":"Bohemia Interactive, ARI Data, Gamepad","g":"Adventure","l":"https://en.wikipedia.org/wiki/Missing_on_Lost_Island","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1l25.jpg","s":"Czech adventure classic."},{"t":"MLB 2001","p":["PlayStation"],"d":"989 Sports","u":"989 Sports","g":"Sports","r":"March 28, 2000","l":"https://en.wikipedia.org/wiki/MLB_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lfo2tgfdeahqc8pgxwks.jpg","s":"Developed by Sony Computer Entertainment America and published under the 989 Sports label. Once again, Vin Scully is the play-by-play announcer with Dave Campbell on color commentary. Chipper Jones of the Atlanta Braves was featured on the cover."},{"t":"Mobile Suit Gundam: Journey to Jaburo","p":["PlayStation 2"],"d":"Bandai","u":"Bandai","g":"Action","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Mobile_Suit_Gundam:_Journey_to_Jaburo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9cqh.jpg","s":"Mobile Suit Gundam: Journey to Jaburo is an action game based directly on the Mobile Suit Gundam films and series. The game begins at the start of the series and ends at the ending of the second film. The game plays in an action game format with a standard third person view. It features newly hand animated cutscenes that depict events from the original television series as well as a CGI opening depicting a space battle from the One Year War and then a scene of the Gundam destroying several Zaku IIs before being attacked by Char Aznable. It is also the prequel to Mobile Suit Gundam: Encounters in Space.\n\nThe English dub of the video game features the voices of the actors who were cast for the Mobile Suit Gundam television series as with most games subsequent to the series' dubbing, rather than the English cast of the films.\n\nJourney to Jaburo takes place during the One Year War, and depicts the crew of the White Base making their way from the Side 7 sector of space colonies to the Federation headquarters at Jaburo. The game starts at Amuro Ray's home of Side 7, where three Zaku mobile suits attack the Federation's prototype mobile suit weapons. Amuro, in the confusion, fights the Zaku units in the Gundam, and is assigned to the White Base as the Gundam's pilot. After the White Base leaves the colony, it is pursued by Char Aznable, \"The Red Comet\".\n\nChar attacks the White Base during re-entry (where the power of the Gundam's beam rifle was revealed), which diverts them into the Zeon-controlled territory of North America. After going through many Zeon defenses (including Garma Zabi in Seattle), the White Base heads into Asia, where they battle Ramba Ral, an ace pilot who raised Sayla Mass when she was a child. After Ramba Ral commits suicide by jumping into Gundam's hand with a grenade, the White Base crew makes their way to Belfast for repairs.\n\nAfter they leave Belfast, they eventually make it to Jaburo, where Char's \"Mad Angler\" squadron finds the location of the base, and launches a massive attack to conquer it. The Zeon forces are beaten back, and the White Base, now dubbed the \"13th Autonomous Mobile Squadron\", heads out into space."},{"t":"MoHo","p":["PlayStation","Dreamcast","Windows"],"d":"Lost Toys","u":"Take-Two Interactive","g":"Action video game","r":"July 27, 2000","l":"https://en.wikipedia.org/wiki/MoHo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40ef.jpg","s":"MoHo is a Sega Dreamcast game developed by Lost Toys and published by Take 2 Interactive in 2000. It is notable for being the only exclusive Dreamcast game for the United Kingdom, despite receiving ratings from the German USK and French SELL ratings bodies and having its back cover description translated into German.\n\nAn American release under the name of Ball Breakers was planned for release in November 2000[5], but cancelled near completion; three different rips of a late prototype were leaked simultaneously in 2012."},{"t":"Monet: The Mystery of the Orangery","p":["Windows"],"d":"index+, Media Factory","u":"Wanadoo Edition","g":"Adventure game, edutainment","l":"https://en.wikipedia.org/wiki/Monet:_The_Mystery_of_the_Orangery"},{"t":"Monkey Puncher","p":["Game Boy Color"],"d":"Atelier Double","u":"Event Horizon Software, Taito","g":"Strategy","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/Monkey_Puncher","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8bsf.jpg","s":"Monkey Puncher is a video game for the Game Boy Color, developed by Atelier Double, published by Taito, and released in March 2000. The game's goal is to train a monkey to fight in organised boxing matches in order to save the main character's father and sibling."},{"t":"Monster Bass","p":["PlayStation"],"d":"Magical Company","u":"Magical Company, XS Games","g":"Fishing, Simulation","r":"June 15, 2000","l":"https://en.wikipedia.org/wiki/Monster_Bass","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ntl.jpg","s":"Pick your bait, grab your fishing rod, and go out and catch the biggest fish you can find! But beware... when the fish are your worst enemy, and the fear of zombie bass flows through the town, what will you do? Hook'em up of course! Fight against against the monstrous fish in the scariest fishing game ever made..."},{"t":"Monster Rancher Battle Card Episode II","p":["PlayStation"],"d":"Tecmo","u":"Tecmo","g":"Strategy","r":"March 23, 2000","l":"https://en.wikipedia.org/wiki/Monster_Rancher_Battle_Card_Episode_II"},{"t":"Monster Rancher Explorer","p":["Game Boy Color"],"d":"Graphic Research","u":"Tecmo","g":"Puzzle","r":"September 29, 2000","l":"https://en.wikipedia.org/wiki/Monster_Rancher_Explorer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/try5qydksrfyaouuy5r5.jpg","s":"The MONSTER RANCHER franchise returns with this thoroughly entertaining adventure for handheld gamers. Help the well-meaning Cox fight through 60 enormous, puzzle-filled levels, fending off certain monsters while allying yourself with others. Each level requires you to find a hidden key in order to advance to the next stage, a task that becomes increasingly difficult as things progress. Luckily, you're not going at it alone. You can unlock such friendly beasts as Gali, Hare, Mocchi, Suezo, and Tiger in order to help you fend off all enemies. Each of the friendly monsters serves as a power-up of sorts, increasing your overall speed, granting you temporary invincibility, and more. Fans of the series know just how fun collecting and utilizing monsters can be, and the premise is at its absolute best in this GBA installment. Cool, anime-style graphics abound throughout the massive gaming experience, which allows you to play alone or square off against a fellow Rancher."},{"t":"Monster Rancher Hop-A-Bout","p":["PlayStation"],"r":"December 10","l":"https://en.wikipedia.org/wiki/Monster_Rancher_Hop-A-Bout"},{"t":"Moomin's Tale","p":[],"l":"https://en.wikipedia.org/wiki/Moomin's_Tale"},{"t":"Moonlight Lady (OVA)","p":[],"l":"https://en.wikipedia.org/wiki/Moonlight_Lady_(OVA)"},{"t":"Mort the Chicken","p":["PlayStation"],"d":"AndNow","u":"Crave Entertainment, Ubi Soft","g":"Platform","r":"November 30, 2000","l":"https://en.wikipedia.org/wiki/Mort_the_Chicken","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6x2i.jpg","s":"The Chickens are in a panic when mysterious creatures from another world kidnap their baby chicks! Stolen from the farm and threatened with becoming tasty snacks, it is up to fearless Mort to come to their rescue. A super chicken with super powers, Mort must cluck, peck and comb-whip the pride of the farm back to safety."},{"t":"Mortadelo y Filemón: Una Aventura de Cine","p":["Windows"],"d":"Alcachofa Soft","u":"Crimson Cow","g":"Adventure game","r":"December 2000","l":"https://en.wikipedia.org/wiki/Mortadelo_y_Filem%C3%B3n:_Una_Aventura_de_Cine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobn1i.jpg","s":"Mortadelo y Filemón: Una Aventura de Cine is a 2000 adventure video game developed by Spanish studio Alcachofa Soft for Microsoft Windows. The game was later re-released in Spain in November 2003 and in Germany in 2004 by Crimson Cow.\n\nThe game is in German and was not localized into English.\n\nIt is the third game in the Mort & Phil adventure game series, following El Sulfato Atómico (1998) by Alcachofa Soft and La Máquina Meteoroloca (1999) by Vega Creaciones Multimedia."},{"t":"Mortal Kombat: Special Forces","p":["PlayStation"],"r":"June 30"},{"t":"Moto Racer World Tour","p":["PlayStation"],"d":"Delphine Software International","u":"Sony Computer Entertainment, Infogrames","g":"Racing","r":"September 29, 2000","l":"https://en.wikipedia.org/wiki/Moto_Racer_World_Tour","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5zi6.jpg","s":"Moto Racer World Tour is the third part of the Moto Racer series for the PlayStation. The game offers you to race on 34 different bikes in both dirt and street bike category. Each bike's settings can be manually adjusted. The game features 18 real-life tracks. Besides normal races you can play a variety of different modes, such as obstacle course, drag race, freestyle race (where you have to perform tricks to score points) and Traffic Race (with normal traffic on the road). The game features two player multiplayer."},{"t":"Motocross Madness 2","p":["Windows"],"d":"Rainbow Studios","u":"Microsoft Games","g":"Vehicle simulation, racing","r":"May 25, 2000","l":"https://en.wikipedia.org/wiki/Motocross_Madness_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ned.jpg","s":"Motocross Madness 2 is one of Microsoft's most popular games and also one of the most well received.\nThis sequel to Motocross Madness was released with improved graphics, which included better textures and many landscape objects like trees, roadsigns and caravans. It has over 40 tracks in 6 event types, over 50,000 3D objects and a new career mode. Players as well as bikes are easily customized. Motocross Madness also supports network play over a LAN environment and, until June 19, 2006, multiplayer gameplay through the MSN Gaming Network."},{"t":"Motocross Mania","p":["Windows"],"d":"Deibus Studios","u":"On Deck Interactive, Take-Two Interactive","g":"Racing","r":"November 14, 2000","l":"https://en.wikipedia.org/wiki/Motocross_Mania","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ek9.jpg","s":"Motocross Mania brings you throttle-twisting fun with tons of racing and freestyle action. Realistic environments and high-performance bikes let you ride everything from big supercross jumps to huge outdoor gaps. The riding only gets better as you progress through the game and unlock different bikes and tracks, adding to your bag of big air tricks."},{"t":"MotoGP","p":["PlayStation 2"],"d":"Namco","u":"Namco, Namco Hometek, Sony Computer Entertainment","g":"Racing","r":"October 12, 2000","l":"https://en.wikipedia.org/wiki/MotoGP_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7sni.jpg","s":"Developed by Namco, this racing simulator brings the excitement of MotoGP to the consoles."},{"t":"Mr. Driller 2","p":["Arcade"],"d":"Namco","u":"Namco, Namco Hometek","g":"Puzzle","r":"July 2000","l":"https://en.wikipedia.org/wiki/Mr._Driller_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co68ad.jpg","s":"Test your drill skills in Mr. Driller 2, a colorful puzzle game for the Game Boy Advance. In an effort to save the world from being buried under colored blocks, you must drill your way through a variety of intricate puzzles while avoiding enemies and obstacles. Based on the arcade version, the sequel to Mr. Driller features Mission Driller, Endless Driller, and Time Attack Driller modes, plus a two-player mode that lets you play against a friend via link cable."},{"t":"Ms. Pac-Man Maze Madness","p":["PlayStation","Nintendo 64","Dreamcast"],"d":"Namco Hometek","u":"Namco Hometek, Namco, Sony Computer Entertainment, Zoo Digital Publishing","g":"Maze","r":"September 13, 2000","l":"https://en.wikipedia.org/wiki/Ms._Pac-Man_Maze_Madness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ivx.jpg","s":"Professor Pac learns that the witch, Mesmerelda, has seized control of the Enchanted Castle using black magic and from there is planning on stealing all four Gems of Virtue (Generosity; Truth; Wisdom; Courage) to control the \"four wonders\" (areas of Pac-Land). He creates a device called a Pactrometer which allows Ms. Pac-Man to go to these areas to recover the gems before Mesmerelda can get them first."},{"t":"MTV Sports: Pure Ride","p":["PlayStation","Game Boy Color"],"d":"Radical Entertainment, Visual Impact","u":"THQ","g":"Snowboarding","r":"September 28, 2000","l":"https://en.wikipedia.org/wiki/MTV_Sports:_Pure_Ride","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8dwz.jpg","s":"MTV Sports: Pure Ride is a Sports game, developed by Visual Impact and published by THQ, which was released in 2000."},{"t":"MTV Sports: Skateboarding Featuring Andy Macdonald","p":["Windows","PlayStation","Game Boy Color","Dreamcast"],"d":"Darkblack, Yellowbelly Corporation","u":"THQ","g":"Sports","r":"September 13, 2000","l":"https://en.wikipedia.org/wiki/MTV_Sports:_Skateboarding_Featuring_Andy_Macdonald","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3g94.jpg","s":"A skateboarding game with similar controls to the classic Tony Hawk games. This game however has a stunt mode."},{"t":"MTV Sports: T.J. Lavin's Ultimate BMX","p":["Game Boy Color"],"d":"Handheld Games, Blue Shift","u":"THQ","g":"Sports","r":"November 30, 2000","l":"https://en.wikipedia.org/wiki/MTV_Sports:_T.J._Lavin's_Ultimate_BMX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/xhrytelazx0uxfebtid6.jpg","s":"MTV SPORTS: T.J. Lavin's Ultimate BMX puts the action of riding a stunt BMX bike in the palm of your hand. The game offers six different professional riders: T.J. Lavin, Fuzzy Hall, Chris Duncan, Mike Ardelean, Jamie Bestwick, or Colin Winkelmann. Try to pull off the most spectacular stunts in three different play modes: Vert, Street, and Dirt. Vert has the player performing tricks on a halfpipe; Street has the player navigate a course with ramps, fun boxes, and other objects while executing tricks to win the judges attention; and the Dirt event puts the player on a dirt track to try to pull off big tricks without biting the dust. Master the skills of professional BMX in MTV SPORTS: T.J. Lavin's Ultimate BMX."},{"t":"Muppet Monster Adventure","p":["PlayStation"],"d":"Magenta Software","u":"Sony Computer Entertainment, Midway Games","g":"Platform","r":"October 20, 2000","l":"https://en.wikipedia.org/wiki/Muppet_Monster_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xfh.jpg","s":"Muppet Monster Adventure is a platform game for the Sony PlayStation developed by Magenta Software and Jim Henson Interactive in 2000, and published by Sony Computer Entertainment in Europe and Midway Home Entertainment in North America."},{"t":"Muppet RaceMania","p":["PlayStation"],"d":"Traveller's Tales","u":"Sony Computer Entertainment, Midway Games","g":"Racing","r":"April 21, 2000","l":"https://en.wikipedia.org/wiki/Muppet_RaceMania","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kzx.jpg","s":"A racing game, in a similar vain to Mario Kart, using Jim Henson's Muppets as characters. It was developed by Traveller's Tales and published by Midway."},{"t":"Mysterious Song","p":["MS-DOS"],"d":"Darkness Ethereal, Frozen Utopia","u":"Darkness Ethereal, Frozen Utopia","g":"Role-playing","r":"March 9, 2000","l":"https://en.wikipedia.org/wiki/Mysterious_Song","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3twi.jpg","s":"Mysterious Song is an RPG strongly influenced by the style of the early Final Fantasy games. Your character is a knight, sent by the king to investigate the trouble arising in the land, with the help of two other party members whom you pick up as you travel. The combat is turn-based, with a very simple magic system based on spell points. One party member is a mage, one specializes in physical combat, and your main character is a mix. There is no class selection, only leveling up."},{"t":"Nanatsu no Hikan: Senritsu no Bishō","p":["Dreamcast"],"d":"Koei","u":"Koei","g":"Survival horror","r":"January 20, 2000","l":"https://en.wikipedia.org/wiki/Nanatsu_no_Hikan:_Senritsu_no_Bish%C5%8D"},{"t":"Nancy Drew: Message in a Haunted Mansion","p":["Windows"],"g":"Adventure","r":"November 24","l":"https://store.steampowered.com/app/615770","i":"images/steam-615770.jpg","s":"Discover who — or what — is behind the mysterious accidents in a house full of secrets!"},{"t":"Napple Tale: Arsia in Daydream","p":["Dreamcast"],"d":"Chime","u":"Sega","g":"Platform","r":"October 19, 2000","l":"https://en.wikipedia.org/wiki/Napple_Tale:_Arsia_in_Daydream","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7k8m.jpg","s":"While enjoying the once-per-year Summer Festival, the heroine Poach Arsia is accidentally brought to Napple World due to a mistake made by Straynap, a novice Spirit Guide who leads souls into the afterlife. Napple World, known as the land of daydreams, lies between the Real World and the Deep Dream, where souls go to rest. The concept of time in Napple World is unlike the real world: the seasons of spring, summer, autumn and winter exist separately from each other as distinct locations. When Poach arrives in Napple World, six fairy-like beings called Petals leave her body and escape into the seasons, and she must retrieve them in order to go home again. To make up for his mistake, Straynap becomes Poach's guide and instructs her throughout the game, explaining the often contradictory nature of Napple World to her."},{"t":"NASCAR 2001","p":["PlayStation","PlayStation 2"],"d":"EA Sports, Black Box Games","u":"EA Sports","g":"Racing","r":"September 19, 2000","l":"https://en.wikipedia.org/wiki/NASCAR_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oxq.jpg","s":"Authentic Nascar Racing: The real drivers, cars, teams, tracks, sponsers, and rules.\n\nTop Drivers: Over 30 drivers including Jeff Gordon, Dale Earnhardt, Tony Stewart, Dale Jarrett, Bobby Labonte, Mark Martin, Dale Earnhardt Jr and Bobby Hamilton.\n\nMore Tracks: Daytona and 13 other Nascar tracks with both day and night racing.\n\nFull or \"Track Pack\" Season: Race a full or half Nascar season or choose to compete on track packs: race just on short tracks, road courses, speedways or superspeedways."},{"t":"NASCAR Arcade","p":["Arcade"],"d":"Sega Rosso","u":"Sega","g":"Racing","r":"September 2000","l":"https://en.wikipedia.org/wiki/NASCAR_Arcade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coajgy.jpg","s":"NASCAR Arcade is a stock car racing game and the first NASCAR game to be made for the arcades. It's officially licensed through Electronic Arts (who had the license at the time) and is based on the 1999 Winston Cup series. There are three different race tracks to choose from each with a different difficulty level: Talladega Superspeedway, Richmond International Raceway and Watkins Glen International. A secret Team SEGA track exist too but it's not made available until 700 races have been made on the machine. Before racing the player can choose from real life cars and drivers that all have different strengths and weaknesses. The cars included are Pontiac Grand Prix, Ford Taurus, Chevrolet Monte Carlo and Pontiac Firebird while there are more than 30 drivers to choose from.\n\nThe game can be played from a first person perspective or several different third person views. It's possible to choose automatic or manual transmission. The objective of the game is to race against the clock and reach a top three position and the finish line before the time runs out. By climbing up to a certain position the player can get a time extension. In time attack or multiplayer the player needs to finish a lap to get a time extension. A race ends when the time is up or if the player reaches the finish line. The multiplayer mode can be played by up to eight players."},{"t":"NASCAR Heat","p":["PlayStation","Windows","Game Boy Color"],"d":"Monster Games, Digital Illusions CE, Game Titan, Pipe Dream Interactive","u":"Hasbro Interactive, Majesco","g":"Racing","r":"August 22, 2000","l":"https://en.wikipedia.org/wiki/NASCAR_Heat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ydm.jpg","s":"Fans of stock car racing, get ready to take on the challenges of NASCAR HEAT for the Game Boy Color. Play as or against 10 stock car racing legends like Dale Earnhardt, Jeff Gordon, Bobby Labonte, and Dale Jarrett. After you pick a driver, you can learn the twists and turns of each track with the Beat the Heat mode, where each of the 10 professional drivers give the player challenges to complete. When you are ready for some competition, get after the other drivers in a Quick Race, or try to become NASCAR champion in the Championship mode. No matter which mode you choose, you will have to make strategic decisions to conquer each race. Most notably, determining when to make a pit stop can win or lose a race. Get all of the racing action you want with NASCAR HEAT."},{"t":"NASCAR Rumble","p":["PlayStation"],"d":"EA Redwood Shores","u":"Electronic Arts","g":"Racing","r":"February 3, 2000","l":"https://en.wikipedia.org/wiki/NASCAR_Rumble","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5um6.jpg","s":"NASCAR Rumble is a racing game by Electronic Arts for the PlayStation. Players race through 18 different courses set in six different areas collecting powerups to aid them. The game was met with fairly positive reviews, and earned an 80% on GameRankings. This game is a great departure to many NASCAR games, as this game is an arcade racer featuring various tracks and Mario Kart esque powerups."},{"t":"NBA 2K1","p":["Dreamcast"],"u":"Sega","r":"October 31, 2000","l":"https://en.wikipedia.org/wiki/NBA_2K1"},{"t":"NBA In The Zone 2000","p":["Nintendo 64","PlayStation","Game Boy Color"],"d":"Konami Computer Entertainment Osaka","u":"Konami","g":"Sports","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/NBA_In_The_Zone_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u8e.jpg","s":"Get set for some serious net time with KONAMI and the NBA! We're back In The Zone for PlayStation, Nintendo 64 and GameBoy Color with our best season yet! Lead the break from the tip off with features like three-point contest, pinpoint passing and the slam dunk contest. All 29 NBA teams are here, with 300 actual players suiting up. So are you ready to try to sink the 3 with 2 seconds left? Work on your \"D\"? Venture into the paint? Or are you just going to sit there with that goofy look on your face? Huh? Huh? Huh?"},{"t":"NBA Jam 2001","p":["Game Boy Color"],"d":"DC Studios","u":"Acclaim Entertainment","g":"Sports","r":"November 28, 2000","l":"https://en.wikipedia.org/wiki/NBA_Jam_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v7u.jpg","s":"Get even more arcade-style basketball action with NBA JAM 2001. Choose from all 29 NBA teams -- over 140 professional players in all. Get used to the controls and action with the Practice mode, and when you are ready for some real action, try to become NBA champion by playing through the Season. If the Season is giving you a headache, you can skip it and go straight to the Playoffs. No matter what mode you play in, there will be plenty of fastbreaks and rim-rattling jams. Throw even more action into the game with the Fun mode that includes Hot Spots, Hang Time, Half Court Dunks, and On Fire. You can also unlock secret teams like the East and West All-Star teams. Get all of the basketball action you want in the palm of your hand with NBA JAM 2001."},{"t":"NBA Live 2001","p":["PlayStation"],"d":"EA Canada","u":"EA Sports","g":"Sports","r":"October 12, 2000","l":"https://en.wikipedia.org/wiki/NBA_Live_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co397z.jpg","s":"With yet another edition of the annual NBA Live Basketball series surfacing, the question is whether the change is worht the price tag. NBA Live 2001 embraces all of the action of the NBA, while featuring all of your favorite NBA stars and rookies."},{"t":"NBA ShootOut 2001","p":["PlayStation"],"d":"Killer Game, 989 Sports","u":"Sony Computer Entertainment","g":"Sports","r":"October 24, 2000","l":"https://en.wikipedia.org/wiki/NBA_ShootOut_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/h7se7bwu6eczilozwl5t.jpg","s":"NBA SHOOTOUT 2001 offers all the standard features you expect from a quality basketball title: Exhibition games, Season mode with in-depth stat tracking, and Playoff mode. You can also choose the style you want to play, either Simulation or Arcade mode. The Season mode gives you the chance to strut your stuff on the court, as awards for MVP, Rookie of the Year, scoring champion, rebounding champion, and Defensive Player of the Year are up for grabs. You'll also have a selection of over 400 plays to choose from, which include team-specific plays that fit a team's playing style. So the Lakers will have a lot of entry passes to the post to utilize Shaq, while the 76ers will feature plenty of isolation plays so Iverson can do what he does best.. You can also take on a friend in the Versus mode and see who is the best hoops maven."},{"t":"NCAA Final Four 2001","p":["PlayStation","PlayStation 2"],"d":"Killer Game","u":"Sony Computer Entertainment America","g":"Sports","r":"November 16, 2000","l":"https://en.wikipedia.org/wiki/NCAA_Final_Four_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nsgz03k9pxzkng8oqhjd.jpg","s":"NCAA FINAL FOUR 2001 has all the standard game modes including Exhibition, Season and Tournament modes, and it also tracks season stats for both players and teams. The game has almost every Division I men's college teams and sports a fair amount of women's squads as well. The game also features the Touch Shooting Meter, so players will have even more control over their jump shots. Quinn Buckner handles the announcing duties and the sound really manages to capture that college game feel. If you get tired of playing the computer you can always take on a friend in the versus mode and take him to school."},{"t":"NCAA Football 2001","p":["PlayStation"],"d":"Sennari Interactive","u":"EA Sports","g":"Sports, American football","r":"July 26, 2000","l":"https://en.wikipedia.org/wiki/NCAA_Football_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qckbbqn6jbk3bhl3bwwi.jpg","s":"The crowd sings a roaring fight song, a sophomore in an animal costume jumps around the sidelines, and players fight for their school and a chance at the pros. What are we talking about? College football, of course, and only NCAA Football 2001 can take you all the way to the Orange Bowl. You'll call the plays and control the moves specific to each position on your team. The running game has been improved from the previous year's release and now includes new defensive player logic, pursuit angles, and receiver routes. In dynasty mode, you can build your team from the ground up, even adding junior-college prospects to your roster. If you're more interested in quick-and-dirty action, play in situation mode where you create the scenario--even putting two minutes on the clock and your team within field-goal range. And to amp up the rah-rah college atmosphere of your games, NCAA Football 2001 lets you customize the setting with frat logos and uniforms and even lets you name your players."},{"t":"NCAA GameBreaker 2001","p":["PlayStation","PlayStation 2"],"d":"Red Zone Interactive, 989 Sports","u":"Sony Computer Entertainment","g":"Sports","r":"August 22, 2000","l":"https://en.wikipedia.org/wiki/NCAA_GameBreaker_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/pj35udoc0yqlrmjztfxk.jpg","s":"Like previous games in 989 Studios' GameBreaker series, NCAA GameBreaker 2001 is a counterpart to their NFL GameDay series. You start out as a bottom-rung coach at one of the 115 division 1-A college teams and as your performance increases, you obtain promotions and offers from other schools. At the end of the season, you're able to export your players to NFL GameDay. As with the previous games, broadcaster Keith Jackson returns to provide voice commentary."},{"t":"NCAA March Madness 2001","p":["PlayStation"],"d":"Black Ops Entertainment","u":"EA Sports","g":"Sports","r":"December 7, 2000","l":"https://en.wikipedia.org/wiki/NCAA_March_Madness_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/n1qljk4vqwgutggi6vbt.jpg","s":"Playstation?s reigning champion of NCAA Men?s basketball is back and hungry for a repeat. This year?s version is boasting promising new features.\n\nCoach Mode is the newest addition to the March Madness stable of gameplay modes. This feature allows masters of the \"X's and O's\" to work their way up from a small college to \"shoecontract-U\" where they vie for the NCAA title. In addition, Dynasty Mode and the playbooks have been expanded, for those gamers who want to dabble in the behind the scenes action of college basketball."},{"t":"Necronomicon: The Dawning of Darkness","p":["Windows"],"d":"Wanadoo Edition","u":"Wanadoo Edition, Cryo Interactive, DreamCatcher Interactive","g":"Horror, adventure","r":"November 10, 2000","l":"https://en.wikipedia.org/wiki/Necronomicon:_The_Dawning_of_Darkness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co256a.jpg","s":"In this thrilling point-and-click adventure based on the works of H.P Lovecraft, you’ll traverse the haunting world of Gothic New England, solving puzzles and acquiring information to help Stanton solve the mystery of the Necronomicon."},{"t":"Need for Speed: Porsche Unleashed","p":["Windows","PlayStation"],"r":"February 29"},{"t":"Neppachi II @VPACHI","p":[],"l":"https://en.wikipedia.org/wiki/Neppachi_II_@VPACHI"},{"t":"Neppachi III @VPACHI","p":[],"l":"https://en.wikipedia.org/wiki/Neppachi_III_@VPACHI"},{"t":"Neppachi IV @VPACHI","p":[],"l":"https://en.wikipedia.org/wiki/Neppachi_IV_@VPACHI"},{"t":"Neppachi V @VPACHI","p":[],"l":"https://en.wikipedia.org/wiki/Neppachi_V_@VPACHI"},{"t":"Nettou Golf","p":["Dreamcast"],"g":"Simulator, Sport","l":"https://en.wikipedia.org/wiki/Nettou_Golf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co829b.jpg","s":"A golf simulation game by Sega for the Dreamcast with online capabilities."},{"t":"Never 7: The End of Infinity","p":["PlayStation","Neo Geo Pocket Color","Dreamcast"],"d":"KID","u":"KID, Cyberfront, 5pb., Mages, Spike Chunsoft","g":"Visual novel","r":"March 23, 2000","l":"https://en.wikipedia.org/wiki/Never_7:_The_End_of_Infinity","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2271.jpg","s":"Never7: The End of Infinity is the first title in the Infinity series, and is followed by Ever17: The Out of Infinity, Remembe 11: The Age of Infinity, 12Riven: The Psi-Climinal of Integral, and Code_18.\n\nIn the game, the player takes the role of Makoto Ishihara, a college student who attends a seminar camp on an island together with three other students; he also befriends three other people who he meets on the island. The game takes place over the course of a week, and consists of the player reading the story, occasionally making choices that affect the direction of the plot; on the sixth day, one of the female characters dies, and the game moves back in time to the beginning, letting the player use knowledge from the first set of six days to make new choices, to try to prevent the character's death."},{"t":"NFL 2K1","p":["Dreamcast"],"u":"Sega","r":"September 7, 2000","l":"https://en.wikipedia.org/wiki/NFL_2K1"},{"t":"NFL Blitz 2001","p":["Dreamcast","PlayStation","Nintendo 64","Game Boy Color"],"d":"Midway Games, Morning Star Multimedia","u":"Midway","g":"Sports","r":"September 12, 2000","l":"https://en.wikipedia.org/wiki/NFL_Blitz_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6wq1.jpg","s":"All of the big plays and bone-crunching hits of the arcade game can be put in the palm of your hand with NFL BLITZ 2001. As with all BLITZ games, football has been reduced to a high-scoring seven-on-seven affair. Pick your squad from any of the 31 NFL teams and go at it in the Season or Arcade modes. Arcade mode has you challenge all of the teams in the league to a game, while Season mode puts you through the paces of a 16-game season, the playoffs, and a chance to win the Super Bowl. No matter what mode you play, you won't miss a second of the action thanks to the multiple camera angles that are available. Whenever there is a great play, the digitized voice of the announcer will let you know, and you will be treated to a full-motion video sequence. Get into the game with NFL BLITZ 2001."},{"t":"NFL GameDay 2001","p":["PlayStation","PlayStation 2"],"d":"Red Zone Interactive, 989 Sports","u":"Sony Computer Entertainment","g":"Sports","r":"August 15, 2000","l":"https://en.wikipedia.org/wiki/NFL_GameDay_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/mwiqcitxrhkclwi6mpwt.jpg","s":"This edition features lifelike player specific graphics that make players look like their real life counterparts. Also new is commentary by Dick Enberg and Phil Simms. Another feature is total-control passing and running. Total-control passing lets you lead, overthrow, and underthrow your receivers so that you can throw more completions and prevent defenders from intercepting your passes. The play editor has been improved making it easier to make new patterns for your receivers and running backs. The general manager mode has also been changed, mostly to help you with the draft so you can easily see what areas of your team need improvement."},{"t":"NFL QB Club 2001","p":["Dreamcast","Nintendo 64"],"d":"High Voltage Software","u":"Acclaim Entertainment","g":"Sports","r":"August 24, 2000","l":"https://en.wikipedia.org/wiki/NFL_QB_Club_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3bey.jpg","s":"Mind-blowing NFL simulation returns with the next installment of this popular, detailed football extravaganza. With full licenses from the NFL and its athletes, the game has all 31teams and 1500 players, plus perfect replication of logos and stadiums. The game’s five modes include Exhibition, Playoff, Season, Practice, and Simulation. Exhibition lets you take the field as any current NFL team, All-Star lineup, or Super Bowl team since 1967. All of the modes keep more comprehensive stats than you could ever hope for, and you can set up a Season to include preseason action, hot-cold streaks, and player development. Not only that, you can create players, teams, playbooks (with up 128 offensive plays), and profiles of chosen formations and pass-run ratios. There’s even a historical mode that allows you to tap into classic games of yesteryear, featuring teams that date back to 1967. ESPN’s Mike Patrick and Randy Cross chime in with commentary, and Brett Favre has returned yet again to add his insight. Throw a dozen camera angles into the mix, and you’ve got yourself a football game."},{"t":"NGEN Racing","p":["PlayStation"],"d":"Curly Monsters","u":"Infogrames","g":"Racing video game, combat flight simulator","r":"May 12, 2000","l":"https://en.wikipedia.org/wiki/NGEN_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3si5.jpg","s":"Instead of a car, like in most racing games, you control a Fighter Jet Plane.\n\nThe game features two game modes: arcade and N.GEN. In the arcade mode you play a serious of championships. Winning a championship grants you access to a higher one. In N.GEN mode you start with a poor plane and have to earn money to upgrade it so you can participate in more challenging and more rewarding races. You can choose between arcade or professional controls.\n\nThe planes can shoot various weapons, such as missiles, rockets and guns at the opponents. There are 38 jets to fly in on 14 different tracks.\n\nIn Two player mode you can play Powerball. Here each player has to try and pick up the ball and score points by flying through drones."},{"t":"NHL 2001","p":["Windows","PlayStation","PlayStation 2"],"u":"EA Sports","r":"September 28, 2000","l":"https://en.wikipedia.org/wiki/NHL_2001"},{"t":"NHL 2K","p":["Dreamcast"],"d":"Black Box Games","u":"Sega","g":"Sports","r":"February 9, 2000","l":"https://en.wikipedia.org/wiki/NHL_2K_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xxu.jpg","s":"NHL 2K is a series of hockey games by Visual Concepts for the Dreamcast, PlayStation 2, Nintendo GameCube, Xbox, iPhone, Xbox 360, PlayStation 3, and the Wii. Initially discontinued after the release of NHL 2K11 in 2010, the brand was revived on mobile devices in 2014. The games are officially licensed from the National Hockey League and NHL Players Association. While its games were released on consoles, its main competition was EA Sports' NHL video games."},{"t":"NHL Blades of Steel 2000","p":["PlayStation","Game Boy Color"],"d":"Konami, Climax Studios","u":"Konami","g":"Sports","r":"February 22, 2000","l":"https://en.wikipedia.org/wiki/NHL_Blades_of_Steel_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7xjv.jpg"},{"t":"NHL FaceOff 2001","p":["PlayStation"],"d":"SolWorks","u":"Sony Computer Entertainment","g":"Sports","r":"September 5, 2000","l":"https://en.wikipedia.org/wiki/NHL_FaceOff_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ied.jpg","s":"This year's edition allows you to compete against legendary players including Gordie Howe, Bobby Hull, Phil Esposito, and Marcel Dionne. New Jersey Devils announcers Mike Emrick & Darren Pang call the games.\n\nThere is an exhibition mode for up to eight players with the Multitap, a season mode for multiple players, playoff mode, tournament mode, a practice option, and shoot-out mode, that helps to sharpen your breakaway and deke moves.\n\nAlso new this year are the updated rosters of all NHL teams including expansion teams Columbus BlueJackets and Minnesota Wild."},{"t":"NHL Rock the Rink","p":["PlayStation"],"d":"EA Canada","u":"Electronic Arts","g":"Sports","r":"March 22, 2000","l":"https://en.wikipedia.org/wiki/NHL_Rock_the_Rink","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2i2h.jpg","s":"A three-on-three arcade-style hockey game which makes use of the license granted by the NHL and its players' association to create a lightning-fast arcade style game as opposed to the more nuanced aspects of an NHL simulation."},{"t":"Nicktoons Racing","p":["Game Boy Color","Windows"],"d":"Software Creations, Pipe Dream, Crawfish Interactive","u":"Hasbro Interactive, Infogrames, Chicago Gaming","g":"Action-adventure, racing","r":"November 27, 2000","l":"https://en.wikipedia.org/wiki/Nicktoons_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j2t.jpg","s":"Nicktoons Racing focuses on engaging players in go-kart racing on various Nicktoons-themed tracks, similar to the Mario Kart line of games. The game features a wide selection of playable characters from various Nicktoons, including characters from Rugrats, Aaahh!!! Real Monsters, The Wild Thornberrys, The Angry Beavers, CatDog, The Ren & Stimpy Show, Hey Arnold! and SpongeBob SquarePants."},{"t":"Nightmare Creatures II","p":["PlayStation","Dreamcast"],"d":"Kalisto Entertainment","u":"Konami","g":"Survival horror","r":"May 23, 2000","l":"https://en.wikipedia.org/wiki/Nightmare_Creatures_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co250m.jpg","s":"\"Assume the role of Herbert Wallace, an escaped test subject, on the trail of the demonic scientist, Dr. Adam Crowley. After enduring years of horrific lab experiments, Wallace is out to settle the score in a chilling and bloody chase through London and Paris.\n\nLittle does he know that exacting revenge on Crowley is also the last hope to save the world from a nightmarish demise.\""},{"t":"Nightmare in the Dark","p":["Arcade"],"d":"AM Factory","u":"Eleven, Gavaking, SNK","g":"Platform","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Nightmare_in_the_Dark","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27ld.jpg","s":"There lived one gravedigger at a very small village in a remote region. He lived a quiet, solitary life in a corner of the cemetery. He kept away from the village people due to his very ugly appearance. One day, he found the graves were ransacked and some corpses were stolen. He didn't want the village people to find out, so he decided to eliminate the grave burglars by himself. Thus, he patrolled the cemetery every night.\n\nA good ghoul goes around graveyards protecting them from evil doers. The player clears the area and collecting power ups using it to eliminate the enemies. There are five stages with five levels each, and each one of them has you throwing fireballs at ghouls, ghosts, goblins, and zombies. When you keep throwing fireballs at these enemies, they will ignite into a giant fireball, which you can throw at other enemies to kill them, and get the remaining treasure before moving on to the next level. At the end of the fifth level, a boss must be defeated in order to continue the game."},{"t":"Ninja Assault","p":["Arcade"],"d":"Now Production","u":"Namco, Sony Computer Entertainment","g":"Light-gun shooter","r":"November 9, 2000","l":"https://en.wikipedia.org/wiki/Ninja_Assault","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vds.jpg","s":"Ninja Assault is an arcade game developed and released by Namco in 2000. Two years later it was also published as a PlayStation 2 exclusive title with GunCon 2 compatibility.\n\nNinja Assault was developed by Namco, who also created the Time Crisis series. However, this game has more in common with Lethal Enforcers, Virtua Cop, and The House of the Dead series, whereby the movement is completely \"on-rails\" (i.e., with no hiding pedal), and the player must shoot away from the screen to reload. Both versions of this game support up to two players in cooperative gameplay."},{"t":"No Escape","p":[],"l":"https://en.wikipedia.org/wiki/No_Escape_(2000_video_game)"},{"t":"Noctis","p":["MS-DOS","Windows"],"g":"Space exploration/flight simulation","l":"https://en.wikipedia.org/wiki/Noctis_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc6hs.jpg","s":"Noctis is a computer space flight simulator featuring first-person visual exploration of an imaginary galaxy.\n\nThe player is manifested in Noctis as the pilot of spacecraft called a Stardrifter, capable of instantaneous interstellar travel. This allows travelling between stars, refuelling the Stardrifter from Lithium ion-ejecting stars, approaching planets in star systems and their moons, and even landing where it is physically possible. Many planets feature atmospheres and weather effects. Some harbour plants and animals, or even mysterious ruins. No goal or measure of success is imposed by the game: it simply allows the player to catalogue and annotate the player's discoveries in a common database of stellar bodies called the GUIDE, which is to be synchronised over the author's Internet server."},{"t":"Noddy and the Birthday Party","p":["Game Boy Color"],"d":"Tiertex Design Studios","u":"BBC Multimedia","g":"Platform","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/Noddy_and_the_Birthday_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co836g.jpg","s":"It's Big-Ears' birthday! Can you help Noddy collect things for the party? Will Noddy earn enough pocket money to buy Big-Ears a really big cake? Explore Toyland, meet your favourite characters, and take part in 10 exciting adventures. Help Noddy find the party invitations--but watch out for Bumpy Dog. Go to the Dark Wood where Sly and Gobbo have hidden all the party hats. From gathering hidden eggs in Farmer Straw's field to jumping over rolling fruit in the market square, help Noddy get everything for Big-Ears' Birthday party. Watch out for Sly and Gobbo, who always seem to be up to mischief, and even Master Tubby Bear, Bumpy Dog and Clockwork Mouse, who accidentally get in the way sometimes.\n\nEncourages recognition of left and right, numbers, colours and objects. There are different skill levels which cater to a range of abilities and ages from 3 upwards."},{"t":"Noddy's Magic Adventure","p":["PlayStation"],"d":"Mind's Eye Productions","u":"BBC Multimedia","g":"Educational","r":"December 1, 2000","l":"https://en.wikipedia.org/wiki/Noddy's_Magic_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co79mp.jpg","s":"Journey into this magical adventure with Noddy to search for the Wizards' missing magic wand. Help Noddy discover the mystery of the strange happenings in Toyland - can he get the wand back from those naughty goblins who are casting mischievous spells?\nThe racing cars are driving by themselves! Help Noddy drive in his car close enough to the speeding cars and say a magic spell to stop them.\nThe goblins have taken all the batteries out of the robots and now they don't work. Put the batteries back in so the robots can continue building a space rocket.\nThe goblins made the balls bounce high in the sky - and stay there! Fly in the aeroplane and use some magic dust to bring them down to earth again.\nStep-stone across the stream to rescue Bumpy Dog after the goblins turned the bridge into Jelly with the magic wand. Use the stones to cross the stream."},{"t":"Nox","p":["Windows"],"r":"January 31","l":"https://en.wikipedia.org/wiki/Nox_(video_game)"},{"t":"O'Leary Manager 2000","p":["Game Boy Color"],"d":"LiveMedia","u":"Ubi Soft","g":"Sports, simulation","r":"September 15, 2000","l":"https://en.wikipedia.org/wiki/O'Leary_Manager_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/p26lapqrmna33r2qkz5p.jpg","s":"O'Leary Manager 2000 is a football player-manager game released in 2000 for the Game Boy Color. The player can choose whether they want to focus on the management side of football, play the matches themselves on the game's 2D match engine, or combine the two features for a more in-depth experience. It is endorsed by Irish football manager David O'Leary, who was managing Leeds United A.F.C. at the time of the game's release.\n\nThe management side of O'Leary Manager 2000 is very comprehensive when compared to similar Game Boy Color games. The player can choose from 240 fully licensed teams from the top two leagues in England, France, Italy, Spain, Germany and the Netherlands to play as or manage, with each team having 16 players in their squad. There is also the option to promote a number of fictional youth team players. However, most of the youth team players are of low ability, so could only realistically be used for back-up when managing a decent quality team.\n\nAs with any football management game, the transfer market can often play a key role in whether the team achieves success. The player's selected team starts with either 10.5m or 5.5m to spend, depending on whether they were in the first or second tier of their country's football hierarchy. The player can also recoup some money by selling players to other teams. This is done by first offering the footballer for sale at a chosen price, from which interested clubs would then place offers that the player could choose to accept or not. Once a price is agreed, the footballer transfers clubs instantly. The values of footballers alternate greatly during the game, with the then Real Betis striker Denílson being the most expensive player at the start of the game. An unfortunate bug in the game allows the player to gain a huge sum of money (around 70m) if the club goes into a certain amount of debt, which pretty much negates the need for financial planning.\n\nThe club's board of directors constantly give assessments as to how they think the club is progressing under your management. This involves a short statement visible at the menu screen. Other features available the menu screen include options to change you team line-up, formation and tactics; all vital when creating a successful team.\n\nSimilarly, you can decide what methods of training your team will undertake for the coming week. You have the option to \"do training\", which generally increase the statistics of your players (but at the risk of injuring them) or to concentrate on fitness training (which helps players stay fit and injured players to recover quicker). Alternatively, you may choose to skip training entirely for the week. You also have the option to view various statistics, such as league tables from around the world, top goalscorers and to view the squads of all available teams on the game."},{"t":"Oddworld Adventures 2","p":["Game Boy Color"],"d":"Saffire","u":"GT Interactive","g":"Platform","r":"January 17, 2000","l":"https://en.wikipedia.org/wiki/Oddworld_Adventures_2"},{"t":"Odyssey: The Search for Ulysses","p":["Windows"],"d":"In Utero, Cryo Interactive","u":"Cryo Interactive, DreamCatcher Interactive","g":"Adventure","l":"https://en.wikipedia.org/wiki/Odyssey:_The_Search_for_Ulysses","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3zvc.jpg","s":"The game's universe stays faithful to Homer's the Odyssey, including its characters, Poseidon, Zeus, Cerberus and the Cyclops. Penelope, who has had no news of Ulysses for many years, requests that Heritias set off in search of his childhood friend. Heritias first goes to Troy, the last place the leader of the Achaean troops was seen. In the game, the player has to fight creatures like the Gorgon and the Cyclops and you will have to foil the manipulation of the gods to escape from the conspiracy of Poseidon's agents, and resist the seductive enchantress."},{"t":"Offroad Thunder","p":["Arcade"],"d":"Midway Studios San Diego","u":"Midway Games","g":"Racing","r":"January 2000","l":"https://en.wikipedia.org/wiki/Offroad_Thunder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/wx7ynzzmwv6dblm0uksl.jpg","s":"This off-road racing game from Midway is part of the company's \"Thunder\" line of products. It was released into arcades in 1999."},{"t":"Ogami Ichiro Funtouki: Sakura Taisen Kayou Show \"Benitokage\" Yori","p":[],"l":"https://en.wikipedia.org/wiki/Ogami_Ichiro_Funtouki:_Sakura_Taisen_Kayou_Show_%22Benitokage%22_Yori"},{"t":"Ogre Battle Gaiden: Prince of Zenobia","p":["Neo Geo Pocket Color"],"d":"SNK","u":"SNK","g":"Tactical role-playing","r":"June 22, 2000","l":"https://en.wikipedia.org/wiki/Ogre_Battle_Gaiden:_Prince_of_Zenobia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa4nq.jpg","s":"\"Ogre Battle Gaiden: Prince of Zenobia\" is a 2000 real-time tactical role-playing game developed and published by SNK for the Neo Geo Pocket Color. The game is a spin-off within the Ogre Battle series, originally created by Quest Corporation. The storyline takes place parallel to \"Ogre Battle: The March of the Black Queen\", and follows the path of Prince Tristan of Zenobia during his quest to reclaim his kingdom. As with other Ogre Battle titles, the player controls squads of an army, moving to different parts of the map accomplishing tasks and battling armies encountered on the route. Choices made during the narrative impact the ending."},{"t":"Oha Suta Dance Dance Revolution","p":["PlayStation"],"d":"Konami","u":"Konami","g":"Music, exergaming","r":"September 14, 2000","l":"https://en.wikipedia.org/wiki/Oha_Suta_Dance_Dance_Revolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yjn.jpg","s":"Oha Suta Dance Dance Revolution is a Japan-exclusive DDR that primarily features songs from the kids show Oha Suta. There are a few Konami original songs thrown in for good measure."},{"t":"Omikron: The Nomad Soul","p":["Dreamcast"],"r":"June 22"},{"t":"One Piece: Become the Pirate King!","p":["WonderSwan"],"d":"Soft Machine","u":"Bandai","g":"Action/Strategy/Role-Playing","r":"July 19, 2000","l":"https://en.wikipedia.org/wiki/One_Piece:_Become_the_Pirate_King!"},{"t":"Opsys","p":["Windows","macOS"],"d":"Lemon Interactive","u":"[hyper]media limited","g":"Educational, adventure","l":"https://en.wikipedia.org/wiki/Opsys","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1y93.jpg"},{"t":"Orbiter (simulator)","p":[],"l":"https://en.wikipedia.org/wiki/Orbiter_(simulator)"},{"t":"Orphen: Scion of Sorcery","p":["PlayStation 2"],"d":"Shade","u":"Kadokawa Shoten/ESP, Activision","g":"Action, role-playing","r":"August 3, 2000","l":"https://en.wikipedia.org/wiki/Orphen:_Scion_of_Sorcery","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4q0o.jpg","s":"SORCERER BY CALLING. HERO BY ACCIDENT.\n\nAs Orphen, the powerful but lazy sorcerer, you've always thought being a hero was too\nmuch work. But now, you don't have a choice. Harnessed into a risky adventure, you must use your dark powers to help your desperate companions resolve their unique quests."},{"t":"Outlive","p":["Windows"],"d":"Continuum Entertainment","u":"Continuum Entertainment, Take-Two Interactive","g":"Real-time strategy","l":"https://en.wikipedia.org/wiki/Outlive","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qwr.jpg","s":"Outlive is a Brazilian real-time strategy computer game developed and produced by Continuum Entertainment. It is a mission-based real-time strategy game where the player controls either the human military or robot forces and attempts to eliminate all opposing forces. It was initially released in 2000 in Brazil (2001 for the rest of the world), and was the second and most successful product of Continuum. The game was one of the few Brazilian games to be published by a mainstream AAA publisher. It was published in the United States and Europe by Take-Two Interactive."},{"t":"Pac-Man: Adventures in Time","p":["Windows"],"d":"Creative Asylum, Mind's Eye Productions","u":"Hasbro Interactive","g":"Maze","r":"October 23, 2000","l":"https://en.wikipedia.org/wiki/Pac-Man:_Adventures_in_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qx5.jpg","s":"As in the original Pac-Man arcade game, the basic objective of each level is to guide Pac-Man through a maze while eating dots, unique food items, and power pellets that make Pac-Man's enemies, the Ghosts, edible for a limited time. The ability to jump returns from Pac-Mania for bypassing hazards and avoiding enemies. Some levels contain obstacles such as deadly boulders, animals who delay or kill Pac-Man, and explosive projectiles. After every few rounds there is a bonus mini-game in which the player can obtain some extra points (with every 50,000 points earning Pac-Man an extra life). The levels also feature a variety of shapes and architectural features such as cylindrical mazes, canopies, bridges, pyramids, and even walls that allow Pac-Man to walk vertically. The game features more sophisticated events than its arcade predecessor, such as collecting a certain number of pellets to unlock another area of a maze. The game also includes the ability to see the short intermission videos that come before a new level and allow for an option of non-storyline play on specific levels. The game also has the ability to connect over the Internet for multiplayer mini-games."},{"t":"Pajama Sam 3: You Are What You Eat from Your Head to Your Feet","p":["Windows"],"d":"Humongous Entertainment","u":"Humongous Entertainment","g":"Adventure game","r":"April 6, 2000","l":"https://en.wikipedia.org/wiki/Pajama_Sam_3:_You_Are_What_You_Eat_from_Your_Head_to_Your_Feet","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ssr.jpg","s":"Pajama Sam chases down some snickering cookies, only to find himself in the midst of a food squabble!"},{"t":"Panty Raider: From Here to Immaturity","p":["Windows"],"d":"Hypnotix","u":"Simon & Schuster Interactive","g":"Adventure","l":"https://en.wikipedia.org/wiki/Panty_Raider:_From_Here_to_Immaturity"},{"t":"Panzer General III: Scorched Earth","p":["Windows"],"d":"Strategic Simulations","u":"Strategic Simulations","g":"Computer wargame","r":"September 28, 2000","l":"https://en.wikipedia.org/wiki/Panzer_General_III:_Scorched_Earth"},{"t":"Paper Mario","p":["Nintendo 64"],"u":"Nintendo","r":"August 11, 2000","l":"https://en.wikipedia.org/wiki/Paper_Mario"},{"t":"Papyrus","p":["Game Boy Color"],"d":"Planet Interactive Development","u":"Ubisoft","g":"Action, platform","r":"February 2000","l":"https://en.wikipedia.org/wiki/Papyrus_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/xv3dyrs3hoycadsdxgju.jpg","s":"Papyrus is an Action game, developed by Planet Interactive and published by Ubisoft, which was released in Europe in 2000."},{"t":"Para Para Paradise","p":["Arcade","PlayStation 2"],"d":"Konami","u":"Konami","g":"Rhythm, music, exercise","l":"https://en.wikipedia.org/wiki/Para_Para_Paradise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u7s.jpg","s":"ParaParaParadise (パラパラパラダイス) is a rhythm game that utilizes five motion sensors positioned around the body of the player. The player waves their hands over these sensors that correspond to the arrows that appear on screen in rhythm to the selected song."},{"t":"Parasite Eve II","p":["PlayStation"],"r":"September 12","l":"https://en.wikipedia.org/wiki/Parasite_Eve_II"},{"t":"Patrician II: Quest for Power","p":["Windows"],"d":"Ascaron","u":"Infogrames, Strategy First","g":"Business simulation","r":"November 24, 2000","l":"https://en.wikipedia.org/wiki/Patrician_II:_Quest_for_Power","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/hi7ywgnz8siasewohrxe.jpg","s":"Sequel to the trading simulator The Patrician"},{"t":"PBA Tour Bowling 2","p":["Windows"],"d":"Bethesda Softworks","u":"Bethesda Softworks","r":"February 2000","l":"https://en.wikipedia.org/wiki/PBA_Tour_Bowling_2"},{"t":"PBA Tour Bowling 2001","p":["Dreamcast","Windows"],"d":"Bethesda Softworks","u":"Bethesda Softworks","l":"https://en.wikipedia.org/wiki/PBA_Tour_Bowling_2001"},{"t":"Perfect Dark","p":["Nintendo 64"],"u":"Nintendo","r":"May 22, 2000","l":"https://en.wikipedia.org/wiki/Perfect_Dark"},{"t":"Persona 2: Eternal Punishment","p":["PlayStation Portable"],"r":"June 29"},{"t":"PGA Championship Golf 2000","p":["Windows"],"u":"Sierra Entertainment","r":"June 1, 2000","l":"https://en.wikipedia.org/wiki/PGA_Championship_Golf_2000"},{"t":"Phantasy Star Online","p":["Dreamcast"],"u":"Sega","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Phantasy_Star_Online"},{"t":"Phantom of Inferno","p":[],"l":"https://en.wikipedia.org/wiki/Phantom_of_Inferno"},{"t":"Planet Harriers","p":["Arcade"],"d":"Amusement Vision","u":"Sega","g":"Rail shooter, third-person shooter","r":"December 2000","l":"https://en.wikipedia.org/wiki/Planet_Harriers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4gj6.jpg","s":"Planet Harriers is a seated twin arcade cabinet in the Space Harrier franchise. Like its 1985 predecessor Space Harrier, Planet Harriers had the most technically advanced graphics of 2000, running on the Sega Hikaru arcade system board, which was very powerful (but very expensive) for its time."},{"t":"Planet Ring","p":["Dreamcast"],"g":"Strategy, Arcade","l":"https://en.wikipedia.org/wiki/Planet_Ring_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co42p7.jpg","s":"Planet Ring is and 'Online Theme Park', containing many exciting elements which you can only experience through Dreamcast. Initially there were 4 mini attractions (games) on this Planet, each is simple but addictive - Dream Dorobo, Ball bubble, SOAR and Splash."},{"t":"Planetarion","p":["Browser"],"d":"Fifth Season A.S.","u":"Jagex","g":"MMOG, Tick-based game","l":"https://en.wikipedia.org/wiki/Planetarion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5bi8.jpg","s":"Planetarion is a browser-based massively multiplayer online game created by Fifth Season AS in early 2000. The game places players in control of a planet, with the ability to mine its asteroids for resources, enabling them to construct a fleet of spaceships to attack other players' planets. Although its popularity has declined with the emergence of other similar games and the introduction of a pay-to-play model, which has since been changed to a freemium format, the game is currently still active, and as such is one of the oldest running internet games of its genre."},{"t":"Pocket Digimon World","p":["PlayStation"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Pocket_Digimon_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5thn.jpg","s":"Original version of Pocket Digimon World using the PocketStation, a PlayStation accessory device. The exclusive digimon of this version are Agumon, Biyomon and Veemon. The actual main game primarily happens in the PocketStation.\n\nIn the PocketStation, you can raise your Digimon and battle it either with in-game Digimon or a friend's PocketStation wirelessly over IR connection. You can also connect it to other Bandai Digimon games and products."},{"t":"POD 2","p":["Dreamcast"],"d":"Ubi Soft Bucharest","u":"Ubi Soft","g":"Racing","r":"December 6, 2000","l":"https://en.wikipedia.org/wiki/POD_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4of8.jpg","s":"POD SpeedZone is the sequel to the original POD for the PC. It is a simple, futuristic racer, where you are able to attack your opponents. You are a miner on the colony of Damethra, and an alien virus has taken over the cars on the colony, creating mutant cars. It was one of the first games playable on SegaNet, and one of the only games to support the Dreamcast Broadband Adaptor. This game features eight different vehicles to use on five 3D tracks."},{"t":"Pokémon Crystal","p":["Game Boy Color"],"r":"December 14","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Crystal"},{"t":"Pokémon Gold and Silver","p":["Game Boy Color"],"r":"October 15","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Gold_and_Silver"},{"t":"Pokémon Puzzle Challenge","p":["Game Boy Color"],"u":"Nintendo","r":"September 21, 2000","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Puzzle_Challenge"},{"t":"Pokémon Puzzle League","p":["Nintendo 64"],"d":"Nintendo Software Technology, Intelligent Systems","u":"Nintendo","g":"Puzzle","r":"September 25, 2000","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Puzzle_League","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ywa.jpg","s":"Discover the most frantic, frenzied, fun-filled Pokémon challenge ever--Pokémon Puzzle League! Line up three or more blocks of the same type to clear them off the screen. Create chains and combos to send garbage to your opponent. Collect badges from other Pokémon trainers to earn the right to enter the ultimate competition... a battle against the mysterious Puzzle Master!"},{"t":"Pokémon Stadium","p":["Nintendo 64"],"r":"February 29","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Stadium"},{"t":"PokéROM","p":["Windows","macOS"],"d":"Basis Applied Technology","u":"The Learning Company, Mattel Interactive","g":"Educational","r":"July 2000","l":"https://en.wikipedia.org/wiki/Pok%C3%A9ROM"},{"t":"Polaris SnoCross","p":["Game Boy Color","PlayStation","Nintendo 64"],"d":"Vicarious Visions","u":"Vatical Entertainment","g":"Racing","r":"February 2000","l":"https://en.wikipedia.org/wiki/Polaris_SnoCross","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3z1e.jpg","s":"If it doesn't say Polaris... it ain't SnoCross! Join the Polaris Snowmobile Racing Team and dare to tame the mountain! Pull off a variety of insane tricks as you master the challenges of monster jumps, hidden pitfalls, shortcuts, and treacherous terrain. Race against fiercely competitive AI characters, or take on your own friends in multi-player mode. Feel your customized Polaris sled move, twist and turn just like a real snowmobile!"},{"t":"Police 911","p":["Arcade"],"d":"Konami","u":"Konami","g":"Light gun shooter","l":"https://en.wikipedia.org/wiki/Police_911","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co96cs.jpg","s":"An arcade light-gun shooter with a camera to detect player movement, allowing the player to use body movement to hide behind cover and dodge the (slow-moving) bullets. It was the first video game with fairly accurate full-body motion detection, and probably the only one with a motion-controlled cover system."},{"t":"Pompei: The Legend of Vesuvius","p":["Windows","macOS"],"d":"Arxel Tribe","u":"Cryo Interactive, DreamCatcher Interactive","g":"Adventure","r":"March 1, 2000","l":"https://en.wikipedia.org/wiki/Pompei:_The_Legend_of_Vesuvius","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/tzhf4thjgvs2xonezljp.jpg","s":"Pompei: The Legend of Vesuvius (aka TimeScape: Journey to Pompeii) is a 2000 historical adventure game. It followed by a sequel, Jerusalem: The Three Roads to the Holy Land.\n\nWhen an explorer and world famous cartographer by the name of Adrien Blake returns from an expedition he discovers that his fiancée, Sophia has disappeared. Wrought with grief Adrian immerses himself in his manuscripts and reveals an ancient curse placed on him by the goddess Ishtar. Blake must go to 79AD Pompei, where a volcano will erupt in four days time, destroying the city, and find Sophia."},{"t":"Pop'n Music Mickey Tunes","p":["Game Boy Color","PlayStation","Arcade"],"d":"Konami","u":"Konami","g":"Dance","r":"November 22, 2000","l":"https://en.wikipedia.org/wiki/Pop'n_Music_Mickey_Tunes"},{"t":"PostPet Gameland","p":[],"l":"https://en.wikipedia.org/wiki/PostPet_Gameland"},{"t":"Power Stone 2","p":["Arcade","Dreamcast"],"d":"Capcom, Klein Computer Entertainment","u":"Capcom, Eidos Interactive","g":"Fighting","r":"April 27, 2000","l":"https://en.wikipedia.org/wiki/Power_Stone_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobr7h.jpg","s":"is a multiplayer fighting game that built on the innovative gameplay introduced by its predecessor, Power Stone. Power Stone 2 allows up to four players to choose from multiple characters and utilize items such as tables, chairs, and rocks in battle.\n\nThere are four different modes available for the game\n\n1-on-1: Much like the original Power Stone, a two-character storyline game.\nArcade: A four-character storyline game, with two characters advancing each round.\nOriginal: Multiplayer mode, with free choice of characters and stages.\nAdventure: An unpredictable storyline game, where players can collect items, cards and money.\nPower Stone 2 offers five interactive 3-D stages to begin with, plus the two boss stages which players can also access in Original mode. All but the Original mode is played out like a storyline, where two battles are fought on the regular stages, followed by the Pharaoh Walker boss, then another battle, and ending with the Dr. Erode boss stage. Three extra stages may be unlocked for Original mode by meeting certain requirements in Arcade mode, as well as a desert area stage, which is essentially the Pharaoh Walker boss stage, but without the boss. Though each player has their own set of default ground and air attacks, the character can execute more powerful fusion attacks after collecting three Power Stones and transforming. Power Stone 2 does not offer an opportunity to block, although tapping on the control pad just before an enemy attacks will cause you to dodge.\n\nMost of the stages are dynamic and will change as the battle progresses. For example, the airplane stage starts out on a warplane. After a set amount of time, the plane will fall apart, forcing all the players to battle while skydiving toward the ground. Shortly after, the players will fall onto a floating platform, where the remainder of the battle will be held. This, in essence, creates three sub-stages within a single one.\n\nEach stage is also littered with item boxes, which hold a random item that a player has acquired and unlocked in Adventure mode or created in the Item Shop. They may also contain Power Stones. Items are extremely diverse. Damaging items range from guns, flamethrowers, gigantic hammers, a wide assortment of swords, to bear traps, roller blades, and even a magazine that can be thrown. Non-damaging items include food that will replenish health, shields for defense, elixirs for invisibility, adhesive sprays to slow your opponents, and wings for extra jumps. Cards that can be used to mix items can also be found in Adventure mode. Furthermore, most stages also have their own collection of unique items and fixtures that the player can use. For example, the submarine level comes with turrets, small planes to drop bombs, and icebergs to throw at opponents. Each level is also highly interactive, as players can use many of the stage elements themselves. All players can also gain extra height by jumping off a wall."},{"t":"Premier Manager 2000","p":["PlayStation"],"d":"Infogrames Sheffield House","u":"Infogrames","g":"Sports","r":"March 31, 2000","l":"https://en.wikipedia.org/wiki/Premier_Manager_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ocgkly0dg7apluvimoco.jpg","s":"Premier Manager 2000 is a Sports game, developed by Infogrames Sheffield and published by Infogrames, which was released in Europe in 2000."},{"t":"Prism Heart","p":[],"l":"https://en.wikipedia.org/wiki/Prism_Heart"},{"t":"Pro Mahjong Kiwame D","p":[],"l":"https://en.wikipedia.org/wiki/Pro_Mahjong_Kiwame_D"},{"t":"Pro Pool","p":["Game Boy Color"],"d":"Blade Interactive","u":"Codemasters","g":"Sports","r":"September 12, 2000","l":"https://en.wikipedia.org/wiki/Pro_Pool","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v9j.jpg","s":"Exciting billiards action comes to the Game Boy Color with PRO POOL. Play a match against the computer or a friend, or play the Single-Player Speed Match and try to clear all of the balls off of the table as quickly as possible. In Hustle mode, you take the role of a pool hustler, traveling from bar to bar placing bets on games. Ultimately, you want to win enough money to buy your own bar. In all of these modes, six different games can be played: 8 Ball, 9 Ball, 6 Ball, 3 Ball, straight pool, and speed pool. And the competition will never get stale thanks to the 64 different computer opponents to play. Plus, an outstanding physics engine makes this the most realistic pool game available for the Game Boy Color. Try to become a great hustler with PRO POOL."},{"t":"Pro Rally 2001","p":["Windows"],"d":"Ubi Soft Barcelona","u":"Ubi Soft","g":"Racing","r":"December 2000","l":"https://en.wikipedia.org/wiki/Pro_Rally_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tc3.jpg","s":"Pro Rally 2001 is a video game of the racing genre released in 2000 by Ubi Soft. A sequel, Pro Rally 2002, was released in 2002."},{"t":"Project I.G.I.","p":["Windows"],"d":"Innerloop Studios","u":"Eidos Interactive","g":"Tactical shooter","r":"December 8, 2000","l":"https://en.wikipedia.org/wiki/Project_I.G.I."},{"t":"Project Justice","p":["Dreamcast","Arcade"],"r":"December 7","l":"https://en.wikipedia.org/wiki/Project_Justice"},{"t":"Putt-Putt Joins the Circus","p":["macOS","Windows"],"d":"Humongous Entertainment","u":"Humongous Entertainment","g":"Adventure","r":"July 11, 2000","l":"https://en.wikipedia.org/wiki/Putt-Putt_Joins_the_Circus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3y4h.jpg","s":"Putt-Putt Enters the Race is a Junior Adventure in which Putt-Putt helps the main acts of a circus get ready for the show. This point-and-click adventure game aimed at children features simple inventory puzzles and a few minigames."},{"t":"Puyo Puyo Box","p":["PlayStation"],"d":"Compile","u":"Compile, Sega","g":"Puzzle","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Puyo_Puyo_Box"},{"t":"Q-Ball: Billiards Master","p":["PlayStation 2"],"d":"Ornith","u":"ASK, Take-Two Interactive","g":"Sports","r":"March 30, 2000","l":"https://en.wikipedia.org/wiki/Q-Ball:_Billiards_Master","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oyj.jpg","s":"Q-Ball: Billiards Master is a pool player's dream. Players can enjoy realistic gameplay in the most beautiful pool halls in the world, master the techniques used by the pros – including curve shots and position play, Play alone, with friends, or with top ranked professionals, and choose from 10 featured games, plus original options like Billiards and Random Six."},{"t":"Quake III Arena","p":["Dreamcast"],"r":"October 22","l":"https://en.wikipedia.org/wiki/Quake_III_Arena"},{"t":"Quest: Brian's Journey","p":["Game Boy Color"],"d":"Atelier Double","u":"Sunsoft, Imagineer","g":"Role-playing game","r":"January 15, 2000","l":"https://en.wikipedia.org/wiki/Quest:_Brian's_Journey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8kyt.jpg","s":"Brian lives in a peaceful and quiet town where nothing ever happens, which is the way everyone likes it. Suddenly, hordes of evildoers overrun the town and start wreaking havoc in this once-sleepy community. The town is counting on Brian to go on a quest to restore peace and harmony. You take control of the unlikely hero and set out on the adventure of a lifetime. While traveling, you will discover something more nefarious is happening, and you'll have your hands full of monsters and enemies. Throughout your journey you will have to battle these monsters and enemies in turn-based combat with a twist. The twist is that you can move between turns to dodge attacks, and you can also combine spells and attacks to create special moves. Help Brian save his town, and maybe even the world, in QUEST RPG: Brian's Journey."},{"t":"Rainbow Cotton","p":["Dreamcast"],"d":"Success","u":"Success","g":"Rail shooter","r":"January 20, 2000","l":"https://en.wikipedia.org/wiki/Rainbow_Cotton","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co526h.jpg","s":"Rainbow Cotton is an Action game, developed and published by Success, which was released in Japan in 2000."},{"t":"Rampage Through Time","p":["PlayStation"],"d":"Avalanche Software, Eggington Productions","u":"Midway Games","g":"Action","r":"June 20, 2000","l":"https://en.wikipedia.org/wiki/Rampage_Through_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yeb.jpg","s":"Rampage is a series of video games released by Midway for various consoles. The basic premise of the series is that the player controls a human transformed into a giant monster by a lab accident. The gameplay revolves around using your monster to destroy cities around the world while attacking or avoiding military forces.\n\nRampage Through Time is the fourth game in the Rampage series. It was released on June 9, 2000. Its predecessor is Rampage 2: Universal Tour and it is followed by Rampage: Total Destruction. In the game, 7 previous Scumlabs monsters, plus a new one, use a time machine to rampage through time.\n\nThe world is again rebuilding after the events of Universal Tour. To clean up the mess quicker, Scumlabs invent a time machine to send people back in time to fix the mess without having to do it in the present. Unfortunately, the monsters, who have somehow made it back to Earth, appear and run into the machine. They begin terrorizing the past, present, and future, messing up the time stream."},{"t":"Rayman 2: The Great Escape","p":["Dreamcast"],"u":"Ubisoft","r":"March 21, 2000"},{"t":"Rayman Revolution","p":["PlayStation 2"],"u":"Ubisoft","r":"December 22, 2000"},{"t":"Razor Freestyle Scooter","p":["PlayStation"],"d":"Shaba Games, Crawfish Interactive, Titanium Studios","u":"Crave Entertainment, Ubi Soft","g":"Sports","r":"December 12, 2000","l":"https://en.wikipedia.org/wiki/Razor_Freestyle_Scooter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6pre.jpg","s":"Razor Freestyle Scooter is an extreme-sports style action game modeled around small, nimble scooters. In contrast to most games of this type, there is a story. A crazed giant robot has kidnapped your skating buddies. By completing skating challenges at the robot's sky fortress, you must rescue your friends. You skate around 3 large areas and attempt to perform wild tricks, collect scooter wheels and earn bonus time. By completing an objective on all 3 areas, you unlock a sky fortress level in which you can rescue a new skater to control."},{"t":"RC Revenge","p":["PlayStation","PlayStation 2"],"d":"Acclaim Studios Cheltenham","u":"Acclaim Entertainment","g":"Racing","r":"August 17, 2000","l":"https://en.wikipedia.org/wiki/RC_Revenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l40.jpg","s":"Players take control of a range of remote controlled cars and boats in an action packed racing game for the Sony PlayStation.\n\nBased around an enchanting movie Theme world, players take their cars through a number of genre styled levels, including horror, sci-fi and cartoons.\n\nMultiplayer split screen racing available in all modes of the game and a unique track editor allows you to create your own tracks to save on memory card and challenge your friends."},{"t":"Ready 2 Rumble Boxing: Round 2","p":["Dreamcast","Nintendo 64","PlayStation","PlayStation 2"],"d":"Midway Studios San Diego, Point of View, Crawfish Interactive","u":"Midway","g":"Sports","r":"October 24, 2000","l":"https://en.wikipedia.org/wiki/Ready_2_Rumble_Boxing:_Round_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coatcf.jpg","s":"Ready 2 Rumble Boxing: Round 2 is a boxing game for the Dreamcast, Nintendo 64, PlayStation, and PlayStation 2. It is also the sequel to Ready 2 Rumble Boxing."},{"t":"Real Pool","p":["PlayStation 2"],"d":"Astroll","u":"Takara, Infogrames, Midas Interactive Entertainment","g":"Sports video game","r":"September 7, 2000","l":"https://en.wikipedia.org/wiki/Real_Pool"},{"t":"Record of Lodoss War: Advent of Cardice","p":["Dreamcast"],"d":"Neverland Co.","u":"Kadokawa Shoten / ESP, Swing! Entertainment Media AG, Conspiracy Entertainment","g":"Action role-playing","r":"June 29, 2000","l":"https://en.wikipedia.org/wiki/Record_of_Lodoss_War:_Advent_of_Cardice","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8fm0.jpg","s":"Record of the Lodoss War is a hack and slash action dungeon crawler RPG, in a similar vein to Diablo. It is very loosely attached to the Japanese fantasy novels and anime series of the same name."},{"t":"Red Dog: Superior Firepower","p":["Dreamcast"],"d":"Argonaut Games","u":"Sega, Crave Entertainment","g":"Shooter","r":"April 21, 2000","l":"https://en.wikipedia.org/wiki/Red_Dog:_Superior_Firepower","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8zdk.jpg","s":"Red Dog: Superior Firepower is a video game released in 2000 for the Sega Dreamcast, it was developed by Argonaut Games PLC."},{"t":"Rescue Shot","p":["PlayStation"],"d":"Now Production","u":"Namco, Sony Computer Entertainment","g":"Light gun","r":"January 20, 2000","l":"https://en.wikipedia.org/wiki/Rescue_Shot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vdaadflscjov0dfqz3ih.jpg","s":"Rescue Shot is a shooter developed and published by Namco. On one side, it differences from the famous Point Blank series. The game, in fact, looks more like Time Crisis, which doesn't rely on accuracy less very much, thus letting you enjoying the fast-pace of the game dynamic. On the other side, the variety in Rescue Shot is similar to the Point Blank series."},{"t":"Resident Evil Survivor","p":["PlayStation"],"d":"Tose","u":"Capcom, Eidos Interactive","g":"Light gun shooter, first-person shooter","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Resident_Evil_Survivor","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3tp5.jpg","s":"Resident Evil Survivor is the first Resident Evil title to be rendered in real time as opposed to making use of pre-rendered backdrops. Levels are explored in first person, and when enemies are encountered the press of a button will bring up a targeting reticle for shooting. As with most light-gun games there is infinite pistol ammunition available, but limited ammunition for more powerful weapons. At the end of each level two doors are presented which both lead to different levels, although all paths eventually lead to the same ending."},{"t":"Resident Evil – Code: Veronica","p":["Dreamcast"],"u":"Capcom","r":"February 3, 2000"},{"t":"Resurrection: Return of the Black Dragon","p":["Windows"],"d":"Nébula Entertainment","u":"Dinamic Multimedia","g":"Action, hack and slash","l":"https://en.wikipedia.org/wiki/Resurrection:_Return_of_the_Black_Dragon"},{"t":"Return of the Incredible Machine: Contraptions","p":["macOS","Windows"],"d":"Dynamix","u":"Sierra On-Line","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Return_of_the_Incredible_Machine:_Contraptions","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jkz.jpg","s":"Return of The Incredible Machine allows players to use unique, sometimes humorous mechanical components to construct fantastic machines that accomplish unusual tasks. Each puzzle contains a partially built machine and the extra pieces needed to complete it and accomplish the goal. The player's job is to use the pieces in the correct way to complete the machine. As players become more familiar with the various machine parts and their functions, the puzzles become more sophisticated and challenging. This third installment of the Incredible Machine series from Sierra features improved graphics and new puzzles to challenge virtual engineers of all ages. Whirring, Boinging, Thinga-Muh-Jiggy, What-Cha-Ma-Callit, Fun! So how do you build a better thinga-muh-bob? With the completely addictive, highly original devices in the Return of The Incredible Machine: Contraptions. In a category by itself, Contraptions is like nothing you've ever played before. Create off-the-wall gadgets using a combination of everyday flumadiddles, doohickeys, and gigamarees, like your basic laser-activated light switch and your typical mouse-driven treadmill. So break out your lab coat because, with its spectacular 3D graphics, Contraptions is sure to bring out the wild, white-haired inventor in you!"},{"t":"Rhapsody III: Memories of Marl Kingdom","p":["PlayStation 2"],"d":"Nippon Ichi Software","u":"Nippon Ichi Software, NIS America","g":"Role-playing video game","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Rhapsody_III:_Memories_of_Marl_Kingdom"},{"t":"Rhyme Rider Kerorican","p":["WonderSwan Color"],"d":"NanaOn-Sha, Ltd.","u":"Bandai","g":"Music","r":"December 6, 2000","l":"https://en.wikipedia.org/wiki/Rhyme_Rider_Kerorican","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gk4.jpg","s":"Rhyme Rider Kerorican is a music video game in the style of Vib-Ribbon, an earlier game developed by the same studio. The game's plot is quite simple involving the adventures of Kerorican, a female astronaut wearing kemonomimi-style frog-helmet, as she walks along accompanied by jazzy techno music. As Kerorican continues her walk, she encounters more and more enemies and obstacles. Kerorican must jump, duck, kick aside, or otherwise dodge these obstacles to progress and as she does so, the actions she takes add notes to the song such that the player's actions results in a generative melody. By successfully clearing strings of obstacles, Kerorican's combo count increases and this can result in a reward to the player of a crown that acts to skip the player over obstacles. This game is played with the WonderSwan Color held diagonally, the only game on the system to do so. This is why all text in the game is oblique.\n\nThe game has been criticized for difficulty of gameplay as timing and tricky button combinations often result in the player's death. The game also only contains 4 levels so replayability-value has also been considered a negative factor."},{"t":"Rhythm 'N' Face","p":["PlayStation"],"d":"OutSide Directors Company","u":"Asmik Ace Entertainment","g":"Rhythm","r":"March 9, 2000","l":"https://en.wikipedia.org/wiki/Rhythm_'N'_Face","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9qcn.jpg","s":"Rhythm 'n' Face is a rhythm video game developed by OutSide Directors Company and published by Asmik Ace Entertainment for the PlayStation."},{"t":"Ribbit King","p":[],"d":"Infinity, Jamsworks","u":"Bandai","g":"Sports","l":"https://en.wikipedia.org/wiki/Ribbit_King"},{"t":"Riddle of the Sphinx: An Egyptian Adventure","p":["Windows","macOS"],"d":"Old World Studios","u":"DreamCatcher Interactive","g":"Adventure","r":"December 5, 2000","l":"https://en.wikipedia.org/wiki/Riddle_of_the_Sphinx:_An_Egyptian_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2smv.jpg"},{"t":"Ridge Racer 64","p":["Nintendo 64"],"d":"Nintendo Software Technology","u":"Nintendo, Namco Hometek","g":"Racing","r":"February 14, 2000","l":"https://en.wikipedia.org/wiki/Ridge_Racer_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6y4q.jpg","s":"Ridge Racer 64 gives Nintendo 64 owners a chance to jump into the world of Ridge Racer. Besides exclusive tracks, this edition contains races from the PlayStation Ridge Racer series, with improved graphics and a new set of cars."},{"t":"Ridge Racer V","p":["PlayStation 2"],"r":"October 26","l":"https://en.wikipedia.org/wiki/Ridge_Racer_V"},{"t":"Ring of Red","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Turn-based tactics","r":"September 21, 2000","l":"https://en.wikipedia.org/wiki/Ring_of_Red","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8x9q.jpg","s":"A highly classified prototype mech was stolen from the allied forces in southern Japan and it's up to you to get it back! Take control of monstrous mechs and brave soldiers. Immerse yourself in detailed 3D battle sequences with an exciting style of gameplay that mixes in-depth strategy and real-time action as you lead the allies to victor"},{"t":"Rip-Tide Racer","p":["Game Boy Color"],"d":"Cryo Interactive","u":"Cryo Interactive","g":"Racing","l":"https://en.wikipedia.org/wiki/Rip-Tide_Racer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7m9n.jpg","s":"Rip-Tide Racer is a Racing game, developed and published by Cryo Interactive, which was released in Europe in 2000."},{"t":"Rising Sun","p":["Windows"],"d":"TalonSoft","u":"Take-Two Interactive","g":"Computer wargame","r":"February 1, 2000","l":"https://en.wikipedia.org/wiki/Rising_Sun_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/i01uipiv1yrcdwdvjdlj.jpg","s":"Fight against, or as, the Japanese Imperial Army during WWII in a turn based environment."},{"t":"Risk II","p":["Windows","macOS"],"d":"Deep Red Games","u":"Hasbro Interactive","g":"Board game","r":"March 22, 2000","l":"https://en.wikipedia.org/wiki/Risk_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r5s.jpg","s":"The year is 1812. Napoleon's army is on the march, and it's every empire for itself. As Supreme Commander, you'll seize territories, crush your enemies, and betray your allies in a fast-paced, ruthless quest for world domination. Play the Classic Game under the familiar rules, trading cards for armies and rolling the dice to outdo your opponent. Play the Simultaneous-Turn option for a whole new Risk experience that includes I-COM communication and negotiation features, territory-depth enhancements, and territory bidding. Risk 2 is the ultimate form of this world-domination game that people of all ages have enjoyed for 40 years."},{"t":"Road Champs: BXS Stunt Biking","p":["Game Boy Color"],"d":"HotGen Ltd","u":"Activision","g":"Sports","r":"December 10, 2000","l":"https://en.wikipedia.org/wiki/Road_Champs:_BXS_Stunt_Biking","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fjb3cn19hwkumsambrmy.jpg","s":"Stunt biking makes an appearance on the Game Boy Color with ROAD CHAMPS BXS STUNT BIKING. When you start the game, you will have to progress through a 26-stage Training mode that teaches you how to perform all 50 moves in the game. After getting through training, you will be able take on a Single-Run, Career, or Tournament. The Single-Run mode allows you to work one course and master stringing tricks together, while Career mode has you compete in competitions to move from the amateur ranks to the world of the professionals. You can also compete in the Tournament mode to become the world champion. There are total of 64 unique levels spread throughout the game do you have what it takes to master ROAD CHAMPS BXS STUNT BIKING?"},{"t":"Road Rash: Jailbreak","p":["PlayStation"],"d":"EA Redwood Shores, Magic Pockets","u":"Electronic Arts","g":"Racing","r":"February 4, 2000","l":"https://en.wikipedia.org/wiki/Road_Rash:_Jailbreak","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6itz.jpg","s":"The Road Rash series continues with an all new chapter of intense motorcycle combat and racing action. In Road Rash: Jail Break it's up to you to bust the toughest rasher of all time, Spaz, out of jail! To accomplish this, you'll have to join a motorcycle gang and move up through the ranks by succeeding at a variety of challenges and winning races.\n\nYou also have the option of playing on the right side of the law in Five-O mode, where you are a police officer out to bust suspects and fill your rasher quota."},{"t":"Robot Warlords","p":["PlayStation 2"],"d":"Nexus Interact","u":"Dazz, Midas Interactive Entertainment","g":"Turn-based tactics","r":"August 10, 2000","l":"https://en.wikipedia.org/wiki/Robot_Warlords","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4tr7.jpg","s":"Robot Warlords is a Sci-fi turn based strategy game that was released on the PS2 back on December 14th 2001. It didn't get very good reviews, or sales and, hence, is very very rare."},{"t":"Robot Wars: Metal Mayhem","p":["Game Boy Color"],"d":"Tiertex Design Studios","u":"BBC Multimedia","g":"Action","r":"December 7, 2000","l":"https://en.wikipedia.org/wiki/Robot_Wars:_Metal_Mayhem","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co488l.jpg","s":"Robot Wars: Metal Mayhem is the first video game based on the British game show Robot Wars. In the game, a competitor robot from the series, or a robot created by the player, is entered into combat against a robot controlled by the game. A bout finishes when one robot's health bar is fully depleted."},{"t":"Rock 'Em Sock 'Em Robots Arena","p":["PlayStation"],"d":"Paradox Development","u":"Mattel Interactive","g":"Fighting game","r":"December 11, 2000","l":"https://en.wikipedia.org/wiki/Rock_'Em_Sock_'Em_Robots_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9rmc.jpg","s":"In this one-on-one fighting game based on the famous plastic robot fighters, players not only get to pit various Rock 'Em Sock 'Em Robots up against one another, they also get to customize their bots' various parts to make them even more steel-twisting and destructive than before.\n\nPlayers initially have 12 different robots to choose from before they head off to the arena. With names such as Slamurai, Sir Haxalot, and General Warfare, it's easy to see that Mattel Interactive is going for a bit of a tongue-and-cheek feel. While the names aren't overly serious, the fighting is less comedic, with the robots throwing all of their various armaments at their opponents in order to assure destruction. These weapons are varied, from swords to bombs to Gatling guns. Each robot starts with a different set of weapons, and depending on the mode you're playing, their attacks can be altered and switched around."},{"t":"Rockman Battle & Fighters","p":["Neo Geo Pocket Color"],"g":"Fighting","l":"https://en.wikipedia.org/wiki/Rockman_Battle_&_Fighters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2me6.jpg","s":"Rockman Battle & Fighters is a fighting game similar to the two arcade titles Mega Man: The Power Battle, and Mega Man 2: The Power Fighters. Playing as one of four characters (Mega Man, Proto Man, Bass, and Duo), the player chooses between three sets of boss battles with various Robot Masters from the series. The battles are fought linearly in any order, and after each boss is defeated, a special weapon is added to the player's arsenal. Each boss is weak to one specific weapon, so the player is encouraged to strategize the order in which the bosses are faced. Two players can use a link cable to transfer database information between systems, but no co-op or versus play is supported."},{"t":"Rollcage Stage II","p":["PlayStation","Windows"],"d":"Attention to Detail","u":"Sony Computer Entertainment, Midway Games, Take-Two Interactive","g":"Racing","r":"March 10, 2000","l":"https://en.wikipedia.org/wiki/Rollcage_Stage_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w50.jpg","s":"Rollcage Stage II is an arcade-style racing game for PlayStation and PC, developed by Attention To Detail, and published by Psygnosis. It is the sequel to Rollcage and was released in 2000. On top of the basic racing concept, the cars can be equipped with weapons, that are picked up on the track as bonuses, which can be used against competing cars. The automobiles themselves, once again, have wheels that are larger than the body of the car thus creating a car that has no 'right way up' and can be flipped and continue to drive."},{"t":"Romance of the Three Kingdoms VII","p":["Windows","macOS","PlayStation","PlayStation 2"],"d":"Koei","u":"Koei","g":"Turn-based strategy","l":"https://en.wikipedia.org/wiki/Romance_of_the_Three_Kingdoms_VII","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x90.jpg","s":"Romance of the Three Kingdoms VII, the seventh title of the series, invites you to live your own Three Kingdoms experience. You will travel back to ancient China and play as any of 535 possible characters. Features new to this installment include multiplayer modes and quicker gameplay. The game has 10 scenarios, each with multiple endings."},{"t":"Rome: Caesar's Will","p":["Windows"],"d":"Montparnasse Multimedia","u":"Montparnasse Multimedia","g":"Adventure, Educational","l":"https://en.wikipedia.org/wiki/Rome:_Caesar's_Will"},{"t":"Ronaldo V-Football","p":["PlayStation"],"d":"PAM Development","u":"Infogrames","g":"Sports","l":"https://en.wikipedia.org/wiki/Ronaldo_V-Football","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ex6.jpg","s":"Ronaldo V-Football is the pinnacle of soccer experiences for the PSX. Endorsed by international legend, Ronaldo Luis Nazario de Lima, Ronaldo V-Football brings Brazilian soccer traditions to the rest of the world. Boasting more than 100 real teams from around the globe, the game is set to an awesome Samba soundtrack and graced by colorful graphics."},{"t":"Roommania 203","p":["Dreamcast"],"d":"Wave Master","u":"Sega","g":"Life simulation","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Roommania_203"},{"t":"Roommate Novel: Sato Yuka","p":[],"l":"https://en.wikipedia.org/wiki/Roommate_Novel:_Sato_Yuka"},{"t":"Rowan's Battle of Britain","p":["Windows"],"d":"Rowan Software","u":"Empire Interactive","g":"Combat flight simulator","r":"December 8, 2000","l":"https://en.wikipedia.org/wiki/Rowan's_Battle_of_Britain","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/k0dimcaby14dhbtpa77j.jpg"},{"t":"Rugby","p":["Windows"],"d":"Creative Assembly","u":"EA Sports","g":"Sports","r":"September 1, 2000","l":"https://en.wikipedia.org/wiki/Rugby_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8nkw.jpg","s":"Rugby (known Rugby 2001 in the European PC version) is the 2000 installment of Electronic Arts' Rugby video game series.\n\nThe game was developed by Creative Assembly and published by EA Sports. The game is EA Sports' first rugby union game on Microsoft Windows and PlayStation 2, and was succeeded by Rugby 2004"},{"t":"Rugrats in Paris: The Movie","p":["PlayStation","Game Boy Color","Nintendo 64"],"d":"Avalanche Software, Software Creations, KnowWonder","u":"THQ, Mattel Interactive","g":"Action-adventure","r":"November 8, 2000","l":"https://en.wikipedia.org/wiki/Rugrats_in_Paris:_The_Movie_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r7a.jpg","s":"Tommy Pickle's father has been sent to Europe for maintenance work at Euroreptarland. The Rugrats join him on his travel to Europe. There are 16 levels and hidden bonus level to play through.\n\nThe game consists of various mini-games that have to be completed in order to earn enough tickets to beat the game. Most tickets, however, can just be collected by running around the park and picking them up. Tickets can be used to buy prizes. There are ten mini games including whack-a-ninja, bumper cars and mini-golf."},{"t":"Rugrats: Totally Angelica","p":["Game Boy Color"],"d":"Tiertex Design Studios, Art Co., Ltd","u":"THQ","g":"Action","r":"May 4, 2000","l":"https://en.wikipedia.org/wiki/Rugrats:_Totally_Angelica","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r7b.jpg","s":"It might be hard to root for the deplorable Angelica Pickles in the RUGRATS television series and films, but she's the star of this exciting video game. It seems that the oft-disgruntled heroine has decided to put together a little fashion show. It'll be up to you to help Angelica organize the entire event by seeking out wigs, purses, shoes, clothing, and other accessories from around the neighborhood. The show's success is entirely in your hands throughout this lighthearted search. All of the usual suspects are here as well, so prepare to get into tiffs with the likes of Chuckie, Tommy, Phil, and Lil. A plethora of mini-games keep things fun, challenging you to perform all sorts of activities based on the hit TV show. Winning these games will earn you rewards that can be used to help get the necessary materials for the fashion show. If the show succeeds, you'll get to move on to hidden areas for all-new challenges!"},{"t":"Rune","p":["Windows","macOS","Linux","PlayStation 2"],"r":"October 27","l":"https://en.wikipedia.org/wiki/Rune_(video_game)"},{"t":"Rune Caster","p":["Dreamcast"],"l":"https://en.wikipedia.org/wiki/Rune_Caster","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ngd.jpg","s":"Rune Caster (ルーンキャスター) is a Sega Dreamcast tactical role-playing game developed by Noisia and published by Vision."},{"t":"Rune Jade","p":["Dreamcast"],"g":"Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/Rune_Jade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8kyy.jpg","s":"Role-playing game that supported the Dreamcast Keyboard.\n\nUp to five people can participate simultaneously in this online RPG. The game can be played offline as well, as any party characters not controlled by players will be controlled by the computer. The adventure begins in the floating island country called Sonia, where demons are about to break free of the seal that keeps them under control."},{"t":"Sacrifice","p":["Windows"],"u":"Interplay Entertainment","r":"November 17, 2000","l":"https://en.wikipedia.org/wiki/Sacrifice_(video_game)"},{"t":"Samba de Amigo","p":["Dreamcast"],"u":"Sega","r":"April 27, 2000","l":"https://en.wikipedia.org/wiki/Samba_de_Amigo"},{"t":"Sammy Sosa High Heat Baseball 2001","p":["Windows","PlayStation"],"d":"Team .366","u":"The 3DO Company","g":"Sports","r":"March 7, 2000","l":"https://en.wikipedia.org/wiki/Sammy_Sosa_High_Heat_Baseball_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6iyk.jpg","s":"3DO's critically acclaimed High Heat Baseball franchise has a new star. The Roberto Clemente Man of the Year award winner for 1999, Sammy Sosa, lends his name to the newest installment of the popular baseball series. This edition boasts an advanced 3-D game engine and several new features. Sosa is among the 750 Major League Baseball players (from the 1999 and 2000 rosters) appearing in this game, which lets you create your own baseball league. This customization feature allows you to define the number of teams, length of schedule, playoff length, and other factors. In the career/season mode, you can make multiplayer trades based on numerous variables."},{"t":"Sammy Sosa Softball Slam","p":["Windows","PlayStation"],"d":"The 3DO Company","u":"The 3DO Company","g":"Sports","r":"February 29, 2000","l":"https://en.wikipedia.org/wiki/Sammy_Sosa_Softball_Slam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/kcaxr2gs6bx815zozepm.jpg","s":"Sammy Sosa Softball Slam brings the ultra-popular game of softball to the PlayStation game console for the first time ever for an entirely new game experience! \n \nStep up to the plate for more fast-paced game play as you knock out doubles and triples. All this over-the-top action comes screaming at you through a non-stop barrage of instant camera cuts combined with sizzling special effects, side-splitting animations and a bombastic announcer guaranteed to keep you on your toes and wanting more!"},{"t":"Sanity: Aiken's Artifact","p":["Windows"],"d":"Monolith Productions","u":"Fox Interactive","g":"Action","r":"September 22, 2000","l":"https://en.wikipedia.org/wiki/Sanity:_Aiken's_Artifact","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x7m.jpg","s":"In the near future, Psionics are among us. Their evil thoughts pulsate across time and space corrupting even the strongest minds. Players assume the role of Agent Cain, a powerful Psionic working for an elite government agency. As Cain, you strive for mastery of innate psychic “Talents” such as the ability to shoot fireballs or the power to summon hideous creatures. Using these “Talents” depletes both Health and Sanity, so players must walk a fine line to ensure that they don't lose their minds!"},{"t":"Sanvein","p":["PlayStation"],"d":"Success","u":"Success, Midas Interactive Entertainment, A1 Games","g":"Shoot 'em up","r":"March 30, 2000","l":"https://en.wikipedia.org/wiki/Sanvein"},{"t":"Science Seekers","p":["Windows","macOS"],"d":"Tom Snyder Productions, American Museum of Natural History","u":"Tom Snyder Productions","g":"Edutainment","l":"https://en.wikipedia.org/wiki/Science_Seekers"},{"t":"Scooby-Doo! Classic Creep Capers","p":["Windows","Nintendo 64"],"r":"November 30","l":"https://en.wikipedia.org/wiki/Scooby-Doo!_Classic_Creep_Capers"},{"t":"Scooby-Doo! Mystery Adventures","p":["macOS","Windows"],"d":"The Learning Company","u":"The Learning Company","g":"Adventure","r":"October 14, 2000","l":"https://en.wikipedia.org/wiki/Scooby-Doo!_Mystery_Adventures"},{"t":"Scooby-Doo!: Phantom of the Knight","p":["Windows"],"u":"The Learning Company","r":"November 1, 2000","l":"https://en.wikipedia.org/wiki/Scooby-Doo!:_Phantom_of_the_Knight"},{"t":"Screamer 4x4","p":["Windows"],"d":"Clever's Games","u":"Virgin Interactive","g":"Racing","r":"December 22, 2000","l":"https://en.wikipedia.org/wiki/Screamer_4x4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/p2xlnisp5qt5z3e38fcd.jpg","s":"Screamer 4x4 lets players loose on rough terrain in a range of modified off-road vehicles, ranging from the simple Land Rover to the massive RÁBA H18.\n\nPlayers compete in a series of time trial championships and trophies, earning new vehicles and upgrades as they go. There is a variety of play modes, including the option of a free drive (like Midtown Madness). Additionally, there is a range of multi-player games reminiscent of Carmageddon."},{"t":"Sea Dogs","p":["Windows"],"d":"Akella","u":"1C Company, Ubi Soft, Bethesda Softworks","g":"Role-playing","r":"November 24, 2000","l":"https://en.wikipedia.org/wiki/Sea_Dogs_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x92.jpg","s":"Combining elements of role-playing, naval combat, and strategy, Sea Dogs provides a boundless, endless pirating experience. Set in the 17th century, players begin with a small ship, allegiance to the British, French, Spanish, or pirates, and some general guidance on what to do next. The campaigns are nonlinear, meaning players can accept quests or play the game any way they want. Towns are a focal point in the game and allow players to repair, resupply, and upgrade their ships, pick up new crew members, look for work, or simply listen to rumors. Through trading or combat, players obtain additional ships to build and command an entire fleet. There are 20 types of ships to choose from, ranging from small corvettes to large battleships.\n\nLocation-specific ship damage allows players to send enemies' sails up in flames, bring their masts crashing to the deck, or shoot holes in their decks. Players can customize their ships with a variety of cannon and shot types to create devastating attacks. Wind and weather effects give advantages during combat and determine how ships sail in general. Players can choose to change allegiances at any time, giving up pirate life to join the cause of a country, leaving one country to fight for another, or choosing to serve only oneself as a pirate."},{"t":"Sega Extreme Sports","p":["Dreamcast"],"d":"Innerloop Studios","u":"Sega, Infogrames, Empire Interactive","g":"Sports","r":"October 27, 2000","l":"https://en.wikipedia.org/wiki/Sega_Extreme_Sports"},{"t":"Sega GT","p":["Dreamcast"],"d":"Wow Entertainment, TOSE","u":"Sega, Activision Value, Empire Interactive","g":"Sim racing","r":"February 17, 2000","l":"https://en.wikipedia.org/wiki/Sega_GT","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co43a4.jpg","s":"With a nod towards GT2, Sega tosses in their entry in the race-career-category, meaning that this game is all about racing. Racing to win competitions, cars, money and other prizes (such as licenses for bigger cars), buying new cars to race in, upgrading cars to race in and gaining licenses to race with.\n\nIt features realistic controls, graphic and physics, and spans over career, multiplayer or arcade modes, and hundreds of cars to boot."},{"t":"Sega Marine Fishing","p":["Arcade","Dreamcast"],"d":"Wow Entertainment","u":"Sega","g":"Sports","r":"March 2000","l":"https://en.wikipedia.org/wiki/Sega_Marine_Fishing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coat4p.jpg","s":"Sega Marine Fishing is a fishing video game in which the player attempts to catch various marine sport fish. The gameplay's emphasis was on enticing fish to bite onto the lure and then successfully fighting the fish and reeling it to the boat.\n\nAs the player catches fish, they earn item cards. Items earned with these cards include fish and artifacts for an aquarium, fishing equipment, additional boats, and various goofy accessories such as different colored shorts. The game also featured two modes of online play: tournament fishing and \"fish mail\". In tournament fishing, players competed to catch the biggest fish within a species. Fish mail consisted of writing short messages. Players could receive random messages by catching fish.\n\nSega Marine Fishing can be played using the Dreamcast fishing rod controller. You could customize your character with hats, shirts, etc."},{"t":"Sega Worldwide Soccer 2000 Euro Edition","p":[],"l":"https://en.wikipedia.org/wiki/Sega_Worldwide_Soccer_2000_Euro_Edition"},{"t":"Sentimental Graffiti","p":[],"l":"https://en.wikipedia.org/wiki/Sentimental_Graffiti"},{"t":"Shade","p":["MS-DOS"],"d":"Andrew Plotkin","u":"Andrew Plotkin","g":"Interactive Fiction, psychological horror","l":"https://en.wikipedia.org/wiki/Shade_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fpe.jpg","s":"A one-room interactive fiction game set in your apartment."},{"t":"Shadow Watch","p":["Windows"],"d":"Red Storm Entertainment","u":"Red Storm Entertainment","g":"Tactical role-playing, turn-based tactics","r":"April 13, 2000","l":"https://en.wikipedia.org/wiki/Shadow_Watch","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ypz.jpg","s":"Congratulations, Soldier, You've been recruited to lead an elite corporate commando squad. \n \nAs chief of security, it's your job to stop a deadly plot to destroy the construction of the world's first international space station. \n \nThere's no end to the adventure, or the danger, when you step into the shadows."},{"t":"Sheep","p":["PlayStation","Windows"],"d":"Mind's Eye Productions, Additional work by:, Capcom","u":"Empire Interactive","g":"Strategy, puzzle","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/Sheep_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wiv.jpg","s":"Sheep is a combination strategy and puzzle game, featuring light elements of war or battle simulations, built around a wacky story in which space-faring alien explorers from millennia ago devolve into domesticated sheep on Earth. Now their ancestors are trying to round them up by secretly enlisting the aid of two humans (Bo Peep and Adam Half Pint) and two animals (a sheepdog and a pet) through subliminal mind control.\n\nPlayers take the role of the Earthly \"herders\" to lead the flocks through six worlds with multiple levels, eventually reaching special rendezvous point where they'll be loaded onto UFOs for the trip back to their home world of Ovis Aries. No direct control is exerted on the sheep so players must manipulate objects and obstacles, as well as rely on the strengths of each herder, to accomplish the tasks. Levels have time limits and a minimum number of sheep to be saved from each flock."},{"t":"Shenmue","p":["Dreamcast"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Shenmue_(video_game)"},{"t":"Shiren the Wanderer 2: Shiren's Castle and the Oni Invasion","p":["Nintendo 64"],"d":"Chunsoft","u":"Nintendo","g":"Role-playing, roguelike","l":"https://en.wikipedia.org/wiki/Shiren_the_Wanderer_2:_Shiren's_Castle_and_the_Oni_Invasion"},{"t":"Shogun: Total War","p":["Windows"],"r":"June 13"},{"t":"Shooter: Space Shot","p":["PlayStation"],"d":"C.I.I.","u":"D3 Publisher, Agetec","g":"Scrolling shooter","r":"August 3, 2000","l":"https://en.wikipedia.org/wiki/Shooter:_Space_Shot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coatsk.jpg","s":"A shoot-'em-up that was originally released in Japan under the Simple 1500 Series Banner and later released in the US as a budget title by A1 Games through Agetec."},{"t":"Siege of Avalon","p":["Windows"],"d":"Digital Tome","u":"Take 2, Globalstar, Blackstar","g":"Action role-playing game","r":"July 19, 2000","l":"https://en.wikipedia.org/wiki/Siege_of_Avalon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co413k.jpg","s":"Siege of Avalon is a traditional fantasy-RPG with an isometric view. The setting is an imaginary land which has been ruined by wars and it is up to you to defeat the evil warrior Mithras, who strives to conquer the entire land. Only the fortress of Avalon resists to his evil intentions.\n\nThe game is mainly story-driven, featuring many NPCs, and has action-based combat. It doesn't follow any particular set of RPG rules; characters level up after having gained enough experience from defeating foes. Class restrictions are rather mild, meaning that a fighter can learn spells and gain proficiency in magic, etc.\n\nThis game has been described as an \"episodic computer game novel\". It is divided into six chapters. The first one is available for free download, but you have to buy the others in order to complete the story. Second chapter takes the events from where the first chapter ended, while third, fourth and fifth chapters are sort of add-ons to the main story. The sixth chapter is dedicated to the final battle with the evil."},{"t":"Silencer","p":["Windows"],"d":"Mind Control Software","u":"WON.net","g":"Shooter, capture the flag","l":"https://en.wikipedia.org/wiki/Silencer_(video_game)"},{"t":"Silent Scope 2","p":["Arcade"],"d":"Konami","u":"Konami","g":"Rail shooter","r":"March 2000","l":"https://en.wikipedia.org/wiki/Silent_Scope_2"},{"t":"SimCity 3000 Unlimited","p":["Windows"],"g":"Casual, Simulation, Strategy","r":"May 16","l":"https://en.wikipedia.org/wiki/SimCity_3000_Unlimited","i":"images/steam-2741560.jpg","s":"SimCity 3000 Unlimited brings you the classic strategy gaming of SimCity 3000 with all-new scenarios that open up a whole world of city planning and building possibilities! The thrills of the classic SimCity 3000 are here again!"},{"t":"SimCity 64","p":["Nintendo 64DD"],"d":"HAL Laboratory","u":"Nintendo","g":"City-building simulation","r":"February 23, 2000","l":"https://en.wikipedia.org/wiki/SimCity_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eth.jpg","s":"SimCity 64 is a city-building video game released only in Japan for the Nintendo 64DD, sequel to the SNES version of SimCity. It was the last SimCity game to feature the mayor assistant Mr. Wright."},{"t":"Sin and Punishment","p":["Nintendo 64"],"d":"Treasure, Nintendo R&D1","u":"Nintendo","g":"Rail shooter, shooting gallery","r":"November 21, 2000","l":"https://en.wikipedia.org/wiki/Sin_and_Punishment","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u47.jpg","s":"Earth is under threat from Ruffians - mutants bred to boost dwindling food stocks who have turned against their masters. As a young resistance fighter, face an onslaught of bio-genetic monsters and corrupt military forces in your battle to save the planet.\n\nFor the first time outside of Japan, you can experience the non-stop action of this Nintendo 64 classic, created by the shoot em up masters at Treasure Co. Ltd.\n\nBattle across land, sea and sky; collect energy, time and point bonuses; rack up massive combos to earn extra continues; and face the wrath of enormous bosses. Plus - invite a friend to join in, controlling the gun sight while you move the character."},{"t":"Sissyfight 2000","p":["Browser"],"d":"Word Magazine","u":"Word Magazine","g":"Turn-based strategy","l":"https://en.wikipedia.org/wiki/Sissyfight_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5zcd.jpg","s":"Sissyfight 2000 is a turn-based strategy online game developed by the Word online magazine staff, including executive producer Marisa Bowe, producer Naomi Clark, lead programmer Ranjit Bhatnagar, and art director Yoshi Sodeoka, with game designer Eric Zimmerman."},{"t":"Ski Resort Tycoon","p":["Windows"],"d":"Cat Daddy Games","u":"Activision Value","g":"Business simulation game","l":"https://en.wikipedia.org/wiki/Ski_Resort_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/i3erp4etjeh2pdlupeth.jpg"},{"t":"Skies of Arcadia","p":["Dreamcast"],"u":"Sega","r":"October 5, 2000","l":"https://en.wikipedia.org/wiki/Skies_of_Arcadia"},{"t":"Sky Odyssey","p":["PlayStation 2"],"r":"November 17","l":"https://en.wikipedia.org/wiki/Sky_Odyssey"},{"t":"Sky Surfer","p":["PlayStation 2"],"d":"Toka","u":"Idea Factory, Midas Interactive Entertainment","g":"Sports","r":"April 20, 2000","l":"https://en.wikipedia.org/wiki/Sky_Surfer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ge7.jpg","s":"Sky Surfer is a Sports game, developed by Toka and published by Idea Factory."},{"t":"Skyhammer","p":["Atari Jaguar"],"d":"Rebellion Developments","u":"Songbird Productions","g":"Shooter","r":"May 2000","l":"https://en.wikipedia.org/wiki/Skyhammer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ysz.jpg","s":"In a futuristic city, you are a mercenary pilot flying a helicopter-like craft in cyberspace. Hired by the large corporation Cytox, you are to defend its corporate holdings from those who seek to destroy all it has accomplished.\n\nThe numerous missions involve flying to several large cities and hunting down the renegades who threaten them. You have a cockpit view of the city as you hunt down your enemies and dock at the Cyber Mart for repairs. As you destroy your enemies and complete missions, you can earn credits for buying more supplies, weapons and ship upgrades at the Cyber Mart.\n\nPlay in Mission Mode or Battle Mode. To win the game, you must complete each mission successfully. The enemies become more tough as you progress through the \"levels\" of gameplay."},{"t":"Smashing Drive","p":["Arcade"],"d":"Gaelco, Point of View, Raylight Studios","u":"Gaelco, Namco Hometek, Zoo Digital Publishing","g":"Racing","l":"https://en.wikipedia.org/wiki/Smashing_Drive","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3r9u.jpg","s":"Smashing Drive puts you in the driver's seat of an insane, outrageous taxi on the busy streets of New York City. Your job is to simply race from point to point in the fastest time possible.\n\nThe key to success in Smashing Drive lies in two features: crazy power-ups and hidden shortcuts. Almost all of the power-ups transform your taxi in some way that allows you to smash your way through traffic with ease. And the shortcuts usually involve crashing through the insides of buildings, like movie theaters and sports arenas."},{"t":"Smuggler's Run","p":["PlayStation 2"],"d":"Angel Studios, Rebellion","u":"Rockstar Games, Destination Software","g":"Racing","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/Smuggler's_Run","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2lcd.jpg","s":"Drive, evade and explore anywhere across 3 vast levels - Rocky Mountain forest, desert and icy tundra.\nAs a member of a gang of international smugglers, it's your job to evade the U.S. Border Patrol, CIA and cutthroat rivals to deliver illegal cargo. It'll take complete mastery of your off-road vehicle to make it across unforgiving terrain and stay one step ahead...and make the drop."},{"t":"SNK Gals' Fighters","p":["Neo Geo Pocket Color"],"r":"February 19","l":"https://en.wikipedia.org/wiki/SNK_Gals%27_Fighters"},{"t":"Sno-Cross Championship Racing","p":["PlayStation","Dreamcast"],"d":"Unique Development Studios","u":"Crave Entertainment, Ubi Soft","g":"Racing, extreme sports","r":"August 9, 2000","l":"https://en.wikipedia.org/wiki/Sno-Cross_Championship_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3yw1.jpg","s":"Sno-Cross Championship Racing provides players with the opportunity to race 12 snowmobiles by Yamaha. In the championship mode snowmobiles can be upgraded with money won by winning races and performing tricks. There are 10 racing circuits set in such locations as Nagano, Aspen, and Munich. A track editor is included as well so that users can modify current tracks or create their own.\n\nStrap on your goggles and helmet, choose your favorite Yamaha sled, and hit the courses. Gain experience day and night, sun rain or snow, racing on the icy flats of Vladivostok, the slopes of Aspen, and the tunnels of Nagano."},{"t":"Snowboarding","p":["PlayStation"],"d":"Atelier Double","u":"D3 Publisher, A1 Games, Midas Interactive Entertainment","g":"Snowboarding","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/Snowboarding_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coavsv.jpg","s":"Agetec's Snowboarding consists of racing downhill and performing death-defying stunts. For speed fans, the Race Mode allows players to race against the clock or two computer-controlled opponents. For those more interested in catching big air, Snowboarding's Trick Mode requires gamers to perform numerous maneuvers to gain more time to complete courses. In both modes, gamers can choose from one of three different boarder characters as they ride through the game's 27 different courses. Additionally, each of these courses can be tackled by two players at once in a horizontally divided split-screen."},{"t":"Soda Constructor","p":[],"d":"Soda Creative Ltd","u":"Soda Creative Ltd","g":"Simulation","r":"April 5, 2000","l":"https://en.wikipedia.org/wiki/Soda_Constructor"},{"t":"Soldier of Fortune","p":["Windows"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Soldier_of_Fortune_(video_game)"},{"t":"Sonic Shuffle","p":["Dreamcast"],"r":"November 14","l":"https://en.wikipedia.org/wiki/Sonic_Shuffle"},{"t":"Sorcerian: Shichisei Mahou no Shito","p":["Dreamcast"],"g":"Platform, Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/Sorcerian:_Shichisei_Mahou_no_Shito","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xxx.jpg","s":"Another remake of the classic RPG Sorcerian this time exclusive to the SEGA Dreamcast. Once again you must take control of a party of 4 player-created adventurers and lead them through 10 scenarios from the original game and 5 new ones specially designed for this version in a side-scrolling fashion, each featuring a unique stand-alone quest for you to complete."},{"t":"Soulbringer","p":["Windows"],"d":"Gremlin Interactive","u":"Interplay Entertainment, Infogrames","g":"Fantasy RPG","r":"July 7, 2000","l":"https://en.wikipedia.org/wiki/Soulbringer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q7v.jpg","s":"Thousands of years ago six demon kings, known as the Revenants, ruled the world with an iron fist and bloody swords. Donning the bodies of mortal vassals, they could live in the realms of man forever. The great hero and warlock Harbinger was the only one who could stand up to their power. One by one he hunted the Revenants, taking their spirits and casting them into the Well of Souls. Alas, the Revenants survived. As a young man you will travel to meet your uncle in the town of Madrigal. There, your destiny draws you into the path that Harbinger trod - to confront the Revenants and banish their souls back to the Well forever. Your travels will take you far from Madrigal, to the ruined kingdoms of Horath, the ancient empire of Thardolin, and through the lost city of Talendrah. You will brave searing deserts and icy plains. You will have to seek answers among the living and the dead.\n\nCustomizable combat and magic system that can be as simple or as complex as you like.\nCompelling story with many twists and turns will keep you hooked for hours.\nDynamic music, high quality voice acting, and more than one possible ending."},{"t":"Space Channel 5","p":["Dreamcast"],"r":"June 4","l":"https://en.wikipedia.org/wiki/Space_Channel_5"},{"t":"Space Empires IV","p":["Windows"],"d":"Malfador Machinations","u":"Shrapnel Games, Strategy First","g":"Turn-based strategy, 4X","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/Space_Empires_IV","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ivm.jpg","s":"The award-winning Space Empires IV is the latest edition in the Space Empires series. A grand strategy title in the space 4X (explore, expand, exploit, and exterminate) genre, Space Empires has already found a place in the heart of strategy gamers everywhere.\n\nResearch technology, design new ships, wage war on a tactical level, put down rebellions, meet and greet new species, and much more. All the level and campaign design tools are included, allowing anyone to become a part of the expansive Space Empires Mod community."},{"t":"Speedy Gonzales: Aztec Adventure","p":["Game Boy Color"],"d":"Sunsoft","u":"Sunsoft","g":"Platformer","r":"January 2000","l":"https://en.wikipedia.org/wiki/Speedy_Gonzales:_Aztec_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lvadbwubcm4aavaqqdui.jpg","s":"Sylvester has kidnapped all of the mice in Mexico and it's up to Speedy Gonzales to rescue them. To get all the mice back, Speedy must collect the cheese in 18 different stages. However, the cheese will not be easy to collect, as along the way Speedy will have to make death-defying jumps while avoiding spikes, lava, and bottomless pits. In addition to those hazards, there are a number of enemies that are glad the mice are gone and don't want Speedy to rescue them. As luck would have it, there are power-ups and weapons scattered throughout the stages. After completing several stages, Speedy will have to face and defeat a boss character. Will Speedy be able to collect all of the cheese and defeat his enemies? Find out by playing SPEEDY GONZALES: Aztec Adventure."},{"t":"Spheres of Chaos","p":["Acorn Archimedes","Windows"],"d":"Iain McLeod","g":"Multidirectional shooter","l":"https://en.wikipedia.org/wiki/Spheres_of_Chaos"},{"t":"Spider-Man","p":["Windows","PlayStation","Game Boy Color","Nintendo 64"],"r":"September 1","l":"https://en.wikipedia.org/wiki/Spider-Man_(2000_video_game)"},{"t":"Spirit of Speed 1937","p":["Windows","Dreamcast"],"r":"July 31","l":"https://en.wikipedia.org/wiki/Spirit_of_Speed_1937"},{"t":"Spirou: The Robot Invasion","p":["Game Boy Color"],"d":"Planet Interactive Development","g":"Puzzle, Platformer","r":"November 14, 2000","l":"https://en.wikipedia.org/wiki/Spirou:_The_Robot_Invasion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1l8g.jpg","s":"Spirou: The Robot Invasion is a 2D side'scrolling platform game based on the Franco-Belgian comic Spirou et Fantasio."},{"t":"Sports Jam","p":["Arcade"],"d":"WOW Entertainment","u":"Sega, Agetec","g":"Sports video game","r":"December 2000","l":"https://en.wikipedia.org/wiki/Sports_Jam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co43ay.jpg","s":"Sports Jam has eight competitive sports for players to master in head-to-head 2-player matches. The goal is for the player to earn the title King of Sports, and this can only be done by mastering all 12 events including Football, Baseball, Hockey, Basketball, Tennis, Soccer, Golf and Cycling."},{"t":"Spyro: Year of the Dragon","p":["PlayStation"],"u":"Sony Computer Entertainment","r":"October 10, 2000"},{"t":"SSX","p":["PlayStation 2"],"u":"EA Sports","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/SSX"},{"t":"Star Trek: Armada","p":["Windows"],"d":"Activision","u":"Activision","g":"Real-time strategy","r":"March 27, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_Armada","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e92.jpg","s":"Star Trek: Armada is a real-time strategy game published in 2000 by Activision. The game's look and feel is based primarily on Star Trek: The Next Generation, and features a few of its main characters and ships. Playable factions include the United Federation of Planets, the Klingon Empire, the Romulan Star Empire and the Borg. The game received positive reviews and was noted for being one of the better Star Trek games to be made."},{"t":"Star Trek: ConQuest Online","p":["Windows"],"d":"Genetic Anomalies","u":"Activision","g":"Digital collectible card game","r":"June 21, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_ConQuest_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e9a.jpg","s":"A strategy game for the PC set in the Star Trek universe."},{"t":"Star Trek: Deep Space Nine: The Fallen","p":["Windows"],"r":"November 23"},{"t":"Star Trek: Invasion","p":["PlayStation"],"d":"Warthog Games","u":"Activision","g":"Space combat simulator","r":"August 23, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_Invasion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49gq.jpg","s":"The Borg are once again invading Federation space. Their target? Sector 001, Earth. You are part of an elite flying team known as Valkyrie squadron, commanded by none other than Lieutenant Commander Worf of Star Trek: The Next Generation fame.\n\nYou'll fly through different territories and encounter familiar races from the popular television series, including Klingons, Romulans, Borg and a new enemy known as the Kam'Jahtae. There are twists and turns throughout the game as you protect convoys from enemy attacks, engage galaxy class starships, and go on solo retrieve and rescue missions. The storyline is accented by the voices of actors Patrick Stewart (Captain Jean-Luc Picard) and Michael Dorn (Lieutenant Worf).\n\nYour ship is outfitted with phaser cannons and photon torpedoes, both of which you will have to master in order to succeed in your battles with enemy crafts. Users can play from a view behind their ship or from a first-person view inside the cockpit. The game supports analog control as well as force feedback, and uses up one block of memory on the standard PlayStation Memory Card to save progress."},{"t":"Star Trek: Klingon Academy","p":["Windows"],"d":"14 Degrees East","u":"Interplay Entertainment","g":"Space flight simulator","r":"June 22, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_Klingon_Academy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e9j.jpg","s":"Star Trek: Klingon Academy is a space flight simulator in the vein of Starfleet Academy. However the player controls Klingon spaceships rather than those of the Federation."},{"t":"Star Trek: New Worlds","p":["Windows"],"d":"Binary Asylum, 14 Degrees East","u":"Interplay Entertainment","g":"Real-time strategy","r":"August 29, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_New_Worlds","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e9m.jpg","s":"New Worlds was a Star Trek RTS released in 2000."},{"t":"Star Trek: Starfleet Command II: Empires at War","p":["Windows"],"d":"Taldren","u":"Interplay Entertainment","g":"Space flight simulator game, Real-time tactics","r":"December 12, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_Starfleet_Command_II:_Empires_at_War"},{"t":"Star Trek: Starship Creator Warp II","p":["Windows","macOS"],"d":"Imergy","u":"Simon & Schuster Interactive, JoWooD","g":"Vehicle simulation","r":"June 12, 2000","l":"https://en.wikipedia.org/wiki/Star_Trek:_Starship_Creator_Warp_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e9u.jpg","s":"A simulation game that lets you pilot the ships from Star Trek."},{"t":"Star Trek: Voyager – Elite Force","p":["Windows"],"r":"September 15"},{"t":"Star Wars Episode I: Obi-Wan's Adventures","p":["Game Boy Color"],"d":"HotGen","u":"THQ, LucasArts","g":"Action-adventure","r":"November 24, 2000","l":"https://en.wikipedia.org/wiki/Star_Wars_Episode_I:_Obi-Wan's_Adventures"},{"t":"Star Wars Episode I: Racer","p":["Dreamcast"],"r":"April 4"},{"t":"Star Wars Math: Jabba's Game Galaxy","p":["Windows","macOS"],"d":"Lucas Learning","u":"Lucas Learning","g":"Educational","r":"September 1, 2000","l":"https://en.wikipedia.org/wiki/Star_Wars_Math:_Jabba's_Game_Galaxy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ea1.jpg","s":"In Star Wars Math: Jabba's Game Galaxy, watch your students' brainpower grow as they face Jabba the Hutt in an age-old strategy game or play a variation of the familiar classroom game \"Pig\" with a classmate or a favorite character. Activities using addition, subtraction, multiplication, place value and equivalencies are included. Balanced attention to both computation and reasoning makes this a great choice."},{"t":"Star Wars: Demolition","p":["PlayStation","Dreamcast"],"d":"Luxoflux","u":"LucasArts, LucasArts/Activision","g":"Vehicular combat","r":"November 16, 2000","l":"https://en.wikipedia.org/wiki/Star_Wars:_Demolition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5vyd.jpg","s":"Star Wars: Demolition is a vehicular combat game set in the Star Wars universe created by both Luxoflux and LucasArts using the Vigilante 8 game engine. The premise of the game is that the Galactic Empire declares they have officially banned Jabba the Hutt's podraces, so Jabba creates a more life-threatening vehicular combat contest to replace the sport of podracing."},{"t":"Star Wars: Force Commander","p":["Windows"],"d":"LucasArts, Ronin Entertainment","u":"LucasArts","g":"Real-time strategy","r":"March 21, 2000","l":"https://en.wikipedia.org/wiki/Star_Wars:_Force_Commander","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6h6i.jpg","s":"Star Wars: Force Commander is a real-time strategy video game released for the Microsoft Windows platform on March 21, 2000. It was co-developed by Ronin Entertainment and LucasArts, and published by LucasArts."},{"t":"Star Wars: Racer Arcade","p":["Arcade"],"d":"Sega-AM5, LucasArts","u":"Sega","g":"Racing","r":"June 2000","l":"https://en.wikipedia.org/wiki/Star_Wars:_Racer_Arcade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wdb.jpg","s":"Star Wars Racer Arcade is a podracing arcade game produced by Sega and released in 2000.\n\nThere are four tracks in the game, each with their own level of difficulty: Bantha Tracks (Easy), Smuggler's Cove (Normal), Pixelito Challenge (Hard) and Boonta Eve Classic (Expert). The player can assume the role of either Anakin Skywalker, Ben Quadinaros, Gasgano or Sebulba."},{"t":"Star Wraith","p":["Windows"],"d":"StarWraith 3D Games","u":"StarWraith 3D Games","g":"Space combat simulator","l":"https://en.wikipedia.org/wiki/Star_Wraith"},{"t":"Starhorse","p":[],"g":"Horse racing","l":"https://en.wikipedia.org/wiki/Starhorse"},{"t":"Starlancer","p":["Windows","Dreamcast"],"r":"March 31","l":"https://en.wikipedia.org/wiki/Starlancer"},{"t":"StarPeace","p":["Windows"],"d":"Oceanus Communications","u":"Monte Cristo Multimedia, Oceanus Communications, Sega, Pugland","g":"MMORTS, City-building game","r":"December 2000","l":"https://en.wikipedia.org/wiki/StarPeace","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/eoaoohzvxfodtvnwy3wo.jpg","s":"Starpeace is a massive multiplayer online city building game developed by Oceanus."},{"t":"Starship Troopers: Terran Ascendancy","p":["Windows"],"d":"Blue Tongue Entertainment","u":"Hasbro Interactive","g":"Real-time tactics","r":"October 23, 2000","l":"https://en.wikipedia.org/wiki/Starship_Troopers:_Terran_Ascendancy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3j7v.jpg","s":"Starship Troopers: Terran Ascendancy is a real time strategy game with a common misunderstanding. This game is not based on the movie Starship Troopers. Both, the game and the movie, are based upon the novel by Robert A. Heinlein.\n\nThis is one of the few strategy games where you cannot build a base and recruit units. Instead you lead up to three squads into combat. Each squad contains a leader, five soldiers and one specialist (medic, engineer, PSI for detecting hidden bugs, MIST-Trooper as a sniper). During a mission there is no reinforcement and you are outnumbered by the bugs. The enemy units are not very intelligent, but they use their own special abilities like splitting acid and are very powerful. There is a wide range of enemies, from simple close-range fighters to suicide units, artillery bugs and even human soldiers. The mission objectives are also different. From simple hunting missions up to escorts or the capturing of bugs.\n\nThe game also have a RPG part. Surviving soldiers gain experience points for each killed bug / destroyed bug holes. By and by the soldiers increase their states and acquire higher ranks. Better battle suits (armor) and stronger weapons are only available for soldiers with high ranks. The basic soldier (called Cat Trooper) have no armor and is an easy prey for the bugs. Besides the experience points you gather upgrade points for your equipment for e.g. increase the damage of the weapons. Another aspect of the RPG part is that you can equip each of your soldiers individual with up to two different weapons and two tech-items (like bombs or toxic gas).\n\nThe graphic of the landscape is low on details, everything looks post apocalyptic. Much better is the combat graphic and the explosions. The cutscenes are made with the in-game graphic. Besides the sound effects your soldiers all have a voice to confirm your orders."},{"t":"Start-Up","p":["Windows"],"d":"Monte Cristo","u":"Monte Cristo","g":"Strategy","r":"January 12, 2000","l":"https://en.wikipedia.org/wiki/Start-Up_(video_game)"},{"t":"Steel Beasts","p":["Windows"],"u":"Shrapnel Games","g":"Action, Indie, Simulation, Strategy, Early Access","r":"September 24, 2000","l":"https://en.wikipedia.org/wiki/Steel_Beasts","i":"images/steam-1871460.jpg","s":"Beasts of Steel is a semi-realistic WWII game that combines FPS and Strategy where you can battle solo or online. Experience intense combat as an infantryman, tank crew, or take to the skies as a pilot. Unleash chaos and dominate the battlefield!"},{"t":"Stepping Selection","p":["PlayStation 2"],"d":"Jaleco","u":"Jaleco","g":"Music","r":"March 4, 2000","l":"https://en.wikipedia.org/wiki/Stepping_Selection","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nmnntqkqwpnn16rnfaus.jpg","s":"Stepping Selection is a rhythm game published by Jaleco for the PlayStation 2. The game features popular songs, but uses shortened cover versions of them instead of the original recording."},{"t":"Street Fighter EX3","p":["PlayStation 2"],"d":"Arika","u":"Capcom","g":"Fighting","r":"March 4, 2000","l":"https://en.wikipedia.org/wiki/Street_Fighter_EX3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p1u.jpg","s":"Street Fighter EX3 is the final game in the Street Fighter EX series series, taking the gameplay and additional moves of EX2, and adding a tag-team element. Multiple characters from the famous Street Fighter series return and clash with Arika's own characters."},{"t":"Street Fighter III: Double Impact","p":[],"l":"https://en.wikipedia.org/wiki/Street_Fighter_III:_Double_Impact"},{"t":"Street Sk8er 2","p":["PlayStation"],"d":"Atelier Double","u":"Electronic Arts, Micro Cabin","g":"Sports","r":"March 14, 2000","l":"https://en.wikipedia.org/wiki/Street_Sk8er_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ye7.jpg","s":"This is a skateboarding game very similar in gameplay to Tony Hawk's Pro Skater. You pick a skater and go through different skate parks, selecting either pro or amateur settings. You can also create your own skate park. Multiplayer competition is also provded, including 4 player serial play. Street Sk8er 2's sound track contains music from many well known bands such as Deftones, Ministry, and Static X."},{"t":"Strider 2","p":["PlayStation"],"r":"July 29","l":"https://en.wikipedia.org/wiki/Strider_2_(1999_video_game)"},{"t":"Stunt Racer 64","p":["Nintendo 64"],"d":"Boss Game Studios","u":"Midway","g":"Racing","r":"October 3, 2000","l":"https://en.wikipedia.org/wiki/Stunt_Racer_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co47zo.jpg","s":"Set in some unspecified time in the future, the gameplay includes more than simple racing. Older vehicles (primarily those regarded even today as classics) are retrofitted with futuristic engine and turbo technology, in addition to jets mounted to allow the car to perform midair stunts. These stunts, including flips, barrel rolls, etc., allow the player to accumulate cash rewards during races on levitating tracks. Money accumulated is used to purchase new cars, as well as upgraded parts for cars (This increases the value of the vehicle. Oddly enough, this feature is relatively useless because vehicles can't be sold.)"},{"t":"Stupid Invaders","p":["Windows"],"d":"Xilam Interactive, Titanium Studios","u":"Ubi Soft","g":"Adventure","r":"December 15, 2000","l":"https://en.wikipedia.org/wiki/Stupid_Invaders","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xc1.jpg","s":"Stupid Invaders is an adventure game based on the Space Goofs cartoon. The game was dedicated to its creator Jean-Yves Raimbaud, who died before the game was released."},{"t":"Submarine Titans","p":["Windows"],"d":"Ellipse Studios","u":"Strategy First","g":"Real-time strategy","r":"August 2, 2000","l":"https://en.wikipedia.org/wiki/Submarine_Titans","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2cgi.jpg","s":"Submarine Titans is a real-time strategy video game that takes place in the year 2115 after a comet has struck Earth, driving two human factions, the militant White Sharks and the scientific Black Octopi, to establish underwater bases and fight for dominance over the oceans. The comet also brought a mysterious alien race known as the Silicons, who compete with the two human factions to collect resources and build a gate that would take them back to their homeworld. Each faction has its own ten-mission campaign, and the player can play the three campaigns in any order."},{"t":"Sudden Strike","p":["Windows"],"d":"Fireglow Games","u":"CDV Software, Russobit-M, Strategy First","g":"Real-time strategy","r":"October 26, 2000","l":"https://en.wikipedia.org/wiki/Sudden_Strike_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaxym.jpg","s":"Sudden Strike is a World War II real-time tactics game released by CDV Software and developed by Fireglow. Players command Soviet, German, or Allied forces in combat scenarios that emphasize tactical decision-making over resource management and base building. The game features realistic military physics where terrain, buildings, and environmental factors affect unit performance and combat outcomes. Units can take cover in buildings, conduct reconnaissance, and require repairs when damaged. The expansion pack, Sudden Strike Forever, adds historically authentic units like the 1944 T-34 tank, new desert and snow environments, plus additional campaigns focused on specific military operations. The game includes multiple scenarios across various theaters of war, with players managing combined arms forces of infantry, tanks, and artillery while adapting to battlefield conditions and limited resources."},{"t":"Super Magnetic Neo","p":["Dreamcast"],"d":"Genki","u":"Genki, Crave Entertainment","g":"Adventure, Platformer","r":"February 3, 2000","l":"https://en.wikipedia.org/wiki/Super_Magnetic_Neo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v4d.jpg","s":"In Super Magnetic Neo, a gang lead by evil, foul-mouthed baby Pinki has taken over Pao Pao Park. The professor must stop her, so her sends Super Magnetic Neo, a little boy robot with a powerful electromagnet on his head.\n\nYou must use all these skills to make it through all four sections of Pao Pao Park and defeat Pinki."},{"t":"Super Mario 3 Special","p":[],"l":"https://en.wikipedia.org/wiki/Super_Mario_3_Special"},{"t":"Super Puzzle Bobble","p":["PlayStation 2"],"d":"Taito, Altron","u":"Taito, Acclaim Entertainment, Ubi Soft, CyberFront","g":"Puzzle","r":"September 28, 2000","l":"https://en.wikipedia.org/wiki/Super_Puzzle_Bobble"},{"t":"Super Robot Wars Alpha","p":["PlayStation"],"d":"Banpresoft","u":"Banpresto","g":"Tactical role-playing game","r":"May 25, 2000","l":"https://en.wikipedia.org/wiki/Super_Robot_Wars_Alpha","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobyka.jpg","s":"Super Robot Taisen Alpha is the second game in the series to be built from the ground up for the Playstation, and is the start of the Alpha series. Alpha is the first SRW to feature the highly choreographed animation that the series is known for."},{"t":"Super Runabout: San Francisco Edition","p":["Dreamcast"],"d":"Climax Entertainment","u":"Climax Entertainment, Interplay Entertainment, Virgin Interactive","g":"Racing","r":"May 25, 2000","l":"https://en.wikipedia.org/wiki/Super_Runabout:_San_Francisco_Edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7sxx.jpg","s":"Drive around San Francisco doing odd jobs and stopping a criminal syndicate from taking over. Includes everything from an Indy car to limousine."},{"t":"Superbike 2000","p":["Windows","PlayStation"],"d":"Milestone s.r.l.","u":"EA Sports","g":"Racing","r":"March 1, 2000","l":"https://en.wikipedia.org/wiki/Superbike_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/itd69dwyk5fho5xanwx3.jpg","s":"Straddle 150 horsepower of mechanical muscle and blast across 3D renditions of real-world tracks in EA Sports' sequel to 1999's Superbike World Championship. The game is designed to simulate the excitement and challenge of high performance motorcycle racing and features several champion riders to compete as and against. This PlayStation version of the game offers a split-screen mode for two-player head-to-head racing. \n \nFeatures: \n* Race all 13 circuits from the 1999 season \n* Hit the macadam on one of six superbikes including Ducati, Honda, Suzuki, and Yamaha"},{"t":"Superbike 2001","p":["Windows"],"u":"EA Sports","r":"October 6, 2000","l":"https://en.wikipedia.org/wiki/Superbike_2001"},{"t":"Supercross","p":["PlayStation"],"d":"Page 44 Studios","u":"EA Sports","g":"Racing, arcade","r":"November 29, 2000","l":"https://en.wikipedia.org/wiki/Supercross_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/j0aa3v1py5tsovk54ec8.jpg","s":"Supercross features a more action-oriented style of gameplay. Tricks are smoother and may come a little more easily, but players will still have to hold the right line and perfect their timing if they're going to be real contenders in the Motocross circuit. Players will race through several indoor and outdoor tracks in this dirt bike simulation from EA SPORTS, and a freestyle mode is available as well, offering a perfect track for maximum air and wild tricks.\n\nThe most notable change in Supercross is that EA opted to go with a more arcade-styled control scheme this time around. While this may come as a disappointment to gamers looking for the ultimate motocross sim, fact of the matter is, they tried the more realistic approach in the last game and it did not work well. Besides, with this game's new hold-the-accelerator-and-don't-let-go approach, gamers will get a better sense of the speed they would experience in they actually participated in a motocross event.\n\nThe game is known in usa as Supercross 2001"},{"t":"Surf Rocket Racers","p":["Dreamcast"],"d":"CRI Middleware","u":"CRI Middleware, Crave Entertainment, Crave/Ubi Soft","g":"Racing video game","l":"https://en.wikipedia.org/wiki/Surf_Rocket_Racers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44rl.jpg","s":"Surf Rocket Racers is a jet-ski racing game for the Dreamcast. As in most aquatic racers, success here depends on your ability to smoothly handle unpredictable waves and aggressive competition at the same time.\n\nThere are several game modes to choose from. First up is the Championship. In this mode, you compete in a series of circuit races and accumulate points based on your finishing position. The racer with the most points at the end of the season wins. The other modes include a trick competition, a hazard and obstacle course, and a head-to-head 2-player mode."},{"t":"Surfing H3O","p":["PlayStation 2"],"d":"Opus","u":"ASCII Entertainment, Rockstar Games","g":"Sports","r":"August 10, 2000","l":"https://en.wikipedia.org/wiki/Surfing_H3O","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/smozc5jnwypcembz99ln.jpg","s":"Surfing H3O is the first game to bring the danger and excitement of professional big wave surfing to the PlayStation 2 computer entertainment system. Set in beautiful locales, you must master hardcore surfing techniques to handle the most epic waves. Features include 11 playable characters each with specific characteristics, six unique surfing environments, over a dozen aerial tricks that can be linked for unlimited combinations, and an authentic punk rock-powered surf soundtrack courtesy of Hopeless Records. As an extra bonus, early versions of Surfing H30 shipped with a special patented X-Board controller attachment that latched onto the analog sticks of the Dual Shock to simulate the surfing experience."},{"t":"Suzuki Bakuhatsu","p":["PlayStation"],"d":"Sol","u":"Enix","g":"Puzzle","r":"July 6, 2000","l":"https://en.wikipedia.org/wiki/Suzuki_Bakuhatsu","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7k0r.jpg","s":"A bomb-disposal puzzle game released exclusively in Japan."},{"t":"Swamp Buggy Racing","p":["Windows"],"d":"Daylight Productions","u":"WizardWorks","g":"Racing","r":"January 2000","l":"https://en.wikipedia.org/wiki/Swamp_Buggy_Racing"},{"t":"Swing Away Golf","p":["PlayStation 2"],"d":"T&E Soft","u":"T&E Soft, Electronic Arts","g":"Sports","r":"March 23, 2000","l":"https://en.wikipedia.org/wiki/Swing_Away_Golf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3aau.jpg","s":"Bring your clubs, caddy, personality and attitude as you join Joe, Rachel, Kelly, Ryan and other golf nuts in a game packed with personality. Laugh, scowl, celebrate and hang your head in defeat- you're going to do it all. Play leisurely for fun, or rise from the amateur ranks to the official pro tour and experience real competition in story mode. Unlock courses, characters, and game modes while earning skill points, prizes, and virtual cash."},{"t":"Sword of the Berserk: Guts' Rage","p":["Dreamcast"],"r":"February 29"},{"t":"Sydney 2000","p":["PlayStation","Windows","Dreamcast"],"d":"Attention to Detail","u":"Eidos Interactive","g":"Sports","r":"August 22, 2000","l":"https://en.wikipedia.org/wiki/Sydney_2000_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co960i.jpg","s":"Sydney 2000 is the official Video Game of the Olympic Games. It features 32 countries represented in 12 events: 100M Sprint, 110M Hurdles, Hammer, Javelin, Triple Jump, High Jump, 100M Freestyle Swimming, Olympic Sprint Cycling, Skeet Shooting, Super Heavyweight Weight Lifting, 10M Platform Diving and Kayak K1 Slalom."},{"t":"Syphon Filter 2","p":["PlayStation"],"d":"Eidetic","u":"989 Studios, Sony Computer Entertainment","g":"Third-person shooter","r":"March 14, 2000","l":"https://en.wikipedia.org/wiki/Syphon_Filter_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gft.jpg","s":"Syphon Filter 2 is a third-person shooter stealth video game developed by Eidetic and published by 989 Studios exclusively for PlayStation. Hours after the events of the first game, Gabriel Logan and Lian Xing are enemies of the state to the Agency after uncovering its connection to Syphon Filter, labelled as terrorists to the general public."},{"t":"Tachyon: The Fringe","p":["Windows"],"d":"NovaLogic","u":"NovaLogic","g":"Space combat simulation","r":"March 30, 2000","l":"https://en.wikipedia.org/wiki/Tachyon:_The_Fringe","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rjz.jpg","s":"Caught in the middle of a violent conflict on the fringe of the galaxy - your ability to survive will depend on your piloting skills and combat savvy as a mercenary space fighter. But, as you explore the vastly detailed world of Tachyon: The Fringe, you will often find that the most powerful weapon on your ship is in your head."},{"t":"Tales of Eternia","p":["PlayStation"],"d":"Wolfteam, Namco Tales Studio","u":"Namco, Namco Hometek, Ubisoft","g":"Action role-playing game","r":"November 30, 2000","l":"https://en.wikipedia.org/wiki/Tales_of_Eternia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9alk.jpg","s":"Tales of Eternia is an action japanese role playing game, with real time battle scenes (combos and spells can be assigned to the face buttons).\n\nThe game is set in the fantasy world of Inferia, follows the story of a young hunter named Reid Hershel and his friends, Farah and Keele, as they meet a mysterious girl who speaks an unknown language. Their subsequent quest to discover her origins leads them across a dimensional boundary to an entirely different realm known as Celestia, where they become involved in an age-old conflict between the two worlds.\n\nIt would later inspire a 13-episode anime co-produced by Production I.G loosely based on the game's plot."},{"t":"Tales of Phantasia: Narikiri Dungeon","p":["Game Boy Color"],"d":"Wolfteam","u":"Namco","g":"Role-playing video game","r":"November 10, 2000","l":"https://en.wikipedia.org/wiki/Tales_of_Phantasia:_Narikiri_Dungeon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6sw4.jpg","s":"Tales of Phantasia: Narikiri Dungeon is a Dungeon RPG. It is the first sequel in the Tales series, which normally does not have connected storylines. The story begins 205 years after the beginning of Tales of Phantasia."},{"t":"Talking Walls","p":["Windows","macOS"],"d":"Edmark","u":"Edmark","l":"https://en.wikipedia.org/wiki/Talking_Walls"},{"t":"Tang Tang","p":["Arcade"],"d":"Excellent Soft Design, GameVision Corporation","u":"Excellent Soft Design, GameVision Corporation, Take-Two Interactive","g":"Platform","r":"May 23, 2000","l":"https://en.wikipedia.org/wiki/Tang_Tang","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobp7m.jpg","s":"This GBA game mimics the gameplay of Solomon's Key. Players are tasked with creating and destroying blocks to collect items and reach stage exits."},{"t":"Tatsunoko Fight","p":["PlayStation"],"d":"Electronics Application","u":"Takara","g":"Fighting","r":"October 5, 2000","l":"https://en.wikipedia.org/wiki/Tatsunoko_Fight","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9pby.jpg","s":"Anison Spirits's top 3, Sasaki Isao, Mizuki Ichio, Horie Michiko, line-up! Completely original opening and ening music as well as original animation work by Tatsunoko Pro! Every character's opening and ending is of course, loaded with rare, game-only animation.\n\nGatchaman, Casshan, Tekkaman, Polymer... A dream match of Tatsunoko Pro's representative heroes! Many sure-kill moves are reproduced from famous scenes in the anime! So those who are not skilled at action games, a \"Sure-kill move button\" is included! Furthermore! A modern arranged heroes anime, subtitle-less opening and ending theme is included!!"},{"t":"Taz Express","p":["Nintendo 64"],"d":"Zed Two","u":"Infogrames","g":"Puzzle, Platformer","r":"August 1, 2000","l":"https://en.wikipedia.org/wiki/Taz_Express","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4b68.jpg","s":"Taz - a delivery boy? Would you trust THIS guy to deliver your fragile package?\n\nTired of seeing Taz do nothing but hang around the house and watch TV, She-Devil decides Taz needs to find a job. She finds the perfect one for him - as a delivery boy for the next courier service, \"Taz Express\". Your job: Help Taz protect the package long enough to deliver it."},{"t":"Team Buddies","p":["PlayStation"],"d":"Psygnosis Camden","u":"Sony Computer Entertainment, Midway Home Entertainment","g":"Action, Real-time strategy","r":"September 15, 2000","l":"https://en.wikipedia.org/wiki/Team_Buddies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7cps.jpg","s":"One fine and sunny day in the land that Buddies roam, there was a great and mighty disco in a tent. This tent would bob up and down with the music. All of a sudden, a large, flat, grey, flying THING blocked out the sun (The Great Eclipse) and began to drop crates. These crates were filled with all sorts of goodies such as Uzis and Bazookas. Inevitably, chaos broke out and the buddies became segregated according to color."},{"t":"Tech Romancer","p":["Dreamcast"],"r":"March 31","l":"https://en.wikipedia.org/wiki/Tech_Romancer"},{"t":"Tekken Tag Tournament","p":["PlayStation 2"],"r":"March 30","l":"https://en.wikipedia.org/wiki/Tekken_Tag_Tournament"},{"t":"Tempest 3000","p":["Nuon"],"d":"Llamasoft","u":"Hasbro Interactive","g":"Tube shooter","r":"December 13, 2000","l":"https://en.wikipedia.org/wiki/Tempest_3000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xqu.jpg","s":"Tempest 3000 is a remake of the Tempest arcade game and a sequel to Tempest 2000, written by Jeff Minter for Nuon. It was released on December 12, 2000. By 2003, the game had sold over 20,000 copies."},{"t":"Tenchu 2: Birth of the Stealth Assassins","p":["PlayStation"],"d":"Acquire","u":"Activision, Acquire","g":"Stealth","r":"August 8, 2000","l":"https://en.wikipedia.org/wiki/Tenchu_2:_Birth_of_the_Stealth_Assassins","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f37.jpg","s":"Tenchu 2 is a prequel to Tenchu, telling a tale of events prior to those of the previous game.\n\nOnce again, you can play as Ayame or Rikimaru, two faithful and honorable ninja whose lord is a gentle man in an age of warfare. With your training nearly complete, you find yourself caught up in aiding your lord against a civil war in his own domain. All is not what it seems, however, and you'll soon realize that your greatest threat has been forged much like you.\n\nMuch like its predecessor, Tenchu 2 is a 3D third person stealth action game. You are not only rewarded for stealth, but also for efficiency of movement this time. This extra feature increases the difficulty of achieving the better items, as you not only have to be quiet, but be direct and near perfect in your steps."},{"t":"Terminus","p":["Windows","macOS","Linux"],"d":"Vicarious Visions","u":"Vatical Entertainment","g":"Role-playing, space flight simulator","r":"June 29, 2000","l":"https://en.wikipedia.org/wiki/Terminus_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9n7s.jpg","s":"Terminus is a space-flight role-playing/action computer game by Vicarious Visions. It was released in 2000 for Microsoft Windows, Linux, and Apple Macintosh. Terminus won awards in the 1999 Independent Games Festival for \"Technical Excellence\" and \"Innovation in Audio\".\n\nTerminus is outstanding in its implementation of Newtonian laws of motion, which means that objects are subject to inertia. Once accelerated, they float indefinitely into one direction, unless again accelerated into a different direction. This makes steering quite complicated, but mirrors actual behaviour in free space.\n\nIn Story mode, the player chooses one of four careers (United Earth League military, Mars Consortium militia, Marauder Pirate Clan, mercenary) and follows Terminus's single-player storyline, set in the year 2197. In 2000, Terminus was unusual among RPGs in that the player's actions can affect the ending of the storyline. Failing a mission, for example, may lead to a different ending than would have occurred if the mission had succeeded. One unique feature of Terminus is the story would progress with or without the player. The player could begin the game in story mode, then go off and do something else and the story missions/battles would still take place, reaching an outcome depending on which side eventually wins."},{"t":"Terracon","p":["PlayStation"],"d":"PictureHouse Software","u":"Sony Computer Entertainment","g":"Action-adventure","r":"August 25, 2000","l":"https://en.wikipedia.org/wiki/Terracon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6rd7.jpg","s":"THE EVIL TERRACON is mercilessly wiping out the Galaxy, planet by planet. As Xed, the toughest little alien ever hatched, you have to face the Terracon Terror in the greatest adventure in the galaxy."},{"t":"Test Drive 2001","p":["Game Boy Color"],"d":"Xantera","u":"Infogrames","g":"Racing","r":"November 28, 2000","l":"https://en.wikipedia.org/wiki/Test_Drive_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/xyburhilugdezmu0lh9g.jpg","s":"All of the action and excitement of sports car racing comes to the Game Boy Color with TEST DRIVE 2001. You can choose from 13 real world cars including the Lotus Elise, Dodge Viper, Jaguar XK-R, and a 1985 Ford Mustang and customize any of them to meet your driving style. Then you can hit one of 48 tracks in 12 different locations. While on the track, you need to watch out for jumps, shortcuts, and traffic that will ram into your vehicle. Try to learn all of curves of a track in a Single Race, or if you are looking for extended competition, try to win a Tournament. For the ultimate challenge, try to catch speeding criminals in the Cop Chase. If your friends want to race you, they can with the link cable option. Get a car and lay some rubber on the street in TEST DRIVE 2001."},{"t":"Test Drive Cycles","p":["Game Boy Color"],"d":"Xantera","u":"Infogrames North America","g":"Racing","r":"July 25, 2000","l":"https://en.wikipedia.org/wiki/Test_Drive_Cycles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coabd8.jpg","s":"If you want the thrill of riding at high speeds on two wheels on a tight track with deadly curves and bone-jarring jumps, look no further TEST DRIVE CYCLES has all of that and more! You've got an assortment of bikes from licensed manufacturers such as Harley Davidson, BMW, Moto Guzzi, and Bimota. Once you've selected your speed machine, head to the track in one of 12 different racing circuits. Each course is packed with twists, turns, and jumps that will test your skill and push you to the edge. Watch out for other racers and obstacles as you speed to the finish line, or you may end up wrecking your fancy ride. By winning races, you can upgrade your bike with various parts that will increase your speed and handling. If you're looking for multiplayer action, link up to race against another player in a Head-to-Head race to the finish. There is also the Cop Chase mode, where you must avoid being pulled over by the fuzz. TEST DRIVE CYCLES is compatible only with Game Boy Color systems."},{"t":"Thandor: The Invasion","p":["Windows"],"d":"Innonics","u":"World: JoWooD Productions, Buka Entertainment","g":"Real-time strategy","r":"December 1, 2000","l":"https://en.wikipedia.org/wiki/Thandor:_The_Invasion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa0yf.jpg","s":"Thandor is a 3D RTS game where you build units and battle other factions for control of resources (to build more units)."},{"t":"The ClueFinders Search and Solve Adventures","p":["Windows","macOS"],"d":"The Learning Company","u":"The Learning Company","g":"Educational/Mystery","l":"https://en.wikipedia.org/wiki/The_ClueFinders_Search_and_Solve_Adventures"},{"t":"The Devil Inside","p":["Windows"],"d":"Gamesquad","u":"Cryo Interactive, TalonSoft","g":"Third-person shooter, survival horror","r":"March 30, 2000","l":"https://en.wikipedia.org/wiki/The_Devil_Inside_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2y3w.jpg","s":"The Devil Inside is a third-person action horror game in which Dave, a hero with a dark secret, is compelled to participate in a cruel television reality show in which he has to please the audience by killing monsters. Dave has a female demonic alter ego called Deva. The player can transform between Dave and Deva at certain places in the stages. Dave mostly uses guns equipped with laser sights. Deva, on the other hand, casts spells that require magic points, which can be restored by consuming souls left from defeated enemies, as well as float in the air and regenerate her health under specific circumstances."},{"t":"The Dukes of Hazzard II: Daisy Dukes It Out","p":["PlayStation"],"d":"Sinister Games","u":"SouthPeak Interactive, Ubi Soft","g":"Racing","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/The_Dukes_of_Hazzard_II:_Daisy_Dukes_It_Out","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coat92.jpg","s":"In Dukes of Hazzard II: Daisy Dukes it Out, it will take a player's racing prowess and lead foot to make it through the pitfalls and troubles of this dusty country county. Players will control either the Duke boys in their high-powered General Lee or Daisy in her jeep as they sweep through the dirt roads and downtown of Hazzard. Levels alternate between the two vehicles, and the objectives you must complete are varied as well. You might find yourself outrunning the law or perhaps showing someone the sights in Hazzard. You might even deliver some mail, but eventually you'll get down to some good, old-fashioned crime fighting."},{"t":"The Emperor's New Groove","p":["Windows","PlayStation","Game Boy Color"],"r":"November 13","l":"https://en.wikipedia.org/wiki/The_Emperor%27s_New_Groove_(video_game)"},{"t":"The F.A. Premier League Stars 2001","p":["Windows","PlayStation"],"d":"Electronic Arts, Krisalis Software","u":"Electronic Arts, THQ","g":"Sports","l":"https://en.wikipedia.org/wiki/The_F.A._Premier_League_Stars_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/dzwus2ztaedt2hjkperj.jpg","s":"Featuring the most exciting and challenging football league in the world, The F.A. Premier League Stars allows players to experience the fast paced action of the English Premier League right from the start of the 2000/2001 season. This GBC version based on the PC game features actual player names with all your favorite players from the F.A. Premier League (16 per team). The players exhibit differing levels of football skills as they do in real life. Controls allow for curling and chips with the help of aftertouch. Play quick matches or create and play in your own league of your favorite 2, 4, 6 or 8 teams for the EA Cup."},{"t":"The Flintstones: Bedrock Bowling","p":["PlayStation","Windows"],"d":"Adrenalin Entertainment","u":"Ubi Soft, SouthPeak Interactive","g":"Sports action","r":"July 28, 2000","l":"https://en.wikipedia.org/wiki/The_Flintstones:_Bedrock_Bowling","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coat96.jpg","s":"Prehistoric times, beware -- The Flintstones have invaded the bowling alley! Fred Flintstone, Barney Rubble, Pebbles, Bamm-Bamm, and Dino are taking advantage of a newly transformed Bedrock. That pesky alien Gazoo is always up to no good; now he's turned the entire town into massive bowling lanes complete with obtruding hazards and lots of rock!"},{"t":"The Grid","p":["Arcade"],"d":"Midway Games","u":"Midway Games","g":"Third-person shooter","l":"https://en.wikipedia.org/wiki/The_Grid_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4b03.jpg","s":"The Grid is a 2000 arcade game by Midway. It is a third person shooter which consists of a super-violent television game show hosted by a Smash TV-like host. The game centres around deathmatches. Players control their character using a joystick with a trigger for shooting, a top button for jumping and trackball for aiming. The object of each match is to accumulate the most points by eliminating other opponents. Local multiplayer with up to six players is possible by linking up multiple cabinets. Computer-controlled bots can also be used in place of human opponents. Players can also collect cash that can be used to upgrade player attributes. Individual player progress and statistics can be saved and retrieved through unique account numbers that are entered on a keypad.\n\nThe game was created by the developers behind the Mortal Kombat series of games and has cameos from characters Sub-Zero, Scorpion, and Noob Saibot. This was Midway's last arcade game."},{"t":"The Grinch","p":["Dreamcast"],"r":"October 31","l":"https://en.wikipedia.org/wiki/The_Grinch_(video_game)"},{"t":"The Jungle Book Groove Party","p":["Windows","PlayStation"],"d":"Ubi Soft Montreal, Ubi Soft Shanghai","u":"Ubi Soft","l":"https://en.wikipedia.org/wiki/The_Jungle_Book_Groove_Party"},{"t":"The King of Fighters 2000","p":["Windows","Dreamcast","PlayStation 2","Arcade"],"r":"July 26","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters_2000"},{"t":"The King of Fighters: Battle de Paradise","p":["Neo Geo Pocket Color"],"d":"SNK","u":"SNK","g":"Party","r":"June 6, 2000","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters:_Battle_de_Paradise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob5m0.jpg","s":"The King of Fighters: Battle de Paradise is a minigame collection, similar to Mario Party or Sonic Shuffle, based loosely on The King of Fighters '99."},{"t":"The Land Before Time: Dinosaur Arcade 3D","p":["macOS","Windows"],"g":"Arcade","l":"https://en.wikipedia.org/wiki/The_Land_Before_Time:_Dinosaur_Arcade_3D","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9bym.jpg","s":"The Land Before Time: Dinosaur Arcade is an educational game for Windows-based PCs intended for children ages 4-7 released by Sound Source Interactive in North America in November 2000. The game features five minigames revolving around Littlefoot, Spike, Petrie, Ducky, and Chomper that involve guiding them around various levels and a pinball-style game. Children's Software Review noted that it was less educational than others in its genre, calling it a \"strictly an entertainment title\", with little real educational value except for some practice with eye-hand coordination and logic."},{"t":"The Land Before Time: Return to the Great Valley","p":["PlayStation"],"g":"Platform","l":"https://en.wikipedia.org/wiki/The_Land_Before_Time:_Return_to_the_Great_Valley","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9bz4.jpg","s":"After being chased by a Sharptooth while returning a stolen egg, Littlefoot, Cera, Ducky, and Spike become lost in the Great Beyond. Players control the four prehistoric pals as they each must find the way back home in The Land Before Time: Return to the Great Valley for PlayStation. Journeying through five 3D levels, the characters must collect treestars while avoiding perilous pitfalls.\n\nLevels contain interactive elements, such as plants and tar bubbles. Depending upon the selected character, players can make use of tail whipping, head butting, and other abilities to build bridges, ride geysers, and overcome other obstacles. Petrie is also readily available to fly onscreen and offer advice and direction. Levels are composed of obstacle courses and puzzle-type action as players need to cross rivers, feed plants, and collect treestars while avoiding hazards, such as lava, water, and steep cliffs. After all five characters exit the fifth level, they are all reunited in the Great Valley."},{"t":"The Last Blade: Beyond the Destiny","p":["Neo Geo Pocket Color"],"d":"SNK","u":"SNK","g":"Fighting","r":"March 16, 2000","l":"https://en.wikipedia.org/wiki/The_Last_Blade:_Beyond_the_Destiny","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ac2.jpg","s":"1863. History's hidden secret is revealed. During the age known as \"Bakumatsu\", 135 years ago, chaos rules! It's all yours: A new type of weapon fighting game in which Power and Speed weapons, in addition to various Repel moves can be used to experience a new sensation in video game thrills!"},{"t":"The Legend Of Dragoon","p":["PlayStation"],"r":"June 13","l":"https://en.wikipedia.org/wiki/The_Legend_Of_Dragoon"},{"t":"The Legend of the Prophet and the Assassin","p":["Windows","macOS"],"d":"Arxel Tribe","u":"Arxel Tribe, Wanadoo Edition, DreamCatcher Interactive","g":"Adventure","r":"October 2000","l":"https://en.wikipedia.org/wiki/The_Legend_of_the_Prophet_and_the_Assassin"},{"t":"The Legend of Zelda: Majora's Mask","p":["Nintendo 64"],"u":"Nintendo","r":"April 27, 2000"},{"t":"The Lion King: Simba's Mighty Adventure","p":["PlayStation","Game Boy Color"],"d":"Paradox Development, Torus Games","u":"Activision","g":"Platform","r":"December 22, 2000","l":"https://en.wikipedia.org/wiki/The_Lion_King:_Simba's_Mighty_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3d3n.jpg","s":"After his father is killed, the young lion prince Simba must travel through the jungle to find his life's path. Eventually, he will return home and claim his rightful place as the Lion King. On his journey, Simba must avoid such dangers of the jungles and plains as wildebeests and rhinos. When he encounters these enemies as a cub, his roar does little to scare them off. However, maturing into a majestic lion deepens his voice and makes the growl useful as a weapon. As he explores the nine levels, Simba will be able to collect a wide variety of items that will open several bonuses that include puzzles, mini-games, and movies. While the film was animated in 2D, Simba and his world are rendered in three dimensions, and the plot unfolds in cinematic sequences between each level. You've got to help Simba take his rightful place in DISNEY'S THE LION KING: Simba's Mighty Adventure."},{"t":"The Little Mermaid 2: Pinball Frenzy","p":["Game Boy Color"],"r":"September 24"},{"t":"The Little Mermaid II: Pinball Frenzy","p":["Game Boy Color"],"d":"Left Field Productions","u":"Nintendo","g":"Pinball","r":"September 24, 2000","l":"https://en.wikipedia.org/wiki/The_Little_Mermaid_II:_Pinball_Frenzy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7x2p.jpg","s":"This game is basically Pokémon Pinball minus all the pokémon plus Ariel and her young daughter, Melody -- and a lot of minigames.\n\nThe game features four-player support via alternating tables, as well as a battery-powered rumble feature for those who absolutely must feel every tilt and tumble of the table."},{"t":"The Lost Golem","p":["Dreamcast"],"d":"Caramelpot","u":"Caramelpot","g":"Puzzle Game","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/The_Lost_Golem","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3kd1.jpg","s":"A Dreamcast puzzler developed mostly by one Japanese student, Golem no Maigo (also known by its English translation \"The Lost Golem\") tasks you with guiding the king to the end of every stage by pushing walls around while also ensuring there are enough walls that remain intact to progress."},{"t":"The Messenger","p":["macOS","PlayStation","Windows"],"d":"4x Technologies, Arxel Tribe, Visual Impact","u":"Wanadoo Edition, Canal+ Multimedia, Réunion des Musées Nationaux, Microïds","g":"Adventure game","r":"November 9, 2000","l":"https://en.wikipedia.org/wiki/The_Messenger_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yb2.jpg","s":"The most terrifying conspiracy has travelled through the centuries and you have been chosen to go back in time to prevent disaster! You are a Secret Service Agent and you have been sent against your will into the very depths of the ancient Louvre castle. Your mission is to wage battle against a mysterious Tempilar brotherhood, thirsty for chaos. You may never return to the 21st century... You are plunged into a 3D world that is astoundingly realistic and filled with historical characters. You will discover a castle that has never been seen before, accurately reconstructed with the help of the Louvre Museum.\nWhat you need in this mentally stimulating adventure are action and reflection. You must uncover the clues and cleverly question the game's characters"},{"t":"The Misadventures of Tron Bonne","p":["PlayStation"],"r":"April 30","l":"https://en.wikipedia.org/wiki/The_Misadventures_of_Tron_Bonne"},{"t":"The Mummy","p":["Windows","PlayStation","Game Boy Color"],"d":"Rebellion Developments, KCE Nagoya","u":"Konami, Universal Interactive Studios","g":"Action-adventure","r":"November 16, 2000","l":"https://en.wikipedia.org/wiki/The_Mummy_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49hh.jpg","s":"The Mummy is an action horror released as a tie-in for the 1999 Film of the same name.\nIt is a platform game for the PlayStation 1 game console and Microsoft Windows. The game is based mostly on the first film in the The Mummy series, taking place immediately after Evie resurrects Imhotep."},{"t":"The New Adventures of the Time Machine","p":["Windows"],"d":"Cryo Interactive","u":"Cryo Interactive, DreamCatcher Interactive","g":"Adventure","r":"April 2, 2000","l":"https://en.wikipedia.org/wiki/The_New_Adventures_of_the_Time_Machine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9cfj.jpg","s":"Inspired by the classic story of H.G. Wells, take the role of an intrepid time adventurer trapped in a mysterious future. The only way home may be the demi-god Khronos, Master of the Hourglass... In a similar manner to Myst, players move around a 3-dimensional world in first person. Collect objects and explore various locations to solve various puzzles. Speak with other characters and grapple with action elements during the game's 40+ hours of playing time."},{"t":"The Operative: No One Lives Forever","p":["Windows"],"u":"Fox Interactive","r":"November 9, 2000"},{"t":"The Powerpuff Girls","p":[],"l":"https://en.wikipedia.org/wiki/The_Powerpuff_Girls_(Sennari_Interactive_games)"},{"t":"The Powerpuff Girls: Bad Mojo Jojo","p":["Game Boy Color"],"r":"November 14","l":"https://en.wikipedia.org/wiki/List_of_The_Powerpuff_Girls_video_games"},{"t":"The Ring: Terror's Realm","p":["Dreamcast"],"d":"Asmik Ace Entertainment","u":"Asmik Ace Entertainment, Infogrames North America","g":"Survival horror","r":"February 24, 2000","l":"https://en.wikipedia.org/wiki/The_Ring:_Terror's_Realm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co439w.jpg","s":"Patterned after genre-defining games such as Resident Evil and Silent Hill, The Ring: Terror's Realm presents a survival-horror experience with all the standard features one would expect. Players assume the role of Meg Rainman, the girlfriend of fellow CDC employee Robert, who, along with three other colleagues, met a mysterious and untimely death while playing a new video game. Determined to uncover the truth, Meg discovers the program on Robert's computer and is promptly sucked into a virtual world. Here, she becomes infected with a virus and has only the next seven days to live.\n\nThe Ring: Terror's Realm presents players with a handful of different perspectives including third-person, first-person, and a dynamic viewpoint similar purpose to that in the Resident Evil series, which provides constantly changing camera angles. The core gameplay has players traveling between the real and virtual worlds while acquiring items, solving puzzles, and killing larvae, lizards, gorillas, and other monsters. Initially armed with little more than a basic handgun, Meg will eventually amass weapons such as a shotgun, an assault rifle, a rocket launcher, and more.\n\nWhen in the virtual world, players can make use of a flashlight to help Meg find her way through the darkened corridors. Other useful items she include healing serum and various context-sensitive objects that will aid her progress through the adventure. Often, Meg will be required to seek out a specific character in order to advance. Cut scenes highlight important encounters throughout the quest. Players can record their progress using devices scattered around the game world and can manage their inventory by placing unwanted items in boxes, which also are found in various locations."},{"t":"The Sims","p":["Windows","macOS"],"u":"Electronic Arts","r":"February 4, 2000","l":"https://en.wikipedia.org/wiki/The_Sims_(video_game)"},{"t":"The Sims: Livin' Large","p":["Windows","macOS"],"d":"Maxis","u":"Electronic Arts, Aspyr Media","g":"Social simulation","r":"August 29, 2000","l":"https://en.wikipedia.org/wiki/The_Sims:_Livin'_Large"},{"t":"The Virtual Disappearance of Miriam","p":[],"l":"https://en.wikipedia.org/wiki/The_Virtual_Disappearance_of_Miriam"},{"t":"The Ward","p":["Windows"],"d":"Fragile Bits","u":"LMI, On-Deck Interactive","g":"Adventure; Science fiction","l":"https://en.wikipedia.org/wiki/The_Ward_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eoy.jpg","s":"The Ward is a point and click adventure video game. The story follows the fictionalized version of events of the Apollo 19 mission from 1979. Two of the crew member are found dead, with the protagonist, David Walker, finding himself in an extraterrestrial laboratory. Throughout the story, the protagonist realizes he is meant to be the mythical Ward, in order to resolve the conflict between two alien races; the Greys and the Reptillians.\nHe sets out to help humanity from total annihilation, but also aids Greys in their war against their former masters, the reptillians. During the course of the adventure, he uncovers many secrets and histories of the universe."},{"t":"The Wild Thornberrys: Rambler","p":["Windows","Game Boy Color"],"d":"Human Code, Vicarious Visions","u":"Mattel Interactive","g":"Action","r":"August 7, 2000","l":"https://en.wikipedia.org/wiki/The_Wild_Thornberrys:_Rambler","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa0n3.jpg","s":"The Wild Thornberrys are trying to win the Golden Schweitzer, an award given for the best nature documentary in the world. You take control of Nigel, Marianne, Eliza, Darwin, Debbie, and Donnie as they travel through six wacky levels of action. Along the way, they will have to travel to exotic locations like the Galapagos Islands, Amazon Rain Forest, Savannah Desert, African Congo, Himalayan Mountains, and Australian Outback. Each area has unique mini-games that can be set to three different difficulty levels. The games include sneaking up on animals and videotaping them, driving the Thornberry bus through the jungle, and helping Nigel collect items as he rappels down the side of a cliff. When you complete a game, the difficulty level determines what ending you see. Help the crew win the big award in THE WILD THRONBERRYS: Rambler."},{"t":"The World Is Not Enough","p":["Windows","PlayStation","Nintendo 64","Game Boy Color"],"r":"November 6","l":"https://en.wikipedia.org/wiki/The_World_Is_Not_Enough_(PlayStation_video_game)"},{"t":"Theocracy","p":["Windows","Linux"],"d":"Philos Laboratories","u":"Ubi Soft","g":"Real-time strategy","r":"March 24, 2000","l":"https://en.wikipedia.org/wiki/Theocracy_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coavgs.jpg","s":"Theocracy is a real-time strategy game for the PC developed by Philos Laboratories and published by Ubisoft in 2000. The game takes place in Mexico and Central America in the 15th century. The player controls a tribe in this region, and has 100 years to prepare for a Spanish invasion by expanding their territory across the Central American map, by conquest, or by allying and trading with other tribes."},{"t":"They Hunger","p":["Windows"],"d":"Black Widow Games","g":"First-person shooter","r":"February 2000","l":"https://en.wikipedia.org/wiki/They_Hunger"},{"t":"Thief II","p":["Windows"],"u":"Eidos Interactive","g":"Indie, Racing","r":"March 23, 2000","l":"https://en.wikipedia.org/wiki/Thief_II","i":"images/steam-4920360.jpg","s":"Catch the thieves within a limited time, and elude the police in an even tighter window. Enjoy the fun of playing tag in a cops-and-robbers theme, available in both single-player and two-player game modes."},{"t":"Thief II: The Metal Age","p":["Windows"],"g":"Action, Simulation","r":"March 23","l":"https://store.steampowered.com/app/211740","i":"images/steam-211740.jpg","s":"The ultimate thief is back! Tread softly as you make your way through 15 new complex, non-linear levels full of loot to steal and guards to outsmart. Improved enemy AI, new gadgets and a riveting story will draw you into the world of Thief II: The Metal Age, a place of powerful new technologies, fanatical religions and corruption."},{"t":"This Is Football 2","p":["PlayStation"],"d":"Team Soho","u":"Sony Computer Entertainment","g":"Sports","r":"November 3, 2000","l":"https://en.wikipedia.org/wiki/This_Is_Football_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lji5bztboxcgkyizlotq.jpg","s":"The sequel to 'This Is Football', attempts to make a realistic yet enjoyable football game. Fully licenced by FIFAPro (International Association of Football Players' Unions) to use every players real name, dozens of the most famous football stadiums from around the world (Mexico, England, Italy, etc.) are faithfully represented while nearly every major football league, cup or competition is included."},{"t":"Threads of Fate","p":["PlayStation"],"r":"July 18","l":"https://en.wikipedia.org/wiki/Threads_of_Fate"},{"t":"Three Kingdoms: Fate of the Dragon","p":["Windows"],"d":"Overmax Studios, Object Software Limited","u":"Eidos Interactive","g":"Real-time strategy","r":"December 21, 2000","l":"https://en.wikipedia.org/wiki/Three_Kingdoms:_Fate_of_the_Dragon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co236t.jpg","s":"Three Kingdoms: Fate of the Dragon is a Real Time Strategy game based on the Romance of the Three Kingdoms."},{"t":"Tiger Woods PGA Tour 2001","p":["Windows","PlayStation"],"d":"Headgate Studios, Stormfront Studios, EA Redwood Shores","u":"EA Sports","g":"Sports","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/Tiger_Woods_PGA_Tour_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co39tj.jpg","s":"Swing into action with the first-ever PS2 golf game from Electronic Arts in Tiger Woods PGA Tour 2001. In all, six pro golfers take to the green on three real-life courses including SpyGlass Hill, Pebble Beach, and Poppy Hills as they swing and putt their way through exact replicas of all 18 holes.\nThe varied modes of play are now supported by two new entries, Challenge and Play-Now, in addition to such returning staples as Match, Skins, and Stroke."},{"t":"Tigger's Honey Hunt","p":["PlayStation","Nintendo 64"],"d":"Doki Denki Studio","u":"NewKidCo, Ubi Soft, Disney Interactive","g":"Platform","r":"September 27, 2000","l":"https://en.wikipedia.org/wiki/Tigger's_Honey_Hunt","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vtd.jpg","s":"Winnie the Pooh needs YOU! How can he throw a party without honey? Play as Tigger and run, jump, and bounce around the 100 Acre Wood in search of Pooh's \"most favorite\" snack. Along the journey there'll be plenty of challenges - blustery blowing leaves to ride, icy terrain, falling boulders, menacing bees, pesky bats and more. Earn Tigger's very special \"Tiggertastic Bounce\" as a bonus!"},{"t":"Timeline","p":["Windows"],"r":"November 10","l":"https://en.wikipedia.org/wiki/Timeline_(video_game)"},{"t":"Times of Conflict","p":["Windows"],"d":"Eugen Systems","u":"Microids","g":"Real-time strategy","r":"December 5, 2000","l":"https://en.wikipedia.org/wiki/Times_of_Conflict","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6z5c.jpg","s":"Times of Conflict is a Sci-Fi RTS game developed by Eugen Systems."},{"t":"TimeSplitters","p":["PlayStation 2"],"r":"October 26","l":"https://en.wikipedia.org/wiki/TimeSplitters_(video_game)"},{"t":"TOCA World Touring Cars","p":["PlayStation"],"d":"Codemasters, Spellbound","u":"Codemasters, Spike","g":"Racing","r":"August 25, 2000","l":"https://en.wikipedia.org/wiki/TOCA_World_Touring_Cars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9h1n.jpg","s":"TOCA World Touring Cars (Called Jarrett & Labonte Stock Car Racing in the USA and WTC: World Touring Car Championship in Japan) is a racing video game developed and published by Codemasters, and released for PlayStation in 2000, and for Game Boy Advance only in Europe in 2003. It is part of the TOCA Touring Car series.\n\nIt features various Touring Car championships from around the world, but despite carrying the TOCA name, a fully licensed British Touring Car Championship (ToCa) series was not included. This upset a lot of fans of the series, but success continued. The gameplay overall became more \"Arcade\" and the replacement of qualifying laps with random grid positions together with the omission of penalties for bad driving made the game much more playable for the casual gamer. Curiously, unlike the first two titles in the TOCA series, World Touring Cars was not released in a Microsoft Windows version."},{"t":"Tokusatsu Bouken Katsugeki Super Hero Retsuden","p":["Dreamcast"],"l":"https://en.wikipedia.org/wiki/Tokusatsu_Bouken_Katsugeki_Super_Hero_Retsuden","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qxqh1cuolmpxbuaftcwj.jpg","s":"An action adventure game featuring characters from various sentai franchises."},{"t":"Tokyo Majin Gakuen: Fuju Hōroku","p":["WonderSwan"],"d":"Shout! Design Works","u":"Asmik Ace, Marvelous Entertainment","g":"Visual Novel, Digital collectible card game","r":"October 12, 2000","l":"https://en.wikipedia.org/wiki/Tokyo_Majin_Gakuen:_Fuju_H%C5%8Droku"},{"t":"Tokyo Xtreme Racer 2","p":["Dreamcast"],"d":"Genki","u":"Genki, Crave Entertainment, Crave/Ubi Soft","g":"Racing","r":"June 22, 2000","l":"https://en.wikipedia.org/wiki/Tokyo_Xtreme_Racer_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44y2.jpg","s":"The thrilling followup to the original, Tokyo Xtreme Racer 2 improves in all fronts. With more road to drive on, rivals to fight, and cars to master, this entry offers everything and more.\n\nIn the game, you race around the streets of Tokyo at night in an almost seamless experience, from cruising around, to joining a race, to cruising again. Flash your headlights when tailing a rival to incite a race, and after a short cinematic, you're both off. To win a race, you need to take down your opponent's power meter, while keeping yours intact. It decreases when hitting objects, and, more importantly, in last place.\n\nThe game is less focused on the realism of a racer, but still takes into account a good amount of customization, from upgrades to tuning. Since you'll be driving the car almost constantly, its best to have your own personal vehicle. The roads you drive on start out limited, but expand as you dive deeper and deeper into the game. Don't expect to go without memorizing the tracks; in order to beat the best, you need to make Tokyo your home."},{"t":"Tom and Jerry in Fists of Furry","p":["Nintendo 64","Windows"],"d":"VIS Interactive","u":"NewKidCo, Ubi Soft","g":"Fighting","r":"November 8, 2000","l":"https://en.wikipedia.org/wiki/Tom_and_Jerry_in_Fists_of_Furry","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4aoy.jpg","s":"One-on-one fighting! Tag team tournaments! Just choose your character and then select the location. All the environments are modeled after scenes from your favorite Tom & Jerry episodes. An \"All-Star\" line-up of characters such as Tom, Jerry, Butch, Spike, Tuffy, and Duckling help to make this the ultimate Tom & Jerry experience! Weapons include shovels, bombs, red-hot pokers, tennis rackets, furniture and an assortment of fruit, plus there are countless other tricks, traps and surprises to be found. It doesn't get any better than this. So go to your corner, wait for the bell and come out fighting. Just keep an eye out behind you, because no one fights fair in this game!"},{"t":"Tom and Jerry in House Trap","p":["PlayStation"],"d":"Warthog Games","u":"NewKidCo, Ubi Soft","g":"Action","r":"November 20, 2000","l":"https://en.wikipedia.org/wiki/Tom_and_Jerry_in_House_Trap","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uam.jpg","s":"As defiant mouse Jerry, single-players move about the house setting traps for Tom the cat. As Jerry continues to set traps in one half of the split screen, players can watch the results in the other half of the screen as Tom falls victim to (or outsmarts) the traps that have already been set. If Jerry notices that Tom seems to be getting a little too close for comfort, he can also blow his dog whistle and Spike will come to chase after Tom and even the odds a bit.\n\nWhen two people play at once, one can take on the role of Tom and help him to avoid the traps that Jerry sets. The game features 15 different rooms to explore, each with its own challenges and rewards, and each successive level unlocks a new room in the house with more weapons scattered throughout. While most of the challenges involve reducing the other player's health first, some levels require rubber duckies be collected and placed in a pond. The first player to collect the required amount wins the match."},{"t":"Tom Clancy's Rainbow Six","p":["Dreamcast"],"r":"May 9","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_Rainbow_Six_(video_game)"},{"t":"Tomb Raider","p":["Game Boy Color"],"r":"June 12","l":"https://en.wikipedia.org/wiki/Tomb_Raider_(Game_Boy_Color)"},{"t":"Tomb Raider: Chronicles","p":["Windows","PlayStation","Dreamcast"],"r":"November 17"},{"t":"Tonka Digs N Rigs","p":["Windows"],"d":"ImageBuilder Software","g":"Educational","r":"September 2000","l":"https://en.wikipedia.org/wiki/Tonka_Digs_N_Rigs"},{"t":"Tony Hawk's Pro Skater","p":["Dreamcast","Nintendo 64"],"u":"Crave Entertainment","r":"May 22, 2000","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater"},{"t":"Tony Hawk's Pro Skater 2","p":["PlayStation","Dreamcast","Windows","Game Boy Color"],"u":"Activision","r":"September 20, 2000","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_2"},{"t":"Toonsylvania","p":["Game Boy Color"],"d":"RFX Interactive","u":"Ubi Soft, Light & Shadow Production","g":"Platform","r":"June 2000","l":"https://en.wikipedia.org/wiki/Toonsylvania_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa9nx.jpg","s":"Having grown tired of being a mad scientist's assistant, Igor creates four inventions: the diving suit, the helmet lamp, the propeller helmet, and the fireproof helmet. Wanting to test them, he has Phil (a gentle Frankenstein-type monster) put them all on. Unfortunately, the combination of all four inventions causes Phil to explode. You must guide Igor through 15 levels as he searches for all of Phil's parts, as well as all four of his inventions to complete the quest. However, getting through the levels is no walk in the park, as enemies lurk behind every corner. Fortunately, there are plenty of weapons to collect and throw at them. Will Igor be able to restore Phil before the mad scientist comes home? Find the answer by playing TOONSYLVANIA for the Game Boy Color"},{"t":"Top Gear Hyper Bike","p":["Nintendo 64"],"d":"Snowblind Studios","u":"Kemco","g":"Racing","r":"March 17, 2000","l":"https://en.wikipedia.org/wiki/Top_Gear_Hyper_Bike"},{"t":"Top Gear: Dare Devil","p":["PlayStation 2"],"d":"Papaya Studio","u":"Kemco","g":"Racing","r":"December 19, 2000","l":"https://en.wikipedia.org/wiki/Top_Gear:_Dare_Devil","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co82q6.jpg","s":"Top Gear: Dare Devil is a game for the Sony PlayStation 2 that involves driving around the cities of Rome, London, Tokyo, and San Francisco.\nThis game consists of Single player and multiplayer.\n\nIn single player, the player drives around one of the four cities, collecting Dare Devil coins. If all Dare Devil coins in a level are collected, the player unlocks a secret car. What also can be collected are keys and wrenches that open up bonus missions. After winning a bonus mission, the player can unlock a paint job for the car used. The player can also free roam around cities.\n\nIn multiplayer, there are three game modes:\n\nLap Racing\nBomb Tag\nCoin Grab"},{"t":"Trade & Battle: Card Hero","p":["Game Boy Color"],"d":"Nintendo R&D1, Intelligent Systems","u":"Nintendo","g":"Role-playing","r":"February 21, 2000","l":"https://en.wikipedia.org/wiki/Trade_&_Battle:_Card_Hero","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9oxt.jpg","s":"The first game in the Card Hero franchise by Yoshio Sakamoto and Intelligent Systems."},{"t":"Traffic Giant","p":["Windows"],"d":"JoWooD Productions","u":"JoWooD Productions, Macmillan Software","g":"City-building game, real-time strategy","r":"March 2, 2000","l":"https://en.wikipedia.org/wiki/Traffic_Giant","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44ud.jpg","s":"Traffic Giant is Public Transit tycoon game released in 2000 by JoWood Productions. Players make public transit routes using various vehicles such as buses, street cars and subways from a top down isometric perspective."},{"t":"Tread Marks","p":["Windows"],"g":"Shooter, Racing","l":"https://en.wikipedia.org/wiki/Tread_Marks","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ykruc8ewarn9qyc8y5wc.jpg","s":"Tread Marks is a tank action game featuring tree different gameplay modes. The first is race mode, in which players race each other on an off-road circuit and can push or shoot their opponents to hinder them. Battle mode is like deathmatch or team deathmatch, the most kills win the game. In capture the flag mode, two or more teams try to capture the other team's flags."},{"t":"Treasure Strike","p":["Dreamcast"],"g":"Fighting","l":"https://en.wikipedia.org/wiki/Treasure_Strike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5s3v.jpg","s":"A four player action puzzle game with deep character customization"},{"t":"Triangle Heart","p":["Windows"],"d":"ivory","u":"Janis","g":"Eroge","l":"https://en.wikipedia.org/wiki/Triangle_Heart"},{"t":"Trick Boarder","p":["Game Boy Color"],"d":"Act Studio","u":"Natsume","g":"Sports, Racing","r":"June 30, 2000","l":"https://en.wikipedia.org/wiki/Trick_Boarder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/d8p6wtwajym3ulngyuxc.jpg","s":"Send yourself speeding down a hill to claim first place in TRICK BOARDER. Choose from eight snowboarders, each with different attributes. Learn how to navigate all nine tracks and set speed records in the Time Trial mode. When you want to compete, try to claim the championship in the Grand Prix mode, where you earn points by finishing well on all nine tracks. If you have friends that are into snowboarding, you can challenge them to a race via the link cable. No matter what mode you play, you must keep an eye out for obstacles, or you will lose precious speed and time. Luckily, you can pick up icons that will give you turbo boosts, and you can perform tricks or go through slalom gates that will award additional speed boosts as well. Work your way through the ranks to become a snowboarding champion in TRICK BOARDER."},{"t":"Tricolore Crise","p":["Dreamcast"],"l":"https://en.wikipedia.org/wiki/Tricolore_Crise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5d1s.jpg","s":"Tricolore Crise (which is read as the English word \"crisis\") is a Japan-only Dreamcast RPG developed by HuneX, a prolific developer of visual novels as well as the Blue Breaker series.\n\nBoasting an ATB-influenced battle system and a slew of mostly optional story events loosely set to a calendar, this open-ended fantasy tale in the vein of the early Atelier games tasks the player with guiding a newly formed team of three young women through the examination process that will test whether they are worthy to become masters of one of many magical towers that protect human civilisation from the threat of the Iblis, a savage, menacing, and mysterious race of magical monsters.\n\nThe player may only control one of the three protagonists at any given time, but may switch freely between them, with certain events only being accessible to certain characters. The three may also each be accompanied in their quest by up to two Mitsukai, or \"Angels\". These guardian spirits can be freely altered and developed by the player, giving the game elements of a monster raising sim."},{"t":"Triple Play 2001","p":["PlayStation","Windows","Game Boy Color"],"d":"Treyarch, Handheld Games","u":"EA Sports, THQ","g":"Sports","r":"March 14, 2000","l":"https://en.wikipedia.org/wiki/Triple_Play_2001","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w3h.jpg","s":"The highly popular baseball series TRIPLE PLAY makes its appearance on the Game Boy Color with TRIPLE PLAY 2001. You can play with or against any of the 30 Major League teams with complete rosters based on the 1999 season. You can also play in all of the Major League ballparks. Once you have chosen your team, try to hit as many homers as possible in the Home Run Derby. When you are ready for real competition, play a game against any opponent. While pitching, you can throw curves, fastballs, and change-ups. And when you're at the plate, you decide when to swing for the fences and when to hit for average. Get all of the baseball action you can handle with TRIPLE PLAY 2001."},{"t":"Tsukihime","p":["Windows"],"g":"Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Tsukihime","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40hg.jpg","s":"This story is about a young boy named Tohno Shiki who, after experiencing a traumatic accident, wakes up in the hospital with the ability to see lines and cracks in every surface and being. These lines, when traced with any sharp or blunt edge, will be permanently cut. As he is forced to see these lines everywhere, Shiki is distraught until he meets a mage girl who gives him glasses that allow him to live a normal life.\n\nYears later, after living in a relative's home, the death of his father has him summoned back to the mansion he left years ago. There he must learn to live with his younger sister and two maid girls.\n\nOne day Shiki's life takes a turn for the worst when, on the way to school, he meets a blonde woman and he's overcome with the urge to kill her."},{"t":"Tsuushin Taisen Logic Battle Daisessen","p":[],"l":"https://en.wikipedia.org/wiki/Tsuushin_Taisen_Logic_Battle_Daisessen"},{"t":"Turnabout","p":["PlayStation"],"d":"Artdink","u":"Artdink, Natsume Inc., Zoo Digital Publishing","g":"Puzzle","r":"April 6, 2000","l":"https://en.wikipedia.org/wiki/Turnabout_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4erh.jpg","s":"While the old adage that \"turnabout is fair play\" applies in many situations, Natsume's Turnabout is all about diabolical puzzles where players rotate the entire puzzle while the pieces move within its borders, sliding and rolling into mind-numbing configurations and patterns. The 100 puzzles provided are divided into two groups of 50: Begin Mode and Main Mode. The first 50 puzzles must be solved in order to open up the remaining 50, but the puzzles are numbered in five rows of ten each -- solving seven rounds in a row will open up the next row of ten, thus the puzzles needn't be solved sequentially.\n\nPuzzle pieces in Turnabout come in three types: colored balls, colored blocks, and sliding blocks. By rotating the puzzle board, balls and sliding blocks adhere to the forces of gravity and fall down into open slots. Manipulating the puzzle correctly takes skill and usually no more than ten to fifteen \"steps,\" even at advanced levels. Learning to solve puzzles backward by picturing the flow of the pieces mentally can be an essential tool to success and none of the 100 puzzle board configurations are the same shape. For players looking for even more challenges, up to 50 custom-made puzzles can be devised, using five different colored balls and blocks and nine movable sliders (blocks) in Edit Mode."},{"t":"Turok 3: Shadow of Oblivion","p":["Nintendo 64"],"d":"Acclaim Studios Austin","u":"Acclaim Entertainment","g":"First-person shooter","r":"August 31, 2000","l":"https://en.wikipedia.org/wiki/Turok_3:_Shadow_of_Oblivion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zqo.jpg","s":"Turok 3: Shadow of Oblivion picks up where Turok 2: Seeds of Evil left off. Oblivion, a monstrous cosmic entity that consumed everything in its path and reigned before the birth of our universe is now invading the bodies of the living and devouring them from the inside-out. When the Primagen's Lightship was destroyed, the chain reaction it triggered as a result was so powerful that the universe as it existed was completely eradicated, and the almighty Oblivion was pushed to the very brink of destruction. For the first time, Oblivion felt pain, fear, and hate.\n\nOblivion survived and now desperately seeks a means to punch through the Netherscape that separates our world from the Lost Lands. The last shreds of the pure energy source that created our world and nearly wiped out Oblivion are contained within the Light Burden, the bag that every member of the Turok lineage has carried. Unless Danielle and Joseph Fireseed, siblings that carry the title of Turok, can stop the death of the Turok mantle, it will signal the beginning of the end - the rebirth of Oblivion."},{"t":"Turok 3: Shadow of Oblivion","p":["Game Boy Color"],"d":"Bit Managers","u":"Acclaim Entertainment","g":"Action, shooter","r":"July 27, 2000","l":"https://en.wikipedia.org/wiki/Turok_3:_Shadow_of_Oblivion_(GBC_video_game)"},{"t":"Tux Racer","p":["Linux","Windows","macOS","Arcade"],"d":"Sunspire Studios","u":"Sunspire Studios","g":"Racing","r":"February 28, 2000","l":"https://en.wikipedia.org/wiki/Tux_Racer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yel.jpg","s":"Tux Racer is a 2000 open-source winter sports racing video game starring the Linux mascot, Tux the penguin. It was originally developed by Jasmin Patry as a computer graphics project in a Canadian university."},{"t":"Tweety's High-Flying Adventure","p":["Game Boy Color"],"d":"Kemco","g":"Platform","r":"November 2000","l":"https://en.wikipedia.org/wiki/Tweety's_High-Flying_Adventure_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/udobzeejevyklwuvka9e.jpg","s":"Are you ready to knock out some bad 'ol puttytats? You had better be ready for action if you want to survive the frantic, side-scrolling mayhem of TWEETY'S HIGH-FLYING ADVENTURE for the Game Boy Color. You play as the lovable Tweety Bird in an adventure to save an endangered orphanage. In an animated take on AROUND THE WORLD IN 80 DAYS, you travel to 10 different locales and collect pawprints from 80 cats spread across exotic foreign cities. You'll need to bop these kitty cats with weapons and power-ups like spatulas, plunger guns, oil slicks, banana peels, and more. Just be careful to avoid chomping plants, squirmy worms, bugs, bees, and butterflies along the way. Lola Bunny updates the action with humorous newscasts between levels as you run, jump, and fly your way to victory. You'll need quick, button-smashing reflexes and platform-hopping skills of the highest degree to save the kids in TWEETY'S HIGH-FLYING ADVENTURE."},{"t":"Tyco R/C Racin' Ratz","p":["Game Boy Color"],"d":"KnowWonder Inc.","u":"Mattel Interactive","g":"Puzzle","r":"November 28, 2000","l":"https://en.wikipedia.org/wiki/Tyco_R/C_Racin'_Ratz"},{"t":"Tyco R/C: Assault with a Battery","p":["PlayStation"],"d":"Lucky Chicken Games","u":"Mattel Interactive","g":"Racing, Simulation","r":"September 19, 2000","l":"https://en.wikipedia.org/wiki/Tyco_R/C:_Assault_with_a_Battery","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ye9.jpg","s":"Taking RC racing to the next level, TYCO RC: Assault With a Battery is every schoolyard remote-controlled racer's dream come true. Choose one of eight RC cars modeled after real life Tyco-brand toy racers such as The Recoil, Fast Traxx and Hot Rocker. Each racer is completely unique and brandishes it's own signature maneuver breaking out with awesome offensive or defensive moves, or even morphing into a menacing super car. Race as Tantrum, replete with a front-spinning axle that damages all in it's path; Nitro-Dozer, with the ability to transform into a powerful bulldozer; or even Speed Wrench, a monster truck that becomes an on-road terror twice it's width. The elaborate detail in the construction of the vehicles is also found in such features as each individual racer's speed, acceleration rate, turning ratio, and all-out power. Test your skills in Single-Player mode or challenge your friends in Two-Player. With theme-based courses designed for maximum mayhem, TYCO RC: Assault With a Battery delivers all the excitement without having to tell Mom you destroyed another car."},{"t":"Tzar: The Burden of the Crown","p":["Windows"],"d":"Haemimont Games","u":"TalonSoft","g":"Real-time strategy","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Tzar:_The_Burden_of_the_Crown","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rro.jpg","s":"Tzar: The Burden of the Crown is a real-time strategy game for the PC published by Take-Two Interactive and developed by the Bulgarian game developer company Haemimont Games.\nThe gameplay is set up in a fictional medieval age. The basic goal is to conquer the neighbouring kingdoms and destroy all traces of them, or destroy their castles, depending on selected playing mode. There are many different buildings and characters you can produce, each depending on which of the 3 races you choose to be: European, Asian or Arabian. The main differences are the types of special buildings available, and the types of troops you can make. There is also a campaign option for single players in which the player must complete specific goals, such as destroying an enemy force, or protecting a citadel from attack. The game also includes a map editor where players can create their own map to play on with strategic rivers, forests, and resources to build their armies with."},{"t":"UEFA Dream Soccer","p":["Dreamcast"],"d":"Silicon Dreams Studio","u":"Sega","g":"Sports","r":"December 8, 2000","l":"https://en.wikipedia.org/wiki/UEFA_Dream_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4523.jpg","s":"UEFA Dream Soccer is essentially an update of Sega Worldwide Soccer 2000 (same developer and game engine). The license pertains only to the clubs; player names are fictional. In this version there are also women teams, which look different but play the same. In-game commentary is provided by Alan Green, Barry Venison and Helen Chamberlain.\n\nAnimation includes 200,000 frames. Internet play was offered by Dreamarena. There is an Arcade mode including game styles such as Time Attack and a Survival knock-out tournament. Traditional mode gives you league competitions and the full World Cup."},{"t":"UEFA Euro 2000","p":["Windows","PlayStation"],"d":"EA Canada","u":"EA Sports","g":"Sports, Football","r":"April 28, 2000","l":"https://en.wikipedia.org/wiki/UEFA_Euro_2000_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8t2f.jpg","s":"This is a specially released FIFA football game that coincided with the Euro 2000 European Cup. You can take charge of a team and playall the qualifying phases for the cup or play for the cup itself."},{"t":"Ultimate Fighting Championship","p":["Dreamcast"],"u":"Crave Entertainment","r":"August 29, 2000","l":"https://en.wikipedia.org/wiki/Ultimate_Fighting_Championship_(video_game)"},{"t":"Ultimate Paintball","p":["Game Boy Color","Game Boy Advance"],"d":"Morning Star Multimedia","u":"Majesco","g":"First-person shooter","r":"September 2000","l":"https://en.wikipedia.org/wiki/Ultimate_Paintball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8439.jpg","s":"Be careful when you wade into enemy territory or they will take you out of the game in ULTIMATE PAINTBALL. To win, you must capture the enemy's flag, and in order to accomplish this you will have drive deep into enemy territory and take out hoards of foot soldiers. Luckily, there are four different weapons to choose from that make eliminating the opposition easier. But don't get caught-up in the shooting, or you will run out of time and your flag will be captured. Fortunately, eliminating the enemies reveals arrows that show the way to the flag. While the game starts out with one flag, there will eventually be three flags to find. Try to capture the flag without getting shot in ULTIMATE PAINTBALL."},{"t":"Undercover AD2025 Kei","p":["Dreamcast"],"d":"Pulse Interactive","u":"Pulse Interactive","g":"Action-adventure","r":"January 27, 2000","l":"https://en.wikipedia.org/wiki/Undercover_AD2025_Kei","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xxq.jpg","s":"Action/adventure game for the Sega Dreamcast released in 2000 exclusivevly in Japan."},{"t":"Unison: Rebels of Rhythm & Dance","p":["PlayStation 2"],"d":"Tecmo","u":"Tecmo","g":"Music","r":"November 30, 2000","l":"https://en.wikipedia.org/wiki/Unison:_Rebels_of_Rhythm_&_Dance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co56ok.jpg","s":"In the city of Twin Ships, Ducker has banished dancing from the land! It is up to the Unison team to bring dance back to the people of the city. Players must memorize and perform routines by using the twin analog sticks. The game features several licensed songs by artists such as Nelly and Aqua."},{"t":"Urban Terror","p":["Linux","Windows","macOS","Amiga"],"d":"FrozenSand, LLC, Silicon Ice Development","g":"First-person shooter","r":"August 5, 2000","l":"https://en.wikipedia.org/wiki/Urban_Terror","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8d9z.jpg","s":"Urban Terror, commonly abbreviated as UrT, is a free multiplayer first person shooter developed, that will run on any Quake III Arena compatible engine. It is available for Windows, Linux and Mac OS.\n\n\"Where Quake Meets Reality\"\n\nThe game can be described as a Hollywood tactical shooter; somewhat realism based, but the motto is \"fun over realism\". This results in a very unique, enjoyable and addictive game.\n\nUrban Terror is a standalone game since 2007 when id Software released its id Tech 3 engine under the GPL license. It now uses the latest ioquake3 engine that it is regularily updated and improved."},{"t":"Vagrant Story","p":["PlayStation"],"u":"Square","r":"February 10, 2000","l":"https://en.wikipedia.org/wiki/Vagrant_Story"},{"t":"Vampire Hunter D","p":["PlayStation"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Vampire_Hunter_D_(video_game)"},{"t":"Vampire: The Masquerade - Redemption","p":["Windows"],"r":"June 7"},{"t":"Vegas Games 2000","p":["Windows","PlayStation","Game Boy Color"],"d":"New World Computing, Inc., The 3DO Company, Digital Eclipse Software, Inc.","u":"The 3DO Company","g":"Gambling simulation","l":"https://en.wikipedia.org/wiki/Vegas_Games_2000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7g2c.jpg","s":"Vegas Games 2000 is a collection of casino games. The game claims twenty five games but this total is achieved by having multiple versions of some games.\n\nThe package contains:\n- Baccarat\n- Big Spin Money Wheel\n- Blackjack: One, Two, Four or Six decks\n- Craps\n- Keno\n- Poker: 5 Card Draw, 5 Card Stud, 7 Card Stud, Texas Hold 'Em, Jacks or Better\n- Roulette\n- Slot Machines: Beyond the Stars, Easy Money, Love 2 Win, Buffet and Ancient\n- Treasures\n- Video Keno\n- Video Poker: Tens or better, Jacks or better double down, Jacks or better high roller, Jokers Wild, Deuces Wild\n\nMany games can be played in multiple denominations and some, such as video poker, have a double down feature."},{"t":"Victorious Boxers: Ippo's Road to Glory","p":["PlayStation 2"],"d":"New Corporation","u":"Entertainment Software Publishing, Empire Interactive","g":"Fighting","r":"December 14, 2000","l":"https://en.wikipedia.org/wiki/Victorious_Boxers:_Ippo's_Road_to_Glory","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa4s3.jpg","s":"Tape up your hands, pull on your gloves and get ready to go toe-to-toe with some of the most accomplished boxers you're ever likely to meet. Victorious Boxers places you directly in the ring as Ippo Makunouchi on his quest to become the champion. But first you must prove to the coach that you're worth training!"},{"t":"Vietnam: Black Ops","p":["Windows"],"d":"Fused Software","u":"ValuSoft","g":"Shooter","l":"https://en.wikipedia.org/wiki/Vietnam:_Black_Ops","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co92x3.jpg"},{"t":"Virtua Athlete 2K","p":["Dreamcast"],"d":"Hitmaker","u":"Sega, Agetec","g":"Sports","r":"July 27, 2000","l":"https://en.wikipedia.org/wiki/Virtua_Athlete_2K","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocm5y.jpg","s":"The top 7 events from Track and Field come to life like never before as players vie for the top sports honor - \"The World's Greatest Athlete!\" Using the latest 3D graphics, Virtua Athlete 2000 challenges you to use quick reflexes, sharp eye-hand coordination, and split-second timing to master each of the events."},{"t":"Virtua Tennis","p":["Dreamcast"],"u":"Sega","r":"June 8, 2000","l":"https://en.wikipedia.org/wiki/Virtua_Tennis"},{"t":"Virtual Pool 3","p":["Windows"],"d":"Celeris","u":"Digital Mayhem, XS Games","g":"Sports","r":"November 7, 2000","l":"https://en.wikipedia.org/wiki/Virtual_Pool_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9xop.jpg","s":"Women's Professional Billiard Association's star sensation Jeanette Lee teams up with developer Celeris, Inc. to create the third installation of the Virtual Pool series by publisher Interplay. Featuring a new single player mode and online gaming capabilities to accommodate multiplayer action over a LAN or a modem, Virtual Pool 3 Featuring Jeanette Lee continues the tradition that made previous installments a commercial success.\n\nThe game offers numerous game modes from which to choose, including a career mode that allows you to begin as a local player and move up through six stages on the proverbial success ladder. You can also play head-to-head against Jeanette Lee (aka \"Black Widow\"), adjust camera angles, set up shots, play in a tournament with 4, 8, 16 or 32 players and choose from 9-ball, 8-ball, straight pool and several other game configurations."},{"t":"Virtual Pro Wrestling 2: Ōdō Keishō","p":["Nintendo 64"],"d":"AKI Corporation","u":"Asmik Ace Entertainment","g":"Wrestling","r":"January 28, 2000","l":"https://en.wikipedia.org/wiki/Virtual_Pro_Wrestling_2:_%C5%8Cd%C5%8D_Keish%C5%8D"},{"t":"Wacky Races","p":["Game Boy Color","Windows","PlayStation"],"d":"Appaloosa Interactive, Velez & Dubail","u":"Infogrames","g":"Racing","r":"June 6, 2000","l":"https://en.wikipedia.org/wiki/Wacky_Races_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wvn.jpg","s":"Based on the original Hanna-Barbera cartoon, Wacky Races lets you join your favorite characters on a wild race where only your wits, your driving skills and your bag of dirty tricks will get you across the finish line first!"},{"t":"Wacky Races: Starring Dastardly and Muttley","p":["Dreamcast"],"d":"Infogrames Sheffield House","u":"Infogrames","g":"Racing","r":"June 27, 2000","l":"https://en.wikipedia.org/wiki/Wacky_Races:_Starring_Dastardly_and_Muttley"},{"t":"Walt Disney World Quest: Magical Racing Tour","p":["Dreamcast","Game Boy Color","PlayStation"],"d":"Crystal Dynamics","u":"Eidos Interactive","g":"Racing","r":"March 23, 2000","l":"https://en.wikipedia.org/wiki/Walt_Disney_World_Quest:_Magical_Racing_Tour","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ru5.jpg","s":"Walt Disney World Quest Magical Racing Tour boasts more playable characters than any kart racer before it (a total of 13 are offered), and each of the game's tracks allows you to maneuver a different vehicle. Instead of being confined to just a go-kart, you'll get a bobsled, or a rocket ship, and several others. Collect a myriad of power-ups to your vehicle such as Mickey coins which allow you to race a little faster with each additional coin you collect. Or use the guided bottle rocket to get a speed boost and home in on your opponent. You can also collect items that can be used against your opponents like the frog spell, which will leave them hopping in your dust. Or launch an acorn at them and send them flying out of control."},{"t":"Waluigi's Toenail Clipping Party","p":["Browser"],"g":"Arcade","l":"https://en.wikipedia.org/wiki/Waluigi's_Toenail_Clipping_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co60lg.jpg","s":"Waluigi's Foot Fault was a Flash game developed by Nintendo in 2000. The game was made to promote Mario Tennis for the Nintendo 64 and was discovered in a Nintendo Power magazine article. In this game, the player is tasked with clipping Waluigi's toenails and catching them with a jar in which points are earned."},{"t":"Wario Land 3","p":["Game Boy Color"],"u":"Nintendo","r":"March 21, 2000","l":"https://en.wikipedia.org/wiki/Wario_Land_3"},{"t":"Warlocked","p":["Game Boy Color"],"d":"Bits Studios","u":"Nintendo of America","g":"Real-time strategy","r":"July 24, 2000","l":"https://en.wikipedia.org/wiki/Warlocked","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u69.jpg","s":"Play as either Humans or Beasts as you plot battle strategies. Harvest resources and construct buildings, then raise an army and order your troops into battle. Search for secret maps and train Dragons to fight on your behalf. With a powerful army at your command, you'll be ready to besiege castles, conquer enemy hordes and drive your foe from the land."},{"t":"Warlords Battlecry","p":["Windows"],"d":"Strategic Studies Group","u":"Strategic Simulations","g":"Real-time strategy","r":"June 26, 2000","l":"https://en.wikipedia.org/wiki/Warlords_Battlecry","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co224y.jpg","s":"Warlords Battlecry, released in 2000 by Strategic Studies Group and published by SSI, is a real-time strategy game that combines resource management, tactical combat, and role-playing elements set in a fantasy world."},{"t":"Warm Up!","p":["PlayStation","Windows"],"d":"Lankhor","u":"Microids","g":"Racing simulator","l":"https://en.wikipedia.org/wiki/Warm_Up!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zln9a7o9splbccedelqe.jpg","s":"The sequel to F1 World Grand Prix."},{"t":"Warriors of Might and Magic","p":["PlayStation","Game Boy Color","PlayStation 2"],"d":"The 3DO Company","u":"The 3DO Company","g":"Action RPG","r":"December 5, 2000","l":"https://en.wikipedia.org/wiki/Warriors_of_Might_and_Magic","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co90ra.jpg","s":"Warriors of Might and Magic is a game in the fictional Might and Magic universe."},{"t":"WaterRace","p":["macOS"],"d":"French Touch, SàRL","u":"French Touch, SàRL","g":"Racing","r":"December 23, 2000","l":"https://en.wikipedia.org/wiki/WaterRace"},{"t":"WCW Backstage Assault","p":["PlayStation","Nintendo 64"],"d":"Kodiak Interactive","u":"Electronic Arts","g":"Sports","r":"November 8, 2000","l":"https://en.wikipedia.org/wiki/WCW_Backstage_Assault","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3b82.jpg","s":"No-Holds-Barred Brawling! Over 50 WCW superstars, including the women of the WCW! 14 playable Backstage Areas, including the new Semi-Trailer Area. Destroy your enemy faster with power-ups! New - First Blood Mode and Torch matches! Use your environment as a weapon!"},{"t":"Westbang","p":["Windows"],"d":"Rake in Grass","u":"Rake in Grass","g":"Shoot 'em up","r":"March 13, 2000","l":"https://en.wikipedia.org/wiki/Westbang"},{"t":"Who Wants to Beat Up a Millionaire","p":["Windows","Dreamcast"],"d":"Hypnotix","u":"Simon & Schuster Interactive, Xplorys","g":"Action","r":"August 8, 2000","l":"https://en.wikipedia.org/wiki/Who_Wants_to_Beat_Up_a_Millionaire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5xxr.jpg","s":"Who Wants to Beat Up a Millionaire? is a video game parody of Who Wants to Be a Millionaire?. It was created by Hypnotixc Inc, and released in 2000 by Simon & Schuster Interactive for Windows 95, Windows 98, and Sega Dreamcast."},{"t":"Wild Arms 2","p":["PlayStation"],"r":"April 30","l":"https://en.wikipedia.org/wiki/Wild_Arms_2"},{"t":"Wild Rapids","p":["PlayStation"],"g":"Racing, Sport","l":"https://en.wikipedia.org/wiki/Wild_Rapids","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4bbh.jpg","s":"Kajak racing game developed for the Sony Playstation by Fujimic Inc and released only in Japan and PAL territories in 2000."},{"t":"Wild Wild Racing","p":["PlayStation 2"],"d":"Rage Software","u":"Imagineer, Interplay Entertainment, Rage Software","g":"Racing","r":"September 14, 2000","l":"https://en.wikipedia.org/wiki/Wild_Wild_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48gn.jpg","s":"It was one of the first games released on the PlayStation 2 and was released on the same day as the console in the US and Europe on October 26, 2000 and November 24, 2000 respectively. Wild Wild Racing allows players to compete in all-terrain vehicle races in various countries around the globe. There are five locations in the game: United States, India, Iceland, Mexico and Australia"},{"t":"Winnie the Pooh: Adventures in the 100 Acre Wood","p":["Game Boy Color"],"d":"NewKidCo, TOSE","u":"NewKidCo, Tomy","g":"Card & Board Game","r":"March 2000","l":"https://en.wikipedia.org/wiki/Winnie_the_Pooh:_Adventures_in_the_100_Acre_Wood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nbg.jpg","s":"Join Winnie the Pooh and his friends as they come to the Game Boy Color in WINNIE THE POOH: Adventures in the 100 Acre Wood. You must help Pooh get to a certain place on the game board within a specified number of dice rolls. Along the way, he will encounter his friends Tigger, Piglet, Rabbit, and Eeyore, who will play along with Pooh and open mini-games for the loveable bear to store in his cupboard. The mini-games will have the player helping Pooh look for honey, exercise, fish, get unstuck from Rabbit's hole, bounce with Tigger, and catch acorns. The more you play WINNIE THE POOH: Adventures in the 100 Acre Wood, the greater the chances of finding a new path or mini-game."},{"t":"Wizards & Warriors","p":["Windows"],"d":"Heuristic Park","u":"Activision","g":"Role-playing video game","r":"October 4, 2000","l":"https://en.wikipedia.org/wiki/Wizards_&_Warriors_(2000_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9uiz.jpg","s":"Wizards & Warriors is a traditional party-based fantasy CRPG designed by David W. Bradley, the designer of the Wizardry series. Being a spiritual successor to that series, Wizards & Warriors plays similarly and incorporates many of the same themes, albeit cosmetically changed to set it outside the Wizardry fictional universe."},{"t":"Woody Woodpecker Racing","p":["PlayStation","Windows"],"d":"Syrox Developments","u":"Konami","g":"Racing","r":"November 15, 2000","l":"https://en.wikipedia.org/wiki/Woody_Woodpecker_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u7o.jpg","s":"Woody Woodpecker Racing brings all of the classic Woody Woodpecker characters to the Game Boy Color. You can race as 10 different characters on 16 unique tracks. The racing action takes place in four different modes: Extreme, Grand Prix, Sprint, and Time Trial. Extreme has players trying to earn cups in a series of races, where the ultimate goal is to win first place in each race. Grand Prix stages races on the same tracks, but players are awarded points based on where they finish. Doing well in the races in both modes allows you to upgrade your vehicle. Both the Sprint and Time Trial modes allow for competition without the bloodlust of the other two modes. If you want to compete against another person, you can via a link cable. Race with a hyperactive bird in WOODY WOODPECKER RACING."},{"t":"Woody Woodpecker Racing","p":["Game Boy Color"],"d":"Konami","u":"Konami","g":"Kart racing","r":"December 12, 2000","l":"https://en.wikipedia.org/wiki/Woody_Woodpecker_Racing_(GBC_video_game)"},{"t":"World Championship Snooker","p":["PlayStation"],"d":"Blade Interactive","u":"Codemasters","g":"Sports","r":"June 30, 2000","l":"https://en.wikipedia.org/wiki/World_Championship_Snooker_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co93o8.jpg","s":"Join the cue for World Championship Snooker, the ground breaking new sports sim which offers you the chance to mix it with the world's biggest stars on the world's biggest stage - The Crucible Theatre in Sheffield.\n\nWith a unique shot aiming system and an in-game WSA-backed coaching mode, World Championship Snooker can take the greenest of green baize players to the top of the table."},{"t":"World Destruction League: Thunder Tanks","p":["PlayStation 2","PlayStation","Game Boy Color"],"d":"The 3DO Company","u":"The 3DO Company","g":"Car Combat","r":"September 28, 2000","l":"https://en.wikipedia.org/wiki/World_Destruction_League:_Thunder_Tanks","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob5hy.jpg","s":"The player must obtain \"powerups\" and defeat enemy vehicles, but must capture the enemy flags in order to win. However, all of the vehicles are tanks, hence its name. The game itself is short, making it quite unpopular among gamers. It was also one of the first PlayStation 2 titles to be released. It is considered a spiritual successor to the Battletanx series, since it has similar gameplay to that as well, and is made by the same company, The 3DO Company. Also a mototank from Battletanx: Global Assault can be seen in the opening title sequence, and many of the playable tanks are inspired or directly copied from Battletanx. A reversed M-80 (only in the PS1 version of Battletanx: Global Assault) can also be seen in game as the unplayable AI controlled Skorpion Bomb Tank."},{"t":"World Neverland 2 Plus: Pluto Kyouwakoku Monogatari","p":[],"l":"https://en.wikipedia.org/wiki/World_Neverland_2_Plus:_Pluto_Kyouwakoku_Monogatari"},{"t":"World Series Baseball 2K1","p":["Dreamcast"],"d":"WOW Entertainment","u":"Sega","g":"Sports","r":"July 25, 2000","l":"https://en.wikipedia.org/wiki/World_Series_Baseball_2K1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45rq.jpg","s":"World Series Baseball 2K1 is a sports video game developed by Wow Entertainment and published by Sega for the Dreamcast. It was the first game in the modern series to be featured on the Dreamcast, and was the spiritual successor to World Series Baseball for the Sega Genesis.[citation needed] It was released in July 2000 to coincide with the 2000 Major League Baseball All-Star Game in Atlanta.[citation needed]\n\nWorld Series Baseball 2K1 featured a cutting-edge graphical presentation adapted from the NAOMI game Super Major League, and its visuals were well ahead of any other baseball game at the time. Unfortunately, a lack of features, shoddy audio presentation, and major gameplay flaws meant that WSB2K1 was not well received by critics despite its fantastic graphics. The game is notorious for its sometimes-unresponsive controls, as well as the fact that manual fielding—a staple of baseball games for a half-decade prior to WSB2K1's release—isn't even an option available to players.[citation needed]\n\nAfter the debacle that was World Series Baseball 2K1, Sega decided to bring Visual Concepts (the developer behind the Dreamcast's far more successful NBA 2K and NFL 2K series) in for the next version of the game. The result was World Series Baseball 2K2, a game that was considered a major improvement over WSB2K1."},{"t":"WWF No Mercy","p":["Nintendo 64"],"u":"THQ","r":"November 17, 2000","l":"https://en.wikipedia.org/wiki/WWF_No_Mercy"},{"t":"WWF Royal Rumble","p":["Dreamcast"],"r":"August 30","l":"https://en.wikipedia.org/wiki/WWF_Royal_Rumble_(2000_video_game)"},{"t":"WWF SmackDown!","p":["PlayStation"],"r":"March 2","l":"https://en.wikipedia.org/wiki/WWF_SmackDown!_(video_game)"},{"t":"WWF SmackDown! 2: Know Your Role","p":["PlayStation"],"u":"THQ","r":"November 21, 2000"},{"t":"X-Men: Mutant Academy","p":["PlayStation","Game Boy Color"],"d":"Paradox Development, Crawfish Interactive","u":"Activision","g":"Fighting","r":"July 14, 2000","l":"https://en.wikipedia.org/wiki/X-Men:_Mutant_Academy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2y74.jpg","s":"X-Men: Mutant Academy is a 3-D/2D fighting game developed by Paradox, the company behind Activision's Wu-Tang: Shaolin Style and the never-published Thrill Kill, and based on the X-Men characters from Marvel Comics. The game was released for the Game Boy Color and PlayStation as a tie-in to X-Men.\n\nX-Men: Mutant Academy is a basic fighting game that uses six buttons: three buttons for punches and three for kicks. Due to the success of the game, it was followed by two sequels: X-Men: Mutant Academy 2 and X-Men: Next Dimension. The game's characters can be played both with their comic book costumes and their costumes from the 2000 film X-Men. Characters not present in the film were given costumes of a similar design."},{"t":"X-Men: Mutant Wars","p":["Game Boy Color"],"d":"Hal Corp./AVIT","u":"Activision Publishing, Inc.","g":"Action","r":"November 10, 2000","l":"https://en.wikipedia.org/wiki/X-Men:_Mutant_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9810.jpg","s":"Released in 2000 for the Game Boy Color, X-Men: Mutant Wars is a side-scrolling beat 'em-up game and the second X-Men title for the system. Its launch was synchronized with the release of the X-Men film on DVD.\n\nThe game's narrative revolves around a menace posed by cyborgs terrorising the planet. Convinced that Magneto is behind the cyborgs' actions, the X-Men are tasked with defeating him. Players can control characters like Wolverine, Storm, Cyclops, Iceman, and Gambit as they gear up for the impending battle to save the planet."},{"t":"X-Squad","p":["PlayStation 2"],"d":"Electronic Arts Square","u":"Electronic Arts Square, Electronic Arts","g":"Third-person shooter","r":"August 3, 2000","l":"https://en.wikipedia.org/wiki/X-Squad","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kbz.jpg","s":"The year is 2037, terrorists have taken over a secret military complex. X Squad, an elite covert force, is called in to eliminate the enemy and regain control.\n\nExplosive Action\nTake your enemies out with a sniper rifle or light them up with a flame thrower when they get close.\n\nCommand Your 4-Person Squad\nTake charge and lead your 3 squad members through intense firefighters.\n\nNext-Generation Graphics\nExperience realistic characters and amazing special effects."},{"t":"Xiama","p":[],"d":"Mulawa Dreaming","u":"Mulawa Dreaming","g":"Puzzle, adventure","l":"https://en.wikipedia.org/wiki/Xiama"},{"t":"Xtreme Sports","p":["Game Boy Color"],"r":"June 28","l":"https://en.wikipedia.org/wiki/Xtreme_Sports_(video_game)"},{"t":"You Don't Know Jack 5th Dementia","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_5th_Dementia"},{"t":"You Don't Know Jack Louder! Faster! Funnier!","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Louder!_Faster!_Funnier!"},{"t":"You Don't Know Jack Mock 2","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Mock_2"},{"t":"Yu-Gi-Oh! Dark Duel Stories","p":["Game Boy Color"],"d":"Konami","u":"Konami","g":"Digital collectible card game","r":"July 13, 2000","l":"https://en.wikipedia.org/wiki/Yu-Gi-Oh!_Dark_Duel_Stories","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yb0.jpg","s":"Yu-Gi-Oh! Dark Duel Stories, released in Japan as Yu-Gi-Oh! Duel Monsters III: Tri-Holy God Advent, is a Game Boy Color video game and the third title in the Yu-Gi-Oh! Duel Monsters series of games. It was released in Japan on July 13, 2000, and it was the first Yu-Gi-Oh! video game to be released outside of Japan, with a United States release date of March 19, 2002.\n\nPlayers of the game can trade and battle with other players using a link cable."},{"t":"Zeus: Master of Olympus","p":["Windows"],"r":"October 16"},{"t":"Zusar Vasar","p":["Dreamcast"],"d":"Real Vision","u":"Real Vision","g":"Racing","r":"July 27, 2000","l":"https://en.wikipedia.org/wiki/Zusar_Vasar","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/u5c51yosyzqkrgbfvgye.jpg","s":"A Japan exclusive Dreamcast racing game"},{"t":"Él","p":[],"l":"https://en.wikipedia.org/wiki/%C3%89l_(video_game)"}];
